def all( bs ) :
	# type: ( Iterable[bool] ) -> bool
	for b in bs :
		if not b :
			return False
	return True

Blizzards = Blizzards.Blizzards()		#Added in Blizzards: TC01

def cast(argsList):
	pCaster, eSpell = argsList
	spell = gc.getSpellInfo(eSpell)
	if not spell.isAbility() and effectBlockedByNullstone(pCaster):
		miscast(argsList)
	else:
		eval(spell.getPyResult())

	if pCaster.getDelayedSpell():
		iDuration = pCaster.getDuration()
		iDelay = pCaster.getImmobileTimer()
		if 0 < iDelay < iDuration:
			pCaster.changeImmobileTimer(-iDuration)

	if pCaster.isHasCasted():
		if pCaster.getUnitType() in [gc.getInfoTypeForString('UNIT_AURIC_ASCENDED'),gc.getInfoTypeForString('UNIT_MORRIGAN'),gc.getInfoTypeForString('UNIT_CLIODNA'),gc.getInfoTypeForString('UNIT_SARABRIDE'),gc.getInfoTypeForString('UNIT_BASIUM_ANIMANS')]:
			pCaster.setHasCasted(False)

def canCast(argsList):
	pCaster, eSpell = argsList
	spell = gc.getSpellInfo(eSpell)

	if 0 < pCaster.getDuration() < spell.getDelay():
		return False

	if spell.isAbility():
		return eval(spell.getPyRequirement())
	elif spell.getReligionPrereq() !=-1 and gc.getInfoTypeForString('PROMOTION_DIVINE') in [spell.getPromotionPrereq1(), spell.getPromotionPrereq2(), spell.getPromotionInStackPrereq()]:

		iLuonnotar = gc.getInfoTypeForString('UNIT_LUONNOTAR')
		if CyGame().getUnitCreatedCount(iLuonnotar) > 0:
			iX = pCaster.getX()
			iY = pCaster.getY()
			for iiX in xrange(iX-1, iX+2, 1):
				for iiY in xrange(iY-1, iY+ 2, 1):
					pPlot = CyMap().plot(iiX, iiY)
					if pPlot.getNumVisibleEnemyDefenders(pCaster) > 0:
						for i in xrange(pPlot.getNumUnits()):
							pUnit = pPlot.getUnit(i)
							if pUnit.getUnitType() == iLuonnotar:
								return False
		# effectArda(pCaster)
		if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_ARDA0')):
			return False
		else:
			return eval(spell.getPyRequirement())
	elif effectBlockedByNullstone(pCaster):
		return False
	else:
		return eval(spell.getPyRequirement())

##	return eval(spell.getPyRequirement())

def effect(argsList):
	pCaster, eProm = argsList
	if pCaster.getUnitType() != gc.getInfoTypeForString('UNIT_SLUAGH'):
		prom = gc.getPromotionInfo(eProm)
		eval(prom.getPyPerTurn())

def effectResisted(pUnit, pCaster, eSpell):
	spell = gc.getSpellInfo(eSpell)
	if not spell.isAbility():
		if pUnit.isHasPromotion(gc.getInfoTypeForString('PROMOTION_ELVENPOX')):
			pCaster.setHasPromotion(gc.getInfoTypeForString('PROMOTION_ELVENPOX'), True)
			CyInterface().addMessage(pCaster.getOwner(), True, 25, localText.getText("TXT_KEY_PROMOTION_ELVENPOX_SPREAD", (pCaster.getName(),pUnit.getName(), )), '', 1, 'Art/Interface/Buttons/Promotions/Cursed.dds', ColorTypes(7), pCaster.getX(), pCaster.getY(), True, True)
		if pCaster.getUnitType() == gc.getInfoTypeForString('UNIT_NULLSTONE_GOLEM'):
			pUnit.cast(iSpell)
			CyInterface().addMessage(pCaster.getOwner(), True, 25, localText.getText("TXT_KEY_SPELL_BACKFIRE", (pCaster.getName(),spell.getDescription(), pUnit.getName(), )), '', 1, 'Art/Interface/Buttons/Units/Nullstone Golem.dds', ColorTypes(7), pCaster.getX(), pCaster.getY(), True, True)
		if pUnit.getReligion() == gc.getInfoTypeForString('RELIGION_CHILDREN_OF_THE_ONE'):
			if pCaster.getUnitCombatType() == gc.getInfoTypeForString('UNITCOMBAT_DISCIPLE') or pCaster.getUnitCombatType() == gc.getInfoTypeForString('PROMOTION_DIVINE'):
				pUnit.cast(eSpell)
				CyInterface().addMessage(pCaster.getOwner(), True, 25, localText.getText("TXT_KEY_SPELL_BACKFIRE", (pCaster.getName(),spell.getDescription(), pUnit.getName(), )), '', 1, 'Art/Interface/Buttons/Religions/colorwheel.dds', ColorTypes(7), pCaster.getX(), pCaster.getY(), True, True)
	return pUnit.isResisted(pCaster, eSpell)

