##Begin atRange
def atRangeCitadelOfLight(pCaster, pPlot):
	if not pPlot.isOwned():
		pPlot.setImprovementType(gc.getInfoTypeForString('IMPROVEMENT_CITADEL'))
	else:
		iTeam = pCaster.getTeam()
		iTeam2 = pPlot.getTeam()
		iPlayer = pPlot.getOwner()
		pPlayer = gc.getPlayer(iPlayer)
##		if pPlayer.getCivilizationType() != gc.getInfoTypeForString('CIVILIZATION_MALAKIM'):
		if pPlayer.getStateReligion() != gc.getInfoTypeForString('RELIGION_THE_EMPYREAN'):
			pPlot.setImprovementType(gc.getInfoTypeForString('IMPROVEMENT_CITADEL'))
		elif iTeam != iTeam2:
			iNum = pPlayer.getNumAvailableBonuses(gc.getInfoTypeForString('BONUS_MANA_SUN'))
			if iNum > 0:
				if gc.getTeam(iTeam).isAtWar(iTeam2) or pCaster.isHiddenNationality():
					if not pCaster.isImmuneToMagic():
						if not pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_IMMUNE_FIRE')):
							iRnd = CyGame().getSorenRandNum(iNum, "Citadel of Light "+ str(pCaster.getName()))
							if iRnd > 0:
								if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_ILLUSION')) or pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_DARK_REFLECTION')):
									pCaster.kill(True, iPlayer)
								elif pCaster.getUnitType() == gc.getInfoTypeForString('UNIT_SHADOWRIDER'):
									pUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_BLIND'), True)
								elif pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_VAMPIRE')):
									pCaster.doDamageNoCaster(iNum, 30, gc.getInfoTypeForString('DAMAGE_HOLY'), False)
									if cf.doFear(pCaster, pPlot, -1, False):
										CyInterface().addMessage(pCaster.getOwner(), True, 25, localText.getText("TXT_KEY_MESSAGE_FEAR", (pCaster.getName(), )), '', 1, 'Art/Interface/Buttons/Spells/Revelation.dds', ColorTypes(7), pCaster.getX(), pCaster.getY(), True, True)
									pCaster.finishMoves()

								pCaster.doDamageNoCaster(10*iNum, 90, gc.getInfoTypeForString('DAMAGE_FIRE'), False)
								pPlot = pCaster.plot()
								CyEngine().triggerEffect(gc.getInfoTypeForString('EFFECT_PILLAR_OF_FIRE'), pPlot.getPoint())
								if iRnd > 1:
									pCaster.setIgnoreHide(True)
									for sProm in [	'PROMOTION_INVISIBLE',
													'PROMOTION_HIDDEN',
													'PROMOTION_BLUR',
													'PROMOTION_SHADOWWALK'
													]:
										pCaster.setHasPromotion(gc.getInfoTypeForString(sProm), False)
									iFeature = pPlot.getFeatureType()
									if pPlot.getImprovementType() == -1:
										if iFeature in [gc.getInfoTypeForString('FEATURE_FOREST_NEW'), gc.getInfoTypeForString('FEATURE_FOREST'), gc.getInfoTypeForString('FEATURE_FOREST_ANCIENT'), gc.getInfoTypeForString('FEATURE_JUNGLE')]:
											pPlot.setImprovementType(gc.getInfoTypeForString('IMPROVEMENT_SMOKE'))
									iTerrain = pPlot.getTerrainType()
									if iTerrain == gc.getInfoTypeForString('TERRAIN_PLAINS'):
										pPlot.setTempTerrainType(gc.getInfoTypeForString('TERRAIN_DESERT'), iRnd)
									elif iTerrain == gc.getInfoTypeForString('TERRAIN_TUNDRA'):
										pPlot.setTempTerrainType(gc.getInfoTypeForString('TERRAIN_PLAINS'), iRnd)
									elif iTerrain == gc.getInfoTypeForString('TERRAIN_SNOW'):
										pPlot.setTempTerrainType(gc.getInfoTypeForString('TERRAIN_TUNDRA'), iRnd)

def atRangeGuardian(pCaster, pPlot):
	if not pCaster.isBarbarian():
		if pPlot.getNumUnits() == 0:
			if CyGame().getWBMapScript() or CyGame().getStartTurn() + 20 < CyGame().getGameTurn(): #fixes a problem if units spawn next to the gargoyle
				pPlot.setPythonActive(False)
				pPlot.setRouteType(gc.getInfoTypeForString('ROUTE_ROAD'))
				bPlayer = gc.getPlayer(gc.getBARBARIAN_PLAYER())
				iUnit = gc.getInfoTypeForString('UNIT_GARGOYLE')
				iX = pPlot.getX()
				iY = pPlot.getY()
				CyInterface().addMessage(pCaster.getOwner(), True, 25, localText.getText("TXT_KEY_MESSAGE_GUARDIAN", ()), '', 1, gc.getUnitInfo(iUnit).getButton(), ColorTypes(8), iX, iY, True, True)
				for i in xrange(3):
					newUnit = bPlayer.initUnit(iUnit, iX, iY, UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
					newUnit.setUnitAIType(gc.getInfoTypeForString('UNITAI_ANIMAL'))
					newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_STRONG'), False)
					newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_MOUNTAINEER'), True)

