def atRangeNecrototem(pCaster, pPlot):
#Fear from Necrototems can apply to units as soon as they are created, before promotions that grant immunity to fear are applied.
	info = gc.getUnitInfo(pCaster.getUnitType())
	for sProm in [	'PROMOTION_COURAGE',
					'PROMOTION_ANGEL',
					'PROMOTION_AVATAR',
					'PROMOTION_DEMON',
					'PROMOTION_DRAGON',
					'PROMOTION_ELEMENTAL',
					'PROMOTION_ILLUSION',
					'PROMOTION_UNDEAD',
					'PROMOTION_GOLEM',
					'PROMOTION_TIMOR_MASK',
					'PROMOTION_POSSESSED',
					'PROMOTION_HEARTSTONE',
					'PROMOTION_ADVENTURER',
					'PROMOTION_OCCISOR',
					'PROMOTION_BURNING_BLOOD',
					'PROMOTION_HERALDS_BLESSING']:
		if info.getFreePromotions(gc.getInfoTypeForString(sProm)):
			break
	else:
		if cf.doFear(pCaster, pPlot, -1, True):
			CyInterface().addMessage(pCaster.getOwner(), True, 25, localText.getText("TXT_KEY_MESSAGE_FEAR", (pCaster.getName(), )), '', 1, 'Art/Interface/Buttons/Improvements/Necrototem.dds', ColorTypes(7), pCaster.getX(), pCaster.getY(), True, True)

def onMoveWiddershins(pCaster, pPlot):

	if pCaster.getUnitType() == gc.getInfoTypeForString('UNIT_DEVOUT'):
		effectPilgrimage(pCaster)

	iPlayer = pCaster.getOwner()
	iGolem = gc.getInfoTypeForString('PROMOTION_GOLEM')
	iCharm = gc.getInfoTypeForString('PROMOTION_DEASIL_CHARM')
	iShadowwalk = gc.getInfoTypeForString('PROMOTION_SHADOWWALK')
	iGrey = gc.getInfoTypeForString('PROMOTION_GREY')
	iAuric = gc.getInfoTypeForString('UNITCLASS_AURIC')
	if pCaster.isHasPromotion(iShadowwalk):
		return False
	elif pCaster.isHasPromotion(iCharm):
		return False
	elif pCaster.isHasPromotion(iGolem):
		return False
	elif pCaster.isHasPromotion(iGrey):
		return False
	elif pCaster.getUnitClassType() == iAuric:
		pPlot.setPythonActive(False)
	else:
		for i in xrange(pPlot.getNumUnits()):
			pUnit = pPlot.getUnit(i)
			if pUnit.getOwner() == iPlayer:
				if pUnit.isHasPromotion(iShadowwalk):
					return False
				if pUnit.isHasPromotion(iCharm):
					return False
				if pUnit.getUnitClassType() == iAuric:
					return False

	pBestPlot = cf.findClearPlot(pCaster, -1)
	if pBestPlot != -1:
		pCaster.setXY(pBestPlot.getX(), pBestPlot.getY(), False, True, True)
		pCaster.changeMoves(-1)
		CyInterface().addMessage(iPlayer, True, 25, localText.getText("TXT_KEY_MESSAGE_WIDDERSHINS", (pCaster.getName(), )), '', InterfaceMessageTypes.MESSAGE_TYPE_INFO, pCaster.getButton(), gc.getInfoTypeForString('COLOR_RED'), pBestPlot.getX(), pBestPlot.getY(), True, True)

def atRangePalus(pCaster, pPlot):
	if not pCaster.isBarbarian():
		if pPlot.getNumUnits() == 0:
			if CyGame().getStartTurn() + 20 < CyGame().getGameTurn(): #fixes a problem if units spawn next to the gargoyle
				bPlayer = gc.getPlayer(gc.getBARBARIAN_PLAYER())
				iUnit = gc.getInfoTypeForString('UNIT_IRON_GOLEM')
				newUnit = bPlayer.initUnit(iUnit, pPlot.getX(), pPlot.getY(), UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
				newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_MAGIC_RESISTANCE'), True)
				newUnit.setUnitAIType(gc.getInfoTypeForString('UNITAI_LAIRGUARDIAN'))
				pPlot.setPythonActive(False)

def effectMaintainRingOfWarding(pCaster):
	effectRemovePromotions(pCaster, ['PROMOTION_FORCE1','PROMOTION_FORCE2','PROMOTION_FORCE3'])

	pPlot = pCaster.plot()
	iWard = gc.getInfoTypeForString('IMPROVEMENT_RING_OF_WARDING')
	if pPlot.getImprovementType() == gc.getInfoTypeForString('IMPROVEMENT_RING_OF_WARDING'):
		iLevel = 0
		if gc.getPlayer(pCaster.getOwner()).getDisableSpellcasting() == 0:
			if pPlot.getTempImprovementTimer() < 2:
				pPlot.changeTempImprovementTimer(1)
			iAffinity = gc.getInfoTypeForString('PROMOTION_AFFINITY_FORCE')
			iChanneling2 = gc.getInfoTypeForString('PROMOTION_CHANNELING2')
			iMana = gc.getInfoTypeForString('BONUS_MANA_FORCE')
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if pUnit.isHasPromotion(iAffinity) and pUnit.isHasPromotion(iChanneling2):
					if pUnit.getImmobileTimer() < 1:
						if gc.getPlayer(pUnit.getOwner()).getDisableSpellcasting() == 0:
							iLevel = max(iLevel, min(pUnit.getLevel(), cf.getNumBonusEffective(pUnit.getOwner(), iMana, pUnit) + 1 ) )
		pPlot.setMinLevel(iLevel)
		if iLevel == 0:
			iReal = pPlot.getRealImprovementType()
			if iReal == iWard:
				pPlot.setImprovementType(-1)
			else:
				pPlot.setImprovementType(iReal)

def atRangeUpdateWarding(pCaster, pPlot):
	iWard = gc.getInfoTypeForString('IMPROVEMENT_RING_OF_WARDING')
	if pPlot.getImprovementType() == iWard:
		iLevel = 0
		if pCaster.getUnitType() == gc.getInfoTypeForString('UNIT_RUNEWYN') and pPlot.getNumVisibleEnemyDefenders(pCaster) > 0:
			pPlot.setMinLevel(0)
			iReal = pPlot.getRealImprovementType()
			if iReal == iWard:
				pPlot.setImprovementType(-1)
			else:
				pPlot.setImprovementType(iReal)
			return False
		else:
			iAffinity = gc.getInfoTypeForString('PROMOTION_AFFINITY_FORCE')
			iChanneling2 = gc.getInfoTypeForString('PROMOTION_CHANNELING2')
			iMana = gc.getInfoTypeForString('BONUS_MANA_FORCE')
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if pUnit.isHasPromotion(iAffinity) and pUnit.isHasPromotion(iChanneling2):
					iLevel = max(iLevel, min(pUnit.getLevel(), cf.getNumBonusEffective(pUnit.getOwner(), iMana, pUnit) + 1 ) )
			pPlot.setMinLevel(iLevel)
			if iLevel == 0:
				iReal = pPlot.getRealImprovementType()
				if iReal == iWard:
					pPlot.setImprovementType(-1)
				else:
					pPlot.setImprovementType(iReal)


			if pCaster.isHasPromotion(iAffinity):
				if reqRingOfWarding(pCaster, 'SPELL_RING_OF_WARDING_IMPROVEMENT'):
					spellRingOfWarding(pCaster, 'SPELL_RING_OF_WARDING_IMPROVEMENT')

def reqRingOfWarding(pCaster, eSpell=-1):
	iMana = gc.getInfoTypeForString('BONUS_MANA_FORCE')

	pPlot = pCaster.plot()
	if pPlot.isCity():
		return False
##		pCity = pPlot.getPlotCity()
##		if pCaster.getOwner()!= pCity.getOwner():
##			return False
	iWard = gc.getInfoTypeForString('IMPROVEMENT_RING_OF_WARDING')
	iX = pCaster.getX()
	iY = pCaster.getY()
	for iDirection in xrange(DirectionTypes.NUM_DIRECTION_TYPES):
		pAdjacentPlot = plotDirection(iX, iY, DirectionTypes(iDirection))
		if pAdjacentPlot.isNone():continue
		if pAdjacentPlot.getImprovementType() == iWard:
			return False#If adjacent rings of warding were allowed, there could be cases where plots were permanently impassible as the casters could not move out of their own rings
	iImprovement = pPlot.getImprovementType()
	if iImprovement != -1:
		if iImprovement == iWard:
			return False
		elif gc.getImprovementInfo(iImprovement).isUnique():
			return False

	if min(pCaster.getLevel(), cf.getNumBonusEffective(pCaster.getOwner(), iMana, pCaster) + 1 ) < 2:
		return False

	return True

def spellRingOfWarding(pCaster, eSpell=-1):
	pPlot = pCaster.plot()
	pPlot.setTempImprovementType(gc.getInfoTypeForString('IMPROVEMENT_RING_OF_WARDING'), 2)
	iMana = gc.getInfoTypeForString('BONUS_MANA_FORCE')
	iLevel = min(pCaster.getLevel(), cf.getNumBonusEffective(pCaster.getOwner(), iMana, pCaster) + 1 )
	pPlot.setMinLevel(iLevel)

def helpRingOfWarding(lpUnits, eSpell=-1):
	szBuffer = ''
	pCaster = lpUnits[0]
	iPlayer = pCaster.getOwner()
	pPlot = pCaster.plot()
	iLevel = 0
	iAffinity = gc.getInfoTypeForString('PROMOTION_AFFINITY_FORCE')
	iChanneling2 = gc.getInfoTypeForString('PROMOTION_CHANNELING2')
	iWard = gc.getInfoTypeForString('IMPROVEMENT_RING_OF_WARDING')
	iMana = gc.getInfoTypeForString('BONUS_MANA_FORCE')
	for pUnit in lpUnits:
		if pUnit.isHasPromotion(iAffinity) and pUnit.isHasPromotion(iChanneling2):
			iLevel = max(iLevel, min(pUnit.getLevel(), cf.getNumBonusEffective(pUnit.getOwner(), iMana, pUnit) + 1 ) )
	szBuffer += localText.getText("TXT_KEY_HELP_SPELL_ADDS", ( )) + CyGameTextMgr().getImprovementHelp(iWard, False)
	szBuffer += '\n' + localText.getText("[ICON_BULLET]", ( )) + localText.getText("TXT_KEY_PLOT_MIN_LEVEL", (iLevel,))

	return szBuffer

def effectWanderlust(pCaster):
	if pCaster.isAlive() and not pCaster.hasMoved():
		if pCaster.getImmobileTimer() < 1:
			if pCaster.getUnitType() != gc.getInfoTypeForString('UNIT_ADVENTURER'):
				pPlot = pCaster.plot()
				if not pPlot.isOwned():
					if CyGame().getSorenRandNum(100, "Wanderlust "+ str(pCaster.getName())) < pCaster.getLevel():
						iRnd = CyGame().getSorenRandNum(100, "Explore Lair "+ str(pCaster.getName()))
						if iRnd < 14:
							cf.exploreLairBigBad(pCaster)
						elif iRnd < 44:
							cf.exploreLairBad(pCaster)
						elif iRnd < 70:
							cf.exploreLairNeutral(pCaster)
						elif iRnd < 95:
							cf.exploreLairGood(pCaster)
						else:
							cf.exploreLairBigGood(pCaster)
						pCaster.changeExperience(1, -1, False, False, False)
				elif pPlot.isCity():
					iX = pCaster.getX()
					iY = pCaster.getY()
					bBoard = True
					iTeam = pCaster.getTeam()
					if pPlot.getNumDefenders(pCaster.getOwner()) < 2:
						bBoard = False
					elif pPlot.findHighestCultureTeam() != iTeam:
						bBoard = False
					elif pPlot.getPlotCity().getOccupationTimer() > 0:
						bBoard = False
					else:
						pTeam = gc.getTeam(iTeam)
						for iiX in xrange(iX-2, iX+ 3, 1):
							for iiY in xrange(iY-2, iY+ 3, 1):
								pPlot2 = CyMap().plot(iiX, iiY)
								if not pPlot2.isNone():
									for i in xrange(pPlot2.getNumUnits()):
										pUnit = pPlot2.getUnit(i)
										if pUnit.getTeam() == iTeam:
											continue
										elif pUnit.isHiddenNationality():
											bBoard = False
											break
										elif pTeam.isAtWar(pUnit.getTeam()):
											bBoard = False
											break
					if bBoard:
						if CyGame().getSorenRandNum(100, "Something Completely Different for "+ str(pCaster.getName())) < 2*pCaster.getLevel():
							bImmortal = pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_IMMORTAL'))
							cf.makeMortal(pCaster)
							iPlayer = pCaster.getOwner()
							CyInterface().addMessage(iPlayer, True, 25, localText.getText("TXT_KEY_SOMETHING", ()), '', 1, 'Art/Interface/Buttons/Units/Adventurer.dds', ColorTypes(7), iX, iY, True, True)
							pPlayer = gc.getPlayer(iPlayer)
							
							bFoxmenHero = False
							if pCaster.getReligion() == gc.getInfoTypeForString('RELIGION_FOXMEN'):
								if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_DIVINE')):
									#if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_AFFINITY_AIR')):
									bFoxmenHero = True

							iUnitCombat = pCaster.getUnitCombatType()
							if iUnitCombat == gc.getInfoTypeForString('UNITCOMBAT_DISCIPLE'):
								for sProm in [
												'PROMOTION_DIVINE',
												'PROMOTION_ZEAL',
												'PROMOTION_INQUISITOR',
												'PROMOTION_EVANGELIST',
												'PROMOTION_EREMITE',
												'PROMOTION_CROWN_OF_BRILLANCE',
												'PROMOTION_EXORCIST',
												'PROMOTION_SUNDERED',
												'PROMOTION_MAGIC_IMMUNE'

												]:
									iProm = gc.getInfoTypeForString(sProm)
									if iProm > -1:
										if pCaster.isHasPromotion(iProm):
											pCaster.setHasPromotion(iProm, False)


							elif iUnitCombat == gc.getInfoTypeForString('UNITCOMBAT_ADEPT'):
								cf.removeAffinities(pCaster, True)
								for sProm in [
												'PROMOTION_CHANNELING1',
												'PROMOTION_CHANNELING2',
												'PROMOTION_CHANNELING3',
												'PROMOTION_CHANNELING4',

												'PROMOTION_MASTERY',
												'PROMOTION_ARCANE',
												'PROMOTION_SUMMONER',
												'PROMOTION_SUNDERED'

												]:
									iProm = gc.getInfoTypeForString(sProm)
									if iProm > -1:
										if pCaster.isHasPromotion(iProm):
											pCaster.setHasPromotion(iProm, False)
											info = gc.getPromotionInfo(iProm)

											iBonus = info.getBonusPrereq()
											if iBonus != -1:
												if gc.getBonusInfo(iBonus).isMana():

													iSpell2 = info.getPrereqPromotion()#Normal Mage tier spell
													if iSpell2 != -1:
														iMana = gc.getPromotionInfo(iSpell2).getBonusPrereq()
														if iMana != -1:
															pCaster.setHasPromotion(iSpell2, True)
															info = gc.getPromotionInfo(iSpell2)
															iSpell1 = info.getPrereqPromotion()#Normal Mage tier spell
															if iSpell1 != -1:
																iMana = gc.getPromotionInfo(iSpell1).getBonusPrereq()
																if iMana != -1:
																	pCaster.setHasPromotion(iSpell1, True)

							iUnit = gc.getInfoTypeForString('UNIT_ADVENTURER')


							newUnit = pPlayer.initUnit(iUnit, iX, iY, UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
							for iProm in xrange(gc.getNumPromotionInfos()):
								if newUnit.isHasPromotion(iProm) and not pCaster.isHasPromotion(iProm):
									newUnit.setHasPromotion(iProm, False)
							newUnit.setPromotionReady(False)
							newUnit.convert(pCaster)
							newUnit.changeExperience(-newUnit.getLevel(), -1, False, False, False)
							if bImmortal:
								newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_IMMORTAL'), True)
							if bFoxmenHero:
								#newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_AFFINITY_AIR'), True)
								newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_FAIR_WINDS'), True)
								newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_DIVINE'), True)

def effectApricus(pCaster):
	iX = pCaster.getX()
	iY = pCaster.getY()
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iTeam = pPlayer.getTeam()
	iDemon = gc.getInfoTypeForString('PROMOTION_DEMON')
	iDemonP = gc.getInfoTypeForString('PROMOTION_POSSESSED')
	iUnholyTaint = gc.getInfoTypeForString('PROMOTION_UNHOLY_TAINT')
	iHoly = gc.getInfoTypeForString('DAMAGE_HOLY')
	iSluagh = gc.getInfoTypeForString('UNIT_SLUAGH')

	eTeam = gc.getTeam(iTeam)
	for iDirection in xrange(DirectionTypes.NUM_DIRECTION_TYPES):
		pPlot = plotDirection(iX, iY, DirectionTypes(iDirection))
		if pPlot.isNone():continue
		for iUnit in xrange(pPlot.getNumUnits()):
			pUnit = pPlot.getUnit(iUnit)
			if pUnit.getUnitType() != iSluagh:
				if pUnit.isHasPromotion(iDemon):
					pUnit.doDamage(35, 100, pCaster, iHoly, False)
				elif pUnit.isHasPromotion(iDemonP):
					pCaster.setHasPromotion(iDemonP, False)
					pUnit.doDamage(35, 70, pCaster, iHoly, False)
				elif pUnit.isHasPromotion(iUnholyTaint):
					pCaster.setHasPromotion(iUnholyTaint, False)
					pUnit.doDamage(35, 50, pCaster, iHoly, False)
	if not pCaster.isAlive():
		if not pCaster.getUnitClassType() == gc.getInfoTypeForString('UNITCLASS_BASIUM'):
			pCaster.setHasPromotion(gc.getInfoTypeForString('PROMOTION_APRICUS'), False)
			newUnit = pPlayer.initUnit(gc.getInfoTypeForString('EQUIPMENT_APRICUS'), iX, iY, UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)


def effectVaultWyrmBait(pCaster):
	iWyrm = gc.getInfoTypeForString('UNIT_VAULT_WYRM')
	pPlot = pCaster.plot()
	if pCaster.getUnitType() == iWyrm:
		#if pCaster.isBarbarian():
		lWyrmhold = cf.findImprovements(gc.getInfoTypeForString('IMPROVEMENT_WYRMHOLD_VAULT'))

		for pPlotWV in lWyrmhold:
			if pCaster.atPlot(pPlotWV):continue
			iDistance = CyMap().calculatePathDistance(pPlot, pPlotWV)
			if iDistance == -1:continue
			pCaster.getGroup().pushMoveToMission( pPlotWV.getX(), pPlotWV.getY())
			break

	else:
		#for pUnit in PyPlayer(gc.getBARBARIAN_PLAYER()).getUnitList():
		for pUnit in PyPlayer(pCaster.getOwner()).getUnitList():
			if pUnit.getUnitType() == iWyrm:
				if pUnit.atPlot(pPlot):continue
				iDistance = CyMap().calculatePathDistance(pUnit.plot(), pPlot)
				if iDistance == -1:continue
				if iDistance <= 1:
					if pUnit.canMoveOrAttackInto(pPlot, False):
						pUnit.attack(pPlot, False)
				else:
					pUnit.getGroup().pushMoveToMission(pPlot.getX(), pPlot.getY())
					
def effectBoneCirclet(pCaster):
	if CyGame().getSorenRandNum(pCaster.getLevel(), "Bone Circlet Wraith") < 3:
		miscastSummonBarbarian(pCaster, gc.getInfoTypeForString('SPELL_SUMMON_WRAITH'))

	iGoat = gc.getInfoTypeForString('UNIT_APOPHIS')
	iSerpent = gc.getInfoTypeForString('UNIT_APOPHIS_SERPENT')

	if pCaster.getUnitType() == iGoat:
		pCaster.setHasPromotion(gc.getInfoTypeForString('PROMOTION_BONE_CIRCLET'), False)
		iPlayer = pCaster.getOwner()
		pPlayer = gc.getPlayer(iPlayer)
		iX = pCaster.getX()
		iY = pCaster.getY()
		newUnit = pPlayer.initUnit(iSerpent, iX, iY, UnitAITypes.UNITAI_HERO, DirectionTypes.DIRECTION_SOUTH)
		newUnit.convert(pCaster)
		newUnit.setScenarioCounter(iSerpent)
	elif CyGame().getUnitCreatedCount(iGoat) > 0:
		iX = pCaster.getX()
		iY = pCaster.getY()
		for iiX in xrange(iX-2, iX+ 3, 1):
			for iiY in xrange(iY-2, iY+ 3, 1):
				pPlot = CyMap().plot(iiX, iiY)
				for i in xrange(pPlot.getNumUnits()):
					pUnit = pPlot.getUnit(i)
					if pUnit.getUnitType() == iGoat:
						iPlayer = pUnit.getOwner()
						pPlayer = gc.getPlayer(iPlayer)
						iX = pUnit.getX()
						iY = pUnit.getY()
						newUnit = pPlayer.initUnit(iSerpent, iX, iY, UnitAITypes.UNITAI_HERO, DirectionTypes.DIRECTION_SOUTH)
						pCaster.setHasPromotion(gc.getInfoTypeForString('PROMOTION_BONE_CIRCLET'), False)
						newUnit.convert(pUnit)
						newUnit.setScenarioCounter(iSerpent)
						break

