def effectAffinityIce(pCaster):
	effectRemovePromotions(pCaster, ['PROMOTION_ICE1','PROMOTION_ICE2','PROMOTION_ICE3'])
	iUnit = pCaster.getUnitType()
	if iUnit == gc.getInfoTypeForString('UNIT_AQUILAN'):
		effectCreateBlizzard(pCaster)
	elif iUnit == gc.getInfoTypeForString('UNIT_BADB'):
		if pCaster.isBarbarian():
			effectCreateBadbsBlizzard(pCaster)
	elif iUnit == gc.getInfoTypeForString('UNIT_AURIC_ASCENDED'):
		spellSnowfallPassive(pCaster)


def effectCreateBadbsBlizzard(pCaster, eSpell=-1):
	iBB = gc.getInfoTypeForString('IMPROVEMENT_BADBS_BLIZZARD')
	pPlot = pCaster.plot()
	iRnd = pCaster.getLevel()
	if pPlot.getImprovementType() != iBB:
		iIce = gc.getInfoTypeForString('BONUS_MANA_ICE')
		lBB = cf.findImprovements(iBB)
		if len(lBB) > 0:
			pPlotBB = lBB[0]
			pPlotBB.changeTempBonusTimer(1-pPlotBB.getTempBonusTimer())
			iBonusReal = pPlotBB.getRealBonusType()
			if iBonusReal == iIce:
				pPlotBB.setBonusType(-1)
			else:
				pPlotBB.setBonusType(iBonusReal)
			pPlotBB.changeTempTerrainTimer(1-pPlotBB.getTempTerrainTimer())
			iReal = pPlotBB.getRealImprovementType()
			if iReal == iBB:
				pPlotBB.setImprovementType(-1)
			else:
				pPlotBB.setImprovementType(iReal)
		pPlot.setTempImprovementType(iBB, iRnd)
		pPlot.setTempBonusType(iIce, iRnd)

		if pCaster.isBarbarian():
			pCaster.setHasCasted(True)
			pCaster.setMadeAttack(True)

	if not pPlot.isCity():
		if reqCallBlizzard(pCaster,'SPELL_CALL_BLIZZARD'):
			spellCallBlizzard(pCaster,'SPELL_CALL_BLIZZARD')
		elif not pPlot.isHasTempFeature():
			pPlot.setTempFeatureType(gc.getInfoTypeForString('FEATURE_BLIZZARD'), 0, iRnd)

def reqCreateBlizzard(pCaster, eSpell=-1):
	pPlot = pCaster.plot()
	iBlizzard = gc.getInfoTypeForString('FEATURE_BLIZZARD')
	if pPlot.getFeatureType() == iBlizzard:
		return False
		
	#if pPlot.getFeatureType() == -1:
	iX = pCaster.getX()
	iY = pCaster.getY()
	for iDirection in xrange(DirectionTypes.NUM_DIRECTION_TYPES):
		pPlot2 = plotDirection(iX, iY, DirectionTypes(iDirection))
		if not pPlot2.isNone():
			if pPlot2.getFeatureType() == iBlizzard:
				return False
	return True
	#return False
	
def spellCreateBlizzard(pCaster, eSpell=-1):
	pPlot = pCaster.plot()
	pPlot.setTempFeatureType(gc.getInfoTypeForString('FEATURE_BLIZZARD'), 0, pCaster.getLevel())

def effectCreateBlizzard(pCaster, eSpell=-1):
	pPlot = pCaster.plot()
	if not pPlot.isCity():
		if reqCallBlizzard(pCaster,'SPELL_CALL_BLIZZARD'):
			spellCallBlizzard(pCaster,'SPELL_CALL_BLIZZARD')
		elif not pPlot.isHasTempFeature():
			pPlot.setTempFeatureType(gc.getInfoTypeForString('FEATURE_BLIZZARD'), 0, pCaster.getLevel())
	return False

def effectCrownOfBrillance(pCaster, eSpell = gc.getInfoTypeForString('SPELL_CROWN_OF_BRILLANCE')):
	if pCaster.getImmobileTimer() > 0 or pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_HELD')):
		return False
#I want Chalid Astrakien and the High Priests of the Empyrean to be able to cause Calabim Lugus worshippers to rebel, but that does not mean that Eurabatres and his fireballs should have the same effect.
	iEmp = gc.getInfoTypeForString('RELIGION_THE_EMPYREAN')
	bEmpyream = pCaster.getReligion() == iEmp
	bTamesis = pCaster.getUnitType() == gc.getInfoTypeForString('UNIT_TAMESIS')
	pPlot = pCaster.plot()
	if bTamesis:
		if reqScorch(pCaster, gc.getInfoTypeForString('SPELL_SCORCH')):
			spellScorch(pCaster, gc.getInfoTypeForString('SPELL_SCORCH'))
		if reqBlaze(pCaster, gc.getInfoTypeForString('SPELL_BLAZE')):
			pPlot.setTempImprovementType(gc.getInfoTypeForString('IMPROVEMENT_SMOKE'), pCaster.getLevel())


	iHoly = gc.getInfoTypeForString('DAMAGE_HOLY')
	iFire = gc.getInfoTypeForString('DAMAGE_FIRE')
	iSluagh = gc.getInfoTypeForString('UNIT_SLUAGH')
	iCalabim = gc.getInfoTypeForString('CIVILIZATION_CALABIM')
	iVamp = gc.getInfoTypeForString('PROMOTION_VAMPIRE')
	iLoyal = gc.getInfoTypeForString('PROMOTION_LOYALTY')
	iRebel = gc.getInfoTypeForString('PROMOTION_REBEL')
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iTeam = pPlayer.getTeam()

	eTeam = gc.getTeam(iTeam)
	iX = pCaster.getX()
	iY = pCaster.getY()
	for iDirection in xrange(DirectionTypes.NUM_DIRECTION_TYPES):
		pPlot = plotDirection(iX, iY, DirectionTypes(iDirection))
		if pPlot.isNone():continue
		if pPlot.isVisibleEnemyUnit(iPlayer):
			for iUnit in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(iUnit)
				if pUnit.getUnitType() != iSluagh:
					iUnitTeam = pUnit.getTeam()
					if bTamesis or pUnit.isHasPromotion(iVamp):
						pUnit.doDamage(3, 50, pCaster, iHoly, True)
						pUnit.doDamage(3, 50, pCaster, iFire, True)
					elif bEmpyream:
						if pUnit.getCivilizationType() == iCalabim and pUnit.getReligion() == iEmp:
							if effectResisted(pUnit, pCaster, eSpell):continue
							pUnit.setHasPromotion(iLoyal, False)
							if not pUnit.isOnlyDefensive():
								pUnit.setHasPromotion(iRebel, True)
							if eTeam.isAtWar(iUnitTeam):
								#A strong Vampire could put an end to the rebellion.
								for i in xrange(pPlot.getNumUnits()):
									pUnit2 = pPlot.getUnit(i)
									if pUnit2.isHasPromotion(iVamp):
										if iUnitTeam == pUnit2.getTeam():
											if getCombatOdds(pCaster, pUnit2) > 500:
												break
								else:
									iPlayerUnit = pUnit.getOwner()
									pPlayerUnit = gc.getPlayer(iPlayerUnit)
									sName = cf.getNameWithColorScheme(pUnit, pUnit.isInvisible(pCaster.getTeam(), False))
									CyInterface().addMessage(iPlayerUnit, True, 25, localText.getText("TXT_KEY_MESSAGE_DEFECT_RELIGION", (sName, )), '', InterfaceMessageTypes.MESSAGE_TYPE_INFO, pCaster.getButton(), gc.getInfoTypeForString('COLOR_RED'), pCaster.getX(), pCaster.getY(), True, True)
									CyInterface().addMessage(iPlayer, True, 25, localText.getText("TXT_KEY_MESSAGE_DEFECT_TO_RELIGION", (sName, pPlayerUnit.getName(), )), '', InterfaceMessageTypes.MESSAGE_TYPE_INFO, pCaster.getButton(), gc.getInfoTypeForString('COLOR_GREEN'), pCaster.getX(), pCaster.getY(), True, True)
									newUnit = pPlayer.initUnit(pUnit.getUnitType(), pCaster.getX(), pCaster.getY(), UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
									cf.removeAffinities(newUnit)
									newUnit.convert(pUnit)
									newUnit.setHasPromotion(iRebel, False)
									newUnit.setReligion(iEmp)


	pCaster.cast(gc.getInfoTypeForString('SPELL_CROWN_OF_BRILLANCE'))

	if not gc.getGame().isOption(GameOptionTypes.GAMEOPTION_NO_PLOT_COUNTER):
		pPlot = pCaster.plot()
		pPlot.changePlotCounter(-pCaster.getLevel()*CyGame().getGlobalCounter()/5)

def effectDahlia(pCaster):
	if pCaster.getDuration() == 1 and pCaster.getUnitType() == gc.getInfoTypeForString('UNIT_TRISTAN'):
		iNum = 0
		iX = pCaster.getX()
		iY = pCaster.getY()
		for iiX in xrange(iX-1, iX+ 2, 1):
			for iiY in xrange(iY-1, iY+ 2, 1):
				pPlot = CyMap().plot(iiX, iiY)
				if pPlot.isNone():continue
				iNum += pPlot.getNumVisibleEnemyDefenders(pCaster)
		iSpirit = cf.getNumBonusEffective(pCaster.getOwner(), gc.getInfoTypeForString('BONUS_MANA_SPIRIT'), pCaster)
		iDuration = CyGame().getSorenRandNum(min(iNum, iSpirit), "Dahlia Duration")
		if iDuration > 0:
			pCaster.setDuration(iDuration)
	effectHallow(pCaster)


