def effectDiscordRebel(pCaster):
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iTeam = pCaster.getTeam()
	eTeam = gc.getTeam(iTeam)
	bRebel = True
	
	if pCaster.getUnitType() == gc.getInfoTypeForString('UNIT_HARLEQUIN'):
		bRebel = False
	
	if pCaster.isAvatarOfCivLeader():
		bRebel = False

	if eTeam.getAtWarCount(True) > 0:
		bRebel = False
	elif pPlayer.getStateReligion() == gc.getInfoTypeForString('RELIGION_SONS_OF_DISCORD'):
		bRebel = False
	if bRebel: 
		pPlot = pCaster.plot()
		if pPlot.isCity():
			pCity = pPlot.getPlotCity()
			if pCity.getNumBuilding(gc.getInfoTypeForString('BUILDING_ARENA')) < 1:
				bRebel = False
	if bRebel: 
		iX = pCaster.getX()
		iY = pCaster.getY()
		for iiX in xrange(iX-2, iX+ 3, 1):
			for iiY in xrange(iY-2, iY+ 3, 1):
				pPlot = CyMap().plot(iiX, iiY)
				if pPlot.isNone():continue
				if pPlot.isVisibleEnemyUnit(iPlayer):
					bRebel = False
					break
			if pPlot.isCity():
				pCity = pPlot.getPlotCity()
				if pCity.getNumBuilding(gc.getInfoTypeForString('BUILDING_ARENA')) < 1:
					bRebel = False
					break
					
		pCaster.setHasPromotion(gc.getInfoTypeForString('PROMOTION_REBEL'), bRebel)
	return False

def effectDragon(pCaster):
	if not (pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_ILLUSION')) or pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_DARK_REFLECTION'))):
		iPlayer = pCaster.getOwner()
		pPlayer = gc.getPlayer(iPlayer)
		iDragonType = pCaster.getUnitType()

		sNameCaster = cf.getNameWithColorScheme(pCaster)
		
		iTeam = pPlayer.getTeam()
		eTeam = gc.getTeam(iTeam)
		pPlot = pCaster.plot()
		iX = pCaster.getX()
		iY = pCaster.getY()
		iUnyielding = gc.getInfoTypeForString('BUILDING_UNYIELDING_ORDER')
		iUnyieldingG = gc.getInfoTypeForString('BUILDING_UNYIELDING_ORDER_GREATER')
		iCult = gc.getInfoTypeForString('RELIGION_CULT_OF_THE_DRAGON')
		iDr = gc.getInfoTypeForString('PROMOTION_DRAGON')


		iClassFanatic = gc.getInfoTypeForString('UNITCLASS_DRAGON_FANATIC')
