def helpEffectArda(lpUnits, eSpell):
	pCaster = lpUnits[0]
	szBuffer = ''
	iReligionCaster= pCaster.getReligion()
	if iReligionCaster in [-1, gc.getInfoTypeForString('RELIGION_MATRONAE'), gc.getInfoTypeForString('RELIGION_CHILDREN_OF_THE_ONE'), gc.getInfoTypeForString('RELIGION_CULT_OF_THE_DRAGON')] or pCaster.getUnitType() in [gc.getInfoTypeForString('UNIT_LOKI'), gc.getInfoTypeForString('UNIT_TREANT'), gc.getInfoTypeForString('UNIT_HARLEQUIN'), gc.getInfoTypeForString('UNIT_BRUJAH'), gc.getInfoTypeForString('UNIT_UNSEELIE_SHADOW')] or pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_AVATAR')) or pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_DRAGON')):
		szBuffer = helpTogglePromotionsBuffCaster(lpUnits, eSpell, [], ['PROMOTION_ARDA0', 'PROMOTION_ARDA1', 'PROMOTION_ARDA2', 'PROMOTION_ARDA3', 'PROMOTION_ARDA4', 'PROMOTION_ARDA5', 'PROMOTION_ARDA6', 'PROMOTION_ARDA7', 'PROMOTION_ARDA8', 'PROMOTION_ARDA9', 'PROMOTION_ARDA10'])
		return szBuffer
	else:
		iArda = 40
		#改造 22：祭祀等级与经验加成（信徒 0 / 祭司 3 / 主教 6；每等级 0.5，不预先取整）
		if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_DIVINE2')):
			iRankArda = 6
		elif pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_DIVINE')):
			iRankArda = 3
		else:
			iRankArda = 0
		iLevelArda = pCaster.getLevel() / 2
		iX = pCaster.getX()
		iY = pCaster.getY()
		pPlot = pCaster.plot()
		iPlotPlayer = PlayerTypes.NO_PLAYER
		iPlayer = pCaster.getOwner()
		pPlayer = gc.getPlayer(iPlayer)
		iTeam = pCaster.getTeam()
		eTeam = gc.getTeam(iTeam)
		infoRel = gc.getReligionInfo(iReligionCaster)
		sIconDesc = u"%c" %(infoRel.getChar())
		sHolyCity = localText.getText("TXT_KEY_RELIGION_SCREEN_HOLY_CITY", ())
		sCity = localText.getText("TXT_KEY_CITY", ())
		sWater = localText.getText("TXT_KEY_BUILDING_WATER_PLOTS", ())
		sRiverside = localText.getText("TXT_KEY_MISC_ALONG_RIVER", ())
		sHills = localText.getText("TXT_KEY_PLOT_HILLS", ())
		sPeak = localText.getText("TXT_KEY_PLOT_PEAK", ())
		sProximity = localText.getText("TXT_KEY_PROXIMITY", ())

		sAlignment = localText.getText("TXT_KEY_CONCEPT_ALIGNMENT", ())
		sTab = localText.getText("[TAB]", ( ))
		sBullet = localText.getText("[ICON_BULLET]", ( ))
		szBufferTerrain = ''
		szBufferCity = ''
		iCityArda = 0
		pCity = -1
