def onMoveDoDamage(pCaster, pPlot, iDmg, iDmgLimit, sDamageType, bStartWar=False):
	pCaster.doDamageNoCaster(iDmg, iDmgLimit, gc.getInfoTypeForString(sDamageType), bStartWar)



def onMoveAncientForest(pCaster, pPlot, bUnitCreation):
	if not bUnitCreation :
		if pPlot.getNumUnits() == 1 and not pCaster.isFlying():
			if pPlot.isOwned() and pPlot.getTeam() != pCaster.getTeam():
				pPlotPlayer = gc.getPlayer(pPlot.getOwner())
				if pPlotPlayer.isBarbarian() or pPlotPlayer.getStateReligion() == gc.getInfoTypeForString('RELIGION_FELLOWSHIP_OF_LEAVES'):
					iChance = gc.getDefineINT('TREANT_SPAWN_CHANCE')
					pCity = CyMap().findCity(pPlot.getX(), pPlot.getY(), pPlot.getOwner(), TeamTypes.NO_TEAM, False, False, TeamTypes.NO_TEAM, DirectionTypes.NO_DIRECTION, pPlotPlayer.getCity(-1))
					if not pCity.isNone():
						for sBuilding in [	'BUILDING_TEMPLE_OF_LEAVES',
									'BUILDING_TEMPLE_UNBLEMISHED',
									'BUILDING_SONG_OF_AUTUMN'
									]:
							if pCity.getNumBuilding(gc.getInfoTypeForString(sBuilding)) > 0:
								iChance *= 2
					if CyGame().getSorenRandNum(100, "Treant Spawn Chance") < iChance:
						if gc.getTeam(pCaster.getTeam()).isAtWar(pPlotPlayer.getTeam()) or pCaster.isHiddenNationality():
							for i in xrange(pPlot.getNumUnits()):
								p2Unit = pPlot.getUnit(i)
								p2Plot = cf.findClearPlot(p2Unit, -1)
								if p2Plot != -1:
									bActive = pPlot.isPythonActive()
									p2Plot.setPythonActive(False)
									p2Unit.setXY(p2Plot.getX(), p2Plot.getY(), False, True, True)
									p2Unit.changeMoves(-1)
									p2Plot.setPythonActive(bActive)
							if pPlot.getNumUnits() == 0:
								newUnit = pPlotPlayer.initUnit(gc.getInfoTypeForString('UNIT_TREANT'), pPlot.getX(), pPlot.getY(), UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
								newUnit.setDuration(3)
								newUnit.AI_setGroupflag(43)	# 43=GROUPFLAG_SUICIDE_SUMMON
								CyInterface().addMessage(pCaster.getOwner(), True, 25, localText.getText("TXT_KEY_MESSAGE_TREANT_ENEMY", ()), 'AS2D_FEATUREGROWTH', 1, 'Art/Interface/Buttons/Units/Treant.dds', ColorTypes(7), newUnit.getX(), newUnit.getY(), True, True)
								CyInterface().addMessage(pPlot.getOwner(), True, 25, localText.getText("TXT_KEY_MESSAGE_TREANT", ()), 'AS2D_FEATUREGROWTH', 1, 'Art/Interface/Buttons/Units/Treant.dds', ColorTypes(8), newUnit.getX(), newUnit.getY(), True, True)


