def onMoveBadbsBlizzard(pCaster, pPlot, bUnitCreation=False):
	if not pCaster.isPromotionImmune(gc.getInfoTypeForString('PROMOTION_SLOW')):
		pCaster.setHasPromotion(gc.getInfoTypeForString('PROMOTION_SLOW'), True)
	if not bUnitCreation :
		bDamage = True
		iWinterborn = gc.getInfoTypeForString('PROMOTION_WINTERBORN')
		if pCaster.getRace() == iWinterborn:
			bDamage = False
		elif pCaster.getReligion() == gc.getInfoTypeForString('RELIGION_WHITE_HAND'):
			if gc.getPlayer(pCaster.getOwner()).getStateReligion() == gc.getInfoTypeForString('RELIGION_WHITE_HAND'):
				bDamage = False
		elif pCaster.getRace() == -1:
			if gc.getUnitInfo(pCaster.getUnitType()).getFreePromotions(iWinterborn):
				bDamage = False
			elif pCaster.isAlive():
				if not pCaster.isAnimal():
					if gc.getCivilizationInfo(pCaster.getCivilizationType()).getDefaultRace() == iWinterborn:
						if not isWorldUnitClass(pCaster.getUnitClassType()):
							if pCaster.getDomainType() == gc.getInfoTypeForString('DOMAIN_LAND'):
								bDamage = False
		if bDamage:
			pCaster.doDamageNoCaster(10, 50, gc.getInfoTypeForString('DAMAGE_COLD'), False)

def onMoveGraveDragonLair(pCaster, pPlot, bUnitCreation=False):
	if not bUnitCreation:
		if not pCaster.isImmortal():
			onMoveDoDamage(pCaster, pPlot, 90, 100, 'DAMAGE_DEATH', False)
			
def onMoveBlizzard(pCaster, pPlot, bUnitCreation=False):
	if not bUnitCreation :
		bDamage = True
		iWinterborn = gc.getInfoTypeForString('PROMOTION_WINTERBORN')
		if pCaster.getRace() == iWinterborn:
			bDamage = False
		elif pCaster.getReligion() == gc.getInfoTypeForString('RELIGION_WHITE_HAND'):
			if gc.getPlayer(pCaster.getOwner()).getStateReligion() == gc.getInfoTypeForString('RELIGION_WHITE_HAND'):
				bDamage = False
		elif pCaster.getRace() == -1:
			if gc.getUnitInfo(pCaster.getUnitType()).getFreePromotions(iWinterborn):
				bDamage = False
			elif pCaster.isAlive():
				if not pCaster.isAnimal():
					if gc.getCivilizationInfo(pCaster.getCivilizationType()).getDefaultRace() == iWinterborn:
						if not isWorldUnitClass(pCaster.getUnitClassType()):
							if pCaster.getDomainType() == gc.getInfoTypeForString('DOMAIN_LAND'):
								bDamage = False
		if bDamage:
			pCaster.doDamageNoCaster(10, 50, gc.getInfoTypeForString('DAMAGE_COLD'), False)

		if pPlot.getNumUnits() == 1 and not pCaster.isFlying() and not pCaster.isAlive():
			if pPlot.isOwned() and pPlot.getTeam() != pCaster.getTeam():
				pPlotPlayer = gc.getPlayer(pPlot.getOwner())
				if pPlotPlayer.isBarbarian() or pPlotPlayer.getStateReligion() == gc.getInfoTypeForString('RELIGION_WHITE_HAND'):
					iChance = gc.getDefineINT('TREANT_SPAWN_CHANCE')
					pCity = CyMap().findCity(pPlot.getX(), pPlot.getY(), pPlot.getOwner(), TeamTypes.NO_TEAM, False, False, TeamTypes.NO_TEAM, DirectionTypes.NO_DIRECTION, pPlotPlayer.getCity(-1))
					if not pCity.isNone():
						for sBuilding in [	'BUILDING_TEMPLE_OF_THE_HAND',
											'BUILDING_NEW_MULYR',
											'BUILDING_TOWER_OF_NECROMANCY'
									]:
							if pCity.getNumBuilding(gc.getInfoTypeForString(sBuilding)) > 0:
								iChance *= 2
					if CyGame().getSorenRandNum(100, "Hollow Man Spawn Chance") < iChance:
						if gc.getTeam(pCaster.getTeam()).isAtWar(pPlotPlayer.getTeam()) or pCaster.isHiddenNationality():
							for i in xrange(pPlot.getNumUnits()):
								p2Unit = pPlot.getUnit(i)
								p2Plot = cf.findClearPlot(p2Unit, -1)
								if p2Plot != -1:
									bActive = pPlot.isPythonActive()
									p2Plot.setPythonActive(False)
									p2Unit.setXY(p2Plot.getX(), p2Plot.getY(), False, True, True)
									p2Unit.changeMoves(-1)
									p2Plot.setPythonActive(bActive)
							if pPlot.getNumUnits() == 0:
								newUnit = pPlotPlayer.initUnit(gc.getInfoTypeForString('UNIT_HOLLOW_MAN'), pPlot.getX(), pPlot.getY(), UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
								newUnit.setDuration(2)
								newUnit.AI_setGroupflag(43)	# 43=GROUPFLAG_SUICIDE_SUMMON
								CyInterface().addMessage(pCaster.getOwner(), True, 25, localText.getText("TXT_KEY_MESSAGE_HOLLOW_MAN_ENEMY", ()), 'AS2D_FEATUREGROWTH', 1, 'Art/Units/Religions/White Hand/Hollow Man/HollowMan.dds', ColorTypes(7), newUnit.getX(), newUnit.getY(), True, True)
								CyInterface().addMessage(pPlot.getOwner(), True, 25, localText.getText("TXT_KEY_MESSAGE_HOLLOW_MAN", ()), 'AS2D_FEATUREGROWTH', 1, 'Art/Interface/Buttons/Units/Treant.dds', ColorTypes(8), newUnit.getX(), newUnit.getY(), True, True)


