def onMoveRestoreMana(pPlot, sBonus):
	iBonus = gc.getInfoTypeForString(sBonus)
	iPlotBonus = pPlot.getBonusType(-1)
	if iPlotBonus != iBonus:
		if iPlotBonus == -1 or not gc.getBonusInfo(iPlotBonus).isMana():
			if not PyHelpers.PyGame().doesBuildingExist(gc.getInfoTypeForString('BUILDING_CRUCIBLE')):
				pPlot.setBonusType(iBonus)

def onMoveSucellus(pCaster, pPlot):
	onMoveRestoreMana(pPlot,'BONUS_MANA_LIFE')

	pCaster.changeDamage(-10, PlayerTypes.NO_PLAYER)
	for sProm in ['PROMOTION_DISEASED', 'PROMOTION_PLAGUED', 'PROMOTION_POISONED', 'PROMOTION_WITHERED', 'PROMOTION_ENRAGED','PROMOTION_BURNING_BLOOD','PROMOTION_PARANOID']:
		pCaster.setHasPromotion(gc.getInfoTypeForString(sProm), False)

def onMoveCarniveansCavern(pCaster, pPlot):
	if pPlot.getNumUnits() < 3:
		if CyGame().getSorenRandNum(( CyGame().getGameTurn() % pCaster.getLevel() ), "Carniveans Cavern") > 5:
			eSpell = gc.getInfoTypeForString('SPELL_EXPLORE_LAIR_CARNIVEANS_CRAG')
			if reqExploreLair(pCaster, eSpell):
				pCaster.cast(eSpell)
	##			spellExploreLairEpic(pCaster, eSpell)
	onMoveRestoreMana(pPlot,'BONUS_MANA_CHAOS')

def onMoveTarch(pCaster, pPlot):
	onMoveRestoreMana(pPlot,'BONUS_MANA_AIR')
	if pPlot.getBonusType(-1) == gc.getInfoTypeForString('BONUS_MANA_AIR'):
		if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_CHANNELING2')):
			pPlot.setPythonActive(False)
		elif not pCaster.isImmuneToMagic():
##			pCaster.finishMoves()
			pCaster.doDamage(5, 50, pCaster, gc.getInfoTypeForString('DAMAGE_LIGHTNING'), False)
			CyEngine().triggerEffect(gc.getInfoTypeForString('EFFECT_MAELSTROM'), pPlot.getPoint())

def onMoveAsmoday(pCaster, pPlot):
	lCurse = [gc.getInfoTypeForString('PROMOTION_PARANOID'),gc.getInfoTypeForString('PROMOTION_CRAZED'), gc.getInfoTypeForString('PROMOTION_ENRAGED'), gc.getInfoTypeForString('PROMOTION_WITHERED'), gc.getInfoTypeForString('PROMOTION_RUSTED'), gc.getInfoTypeForString('PROMOTION_POISONED'), gc.getInfoTypeForString('PROMOTION_DISEASED'), gc.getInfoTypeForString('PROMOTION_PLAGUED'), gc.getInfoTypeForString('PROMOTION_PACT_WITH_SALLOS'), gc.getInfoTypeForString('PROMOTION_UNHOLY_TAINT')]
	for iProm in lCurse:
		if pCaster.isHasPromotion(iProm):
			return False
		if pCaster.isPromotionImmune(iProm):
			lCurse.remove(iProm)
	if len(lCurse) >0:
		iCurse = lCurse[CyGame().getSorenRandNum(len(lCurse), "Asmoday's curse on " + str(pCaster.getName()))]
		pCaster.setHasPromotion(iCurse, True)
		info = gc.getPromotionInfo(iCurse)
		CyInterface().addMessage(pCaster.getOwner(),True, 25, localText.getText("TXT_KEY_MESSAGE_CURSE_GRAVE_OF_ASMODAY", (pCaster.getName(), info.getDescription(),)), 'AS2D_FEATUREGROWTH', 1, info.getButton(), ColorTypes(8), pCaster.getX(), pCaster.getY(), True, True)


def onMoveTormentedSouls(pCaster, pPlot):

	if pPlot.getImprovementType() == gc.getInfoTypeForString('IMPROVEMENT_BRADELINES_WELL'):
		iCurse = gc.getInfoTypeForString('PROMOTION_DEATHPHAGE')
		if not (pCaster.isHasPromotion(iCurse) or pCaster.isPromotionImmune(iCurse)):
			pCaster.setHasPromotion(iCurse, True)


	if pPlot.getNumUnits() == 1:
		if pCaster.isAlive() and not pCaster.isFlying():
			if CyGame().getSorenRandNum(66, "Tormented Souls "+ str(pCaster.getName())) <= 18:
				iPlayer = pCaster.getOwner()
				pPlayer = gc.getPlayer(iPlayer)
				bPlayer = gc.getPlayer(gc.getBARBARIAN_PLAYER())
				eTeam = gc.getTeam(pPlayer.getTeam())
				ibTeam = bPlayer.getTeam()
				if eTeam.isAtWar(ibTeam):
					for i in xrange(pPlot.getNumUnits()):
						p2Unit = pPlot.getUnit(i)
						p2Plot = cf.findClearPlot(p2Unit, -1)
						if p2Plot != -1:
							p2Unit.setXY(p2Plot.getX(), p2Plot.getY(), False, True, True)
							p2Unit.finishMoves()
					if pPlot.getNumUnits() == 0:
						newUnit = bPlayer.initUnit(gc.getInfoTypeForString('UNIT_SPECTRE'), pPlot.getX(), pPlot.getY(), UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
						newUnit.setDuration(3)
						newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_CRAZED'), True)
						newUnit.AI_setGroupflag(43)	# 43=GROUPFLAG_SUICIDE_SUMMON
						CyInterface().addMessage(pCaster.getOwner(), True, 25, localText.getText("TXT_KEY_MESSAGE_SPECTRE_ENEMY", ()), 'AS2D_FEATUREGROWTH', 1, 'Art/Interface/Buttons/Units/Spectre.dds', ColorTypes(7), newUnit.getX(), newUnit.getY(), True, True)

