def postCombatAuricAscendedWon(pCaster, pOpponent):
	pCaster.setDamage(0, -1)
	if pOpponent.isHasPromotion(gc.getInfoTypeForString('PROMOTION_GODSLAYER')):
		pCaster.setHasPromotion(gc.getInfoTypeForString('PROMOTION_AVATAR'), False)
		cf.makeMortal(pCaster)
		pCaster.kill(True, pOpponent.getOwner())
		if pOpponent.isHuman():
			t = "TROPHY_FEAT_GODSLAYER"
			if not CyGame().isHasTrophy(t):
				CyGame().changeTrophyValue(t, 1)
	elif pOpponent.isHasPromotion(gc.getInfoTypeForString('PROMOTION_NETHER_BLADE')):
		pCaster.setHasPromotion(gc.getInfoTypeForString('PROMOTION_NETHERBIND'), True)
		cf.makeMortal(pCaster)
		pCaster.kill(True, pOpponent.getOwner())
	if not pCaster.isImmortal():
		iPlayer = pCaster.getOwner()
		pPlayer = gc.getPlayer(iPlayer)
		if pPlayer.getLeaderType() == gc.getInfoTypeForString('LEADER_AURIC'):
			for iTrait in xrange(gc.getNumTraitInfos()):
				if pPlayer.hasTrait(iTrait):
					pPlayer.setHasTrait(iTrait, False)
		if pOpponent.isHuman():
			sTrophy = "TROPHY_DEFEATED_AURIC"
			if sTrophy != -1:
				if not CyGame().isHasTrophy(sTrophy):
					CyGame().changeTrophyValue(sTrophy, 1)
			if pOpponent.isHasPromotion(gc.getInfoTypeForString('PROMOTION_GODSLAYER')):
				if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_AVATAR')):
					t = "TROPHY_FEAT_GODSLAYER"
					if not CyGame().isHasTrophy(t):
						CyGame().changeTrophyValue(t, 1)

