def postCombatDonal(pCaster, pOpponent):
	if pOpponent.getRace() in [gc.getInfoTypeForString('PROMOTION_DEMON'), gc.getInfoTypeForString('PROMOTION_UNDEAD')]:
		pCaster.setHasPromotion(gc.getInfoTypeForString('PROMOTION_RECRUITER'), True)

def postCombatDullahan(pCaster, pOpponent):
	if pOpponent.isAlive() or pOpponent.getRace() == gc.getInfoTypeForString('PROMOTION_UNDEAD'):
		cf.makeMortal(pOpponent)
	pPlot = pOpponent.plot()
	if pPlot.isCity():
		pCity = pPlot.getPlotCity()
		if pCity.getPopulation() > 1:
			pCity.changePopulation(-1)
			CyInterface().addMessage(pCity.getOwner(), True, 25, localText.getText("TXT_KEY_MESSAGE_POPULATION_REDUCED", ()), '', 1, 'Art/Interface/Buttons/Units/Angel of Death.dds', ColorTypes(7), pCity.getX(), pCity.getY(), True, True)

def postCombatEvangelize(pCaster, pOpponent):
	if not pCaster.isNoCapture():
		pPlot = pOpponent.plot()
		if pPlot.isCity():
			pCity = pPlot.getPlotCity()
			iRel = pCaster.getReligion()
			if not pCity.isHasReligion(iRel):
				if gc.getTeam(pCaster.getTeam()).isAtWar(pCity.getTeam()):
					if CyGame().getSorenRandNum(10, "Violent Evangelism "+ str(pCaster.getName())) < pCaster.getLevel():
						bEvangelize = True
						if pOpponent.isImmortal():
							if pCity.isCapital():
								if pOpponent.getOwner() == pCity.getOwner():
									bEvangelize = False
						if bEvangelize:
							for i in xrange(pPlot.getNumUnits()):
								pUnit = pPlot.getUnit(i)
								if not pUnit.isDelayedDeath():
									if pUnit.canDefend(pPlot):
										bEvangelize = False
										break
						if bEvangelize:
							pCity.setHasReligion(iRel, True, False, False)

def postCombatExplode(pCaster, pOpponent):
	iForest = gc.getInfoTypeForString('FEATURE_FOREST')
	iForestN = gc.getInfoTypeForString('FEATURE_FOREST_NEW')
	iJungle = gc.getInfoTypeForString('FEATURE_JUNGLE')
	iSmoke = gc.getInfoTypeForString('IMPROVEMENT_SMOKE')
	iFire = gc.getInfoTypeForString('DAMAGE_FIRE')
	iChance = gc.getDefineINT('FLAMES_SPREAD_CHANCE')
	iX = pCaster.getX()
	iY = pCaster.getY()
	for iDirection in xrange(DirectionTypes.NUM_DIRECTION_TYPES):
		pPlot = plotDirection(iX, iY, DirectionTypes(iDirection))
		if pPlot.isNone():continue
		if pPlot.getFeatureType() in [iForest, iJungle, iForestN]:
			if CyGame().getSorenRandNum(100, "Flames Spread from " + str(pCaster.getName())) < iChance:
				bValid = True
				iImprovement = pPlot.getImprovementType()
				if iImprovement != -1 :
					if gc.getImprovementInfo(iImprovement).isPermanent() :
						bValid = False
				if bValid:
					pPlot.setImprovementType(iSmoke)
		for i in xrange(pPlot.getNumUnits()):
			pUnit = pPlot.getUnit(i)
			pUnit.doDamage(10, 99, pCaster, iFire, False)

def postCombatHealSelf(pCaster, iAmount):
	if not pCaster.isDelayedDeath():
		if pCaster.getDamage() > 0:
			pCaster.changeDamage(-iAmount, PlayerTypes.NO_PLAYER)
		if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_AVATAR')):
			if not pCaster.isImmortal():
				pCaster.changeImmortal(1)

def postCombatIra(pCaster, pOpponent):
	if pOpponent.isHasPromotion(gc.getInfoTypeForString('PROMOTION_AFFINITY_SPIRIT')) or pOpponent.isHasPromotion(gc.getInfoTypeForString('PROMOTION_SPIRIT3')):
		pCaster.setBaseCombatStr((pCaster.baseCombatStr() - pCaster.getTotalDamageTypeCombat())//2)
		pCaster.setBaseCombatStrDefense((pCaster.baseCombatStrDefense() - pCaster.getTotalDamageTypeCombat())//2)
	elif pOpponent.isAlive():
		if pCaster.baseCombatStr() < 36:
			pCaster.setBaseCombatStr(pCaster.baseCombatStr() - pCaster.getTotalDamageTypeCombat() + 1)
			pCaster.setBaseCombatStrDefense(pCaster.baseCombatStrDefense() - pCaster.getTotalDamageTypeCombat() + 1)

