def postCombatLostMerchant(pCaster, pOpponent):
	info = gc.getUnitInfo(pCaster.getUnitType())
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iPlayerO = pOpponent.getOwner()
	pPlayerO = gc.getPlayer(iPlayerO)
	iTradeGoods = CyGame().getSorenRandNum(info.getBaseTrade(), "Merchant base" + str(pCaster.getName()) + " Raided by " + str(pOpponent.getName()))
	pCity = CyMap().findCity(pCaster.getX(), pCaster.getY(), iPlayer, TeamTypes.NO_TEAM, False, pCaster.getDomainType() == gc.getInfoTypeForString('DOMAIN_SEA'), TeamTypes.NO_TEAM, DirectionTypes.NO_DIRECTION, pPlayer.getCity(-1))
	pCityO = CyMap().findCity(pCaster.getX(), pCaster.getY(), iPlayerO, TeamTypes.NO_TEAM, False, pCaster.getDomainType() == gc.getInfoTypeForString('DOMAIN_SEA'), TeamTypes.NO_TEAM, DirectionTypes.NO_DIRECTION, pPlayerO.getCity(-1))
	if pCity.isNone():
		pCity = pPlayer.getCapitalCity()
	if pCityO.isNone():
		pCityO = pPlayerO.getCapitalCity()
	if not (pCity.isNone() or pCityO.isNone()):
		iProfit = pCity.calculateTradeProfit(pCityO) * info.getTradeMultiplier()/4
		if iProfit > 0:
			iTradeGoods += CyGame().getSorenRandNum(iProfit, "Merchant modifier" + str(pCaster.getName()) + " Raided by " + str(pOpponent.getName()))
	if iTradeGoods > 0:
		pPlayerO.changeGold(iTradeGoods)
		CyInterface().addMessage(iPlayerO, True, 25, localText.getText("TXT_KEY_MESSAGE_GOLD_FROM_COMBAT", (iTradeGoods,)), '', 1, info.getButton(), ColorTypes(8), pCaster.getX(), pCaster.getY(), True, True)


def postCombatOdioRage(pCaster):
	iSpell = gc.getInfoTypeForString(gc.getInfoTypeForString('SPELL_RAGE'))
	pCaster.cast(iSpell)



def postCombatSplit(pCaster, pOpponent):
	if not pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_WEAK')):
		if not (pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_DEMON')) and (pOpponent.isHasPromotion(gc.getInfoTypeForString('PROMOTION_ANGELORUM_CAVEA')) or pOpponent.isHasPromotion(gc.getInfoTypeForString('PROMOTION_CUSTOS_JUDICII')))):
			iPlayer = pCaster.getOwner()
			pPlayer = gc.getPlayer(iPlayer)
			iUnit = pCaster.getUnitType()
			for i in xrange(2):
				newUnit = pPlayer.initUnit(iUnit, pCaster.getX(), pCaster.getY(), UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
				newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_STRONG'), False)
				newUnit.setDamage(25, -1)
				if not pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_STRONG')):
					newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_WEAK'), True)
				newUnit.setDuration(pCaster.getDuration())

				iRace = pCaster.getRace()
				if iRace !=-1:
					newUnit.setHasPromotion(iRace, True)
				if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_LAIR_GUARDIAN')):
					newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_LAIR_GUARDIAN'), True)
				if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_HIDDEN_NATIONALITY')):
					newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_HIDDEN_NATIONALITY'), True)
				if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_MOBILITY2')):
					newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_MOBILITY1'), True)


			CyInterface().addMessage(pCaster.getOwner(), True, 25, localText.getText("TXT_KEY_MESSAGE_SPLIT", ()), '', 1, gc.getUnitInfo(iUnit).getButton(), ColorTypes(7), pCaster.getX(), pCaster.getY(), True, True)

def postCombatStephanos(pCaster, pOpponent):
	if pOpponent.isHuman():
		t = "TROPHY_DEFEATED_STEPHANOS"
		if not CyGame().isHasTrophy(t):
			CyGame().changeTrophyValue(t, 1)

def postCombatWolfRider(pCaster, pOpponent):
	if pOpponent.getUnitType() in [gc.getInfoTypeForString('UNIT_WOLF'), gc.getInfoTypeForString('UNIT_WOLF_PACK')]:
		
		iPlayer = pCaster.getOwner()
		pPlayer = gc.getPlayer(iPlayer)
		if pOpponent.plot().getNumVisibleEnemyDefenders(pCaster) > 1:
			newUnit = pPlayer.initUnit(gc.getInfoTypeForString('UNIT_WOLF_RIDER'), pCaster.getX(), pCaster.getY(), UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
			CyInterface().addMessage(pCaster.getOwner(), True, 25, localText.getText("TXT_KEY_MESSAGE_WOLF_RIDER", ()), '', 1, 'Art/Interface/Buttons/Units/Wolf Rider.dds', ColorTypes(8), pCaster.getX(), pCaster.getY(), True, True)
		else:
			newUnit = pPlayer.initUnit(gc.getInfoTypeForString('UNIT_WOLF_RIDER'), pOpponent.getX(), pOpponent.getY(), UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
			CyInterface().addMessage(pCaster.getOwner(), True, 25, localText.getText("TXT_KEY_MESSAGE_WOLF_RIDER", ()), '', 1, 'Art/Interface/Buttons/Units/Wolf Rider.dds', ColorTypes(8), newUnit.getX(), newUnit.getY(), True, True)
		newUnit.convert(pCaster)

def postCombatValinSaverous(pCaster, pOpponent):
	if pOpponent.getUnitType() == gc.getInfoTypeForString('UNIT_SAVEROUS'):
		pOpponent.setHasPromotion(gc.getInfoTypeForString('PROMOTION_DARK_REFLECTION'), True)
		cf.makeMortal(pOpponent)
		iPlayer = pCaster.getOwner()
		pPlayer = gc.getPlayer(iPlayer)
		iUnit = gc.getInfoTypeForString('UNIT_SQUIRE_SAVEROUS')
		newUnit = pPlayer.initUnit(iUnit, pCaster.getX(), pCaster.getY(), UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
		for i in xrange(gc.getNumPromotionInfos()):
			newUnit.setHasPromotion(i, pOpponent.isHasPromotion(i))
			if gc.getPromotionInfo(i).isEquipment():
				newUnit.setHasPromotion(i, False)
		newUnit.setDamage(pOpponent.getDamage()/2, pCaster.getOwner())
		newUnit.setLevel(pOpponent.getLevel())
		newUnit.setExperience(pOpponent.getExperience(), -1)
		newUnit.setReligion(gc.getInfoTypeForString('RELIGION_RUNES_OF_KILMORPH'))
		newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_LOYALTY'), True)
		for sProm in [	'PROMOTION_DEMON',
						'PROMOTION_POSSESSED',
						'PROMOTION_UNHOLY_TAINT',
						'PROMOTION_DARK_REFLECTION',
						'PROMOTION_CRAZED',
						'PROMOTION_ENRAGED',
						'PROMOTION_REBEL'
						]:
			newUnit.setHasPromotion(gc.getInfoTypeForString(sProm), False)

