def reqDamageUnits(pCaster, eSpell, sDamageType = 'DAMAGE_PHYSICAL', iRange = 1, iDamage = 0, iDamageLimit = 99):
	iDamageType = gc.getInfoTypeForString(sDamageType)
	lTargets = []
	iX = pCaster.getX()
	iY = pCaster.getY()
	for iiX in xrange(iX-iRange, iX+ 1+ iRange, 1):
		for iiY in xrange(iY-iRange, iY+ 1+ iRange, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if not pPlot.isNone():
				if not pPlot.at(iX, iY):
					if plotDistance(iX, iY, iiX, iiY) > iRange:continue
					for i in xrange(pPlot.getNumUnits()):
						pUnit = pPlot.getUnit(i)
						if pUnit.isImmuneToSpell(pCaster, eSpell):continue
						if pUnit.getDamageTypeResist(iDamageType) >= 100:continue
						if pUnit.getDamage() < iDamageLimit:
							return True
	return False

def helpDamageUnits(lpUnits, eSpell, sDamageType = 'DAMAGE_PHYSICAL', iRange = 1, iDamage = 0, iDamageLimit = 99,bImmuneTeam=True, bImmuneNeutral=True, bImmuneEnemy=False,bImmuneFlying=False, bImmuneNotAlive=False):
	szBuffer = ''
	iDamageType = gc.getInfoTypeForString(sDamageType)
	pCaster = lpUnits[0]
	iTeam = pCaster.getTeam()
	eTeam = gc.getTeam(iTeam)
	lTargets = []
	iX = pCaster.getX()
	iY = pCaster.getY()
	iTeam = pCaster.getTeam()
	for pCaster in lpUnits:
		if pCaster.canCast(eSpell, True):
			for iiX in xrange(iX-iRange, iX + iRange+1, 1):
				for iiY in xrange(iY-iRange, iY+ iRange+1, 1):
					pPlot = CyMap().plot(iiX, iiY)
					if pPlot.isNone():continue
					if pPlot.at(iX, iY):continue
					if plotDistance(iX, iY, iiX, iiY) > iRange:continue
					for i in xrange(pPlot.getNumUnits()):
						pUnit = pPlot.getUnit(i)
						if pUnit.isImmuneToSpell(pCaster, eSpell):continue
						if iTeam == pUnit.getTeam():
							if bImmuneTeam:
								continue
						elif eTeam.isAtWar(pUnit.getTeam()) or pUnit.isHiddenNationality() or pCaster.isHiddenNationality():
							if bImmuneEnemy:
								continue
						elif bImmuneNeutral:
							continue
						if bImmuneFlying:
							if pUnit.isFlying():
								continue
						if bImmuneNotAlive:
							if not pUnit.isAlive():
								continue
						# if pUnit.isInvisible(iTeam, False):
							# continue
						if pUnit.getDamageTypeResist(iDamageType) >= 100:
							continue
						if pUnit.getDamage() < iDamageLimit:
							lTargets.append(pUnit)
							continue
	lTargets = list(set(lTargets))
	iCount = len(lTargets)
	if iCount > 0:
		szBuffer += '\n' + localText.getText("TXT_KEY_SPELL_DAMAGE", (iDamage, iDamageLimit, ))
		if iCount == 1:
			pUnit = lTargets.pop(0)
			pPlayer = gc.getPlayer(pUnit.getOwner())
			if pPlayer != -1:
				sList = cf.getNameWithColorScheme(pUnit, pUnit.isInvisible(pCaster.getTeam(), False))
				szBuffer += localText.getText("TXT_KEY_HELP_SPELL_TARGETS_THIS", ( sList, ))
		elif iCount > 0:
			sList = ''
			while len(lTargets) > 0:
				pUnit = lTargets.pop(0)
				pPlayer = gc.getPlayer(pUnit.getOwner())
				if pPlayer != -1:
					sList += cf.getNameWithColorScheme(pUnit, pUnit.isInvisible(pCaster.getTeam(), False))
					if len(lTargets) > 0:
						if len(lTargets) == 1:
							sList += " and "
						else:
							sList += ", "
			szBuffer += localText.getText("TXT_KEY_HELP_SPELL_TARGETS_THESE_COUNT_LIST", (iCount, sList, ))
	return szBuffer

def helpTogglePromotions(lpUnits, eSpell, lsAddProms, lsRemoveProms, iRange=0, bResistable=False):
	szBuffer = ''
	pCaster = lpUnits[0]
	iTeam = pCaster.getTeam()
	iX = pCaster.getX()
	iY = pCaster.getY()
	sAdd = localText.getText("TXT_KEY_HELP_SPELL_ADDS", ())
	sRemove = localText.getText("TXT_KEY_HELP_SPELL_REMOVES", ())
	if bResistable:
		sAdd = localText.getText("TXT_KEY_HELP_SPELL_MAY_ADD", ())
		sRemove = localText.getText("TXT_KEY_HELP_SPELL_MAY_REMOVE", ())
	lProms = []
	for sProm in lsAddProms:
		lTargets = []
		iProm = gc.getInfoTypeForString(sProm)
		info = gc.getPromotionInfo(iProm)
		for iiX in xrange(iX-iRange, iX+ 1+ iRange, 1):
			for iiY in xrange(iY-iRange, iY+ 1+ iRange, 1):
				pPlot = CyMap().plot(iiX, iiY)
				if pPlot.isNone():continue
				for i in xrange(pPlot.getNumUnits()):
					pUnit = pPlot.getUnit(i)
					if pUnit.isDelayedDeath():continue
					if pUnit.isHasPromotion(iProm):continue
					if pUnit.isPromotionImmune(iProm):continue
					if pUnit.isImmuneToSpell(pCaster, eSpell):continue
					# if pUnit.isInvisible(iTeam, False):continue
					if pUnit.getUnitCombatType() == -1:continue
					if info.getUnitCombat(pUnit.getUnitCombatType()):
						lTargets.append(pUnit)
						continue
		lTargets = list(set(lTargets))
		iCount = len(lTargets)
		if iCount > 0:
			szBuffer += sAdd + CyGameTextMgr().getPromotionHelp(iProm, False)
			if iCount == 1:
				pUnit = lTargets.pop(0)
				iPlayer = pUnit.getOwner()
				if iPlayer != -1:
					pPlayer = gc.getPlayer(iPlayer)
					sList = cf.getNameWithColorScheme(pUnit, pUnit.isInvisible(pCaster.getTeam(), False))
					szBuffer += localText.getText("TXT_KEY_HELP_SPELL_TARGETS_THIS", (sList, ))
			else:
				sList = ''
				while len(lTargets) > 0:
					pUnit = lTargets.pop(0)
					iPlayer = pUnit.getOwner()
					if iPlayer != -1:
						pPlayer = gc.getPlayer(iPlayer)
						sList += cf.getNameWithColorScheme(pUnit, pUnit.isInvisible(pCaster.getTeam(), False))
##						szBuffer += localText.getText("TXT_KEY_HELP_SPELL_TARGETS_THIS", (sList, ))
						if len(lTargets) > 0:
							if len(lTargets) == 1:
								sList += " and "
							else:
								sList += ", "
				szBuffer += localText.getText("TXT_KEY_HELP_SPELL_TARGETS_THESE_COUNT_LIST", (iCount, sList, ))
	lProms = []
	for sProm in lsRemoveProms:
		lTargets = []
		iProm = gc.getInfoTypeForString(sProm)
		info = gc.getPromotionInfo(iProm)
		for iiX in xrange(iX-iRange, iX+ 1+ iRange, 1):
			for iiY in xrange(iY-iRange, iY+ 1+ iRange, 1):
				pPlot = CyMap().plot(iiX, iiY)
				if pPlot.isNone():continue
				for i in xrange(pPlot.getNumUnits()):
					pUnit = pPlot.getUnit(i)
					if pUnit.isHasPromotion(iProm):
						if pUnit.isImmuneToSpell(pCaster, eSpell):continue
						# if pUnit.isInvisible(iTeam, False):continue
						lTargets.append(pUnit)
						continue
		lTargets = list(set(lTargets))
		iCount = len(lTargets)
		if iCount > 0:
			szBuffer += sRemove + CyGameTextMgr().getPromotionHelp(iProm, False)
			if iCount == 1:
				pUnit = lTargets.pop(0)
				iPlayer = pUnit.getOwner()
				if iPlayer != -1:
					pPlayer = gc.getPlayer(iPlayer)
					sList = cf.getNameWithColorScheme(pUnit, pUnit.isInvisible(pCaster.getTeam(), False))
					szBuffer += localText.getText("TXT_KEY_HELP_SPELL_TARGETS_THIS", (sList, ))
			else:
				sList = ''
				while len(lTargets) > 0:
					pUnit = lTargets.pop(0)
					iPlayer = pUnit.getOwner()
					if iPlayer != -1:
						pPlayer = gc.getPlayer(iPlayer)
						sList += cf.getNameWithColorScheme(pUnit, pUnit.isInvisible(pCaster.getTeam(), False))
						if len(lTargets) > 0:
							if len(lTargets) == 1:
								sList += " and "
							else:
								sList += ", "
				szBuffer += localText.getText("TXT_KEY_HELP_SPELL_TARGETS_THESE_COUNT_LIST", (iCount, sList, ))
	return szBuffer

