def reqAddToWolfPack(pCaster, eSpell=-1):
	iPlayer = pCaster.getOwner()
	pPlot = pCaster.plot()
	iWolfPack = gc.getInfoTypeForString('UNIT_WOLF_PACK')
	iEmpower5 = gc.getInfoTypeForString('PROMOTION_EMPOWER5')
	if not pCaster.isHuman():
		if pCaster.baseCombatStr() > 2:
			return False
	for i in xrange(pPlot.getNumUnits()):
		pUnit = pPlot.getUnit(i)
		if pUnit.getUnitType() == iWolfPack:
			if pUnit.getOwner() == iPlayer:
				if not pUnit.isHasPromotion(iEmpower5):
					return True
	return False

def spellAddToCity(pCaster, eSpell=-1):
	pPlot = pCaster.plot()
	if pPlot.isCity():
		pCity = pPlot.getPlotCity()
		pCity.changeProduction(pCaster.getExperience())
		pCity.changeCulture(pCaster.getOwner(), pCaster.getExperience(), True)
		iRel = pCaster.getReligion()
		if iRel != -1:
			if CyGame().isReligionFounded(iRel):
				pCity.setHasReligion(iRel, True, False, False)
		if pCaster.getUnitType() == gc.getInfoTypeForString('UNIT_MANES'):
			if pCity.getNumBuilding(gc.getInfoTypeForString('BUILDING_DEMONIC_CITIZENS')) < 1:
				pCity.setNumRealBuilding(gc.getInfoTypeForString('BUILDING_DEMONIC_CITIZENS'), 1)

def reqAddToCity(pCaster, eSpell=-1):
	if pCaster.isHuman():
		return True
	if gc.getGame().isOption(GameOptionTypes.GAMEOPTION_ONE_CITY_CHALLENGE):
		return True
	if pCaster.getUnitType() == gc.getInfoTypeForString('UNIT_REFUGEE'):
		return True
	if pCaster.getUnitType() == gc.getInfoTypeForString('UNIT_MANES'):
		return True
	if pCaster.getUnitType() == gc.getInfoTypeForString('UNIT_SETTLER'):
		iPlayer = pCaster.getOwner()
		pPlayer = gc.getPlayer(iPlayer)
		if pPlayer.getUnitClassCount(gc.getInfoTypeForString('UNITCLASS_SETTLER')) < 3:
			return False
		if pPlayer.getUnitClassCount(gc.getInfoTypeForString('UNITCLASS_SETTLER')) > 7:
			return True
		if pPlayer.hasTrait(gc.getInfoTypeForString('TRAIT_FALLOW')):
			return True
		if pPlayer.hasTrait(gc.getInfoTypeForString('TRAIT_SPRAWLING')):
			pPlot = pCaster.plot()
			if pPlot.isCity():
				pCity = pPlot.getPlotCity()
				if pCity.isSettlement():
					return False
				if pPlayer.getMaxCities() <= pPlayer.getNumCities():
					return True
	return False

def helpAddToCity(lpUnits, eSpell=-1):
	szBuffer = ''
	pCaster = lpUnits[0]
	pPlot = pCaster.plot()
	if pPlot.isCity():
		pCity = pPlot.getPlotCity()
		iPlayer = pCaster.getOwner()
		if pCity.getOwner() == iPlayer:
			pPlayer = gc.getPlayer(iPlayer)
			sNameCity = "<color=%d,%d,%d,%d>%s</color>" %(pPlayer.getPlayerTextColorR(), pPlayer.getPlayerTextColorG(), pPlayer.getPlayerTextColorB(), pPlayer.getPlayerTextColorA(), pCity.getName() )
			iPop = pCity.getPopulation()
			iXP = 0
			lReligions = []
			bDemonicCitizens = False
			iDemonicCitizens = gc.getInfoTypeForString('BUILDING_DEMONIC_CITIZENS')
			iDemon = gc.getInfoTypeForString('PROMOTION_DEMON')

			for pCaster in lpUnits:
				if pCaster.canCast(eSpell, True):
					iPop += 1
					iXP += pCaster.getExperience()
					iRel = pCaster.getReligion()
					if iRel != -1:
						if not pCity.isHasReligion(iRel):
							if CyGame().isReligionFounded(iRel):
								lReligions.append(pCaster.getReligion())

					if pCity.getNumBuilding(iDemonicCitizens) < 1 and pCaster.getRace() == iDemon:
						bDemonicCitizens = True

			szBuffer += localText.getText("TXT_KEY_HELP_SPELL_NEW_POP", (sNameCity, iPop, ))
			if iXP > 0:
				szBuffer += localText.getText("TXT_KEY_HELP_SPELL_CHANGE_PRODUCTION", (iXP, ))
				szBuffer += localText.getText("TXT_KEY_HELP_SPELL_CHANGE_CULTURE", (iXP, ))
			lReligions = list(set(lReligions))
			for iRel in lReligions:
				szBuffer += '\n' + localText.getText("TXT_KEY_SPELL_SPREAD_RELIGION", (gc.getReligionInfo(iRel).getDescription(), ))
				szBuffer += u"%c" %(gc.getReligionInfo(iRel).getChar())
			if bDemonicCitizens:
				szBuffer += '\n' + localText.getText("TXT_KEY_SPELL_CREATE_BUILDING", (gc.getBuildingInfo(iDemonicCitizens).getDescription(), ))
				szBuffer += helpToggleBuildings(lpUnits, ['BUILDING_DEMONIC_CITIZENS'], [])
	return szBuffer

def spellAddToWolfPack(pCaster, eSpell=-1):
	pPlot = pCaster.plot()
	iWolfPack = gc.getInfoTypeForString('UNIT_WOLF_PACK')
	lEmpower = [	gc.getInfoTypeForString('PROMOTION_COMBAT1'),
			gc.getInfoTypeForString('PROMOTION_COMBAT2'),
			gc.getInfoTypeForString('PROMOTION_COMBAT3'),
			gc.getInfoTypeForString('PROMOTION_COMBAT4'),
			gc.getInfoTypeForString('PROMOTION_COMBAT5')]
	bValid = True
	for i in xrange(pPlot.getNumUnits()):
		if bValid:
			pUnit = pPlot.getUnit(i)
			if pUnit.getUnitType() == iWolfPack:
				if pUnit.getOwner() == pCaster.getOwner():
					for iProm in lEmpower:
						if not pUnit.isHasPromotion(iProm):
							pUnit.setHasPromotion(iProm, True)
							bValid = False
							break

def reqApostacy(pCaster, eSpell=-1):
	if pCaster.getReligion() in [-1, gc.getInfoTypeForString('RELIGION_MATRONAE')]:
		return False
	return True

def reqArcaneLacuna(pCaster, eSpell=-1):
	iCount = 0
	for iBonus in xrange (gc.getNumBonusInfos()):
		if gc.getBonusInfo(iBonus).isMana():
			iCount += CyMap().getNumBonuses(iBonus)
	if iCount == 0:
		return False
	if not pCaster.isHuman():
		if iCount < 7:
			return False
		iTeam = pCaster.getTeam()
		eTeam = gc.getTeam(iTeam)
		if eTeam.getAtWarCount(True) < 1:
			return False
	return True

def helpArcaneLacuna(lpUnits, eSpell=-1):
	szBuffer = ''
	pPlayer = gc.getPlayer(lpUnits[0].getOwner())
	iCount = 0
	for iBonus in xrange (gc.getNumBonusInfos()):
		if gc.getBonusInfo(iBonus).isMana():
			iCount += pPlayer.getNumAvailableBonuses(iBonus)
	iBaseDelay = iCount
	iDelay = (iBaseDelay * gc.getGameSpeedInfo(CyGame().getGameSpeedType()).getVictoryDelayPercent()) / 50
	szBuffer += localText.getText("TXT_KEY_HELP_SPELL_ARCANE_LACUNA", (iCount, iDelay, ))
	return szBuffer

def spellArcaneLacuna(pCaster, eSpell=-1):
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iCount = 0
	for iBonus in xrange (gc.getNumBonusInfos()):
		if gc.getBonusInfo(iBonus).isMana():
			iCount += pPlayer.getNumAvailableBonuses(iBonus)
	iAdept = gc.getInfoTypeForString('UNITCOMBAT_ADEPT')
	for loopUnit in PyPlayer(iPlayer).getUnitList():
		if loopUnit.getUnitCombatType() == iAdept:
			loopUnit.changeExperience(iCount, -1, False, False, False)
	iBaseDelay = iCount
	iDelay = (iBaseDelay * gc.getGameSpeedInfo(CyGame().getGameSpeedType()).getVictoryDelayPercent()) / 50
	iTeam = pCaster.getTeam()
	eTeam = gc.getTeam(iTeam)
	for iPlayer2 in xrange(gc.getMAX_PLAYERS()):
		pPlayer2 = gc.getPlayer(iPlayer2)
		if pPlayer2.isAlive():
			iTeam2 = pPlayer2.getTeam()
			if iTeam != iTeam2:
				if eTeam.isAtWar(iTeam2):
					pPlayer2.changeDisableSpellcasting(iDelay)

def reqArdor(pCaster, eSpell=-1):
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	if pPlayer.getGreatPeopleCreated() == 0:
		return False
	if not pPlayer.isHuman():
		if pPlayer.getGreatPeopleCreated() < 6:
			return False
	return True

def spellArdor(pCaster, eSpell=-1):
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	pPlayer.setGreatPeopleCreated(0)
	pPlayer.setGreatPeopleThresholdModifier(0)

def reqArenaBattle(pCaster, eSpell=-1):

	if pCaster.isHuman():
		if pCaster.getUnitCombatType() in [gc.getInfoTypeForString('UNITCOMBAT_MELEE'), gc.getInfoTypeForString('UNITCOMBAT_RECON')]:
			return True
		if pCaster.getUnitClassType() == gc.getInfoTypeForString('UNITCLASS_SLAVE'):
			return True
	else:
		if pCaster.getUnitClassType() == gc.getInfoTypeForString('UNITCLASS_SLAVE'):
			return True
		if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_ASPECT_OF_WAR')):
			return True
		elif isWorldUnitClass(pCaster.getUnitClassType()):
			return False
		if pCaster.getLevel() > 3:
			return False
		if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_WEAK')):
			if pCaster.getUnitCombatType() in [gc.getInfoTypeForString('UNITCOMBAT_MELEE'), gc.getInfoTypeForString('UNITCOMBAT_RECON')]:
				return True
	return False

def spellArenaBattle(pCaster, eSpell=-1):
	pCity = pCaster.plot().getPlotCity()
	pCity.changeHappinessTimer(3)
	sName = cf.getNameWithColorScheme(pCaster)
	
	
	if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_ASPECT_OF_WAR')) or CyGame().getSorenRandNum(100, "Arena Battle " + str(pCaster.getName()) ) < 50:
		pCaster.changeExperience(CyGame().getSorenRandNum(6, "Arena Battle " + str(pCaster.getName()) ) + 1, -1, False, False, False)
		pCaster.setDamage(25, pCaster.getOwner())
		CyInterface().addMessage(pCaster.getOwner(), True, 25, localText.getText("TXT_KEY_MESSAGE_ARENA_WIN", (sName,)), '', 1, 'Art/Interface/Buttons/Buildings/Arena.dds', ColorTypes(8), pCaster.getX(), pCaster.getY(), True, True)
		if pCaster.getUnitClassType() == gc.getInfoTypeForString('UNITCLASS_SLAVE'):
			iPlayer = pCaster.getOwner()
			pPlayer = gc.getPlayer(iPlayer)
			newUnit = pPlayer.initUnit(gc.getInfoTypeForString('UNIT_WARRIOR'), pCaster.getX(), pCaster.getY(), UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
			newUnit.convert(pCaster)
	else:
		CyInterface().addMessage(pCaster.getOwner(), True, 25, localText.getText("TXT_KEY_MESSAGE_ARENA_LOSE", (sName,)), '', 1, 'Art/Interface/Buttons/Buildings/Arena.dds', ColorTypes(7), pCaster.getX(), pCaster.getY(), True, True)
		pCaster.kill(True, PlayerTypes.NO_PLAYER)


def spellAssuage(pCaster, eSpell=-1):

	iStatius = gc.getInfoTypeForString('PROMOTION_PACT_WITH_STATIUS')

	bAffinity = pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_AFFINITY_SPIRIT'))
	iHallowedGround = gc.getInfoTypeForString('FEATURE_HALLOWED_GROUND')
	iTormentedSouls = gc.getInfoTypeForString('FEATURE_TORMENTED_SOULS')
	iDamage = gc.getInfoTypeForString('DAMAGE_HOLY')
	if pCaster.isHasPromotion(gc.getInfoTypeForString('DAMAGE_HOLY')):
		iDamage = gc.getInfoTypeForString('DAMAGE_UNHOLY')
	lVulnerableUnits = [	gc.getInfoTypeForString('UNIT_WRATH'),
				gc.getInfoTypeForString('UNIT_ODIO'),
				gc.getInfoTypeForString('UNIT_CHAOS_MARAUDER'),
				gc.getInfoTypeForString('UNIT_PIT_BEAST'),
				gc.getInfoTypeForString('UNIT_IRA')
				]
	lRemoveProms = [	gc.getInfoTypeForString('PROMOTION_REBEL'),
						gc.getInfoTypeForString('PROMOTION_CRAZED'),
						gc.getInfoTypeForString('PROMOTION_ENRAGED'),
						gc.getInfoTypeForString('PROMOTION_BURNING_BLOOD'),
						gc.getInfoTypeForString('PROMOTION_PARANOID')
						]
	iDuin = gc.getInfoTypeForString('UNIT_DUIN')
	iWerewolf = gc.getInfoTypeForString('PROMOTION_WEREWOLF')
	iRavenous = gc.getInfoTypeForString('PROMOTION_RAVENOUS')
	iVampire = gc.getInfoTypeForString('PROMOTION_VAMPIRE')
	iBlockMagic = gc.getInfoTypeForString('PROMOTION_CANNOT_CAST')
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iX = pCaster.getX()
	iY = pCaster.getY()
	for iiX in xrange(iX-2, iX+ 3, 1):
		for iiY in xrange(iY-2, iY+ 3, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			if pPlot.getFeatureType() == iTormentedSouls:
				iTimer = pPlot.getTempFeatureTimer()
				if iTimer < 1:
					pPlot.setFeatureType(iHallowedGround, 0)
				else:
					pPlot.setTempFeatureType(iHallowedGround, 0, iTimer)
			for iUnit in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(iUnit)
				if pUnit.isImmuneToMagic():continue
				if pUnit.isHasPromotion(iStatius):continue
				iUnit = pUnit.getUnitType()
				if iUnit in lVulnerableUnits:
					if bAffinity:
						pUnit.doDamage(75, 100, pCaster, iDamage, False)
					else:
						pUnit.doDamage(50, 95, pCaster, iDamage, False)
				elif pUnit.isAlive():
					if pUnit.isHasPromotion(iWerewolf) and not iUnit == iDuin:
						if not effectResisted(pUnit, pCaster, eSpell):
							pUnit.setHasPromotion(iWerewolf, False)
							pUnit.setHasPromotion(iBlockMagic, False)
							iUnit = pUnit.getScenarioCounter()
							if -1 < iUnit < gc.getNumUnitInfos():
								iPlayerU = pUnit.getOwner()
								pPlayerU = gc.getPlayer(iPlayerU)
								sName = cf.getNameWithColorScheme(pUnit, pUnit.isInvisible(pCaster.getTeam(), False))
								CyInterface().addMessage(iPlayerU, True, 25, localText.getText("TXT_KEY_MESSAGE_POOL_OF_TEARS_LYCANTHROPY", (sName, )), 'AS2D_FEATUREGROWTH', 1, 'Art/Interface/Buttons/Improvements/Pool of Tears.dds', ColorTypes(7), iX, iY, True, True)
								CyInterface().addMessage(iPlayer, True, 25, localText.getText("TXT_KEY_MESSAGE_POOL_OF_TEARS_LYCANTHROPY", (sName, )), 'AS2D_FEATUREGROWTH', 1, 'Art/Interface/Buttons/Improvements/Pool of Tears.dds', ColorTypes(8), iX, iY, True, True)
								newUnit = pPlayer.initUnit(iUnit, iX, iY, UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
								cf.removeAffinities(newUnit)
								newUnit.convert(pUnit)
								if not pUnit.isHasPromotion(iVampire):
									pUnit.setHasPromotion(iRavenous, False)
							else:
								pUnit.kill(True, -1)
					else:
						bValid = False
						for iProm in lRemoveProms:
							if pUnit.isHasPromotion(iProm):
								bValid = True
								break
						if bValid:
							if not effectResisted(pUnit, pCaster, eSpell):
								for iProm in lRemoveProms:
									pUnit.setHasPromotion(iProm, False)

def helpAssuage(lpUnits, eSpell=-1):
	szBuffer = ''
	pCaster = lpUnits[0]
	iTeam = pCaster.getTeam()
	lTargets= []
	lVulnerableUnits = [	gc.getInfoTypeForString('UNIT_WRATH'),
				gc.getInfoTypeForString('UNIT_ODIO'),
				gc.getInfoTypeForString('UNIT_CHAOS_MARAUDER'),
				gc.getInfoTypeForString('UNIT_PIT_BEAST'),
				gc.getInfoTypeForString('UNIT_IRA')
				]
	iDuin = gc.getInfoTypeForString('UNIT_DUIN')
	iWerewolf = gc.getInfoTypeForString('PROMOTION_WEREWOLF')
	iHallowedGround = gc.getInfoTypeForString('FEATURE_HALLOWED_GROUND')
	iStatius = gc.getInfoTypeForString('PROMOTION_PACT_WITH_STATIUS')

	iTormentedSouls = gc.getInfoTypeForString('FEATURE_TORMENTED_SOULS')
	bTormented = False
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iX = pCaster.getX()
	iY = pCaster.getY()
	for iiX in xrange(iX-2, iX+ 3, 1):
		for iiY in xrange(iY-2, iY+ 3, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if not pPlot.isNone():
				if pPlot.getFeatureType() == iTormentedSouls:
					bTormented = True
					szBuffer += localText.getText("TXT_KEY_HELP_SPELL_CHANGE_A_TO_B", (gc.getFeatureInfo(iTormentedSouls).getDescription(), gc.getFeatureInfo(iHallowedGround).getDescription(), ))

				for iUnit in xrange(pPlot.getNumUnits()):
					pUnit = pPlot.getUnit(iUnit)
					if pUnit.isImmuneToMagic():continue
					if pUnit.isHasPromotion(iStatius):continue
					# if pUnit.isInvisible(iTeam, False):continue
					iUnit = pUnit.getUnitType()
					if iUnit in lVulnerableUnits:
						lTargets.append(pUnit)
						continue
					elif pUnit.isAlive():
						if pUnit.isHasPromotion(iWerewolf):
							if not iUnit == iDuin:
								if -1 < pUnit.getScenarioCounter() < gc.getNumUnitInfos():
									lTargets.append(pUnit)
									continue
	lTargets = list(set(lTargets))
	iCount = len(lTargets)
	if iCount == 1:
		pUnit = lTargets.pop(0)
		pPlayer = gc.getPlayer(pUnit.getOwner())
		sList = cf.getNameWithColorScheme(pUnit, pUnit.isInvisible(pCaster.getTeam(), False))
		szBuffer += localText.getText("TXT_KEY_HELP_SPELL_TARGETS_THIS", ( sList, ))
	elif iCount > 0:
		sList = ''
		while len(lTargets) > 0:
			pUnit = lTargets.pop(0)
			pPlayer = gc.getPlayer(pUnit.getOwner())
			sList = cf.getNameWithColorScheme(pUnit, pUnit.isInvisible(pCaster.getTeam(), False))
			if len(lTargets) > 0:
				if len(lTargets) == 1:
					sList += " and "
				else:
					sList += ", "
		szBuffer += localText.getText("TXT_KEY_HELP_SPELL_TARGETS_THESE_COUNT_LIST", (iCount, sList, ))

	szBuffer += helpTogglePromotions(lpUnits, eSpell, [], ['PROMOTION_REBEL','PROMOTION_CRAZED','PROMOTION_ENRAGED','PROMOTION_PARANOID','PROMOTION_BURNING_BLOOD'], 2, True)
	return szBuffer

def reqAssuage(pCaster, eSpell=-1):
	lRemoveProms = [	gc.getInfoTypeForString('PROMOTION_REBEL'),
						gc.getInfoTypeForString('PROMOTION_CRAZED'),
						gc.getInfoTypeForString('PROMOTION_ENRAGED'),
						gc.getInfoTypeForString('PROMOTION_BURNING_BLOOD')	]
	lVulnerableUnits = [	gc.getInfoTypeForString('UNIT_WRATH'),
				gc.getInfoTypeForString('UNIT_ODIO'),
				gc.getInfoTypeForString('UNIT_CHAOS_MARAUDER'),
				gc.getInfoTypeForString('UNIT_PIT_BEAST'),
				gc.getInfoTypeForString('UNIT_IRA')	]
	iDuin = gc.getInfoTypeForString('UNIT_DUIN')
	iWerewolf = gc.getInfoTypeForString('PROMOTION_WEREWOLF')
	iHallowedGround = gc.getInfoTypeForString('FEATURE_HALLOWED_GROUND')
	iTormentedSouls = gc.getInfoTypeForString('FEATURE_TORMENTED_SOULS')
	iStatius = gc.getInfoTypeForString('PROMOTION_PACT_WITH_STATIUS')
	iX = pCaster.getX()
	iY = pCaster.getY()
	for iiX in xrange(iX-1, iX+ 2, 1):
		for iiY in xrange(iY-1, iY+ 2, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			if pPlot.getFeatureType() == iTormentedSouls:
				return True
			for iUnit in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(iUnit)
				if pUnit.isImmuneToMagic():continue
				if pUnit.isHasPromotion(iStatius):continue
				iUnit = pUnit.getUnitType()
				if iUnit in lVulnerableUnits or (pUnit.isHasPromotion(iWerewolf) and not iUnit == iDuin):
					return True
				if pUnit.isAlive():
					for iProm in lRemoveProms:
						if pUnit.isHasPromotion(iProm):
							return True
	return False

def reqAssumeTrueForm(pCaster, eSpell=-1):
	iUnit = pCaster.getScenarioCounter()
	if not -1 < iUnit < gc.getNumUnitInfos():
		return False
	if iUnit == pCaster.getUnitType():
		return False
	return True

