def spellAssumeTrueForm(pCaster, eSpell=-1):
	iUnit = pCaster.getScenarioCounter()
	newUnit = gc.getPlayer(pCaster.getOwner()).initUnit(iUnit, pCaster.getX(), pCaster.getY(), UnitAITypes.UNITAI_ATTACK, DirectionTypes.NO_DIRECTION)
	pCaster.setHasPromotion(gc.getInfoTypeForString('PROMOTION_DARK_REFLECTION'), True)

	info = gc.getUnitInfo(pCaster.getUnitType())
	info2 = gc.getUnitInfo(iUnit)

	cf.makeMortal(pCaster)
	cf.makeMortal(newUnit)
	bKill = False
	if pCaster.isDelayedDeath():
		bKill = True
	newUnit.convert(pCaster)
##	newUnit.setMadeAttack(True)
##	newUnit.setHasCasted(True)
##	gc.getGame().decrementUnitClassCreatedCount(newUnit.getUnitClassType())
##	gc.getGame().decrementUnitCreatedCount(iUnit)


	lRemoveAffinity = [	gc.getInfoTypeForString('PROMOTION_AFFINITY_AIR'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_BODY'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_CHAOS'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_CREATION'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_DEATH'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_DEATH_ARAWN'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_DIMENSIONAL'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_EARTH'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_ENCHANTMENT'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_ENTROPY'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_FIRE'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_FORCE'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_ICE'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_LAW'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_LIFE'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_METAMAGIC'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_MIND'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_NATURE'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_SHADOW'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_SPIRIT'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_SUN'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_WATER')
						]

	for iProm in xrange(gc.getNumPromotionInfos()):
		if pCaster.isHasPromotion(iProm):
			if info.getFreePromotions(iProm) and not info2.getFreePromotions(iProm):
				newUnit.setHasPromotion(iProm,False)
			infoProm = gc.getPromotionInfo(iProm)
			if infoProm.getAIWeight() < 0:
				newUnit.setHasPromotion(iProm,False)
			if infoProm.isRace():
				newUnit.setHasPromotion(iProm,False)
			if iProm in lRemoveAffinity:
				newUnit.setHasPromotion(iProm,False)
	newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_DARK_REFLECTION'), False)
	if bKill:
		newUnit.kill(True, -1)
	return newUnit

def spellAwakenMagic(pCaster, eSpell=-1):

	pPlot = pCaster.plot()
	iTeam = pCaster.getTeam()
	iX = pCaster.getX()
	iY = pCaster.getY()
	iAdept = gc.getInfoTypeForString('UNITCOMBAT_ADEPT')
	iChanneling1 = gc.getInfoTypeForString('PROMOTION_CHANNELING1')
	iChanneling2 = gc.getInfoTypeForString('PROMOTION_CHANNELING2')

	lChanneling = [iChanneling1, iChanneling2, gc.getInfoTypeForString('PROMOTION_CHANNELING3'), gc.getInfoTypeForString('PROMOTION_CHANNELING4'), gc.getInfoTypeForString('PROMOTION_ARCANE'), gc.getInfoTypeForString('PROMOTION_SUMMONER'), gc.getInfoTypeForString('PROMOTION_SUNDERED'), gc.getInfoTypeForString('PROMOTION_ILLUSIONIST')]

	lMagical = []
	for iProm in xrange(gc.getNumPromotionInfos()):
		iBonus = gc.getPromotionInfo(iProm).getBonusPrereq()
		if iBonus != -1:
			if gc.getBonusInfo(iBonus).isMana():
				lMagical.append(iProm)


	listAffinities = [	gc.getInfoTypeForString('PROMOTION_AFFINITY_AIR'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_BODY'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_CHAOS'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_CREATION'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_DEATH'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_DEATH_ARAWN'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_DIMENSIONAL'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_EARTH'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_ENCHANTMENT'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_ENTROPY'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_FIRE'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_FORCE'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_ICE'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_LAW'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_LIFE'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_METAMAGIC'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_MIND'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_NATURE'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_SHADOW'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_SPIRIT'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_SUN'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_WATER')
						]

	for iiX in xrange(iX-1, iX+ 2, 1):
		for iiY in xrange(iY-1, iY+ 2, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if pUnit.getTeam() != iTeam:continue
				if pUnit.isImmuneToSpell(pCaster, eSpell):continue
				uInfo = gc.getUnitInfo(pUnit.getUnitType())

				for iProm in lMagical:
					if uInfo.getFreePromotions(iProm):
						if not pUnit.isHasPromotion(iProm):
							pUnit.setHasPromotion(iProm, True)
							em.onUnitPromoted([pUnit, iProm])
				for iProm in lChanneling:
					if uInfo.getFreePromotions(iProm):
						if not pUnit.isHasPromotion(iProm):
							pUnit.setHasPromotion(iProm, True)
							em.onUnitPromoted([pUnit, iProm])

				if not isWorldUnitClass(pUnit.getUnitClassType()):
					if pUnit.isHasPromotion(iChanneling2) or (gc.getPromotionInfo(iChanneling2).getUnitCombat(pUnit.getUnitCombatType()) and not pUnit.isPromotionImmune(iChanneling2)):
						for iProm in listAffinities:
							if pUnit.isPromotionImmune(iProm):
								continue
							if pUnit.isHasPromotion(iProm):
								break
						else:
							em.onUnitPromoted([pUnit, iChanneling2])

					elif pUnit.isHasPromotion(iChanneling1) or (gc.getPromotionInfo(iChanneling1).getUnitCombat(pUnit.getUnitCombatType()) and not pUnit.isPromotionImmune(iChanneling1)):

						for iProm in lMagical:
							if pUnit.isPromotionImmune(iProm):
								continue
							if pUnit.isHasPromotion(iProm):
								break
						else:
							em.onUnitPromoted([pUnit, iChanneling1])


def reqAwakenMagic(pCaster, eSpell=-1):

	pPlot = pCaster.plot()
	iTeam = pCaster.getTeam()
	iX = pCaster.getX()
	iY = pCaster.getY()
	iAdept = gc.getInfoTypeForString('UNITCOMBAT_ADEPT')
	iChanneling1 = gc.getInfoTypeForString('PROMOTION_CHANNELING1')
	iChanneling2 = gc.getInfoTypeForString('PROMOTION_CHANNELING2')

	lChanneling = [iChanneling1, iChanneling2, gc.getInfoTypeForString('PROMOTION_CHANNELING3'), gc.getInfoTypeForString('PROMOTION_CHANNELING4'), gc.getInfoTypeForString('PROMOTION_ARCANE'), gc.getInfoTypeForString('PROMOTION_SUMMONER'), gc.getInfoTypeForString('PROMOTION_SUNDERED'), gc.getInfoTypeForString('PROMOTION_ILLUSIONIST')]

	lMagical = []
	for iProm in xrange(gc.getNumPromotionInfos()):
		iBonus = gc.getPromotionInfo(iProm).getBonusPrereq()
		if iBonus != -1:
			if gc.getBonusInfo(iBonus).isMana():
				lMagical.append(iProm)


	listAffinities = [	gc.getInfoTypeForString('PROMOTION_AFFINITY_AIR'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_BODY'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_CHAOS'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_CREATION'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_DEATH'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_DEATH_ARAWN'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_DIMENSIONAL'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_EARTH'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_ENCHANTMENT'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_ENTROPY'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_FIRE'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_FORCE'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_ICE'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_LAW'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_LIFE'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_METAMAGIC'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_MIND'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_NATURE'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_SHADOW'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_SPIRIT'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_SUN'),
						gc.getInfoTypeForString('PROMOTION_AFFINITY_WATER')
						]

	for iiX in xrange(iX-1, iX+ 2, 1):
		for iiY in xrange(iY-1, iY+ 2, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if pUnit.getTeam() != iTeam:continue
				if pUnit.isImmuneToSpell(pCaster, eSpell):continue
				uInfo = gc.getUnitInfo(pUnit.getUnitType())
				iCombat = pUnit.getUnitCombatType()

				if gc.getPromotionInfo(iChanneling1).getUnitCombat(iCombat) and not (pUnit.isHasPromotion(iChanneling1) or pUnit.isPromotionImmune(iChanneling1)):
					return True
				if gc.getPromotionInfo(iChanneling2).getUnitCombat(iCombat) and not (pUnit.isHasPromotion(iChanneling2) or pUnit.isPromotionImmune(iChanneling2)):
					return True

				for iProm in lMagical:
					if uInfo.getFreePromotions(iProm):
						if not pUnit.isHasPromotion(iProm) and not pUnit.isPromotionImmune(iProm):
							return True
				for iProm in lChanneling:
					if uInfo.getFreePromotions(iProm):
						if not pUnit.isHasPromotion(iProm) and not pUnit.isPromotionImmune(iProm):
							return True

				if not isWorldUnitClass(pUnit.getUnitClassType()):
					if pUnit.isHasPromotion(iChanneling2) or (gc.getPromotionInfo(iChanneling2).getUnitCombat(iCombat) and not pUnit.isPromotionImmune(iChanneling2)):
						for iProm in listAffinities:
							if pUnit.isPromotionImmune(iProm):
								continue
							if pUnit.isHasPromotion(iProm):
								break
						else:
							return True
					elif pUnit.isHasPromotion(iChanneling1) or (gc.getPromotionInfo(iChanneling1).getUnitCombat(iCombat) and not pUnit.isPromotionImmune(iChanneling1)):
						for iProm in lMagical:
							if pUnit.isPromotionImmune(iProm):
								continue
							if pUnit.isHasPromotion(iProm):
								break
						else:
							return True

	return False

