def spellBanish(pCaster, eSpell):

	iNeutral = gc.getInfoTypeForString('ALIGNMENT_NEUTRAL')
	iEvil = gc.getInfoTypeForString('ALIGNMENT_EVIL')
	iDemon = gc.getInfoTypeForString('PROMOTION_DEMON')
	iAngel = gc.getInfoTypeForString('PROMOTION_ANGEL')
	iElemental = gc.getInfoTypeForString('PROMOTION_ELEMENTAL')
	iUndead = gc.getInfoTypeForString('PROMOTION_UNDEAD')
	iAV = gc.getInfoTypeForString('RELIGION_THE_ASHEN_VEIL')
	iInfernal = gc.getInfoTypeForString('CIVILIZATION_INFERNAL')
	iBbC = gc.getInfoTypeForString('PROMOTION_BOUND_BY_COMPACT')
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iTeam = pCaster.getTeam()
	eTeam = gc.getTeam(iTeam)

	bHighPriest = pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_DIVINE2'))

	iX = pCaster.getX()
	iY = pCaster.getY()
	for iiX in xrange(iX-1, iX+ 2, 1):
		for iiY in xrange(iY-1, iY+ 2, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():
				continue
#			if gc.getTerrainInfo(pPlot.getTerrainType()).getTerrainDown() != -1:#i.e., is hell terrain
#				continue
			bExileLiving = False
			if not pPlot.isOwned():
				if not bHighPriest:
					continue
			elif pPlot.getTeam() == iTeam:
				if bHighPriest:
					bExileLiving = True

			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if pUnit.isHiddenNationality() or eTeam.isAtWar(pUnit.getTeam()):
					if pUnit.isImmuneToSpell(pCaster, eSpell):
						continue
					if pPlot.isOwned():
						if pPlot.getTeam() == pUnit.getTeam():
							continue
					if pUnit.getRace() in [iDemon, iAngel, iElemental, iUndead]:
						if effectResisted(pUnit, pCaster, eSpell):
							continue
						if (pUnit.getDuration() != 0 or pUnit.getSummoner() != -1):
							pUnit.kill(True, iPlayer)
						else:
							pUnit.setHasPromotion(iBbC, True)
							pUnit.jumpToNearestValidPlot()
					elif pPlot.getOwner() == iPlayer:
						if cf.getUnitAlignment(pCaster) != iNeutral:
							pUnit.jumpToNearestValidPlot()

