def helpBless(lpUnits, eSpell=-1, sProm ='PROMOTION_BLESSED'):
	iProm = gc.getInfoTypeForString(sProm)
	szBuffer = ''
	pCaster = lpUnits[0]
	listBlessed = []
	lRels = [-1]
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	if pPlayer.getAlignment() != gc.getInfoTypeForString('ALIGNMENT_EVIL'):
		for pCaster in lpUnits:
			if pCaster.canCast(eSpell, False):
				lRels.append(pCaster.getReligion())
		lRels = list(set(lRels))

		bState = (pPlayer.getStateReligion() in lRels)
		if cf.getUnitAlignment(pCaster) == gc.getInfoTypeForString('ALIGNMENT_GOOD'):
			iTeam = pCaster.getTeam()
			info = gc.getPromotionInfo(iProm)
			pPlot = pCaster.plot()
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if pUnit.getTeam() != iTeam:continue
				if pUnit.isHasPromotion(iProm):continue
				if pUnit.isPromotionImmune(iProm):continue
				if pUnit.isImmuneToSpell(pCaster, eSpell):continue
				if pUnit.isAlive():
					if bState or pUnit.getReligion() in lRels:
						if info.getUnitCombat(pUnit.getUnitCombatType()):
							if cf.getUnitAlignment(pUnit) != gc.getInfoTypeForString('ALIGNMENT_EVIL'):
								listBlessed.append(pUnit)
	if len(listBlessed):
		szBuffer += helpTogglePromotionsSpecificUnitsIndex(lpUnits,listBlessed, eSpell, [iProm], [], False)
	return szBuffer

def spellBless(pCaster, eSpell=-1, sProm ='PROMOTION_BLESSED'):
	iProm = gc.getInfoTypeForString(sProm)
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	if pPlayer.getAlignment() != gc.getInfoTypeForString('ALIGNMENT_EVIL'):
		iRel = pCaster.getReligion()
		bState = (pPlayer.getStateReligion() == iRel)
		if cf.getUnitAlignment(pCaster) == gc.getInfoTypeForString('ALIGNMENT_GOOD'):
			iTeam = pCaster.getTeam()
			info = gc.getPromotionInfo(iProm)
			pPlot = pCaster.plot()
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if pUnit.getTeam() != iTeam:continue
				if pUnit.isHasPromotion(iProm):continue
				if pUnit.isPromotionImmune(iProm):continue
				if pUnit.isImmuneToSpell(pCaster, eSpell):continue
				if pUnit.isAlive():
					if bState or pUnit.getReligion() in [-1, iRel]:
						if info.getUnitCombat(pUnit.getUnitCombatType()):
							if cf.getUnitAlignment(pUnit) != gc.getInfoTypeForString('ALIGNMENT_EVIL'):
								pUnit.setHasPromotion(iProm, True)

