def spellBeastFeast(pCaster, eSpell):
	pPlot = pCaster.plot()
	if pPlot.isCity():
		pCity = pPlot.getPlotCity()
		if pCity.getPopulation() > 2:
			iPlayer = pCaster.getOwner()
			pPlayer = gc.getPlayer(iPlayer)

			iPlayer2 = pCity.getOriginalOwner()
			if iPlayer != iPlayer2:
				gc.getPlayer(iPlayer2).AI_changeAttitudeExtra(iPlayer, -1)

			if pCaster.getDuration() > 0:
				pCaster.setDuration(pCaster.getDuration()+ 2)
			pCaster.setDamage(0, pCaster.getOwner())
			pCaster.setMadeAttack(False)
			pCaster.setMoves(max(0, pCaster.getMoves() - gc.getMOVE_DENOMINATOR()))

			iPlayerCity = pCity.getOwner()
			pPlayerCity = gc.getPlayer(iPlayerCity)

			if not pPlayerCity.hasTrait(gc.getInfoTypeForString('TRAIT_FALLOW')):
				pCity.changeHurryAngerTimer(pCaster.getDuration())
				bRevolt = True
				for sBuilding in ['BUILDING_TOWER_OF_COMPLACENCY', 'BUILDING_PILLAR_OF_CHAINS', 'BUILDING_UNYIELDING_ORDER','BUILDING_UNYIELDING_ORDER_GREATER']:
					if pCity.getNumBuilding(gc.getInfoTypeForString(sBuilding)) > 0:
						bRevolt=False
						break
				if bRevolt:
					pCity.changeOccupationTimer(1)
					pCity.setRevolutionIndex(pCity.getRevolutionIndex()+ 6)


