def reqRevereDragon(pCaster, eSpell=-1):
	if eSpell != -1:
		iUnit = gc.getSpellInfo(eSpell).getConvertUnitType()
		if iUnit > -1:
			info = gc.getUnitInfo(iUnit)
			iPlayer = pCaster.getOwner()
			pPlayer = gc.getPlayer(iPlayer)
			iUnitClass = info.getUnitClassType()
			if pPlayer.isUnitClassMaxedOut(iUnitClass, 0):
				return False
			iBonus = info.getPrereqAndBonus()
			if iBonus != -1:
				if cf.getNumBonusEffective(iPlayer, iBonus, -1) < 1:
					return False
			if pPlayer.getAlignment() != gc.getInfoTypeForString('ALIGNMENT_GOOD'):
				if iUnit in [	gc.getInfoTypeForString('UNIT_DRAGON_FANATIC_CORAL'),
								gc.getInfoTypeForString('UNIT_DRAGON_FANATIC_DAWN'),
								gc.getInfoTypeForString('UNIT_DRAGON_FANATIC_GOLD'),
								gc.getInfoTypeForString('UNIT_DRAGON_FANATIC_RUNE'),
								gc.getInfoTypeForString('UNIT_DRAGON_FANATIC_SHIELD'),
								gc.getInfoTypeForString('UNIT_DRAGON_FANATIC_SHIMMERING')]:
					return False
			# if pPlayer.getAlignment() == gc.getInfoTypeForString('ALIGNMENT_NEUTRAL'):
				# if iUnit in [	gc.getInfoTypeForString('UNIT_DRAGON_FANATIC_ELDER'),
								# gc.getInfoTypeForString('UNIT_DRAGON_FANATIC_FANG'),
								# gc.getInfoTypeForString('UNIT_DRAGON_FANATIC_FEATHERED'),
								# gc.getInfoTypeForString('UNIT_DRAGON_FANATIC_GRAVE'),
								# gc.getInfoTypeForString('UNIT_DRAGON_FANATIC_SCALED'),
								# gc.getInfoTypeForString('UNIT_DRAGON_FANATIC_SEED'),
								# gc.getInfoTypeForString('UNIT_DRAGON_FANATIC_SPIRE')]]:
					# return True
			if pPlayer.getAlignment() != gc.getInfoTypeForString('ALIGNMENT_EVIL'):
				if iUnit in [	gc.getInfoTypeForString('UNIT_DRAGON_FANATIC_BLOOD'),
								gc.getInfoTypeForString('UNIT_DRAGON_FANATIC_FURNACE'),
								gc.getInfoTypeForString('UNIT_DRAGON_FANATIC_OBSIDIAN'),
								gc.getInfoTypeForString('UNIT_DRAGON_FANATIC_PIT'),
								gc.getInfoTypeForString('UNIT_DRAGON_FANATIC_SHADOW'),
								gc.getInfoTypeForString('UNIT_DRAGON_FANATIC_SIEGE'),
								gc.getInfoTypeForString('UNIT_DRAGON_FANATIC_VAULT'),
								gc.getInfoTypeForString('UNIT_DRAGON_FANATIC_WINTER'),
								gc.getInfoTypeForString('UNIT_DRAGON_FANATIC_DRACOLICH')]:
					return False
			return True

	return False



def reqSummonDragon(pCaster, eSpell=-1):
	if eSpell != -1:
		iUnit = gc.getSpellInfo(eSpell).getCreateUnitType()
		if iUnit > -1:
			info = gc.getUnitInfo(iUnit)
			iPlayer = pCaster.getOwner()
			pPlayer = gc.getPlayer(iPlayer)
			iUnitClass = info.getUnitClassType()
			if pPlayer.isUnitClassMaxedOut(iUnitClass, 0):
				return False
			iBonus = info.getPrereqAndBonus()
			if iBonus != -1:
				if cf.getNumBonusEffective(iPlayer, iBonus, -1) < 3:
					return False

			if pPlayer.getAlignment() == gc.getInfoTypeForString('ALIGNMENT_GOOD'):
				if iUnit in [	gc.getInfoTypeForString('UNIT_DRAGON_CORAL'),
								gc.getInfoTypeForString('UNIT_DRAGON_DAWN'),
								gc.getInfoTypeForString('UNIT_DRAGON_GOLD'),
								gc.getInfoTypeForString('UNIT_DRAGON_RUNE'),
								gc.getInfoTypeForString('UNIT_DRAGON_SHIELD'),
								gc.getInfoTypeForString('UNIT_DRAGON_SHIMMERING')]:
					return True

			if pPlayer.getAlignment() == gc.getInfoTypeForString('ALIGNMENT_NEUTRAL'):

				if iUnit in [	gc.getInfoTypeForString('UNIT_DRAGON_ELDER'),
								gc.getInfoTypeForString('UNIT_DRAGON_FANG'),
								gc.getInfoTypeForString('UNIT_DRAGON_FEATHERED'),
								gc.getInfoTypeForString('UNIT_DRAGON_GRAVE'),
								gc.getInfoTypeForString('UNIT_DRAGON_SCALED'),
								gc.getInfoTypeForString('UNIT_DRAGON_SEED'),
								gc.getInfoTypeForString('UNIT_DRAGON_SPIRE')]:
					return True


			if pPlayer.getAlignment() == gc.getInfoTypeForString('ALIGNMENT_EVIL'):
				if iUnit in [	gc.getInfoTypeForString('UNIT_DRAGON_BLOOD'),
								gc.getInfoTypeForString('UNIT_DRAGON_FURNACE'),
								gc.getInfoTypeForString('UNIT_DRAGON_OBSIDIAN'),
								gc.getInfoTypeForString('UNIT_DRAGON_PIT'),
								gc.getInfoTypeForString('UNIT_DRAGON_SHADOW'),
								gc.getInfoTypeForString('UNIT_DRAGON_SIEGE'),
								gc.getInfoTypeForString('UNIT_VAULT_WYRM'),
								gc.getInfoTypeForString('UNIT_DRAGON_WINTER'),
								gc.getInfoTypeForString('UNIT_DRACOLICH')]:
					return True

	return False

def reqSummonBeastofAgares(pCaster, eSpell=-1):

	if not reqEntropyAllowed(pCaster, eSpell):
		return False
	if isWorldUnitClass(pCaster.getUnitClassType()):
		return False
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	if pPlayer.getUnitClassCount(gc.getInfoTypeForString('UNITCLASS_BEAST_OF_AGARES')) >= 7:
		return False
	return True

def reqBeastFeast(pCaster, eSpell):
	pPlot = pCaster.plot()
	if pPlot.isCity():
		pCity = pPlot.getPlotCity()
		if pCity.getPopulation() > 2:
			iCityPlayer = pCity.getOwner()
			if iCityPlayer != -1:
				iPlayer = pCaster.getOwner()
				pPlayer = gc.getPlayer(iPlayer)
				if iCityPlayer != iPlayer:
					if gc.getPlayer(iCityPlayer).hasTrait(gc.getInfoTypeForString('TRAIT_FALLOW')):
						return False
				if pPlayer.isHuman():
					return True
				elif gc.getTeam(pCaster.getTeam()).getAtWarCount(False) == 0:
					return False
				elif pCaster.getDuration() == 1:
					return True
				elif pCaster.getDamage() > 50:
					return True
				elif pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_BOUND_BY_COMPACT')):
					return True
	return False

def helpBeastFeast(lpUnits, eSpell):

	szBuffer = ''
	pCaster = lpUnits[0]

	pPlot = pCaster.plot()
