def spellSubmerge(pCaster, eSpell=-1):
	if pCaster.isBarbarian():
		iUndertow = gc.getInfoTypeForString('RELIGION_OCTOPUS_OVERLORDS')
		if gc.getUnitInfo(pCaster.getUnitType()).getStateReligion() == iUndertow:
##		if pCaster.getUnitType() in [gc.getInfoTypeForString('UNIT_KRAKEN'), gc.getInfoTypeForString('UNIT_DROWN')]:
			pPlot = pCaster.plot()
			if pPlot.isOwned():
				iPlayer = pPlot.getOwner()
				if iPlayer != pCaster.getOwner():
					pPlayer = gc.getPlayer(iPlayer)
					if pPlayer.getStateReligion() == iUndertow:
						iX = pCaster.getX()
						iY = pCaster.getY()
						iDuration = pCaster.getDuration() + 1 + cf.getNumBonusEffective(iPlayer, gc.getInfoTypeForString('BONUS_MANA_MIND'), -1) + cf.getNumBonusEffective(iPlayer, gc.getInfoTypeForString('BONUS_MANA_WATER'), -1)
						newUnit = pPlayer.initUnit(pCaster.getUnitType(), iX, iY, UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
						newUnit.convert(pCaster)
						newUnit.setDuration(iDuration)

def reqSubmerge(pCaster, eSpell=-1):
	if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_INVISIBLE')):
		return False

	pPlot = pCaster.plot()
	iHidden = gc.getInfoTypeForString('PROMOTION_HIDDEN')
	if pPlot.isWater():
		if not pCaster.isHasPromotion(iHidden):
			if pCaster.isMadeAttack():
				return False
			return True
	elif pCaster.isHasPromotion(iHidden):
		if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_GREY')):
			return False
		if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_STEALTH')):
			return False
		if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_SNOW_STEALTH')):
			if pPlot.getTerrainType() in [gc.getInfoTypeForString('TERRAIN_TUNDRA'), gc.getInfoTypeForString('TERRAIN_WASTELAND'), gc.getInfoTypeForString('TERRAIN_SNOW'), gc.getInfoTypeForString('TERRAIN_GLACIER')] or pPlot.getFeatureType() in [gc.getInfoTypeForString('FEATURE_BLIZZARD'), gc.getInfoTypeForString('FEATURE_ICE')]:
				return False
		if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_FOREST_STEALTH')) and pPlot.getFeatureType() in [gc.getInfoTypeForString('FEATURE_FOREST'), gc.getInfoTypeForString('FEATURE_JUNGLE'), gc.getInfoTypeForString('FEATURE_FOREST_ANCIENT')]:
			return False

		pCaster.setHasPromotion(iHidden, False)
	return False


