def reqBreathYouth(pCaster, eSpell, iRange):
	pPlot = pCaster.plot()
	iX = pCaster.getX()
	iY = pCaster.getY()
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iTeam = pCaster.getTeam()
	eTeam = gc.getTeam(iTeam)
	iX = pCaster.getX()
	iY = pCaster.getY()
	for iiX in xrange(iX-iRange, iX+ 1+ iRange, 1):
		for iiY in xrange(iY-iRange, iY+ 1+ iRange, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if pUnit.isImmuneToSpell(pCaster, eSpell):continue
				if pUnit.getLevel() > 1:
					return True
				if iTeam == pUnit.getTeam():
					info = gc.getUnitInfo(pUnit.getUnitType())
					for iProm in xrange(gc.getNumPromotionInfos()):
						infoProm = gc.getPromotionInfo(iProm)
						if pCaster.isHasPromotion(iProm):
							if not info.getFreePromotions(iProm):
								if infoProm.getAIWeight() < 0:
									return True
						if info.getFreePromotions(iProm):
							if infoProm.getAIWeight() > 0:
								return True
				elif eTeam.isAtWar(pUnit.getTeam()):
					info = gc.getUnitInfo(pUnit.getUnitType())
					for iProm in xrange(gc.getNumPromotionInfos()):
						infoProm = gc.getPromotionInfo(iProm)
						if pCaster.isHasPromotion(iProm):
							if not info.getFreePromotions(iProm):
								if infoProm.getAIWeight() > 0:
									return True
						if info.getFreePromotions(iProm):
							if infoProm.getAIWeight() < 0:
								return True
	return False

def spellBreathYouth(pCaster, eSpell, iRange = 1):
	pPlot = pCaster.plot()
	iX = pCaster.getX()
	iY = pCaster.getY()
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iTeam = pCaster.getTeam()
	eTeam = gc.getTeam(iTeam)
	iX = pCaster.getX()
	iY = pCaster.getY()
	for iiX in xrange(iX-iRange, iX+ 1+ iRange, 1):
		for iiY in xrange(iY-iRange, iY+ 1+ iRange, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if pUnit.isImmuneToSpell(pCaster, eSpell):continue
				if pUnit.getLevel() > 1:
					if effectResisted(pUnit, pCaster, eSpell):continue
					pUnit.setLevel(1+ CyGame().getSorenRandNum(pUnit.getLevel(), "Breath of Youth Level"))
					pUnit.setExperience(CyGame().getSorenRandNum(pUnit.getExperience(), "Breath of Youth Level"),-1)
					if iTeam == pUnit.getTeam():
						info = gc.getUnitInfo(pUnit.getUnitType())
						for iProm in xrange(gc.getNumPromotionInfos()):
							infoProm = gc.getPromotionInfo(iProm)
							if pCaster.isHasPromotion(iProm):
								if not info.getFreePromotions(iProm):
									if infoProm.getAIWeight() < 0:
										pUnit.setHasPromotion(iProm,False)
							if info.getFreePromotions(iProm):
								if infoProm.getAIWeight() > 0:
									pUnit.setHasPromotion(iProm,True)
					elif eTeam.isAtWar(pUnit.getTeam()):
						info = gc.getUnitInfo(pUnit.getUnitType())
						for iProm in xrange(gc.getNumPromotionInfos()):
							infoProm = gc.getPromotionInfo(iProm)
							if pCaster.isHasPromotion(iProm):
								if not info.getFreePromotions(iProm):
									if infoProm.getAIWeight() > 0:
										pUnit.setHasPromotion(iProm,False)
							if info.getFreePromotions(iProm):
								if infoProm.getAIWeight() < 0:
									pUnit.setHasPromotion(iProm,True)
						if CyGame().getSorenRandNum(pUnit.getLevel(), "Breath of Youth convert") < 2:
							newUnit = pPlayer.initUnit(pUnit.getUnitType(), iX, iY, UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
							cf.removeAffinities(newUnit)
							newUnit.convert(pUnit)


