def spellBreathNexus(pCaster, eSpell):
	pPlot = pCaster.plot()
	iX = pCaster.getX()
	iY = pCaster.getY()
	iPlayer = pCaster.getOwner()
	iTeam = pCaster.getTeam()
	eTeam = gc.getTeam(iTeam)
	listVictims = []

	iX = pCaster.getX()
	iY = pCaster.getY()
	for iiX in xrange(iX-1, iX+ 1, 1):
		for iiY in xrange(iY-1, iY+ 1, 1):
			pPlot = CyMap().plot(iiX, iiY)
