def helpCallForm(lpUnits, eSpell=1):
	szBuffer = ''
	pCaster = lpUnits[0]
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	for pCaster in lpUnits:
		if pCaster.isNone(): continue
		if pCaster.canCast(eSpell, True):
			if pCaster.getSummoner() != -1:
				pSummoner = pPlayer.getUnit(pCaster.getSummoner())
				if not pSummoner.isNone():
					iX1 = pSummoner.getX()
					iY1 = pSummoner.getY()
					iX2 = pCaster.getX()
					iY2 = pCaster.getY()
					pExitPlot = CyMap().plot(iX2, iY2)
					if not pExitPlot.isNone():
						sList = cf.getNameWithColorScheme(pSummoner, pSummoner.isInvisible(pCaster.getTeam(), False))
						szBuffer += localText.getText("TXT_KEY_SPELL_SUMMON_UNIT", (sList,))
						idX = iX2 - iX1
						if idX != 0:
							sdX = 'East'
							if idX < 0:
								idX = -idX
								sdX = 'West'
							szBuffer += localText.getText("TXT_KEY_HELP_MOVE_UNIT", (sList,idX, sdX, ))
						idY = iY2 - iY1
						if idY != 0:
							sdY = 'North'
							if idY < 0:
								idY = -idY
								sdY = 'South'
							szBuffer += localText.getText("TXT_KEY_HELP_MOVE_UNIT", (sList,idY, sdY, ))
	return szBuffer

def reqCallOfTheGrave(pCaster, eSpell=-1):
	if reqNecromancyAllowed(pCaster):
		iX = pCaster.getX()
		iY = pCaster.getY()
		iPlayer = pCaster.getOwner()
		pPlayer = gc.getPlayer(iPlayer)
		iTeam = pCaster.getTeam()
		eTeam = gc.getTeam(iTeam)
		iGraveyard = gc.getInfoTypeForString('IMPROVEMENT_GRAVEYARD')
		iHeld = gc.getInfoTypeForString('PROMOTION_HELD')
		iSluagh = gc.getInfoTypeForString('UNIT_SLUAGH')
		iUndead = gc.getInfoTypeForString('PROMOTION_UNDEAD')
		iDemon = gc.getInfoTypeForString('PROMOTION_DEMON')

		lBoundProm = [	gc.getInfoTypeForString('PROMOTION_NETHERBIND'),
						gc.getInfoTypeForString('PROMOTION_CAPTUS_CAVEAE_SAWOL'),
						gc.getInfoTypeForString('PROMOTION_CAPTUS_CAVEAE_ANGELORUM'),
						gc.getInfoTypeForString('PROMOTION_INCARCERATUS_JUDICII'),
						gc.getInfoTypeForString('PROMOTION_SOUL_FORGED'),
	#					gc.getInfoTypeForString('PROMOTION_AFFINITY_DEATH')
						]
		if gc.getGame().getProjectCreatedCount(gc.getInfoTypeForString('PROJECT_STIR_FROM_SLUMBER')) < 1 and pCaster.getReligion() != gc.getInfoTypeForString('RELIGION_CULT_OF_THE_DRAGON'):
			lBoundProm.append(gc.getInfoTypeForString('PROMOTION_DRAGON'))
		listRemove = [
						gc.getInfoTypeForString('PROMOTION_HELD'),
						gc.getInfoTypeForString('PROMOTION_MAGIC_IMMUNE'),
						gc.getInfoTypeForString('PROMOTION_CANNOT_CAST'),
						gc.getInfoTypeForString('PROMOTION_LAIR_GUARDIAN')
					]

		if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_SAWOL_CAVEA')):
			lBoundProm.remove(gc.getInfoTypeForString('PROMOTION_CAPTUS_CAVEAE_SAWOL'))
			listRemove.append(gc.getInfoTypeForString('PROMOTION_CAPTUS_CAVEAE_SAWOL'))
		if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_ANGELORUM_CAVEA')):
			lBoundProm.remove(gc.getInfoTypeForString('PROMOTION_CAPTUS_CAVEAE_ANGELORUM'))
			listRemove.append(gc.getInfoTypeForString('PROMOTION_CAPTUS_CAVEAE_ANGELORUM'))
		if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_NETHER_BLADE')):
			lBoundProm.remove(gc.getInfoTypeForString('PROMOTION_NETHERBIND'))
			listRemove.append(gc.getInfoTypeForString('PROMOTION_NETHERBIND'))

		iRange = 3
		for iiX in xrange(iX-iRange, iX + iRange+1, 1):
			for iiY in xrange(iY-iRange, iY+ iRange+1, 1):
				pPlot = CyMap().plot(iiX, iiY)
				if pPlot.isNone():continue
				# if pPlot.at(iX, iY):continue
				if plotDistance(iX, iY, iiX, iiY) > iRange:continue
				
				if pPlot.getImprovementType() == gc.getInfoTypeForString('IMPROVEMENT_BROKEN_SEPULCHER'):
					iUnit = gc.getInfoTypeForString('UNIT_BARBATOS')
					if CyGame().getUnitCreatedCount(iUnit) == 0:
						if eTeam.isHasTech(gc.getInfoTypeForString('TECH_STRENGTH_OF_WILL')):
							return True
				for i in xrange(pPlot.getNumUnits()):
					pUnit = pPlot.getUnit(i)
					if pUnit.getUnitType() == iSluagh:
						if pUnit.isDelayedDeath():
							continue
						for iProm in lBoundProm:
							if pUnit.isHasPromotion(iProm):
								break
						else:
							iUnit = pUnit.getScenarioCounter()
							if -1 < iUnit < gc.getNumUnitInfos():
								info = gc.getUnitInfo(iUnit)
								iTech = info.getPrereqAndTech()
								if iTech != -1 and not eTeam.isHasTech(iTech):
									continue
								if isWorldUnitClass(info.getUnitClassType()) and not pUnit.getRace() == iUndead:
									continue
							return True
					if pUnit.getTeam() == iTeam:
						if pUnit.getRace() == iUndead:
							if pUnit.getDamage() > 0:
								return True
					elif pUnit.isAlive():
						if eTeam.isAtWar(pUnit.getTeam()):
							return True

	return False

def spellCallOfTheGrave(pCaster, eSpell=-1):
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iTeam = pPlayer.getTeam()
	eTeam = gc.getTeam(iTeam)
	iX = pCaster.getX()
	iY = pCaster.getY()
	iGraveyard = gc.getInfoTypeForString('IMPROVEMENT_GRAVEYARD')
	iHeld = gc.getInfoTypeForString('PROMOTION_HELD')
	iUndead = gc.getInfoTypeForString('PROMOTION_UNDEAD')
	iDemon = gc.getInfoTypeForString('PROMOTION_DEMON')
	iSluagh = gc.getInfoTypeForString('UNIT_SLUAGH')

	lBoundProm = [	gc.getInfoTypeForString('PROMOTION_NETHERBIND'),
					gc.getInfoTypeForString('PROMOTION_CAPTUS_CAVEAE_SAWOL'),
					gc.getInfoTypeForString('PROMOTION_CAPTUS_CAVEAE_ANGELORUM'),
					gc.getInfoTypeForString('PROMOTION_INCARCERATUS_JUDICII'),
					gc.getInfoTypeForString('PROMOTION_SOUL_FORGED'),
#					gc.getInfoTypeForString('PROMOTION_AFFINITY_DEATH')
					]
	if gc.getGame().getProjectCreatedCount(gc.getInfoTypeForString('PROJECT_STIR_FROM_SLUMBER')) < 1 and pCaster.getReligion() != gc.getInfoTypeForString('RELIGION_CULT_OF_THE_DRAGON'):
		lBoundProm.append(gc.getInfoTypeForString('PROMOTION_DRAGON'))
	listRemove = [
					gc.getInfoTypeForString('PROMOTION_HELD'),
					gc.getInfoTypeForString('PROMOTION_MAGIC_IMMUNE'),
					gc.getInfoTypeForString('PROMOTION_CANNOT_CAST'),
					gc.getInfoTypeForString('PROMOTION_LAIR_GUARDIAN')
				]
	if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_SAWOL_CAVEA')):
		lBoundProm.remove(gc.getInfoTypeForString('PROMOTION_CAPTUS_CAVEAE_SAWOL'))
		listRemove.append(gc.getInfoTypeForString('PROMOTION_CAPTUS_CAVEAE_SAWOL'))
	if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_ANGELORUM_CAVEA')):
		lBoundProm.remove(gc.getInfoTypeForString('PROMOTION_CAPTUS_CAVEAE_ANGELORUM'))
		listRemove.append(gc.getInfoTypeForString('PROMOTION_CAPTUS_CAVEAE_ANGELORUM'))
	if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_NETHER_BLADE')):
		lBoundProm.remove(gc.getInfoTypeForString('PROMOTION_NETHERBIND'))
		listRemove.append(gc.getInfoTypeForString('PROMOTION_NETHERBIND'))
	lSluaghs = []
	iX = pCaster.getX()
	iY = pCaster.getY()
	iRange = 3
	for iiX in xrange(iX-iRange, iX + iRange+1, 1):
		for iiY in xrange(iY-iRange, iY+ iRange+1, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			# if pPlot.at(iX, iY):continue
			if plotDistance(iX, iY, iiX, iiY) > iRange:continue
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if pUnit.getUnitType() == iSluagh:
					if pUnit.isDelayedDeath():
						continue
					for iProm in lBoundProm:
						if pUnit.isHasPromotion(iProm):
							break
					else:
						iUnit = pUnit.getScenarioCounter()
						if -1 < iUnit < gc.getNumUnitInfos():
							info = gc.getUnitInfo(iUnit)
							iTech = info.getPrereqAndTech()
							if iTech != -1 and not eTeam.isHasTech(iTech):
								continue
						lSluaghs.append(pUnit)
				elif pUnit.getTeam() == iTeam:
					if pUnit.getRace() == iUndead:
						if pUnit.getDamage() > 0:
							pUnit.setDamage(0, pCaster.getOwner())
							CyInterface().addMessage(pUnit.getOwner(),True,25,localText.getText("TXT_KEY_MESSAGE_UNIT_HEALED",()),'AS2D_FEATUREGROWTH',1,'Art/Interface/Buttons/Promotions/Cursed.dds',ColorTypes(8),pUnit.getX(),pUnit.getY(),True,True)
#				elif eTeam.isAtWar(pUnit.getTeam()):
					# pUnit.doDamage(40, 100, pCaster, gc.getInfoTypeForString('DAMAGE_DEATH'), True)
					# pUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_DEATHPHAGE'), True)

	if len (lSluaghs) > 0:
		for pUnit2 in lSluaghs:
			pPlot = pUnit2.plot()
			iUnit = pUnit2.getScenarioCounter()
			if not (-1 < iUnit < gc.getNumUnitInfos()):
				iUnit = gc.getInfoTypeForString('UNIT_SPECTRE')
			sName = pUnit2.getNameNoDesc()[:pUnit2.getNameNoDesc().find("'s Sluagh")]
			info = gc.getUnitInfo(iUnit)
			if info.getSpecialUnitType() == gc.getInfoTypeForString('SPECIALUNIT_DRAGON'):
				iUnit = gc.getInfoTypeForString('UNIT_DRACOLICH')
			newUnit = pPlayer.initUnit(iUnit, pPlot.getX(), pPlot.getY(), UnitAITypes.UNITAI_HERO, DirectionTypes.DIRECTION_SOUTH)
	#		cf.removeAffinities(newUnit)
			newUnit.convert(pUnit2)
			for iProm in listRemove:
				if not gc.getUnitInfo(iUnit).getFreePromotions(iProm):
					newUnit.setHasPromotion(iProm, False)
					pUnit2.setHasPromotion(iProm, False)
			newUnit.setSummoner(pCaster.getID())
			newUnit.convert(pUnit2)
			newUnit.setPermanentSummon(True)
			cf.grantSummonPerks(newUnit, pCaster)
			newUnit.setHasPromotion(iUndead, True)
			if newUnit.isHasPromotion(gc.getInfoTypeForString('PROMOTION_AFFINITY_DEATH_ARAWN')):
				newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_AFFINITY_DEATH_ARAWN'), False)
				newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_AFFINITY_DEATH'), True)
			if newUnit.isHasPromotion(gc.getInfoTypeForString('PROMOTION_DEATH_ARAWN1')):
				newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_DEATH_ARAWN1'), False)
				newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_DEATH1'), True)
			if newUnit.isHasPromotion(gc.getInfoTypeForString('PROMOTION_DEATH_ARAWN2')):
				newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_DEATH_ARAWN2'), False)
				newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_DEATH2'), True)
			if newUnit.isHasPromotion(gc.getInfoTypeForString('PROMOTION_DEATH_ARAWN3')):
				newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_DEATH_ARAWN3'), False)
				newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_DEATH3'), True)
			newUnit.setName(sName)
			sName = cf.getNameWithColorScheme(newUnit)
			sButton = newUnit.getButton()
			iX = pCaster.getX()
			iY = pCaster.getY()
			if isWorldUnitClass(gc.getUnitInfo(iUnit).getUnitClassType()):
				for iLoopPlayer in xrange(gc.getMAX_PLAYERS()):
					pLoopPlayer = gc.getPlayer(iLoopPlayer)
					if pLoopPlayer.isAlive():
						CyInterface().addMessage(iLoopPlayer, True, 25, localText.getText("TXT_KEY_MESSAGE_RAISED_UNDEAD", (sName, )), 'AS2D_CHARM_PERSON', 1, sButton, ColorTypes(8), iX, iY, True, True)
			else:
				CyInterface().addMessage(iPlayer, True, 25, localText.getText("TXT_KEY_MESSAGE_RAISED_UNDEAD", (sName, )), 'AS2D_CHARM_PERSON', 1, sButton, ColorTypes(8), iX, iY, True, True)
			if pPlot.getImprovementType() == gc.getInfoTypeForString('IMPROVEMENT_GRAVEYARD'):
				if reqRobGrave(pCaster, eSpell):
					spellRobGrave(pCaster, eSpell)

