def spellCasswallawnJoin(pCaster, eSpell):

	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	pPlot = pCaster.plot()
	iGastrius = gc.getInfoTypeForString('UNIT_GASTRIUS')
	iIllusion = gc.getInfoTypeForString('PROMOTION_ILLUSION')
	iReflection = gc.getInfoTypeForString('PROMOTION_DARK_REFLECTION')
	pGastrius = -1
	sName = pCaster.getName()
	for i in xrange(pPlot.getNumUnits()):
		pUnit = pPlot.getUnit(i)
		if iPlayer == pUnit.getOwner():
			if pUnit.getRace() in [iIllusion,iReflection]:
				continue
			if pUnit.getUnitType() == iGastrius:
				pGastrius = pUnit
	if pGastrius != -1:
##		pCaster.convert(pUnit)

		for iProm in xrange(gc.getNumPromotionInfos()):
			if pGastrius.isHasPromotion(iProm):
				pCaster.setHasPromotion(iProm, True)

		pGastrius.setHasPromotion(gc.getInfoTypeForString('PROMOTION_GOLEM'), True)
		cf.makeMortal(pGastrius)
		pGastrius.kill(False, PlayerTypes.NO_PLAYER)
		pCaster.setHasPromotion(gc.getInfoTypeForString('PROMOTION_CANNOT_CAST'), False)
		pCaster.setHasPromotion(gc.getInfoTypeForString('PROMOTION_CASSWALLAWN'), True)

		pCaster.setName(sName + " the Casswallawn")

def helpCasswallawnJoin(lpUnits, eSpell, sCommander = 'PROMOTION_CASSWALLAWN'):
	szBuffer = ''
	liAddProms = [gc.getInfoTypeForString('PROMOTION_CASSWALLAWN')]
	iBlock = gc.getInfoTypeForString('PROMOTION_CANNOT_CAST')

	iIllusion = gc.getInfoTypeForString('PROMOTION_ILLUSION')
	iReflection = gc.getInfoTypeForString('PROMOTION_DARK_REFLECTION')
	pCaster = lpUnits[0]
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	pPlot= pCaster.plot()
	iCommander = gc.getInfoTypeForString(sCommander)
	pCommander = -1
	for i in xrange(pPlot.getNumUnits()):
		pUnit = pPlot.getUnit(i)
		if iPlayer == pUnit.getOwner():
			if pUnit.getRace() in [iIllusion,iReflection]:
				continue
			if pUnit.getUnitType() == iCommander:
				pCommander = pUnit
				for iProm in xrange(gc.getNumPromotionInfos()):
					if pCommander.isHasPromotion(iProm) and not pCaster.isHasPromotion(iProm):
						liAddProms.append(iProm)
				if iBlock in liAddProms:
					liAddProms.remove(iBlock)
				szBuffer += helpTogglePromotionsBuffCasterIndex(lpUnits, eSpell, liAddProms, [iBlock], False)
				break
	return szBuffer

def reqCasswallawnSplit(pCaster, eSpell=1):
	iGastrius = gc.getInfoTypeForString('UNIT_GASTRIUS')
	if CyGame().getUnitCreatedCount(iGastrius) < 1:
		return False
	for iProm in [gc.getInfoTypeForString('PROMOTION_CHANNELING4'), gc.getInfoTypeForString('PROMOTION_AFFINITY_METAMAGIC'), gc.getInfoTypeForString('PROMOTION_CASSWALLAWN')]:
		if not pCaster.isHasPromotion(iProm):
			return False
	if pCaster.getName().find(" the Casswallawn") == -1:
		return False
	return not pCaster.isMadeAttack()


def spellCasswallawnSplit(pCaster, eSpell=-1):
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iGastrius = gc.getInfoTypeForString('UNIT_GASTRIUS')

	newUnit = pPlayer.initUnit(iGastrius, pCaster.getX(), pCaster.getY(), UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
	newUnit.finishMoves()
	pCaster.setHasPromotion(gc.getInfoTypeForString('PROMOTION_CANNOT_CAST'), True)

	sName = pCaster.getName()[:pCaster.getName().find(" the Casswallawn")]
	pCaster.setName(sName)


	infoUnit = gc.getUnitInfo(pCaster.getUnitType())
	infoUnitG = gc.getUnitInfo(iGastrius)

	lChanneling = [gc.getInfoTypeForString('PROMOTION_CHANNELING1'), gc.getInfoTypeForString('PROMOTION_CHANNELING2'), gc.getInfoTypeForString('PROMOTION_CHANNELING3'), gc.getInfoTypeForString('PROMOTION_CHANNELING4')]


	for iProm in xrange(gc.getNumPromotionInfos()):
		if not infoUnit.getFreePromotions(iProm):
			if infoUnitG.getFreePromotions(iProm):
				pCaster.setHasPromotion(iProm, False)
			else:
				infoProm = gc.getPromotionInfo(iProm)
				iBonus = infoProm.getBonusPrereq()
				if iBonus != -1:
					if gc.getBonusInfo(iBonus).isMana():
						pCaster.setHasPromotion(iProm, False)
						if pCaster.canAcquirePromotion(iProm):
							pCaster.setHasPromotion(iProm, True)

						# iPrereqOr1 = infoProm.getPrereqOrPromotion1()
						# if iPrereqOr1 in lChanneling:
							# if infoUnitG.getFreePromotions(iPrereqOr1):
								# pCaster.setHasPromotion(iProm, False)

def helpCasswallawnSplit(lpUnits, eSpell):
	szBuffer = ''
	pCaster = lpUnits[0]
	iGastrius = gc.getInfoTypeForString('UNIT_GASTRIUS')
	sHelp = helpUnitHelp(iGastrius)
	sHelp = localText.getText("TXT_KEY_SPELL_SUMMON_UNIT", (sHelp,))
	szBuffer += '\n' + sHelp + szBuffer
	liRemoveProms = [gc.getInfoTypeForString('PROMOTION_CASSWALLAWN')]
	infoUnit = gc.getUnitInfo(pCaster.getUnitType())
	infoUnitG = gc.getUnitInfo(iGastrius)
	lChanneling = [gc.getInfoTypeForString('PROMOTION_CHANNELING1'), gc.getInfoTypeForString('PROMOTION_CHANNELING2'), gc.getInfoTypeForString('PROMOTION_CHANNELING3'), gc.getInfoTypeForString('PROMOTION_CHANNELING4')]


	for iProm in xrange(gc.getNumPromotionInfos()):
		if not infoUnit.getFreePromotions(iProm):
			if infoUnitG.getFreePromotions(iProm):
				liRemoveProms.append(iProm)
			else:
				infoProm = gc.getPromotionInfo(iProm)
				iPrereqOr1 = infoProm.getPrereqOrPromotion1()
				if iPrereqOr1 in lChanneling:
					if infoUnitG.getFreePromotions(iPrereqOr1):
						liRemoveProms.append(iProm)

	szBuffer += helpTogglePromotionsBuffCasterIndex(lpUnits, eSpell, [], liRemoveProms, False)
	return szBuffer

def spellConjureCaptive(pCaster, eSpell):
	listConjurable = []
	listRemove = [gc.getInfoTypeForString('PROMOTION_HELD'),gc.getInfoTypeForString('PROMOTION_MAGIC_IMMUNE'),gc.getInfoTypeForString('PROMOTION_CANNOT_CAST')]


	if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_SAWOL_CAVEA')):
		iBound=gc.getInfoTypeForString('PROMOTION_CAPTUS_CAVEAE_SAWOL')
		listRemove.append(iBound)
		for pSluagh in PyPlayer(gc.getBARBARIAN_PLAYER()).getUnitList():
			if pSluagh.isHasPromotion(iBound):
				listConjurable.append(pSluagh)
	if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_ANGELORUM_CAVEA')):
		iBound=gc.getInfoTypeForString('PROMOTION_CAPTUS_CAVEAE_ANGELORUM')
		listRemove.append(iBound)
		for pSluagh in PyPlayer(gc.getBARBARIAN_PLAYER()).getUnitList():
			if pSluagh.isHasPromotion(iBound):
				listConjurable.append(pSluagh)

	if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_NETHER_BLADE')):
		iBound=gc.getInfoTypeForString('PROMOTION_NETHERBIND')
		listRemove.append(iBound)
		for pSluagh in PyPlayer(gc.getBARBARIAN_PLAYER()).getUnitList():
			if pSluagh.isHasPromotion(iBound):
				listConjurable.append(pSluagh)

	listConjurable = list(set(listConjurable))
	if len(listConjurable) > 0:
		pUnit = listConjurable[CyGame().getSorenRandNum(len(listConjurable), "Conjure Spirit")]

		sName = pUnit.getName()[:pUnit.getName().find("'s Sluagh")]
		iUnit = pUnit.getScenarioCounter()
		if not -1 < iUnit < gc.getNumUnitInfos():
			iUnit = gc.getInfoTypeForString('UNIT_IMP')

		iPlayer = pCaster.getOwner()
		pPlayer = gc.getPlayer(iPlayer)
		pPlot = pCaster.plot()

		newUnit = pPlayer.initUnit(iUnit, pPlot.getX(), pPlot.getY(), UnitAITypes.UNITAI_HERO, DirectionTypes.DIRECTION_SOUTH)
		cf.removeAffinities(newUnit)
		newUnit.convert(pUnit)


		for iProm in listRemove:
			if not gc.getUnitInfo(iUnit).getFreePromotions(iProm):
				newUnit.setHasPromotion(iProm, False)

		for iProm in xrange(gc.getNumPromotionInfos()):
			if gc.getPromotionInfo(iProm).isEquipment():
				newUnit.setHasPromotion(iProm, False)

		newUnit.setName(sName)
		newUnit.setSummoner(pCaster.getID())

