def spellConsumeSoul(pCaster, eSpell=-1):
	pPlot = pCaster.plot()
	if pPlot.isCity():
		pCity = pPlot.getPlotCity()
		if pCity.getPopulation() > 1:
			iPlayer = pCaster.getOwner()
			pPlayer = gc.getPlayer(iPlayer)
			pPlayer.setAlignment(gc.getInfoTypeForString('ALIGNMENT_EVIL'))
			pCaster.changeImmortal(1)
			pCaster.setMadeAttack(False)
			pCaster.setHasCasted(False)
			pCity.changeHurryAngerTimer(3)
			pPlayer2 = gc.getPlayer(pCity.getOriginalOwner())
			iPlayer = pCaster.getOwner()
			pPlayer2.AI_changeAttitudeExtra(iPlayer, -1)


			if pCity.isProductionUnit():
				if pCity.getOccupationTimer() > 0 or pPlayer.getAnarchyTurns() > 0:
					iUnit = pCity.getProductionUnit()
					if iUnit == -1:

						for j in xrange(pCity.getOrderQueueLength()):
							iOrderData = pCity.getOrderFromQueue(j)
							if iOrderData.eOrderType == OrderTypes.ORDER_TRAIN:
								pCity.popOrder(j, True, True)
								iUnit = iOrderData.iData1
								pCity.pushOrder(OrderTypes.ORDER_TRAIN, iUnit, -1, False, False, False, True)
								break



					iProduction = pCity.getUnitProduction(iUnit)
					iProduction += pCity.getHurryAngerTimer()+ pCity.getOccupationTimer() + pPlayer.getAnarchyTurns()
					pCity.setUnitProduction(iUnit, iProduction)
					while pCity.getProductionNeeded() < iProduction:
						newUnit = pPlayer.initUnit(iUnit, pCity.getX(), pCity.getY(), UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
						pCity.applyBuildEffects(newUnit)
						iProduction -= pCity.getProductionNeeded()

						for j in xrange(1,pCity.getOrderQueueLength()):
							iOrderData = pCity.getOrderFromQueue(j)
							if iOrderData.eOrderType == OrderTypes.ORDER_TRAIN:
								pCity.popOrder(j, True, True)
								iUnit = iOrderData.iData1
								pCity.pushOrder(OrderTypes.ORDER_TRAIN, iUnit, -1, False, False, False, True)
								break

						pCity.setUnitProduction(iUnit, iProduction)


def helpConsumeSoul(lpUnits, eSpell=-1):
	szBuffer = ''
	pCaster = lpUnits[0]
	pPlot = pCaster.plot()
	if pPlot.isCity():
		pCity = pPlot.getPlotCity()
		iPlayer = pCaster.getOwner()
		if pCity.getOwner() == iPlayer:
			pPlayer = gc.getPlayer(iPlayer)
			sNameCity = "<color=%d,%d,%d,%d>%s</color>" %(pPlayer.getPlayerTextColorR(), pPlayer.getPlayerTextColorG(), pPlayer.getPlayerTextColorB(), pPlayer.getPlayerTextColorA(), pCity.getName() )
			iPop = pCity.getPopulation()
