def reqContainPlague(pCaster, eSpell):

	listPlagues = [	gc.getInfoTypeForString('PROMOTION_PLAGUED'),
					gc.getInfoTypeForString('PROMOTION_PLAGUE_CARRIER'),
					gc.getInfoTypeForString('PROMOTION_DISEASED'),
					gc.getInfoTypeForString('PROMOTION_POISONED'),
					gc.getInfoTypeForString('PROMOTION_WITHERED'),
					gc.getInfoTypeForString('PROMOTION_GALLOWBLIGHT')
					]
	pPlot = pCaster.plot()
	iX = pPlot.getX()
	iY = pPlot.getY()
	for iiX in xrange(iX-2, iX+ 3, 1):
		for iiY in xrange(iY-2, iY+ 3, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			if pPlot.isCity():
				pCity = pPlot.getPlotCity()
				if pCity.getEspionageHealthCounter() > 0:
					return True
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				for iProm in listPlagues:
					if pUnit.isHasPromotion(iProm):
						return True
	return False


