def reqConvertCityBasium(pCaster, eSpell=-1):
	pCity = pCaster.plot().getPlotCity()
	if pCity.getOwner() != pCaster.getOwner() and pCaster.getTeam() == pCity.getTeam():
		if pCity.isCapital():
			return False
		if not pCity.isHuman():
			if pCaster.isHuman():
				return True
			elif pCity.isSettlement():
				return True
			elif 2*gc.getPlayer(pCaster.getOwner()).getNumCities() < gc.getPlayer(pCity.getOwner()).getNumCities():
				return True
	return False

def spellConvertCityBasium(pCaster, eSpell=-1):
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	pCity = pCaster.plot().getPlotCity()
	iPlayerCity = pCity.getOwner()
	iCulture = pCity.getCulture(iPlayerCity)
	pPlayer.acquireCity(pCity, False, True)
	pCity = pCaster.plot().getPlotCity()
	pCity.changeCulture(iPlayer, iCulture, True)
	if pCity.getCivilizationType() == gc.getInfoTypeForString('CIVILIZATION_INFERNAL'):
		pCity.setCivilizationType(gc.getInfoTypeForString('CIVILIZATION_MERCURIANS'))
		CyInterface().setDirty(InterfaceDirtyBits.CityInfo_DIRTY_BIT, True)

def reqConvertCityDemonLord(pCaster, eSpell=-1):
	if not pCaster.isAvatarOfCivLeader():
		return False
	if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_GELA')):
		return False
	return reqConvertCityRantine(pCaster, eSpell)

def reqConvertCityGela(pCaster, eSpell=-1):
	pPlot = pCaster.plot()
	pCity = pPlot.getPlotCity()
	if pCity.isCapital():
		return False
	if pCity.getOwner() == pCaster.getOwner():
		return False
	iAV = gc.getInfoTypeForString('RELIGION_THE_ASHEN_VEIL')
	if not pCity.isHasReligion(iAV):
		return False
	pPlayer2 = gc.getPlayer(pCity.getOwner())
	if pPlayer2.getStateReligion() == iAV:
		return False
	for i in xrange(pPlot.getNumUnits()):
		pUnit = pPlot.getUnit(i)
		if pUnit.getOwner() == pCity.getOwner():
			if pUnit.baseCombatStr() > pCaster.baseCombatStr():
				return False
	return True

def spellConvertCityGela(pCaster, eSpell=-1):
	pCity = pCaster.plot().getPlotCity()
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	pPlayer.acquireCity(pCity, False, False)

def reqConvertCityRantine(pCaster, eSpell=-1):
	if pCaster.isBarbarian():
		return False
	pPlot = pCaster.plot()
	if not pPlot.getPlotCity().isBarbarian():
		return False
	for i in xrange(pPlot.getNumUnits()):
		pUnit = pPlot.getUnit(i)
		if pUnit.isBarbarian():
			if pUnit.baseCombatStr() > pCaster.baseCombatStr():
				return False
	return True

def spellConvertCityRantine(pCaster, eSpell=-1):
	pPlot = pCaster.plot()
	iX = pPlot.getX()
	iY = pPlot.getY()
	pCity = pPlot.getPlotCity()
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	pPlayer.acquireCity(pCity, False, False)
	for i in xrange(pPlot.getNumUnits()):
		pUnit = pPlot.getUnit(i)
		if pUnit.isBarbarian():
			if not (isWorldUnitClass(pUnit.getUnitClassType()) or isNationalUnitClass(pUnit.getUnitClassType())):
				newUnit = pPlayer.initUnit(pUnit.getUnitType(), iX, iY, UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
				cf.removeAffinities(newUnit)
				newUnit.convert(pUnit)

def reqConvertFort(pCaster, eSpell=-1):
	if gc.getGame().isOption(GameOptionTypes.GAMEOPTION_ADVANCED_TACTICS):
		pPlot = pCaster.plot()
		if pPlot.isOwned():
			iImprovement = pPlot.getImprovementType()
			if iImprovement != -1:
				if gc.getImprovementInfo(iImprovement).isActsAsCity():
					pPlayer = gc.getPlayer(pPlot.getOwner())
					if pCaster.getTeam() == pPlot.getTeam():
						if pCaster.getOwner() != pPlot.getOwner():
							return True
	return False

def spellConvertFort(pCaster, eSpell=-1):
	pPlot = pCaster.plot()
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	pPlot.setOwner(iPlayer)
	iImprovement = pPlot.getImprovementType()
	if iImprovement == gc.getInfoTypeForString('IMPROVEMENT_HELLFIRE'):
		if pPlot.isBarbarian():
			pass
		elif pPlayer.getCivilizationType() == gc.getInfoTypeForString('CIVILIZATION_INFERNAL'):
			pass
		elif pPlayer.getStateReligion() == gc.getInfoTypeForString('RELIGION_THE_ASHEN_VEIL'):
			pass
		else:
			pPlot.setOwner(gc.getBARBARIAN_PLAYER())
	elif iImprovement == gc.getInfoTypeForString('IMPROVEMENT_CITADEL'):
		if pPlayer.getStateReligion() == gc.getInfoTypeForString('RELIGION_THE_EMPYREAN'):
			pPlot.setImprovementType(gc.getInfoTypeForString('IMPROVEMENT_CITADEL_OF_LIGHT'))
	elif iImprovement == gc.getInfoTypeForString('IMPROVEMENT_CITADEL_OF_LIGHT'):
		if pPlayer.getStateReligion() != gc.getInfoTypeForString('RELIGION_THE_EMPYREAN'):
			pPlot.setImprovementType(gc.getInfoTypeForString('IMPROVEMENT_CITADEL'))

