def helpCraftArtifact(lpUnits, eSpell=-1, iNum = 1):
	pCaster = lpUnits[0]
	pPlot = pCaster.plot()
	iBonus = pPlot.getBonusType(-1)
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	szBuffer = ''
	listItems = []
	iTotal = 0
	bChanneling4 = False
	bAffinity = False
	for pCaster in lpUnits:
		if pCaster.canCast(eSpell, True):
			iTotal += iNum
			if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_TWINCAST')):
				iTotal += iNum
			if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_CHANNELING4')):
				bChanneling4 = True
			if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_AFFINITY_ENCHANTMENT')):
				bChanneling4 = True

	if iBonus !=-1:
		for iUnit in range(gc.getNumUnitInfos()):
			info = gc.getUnitInfo(iUnit)
			if info.isObject():
				iUnitClass = info.getUnitClassType()
				if pPlayer.isUnitClassMaxedOut(iUnitClass, 1) or CyGame().isUnitClassMaxedOut(iUnitClass, 1):
					continue
				if isWorldUnitClass(iUnitClass):
					if not bChanneling4:
						continue
				if info.getPrereqAndBonus() == iBonus:
					listItems.append(iUnit)

	if len(listItems) == 0 and pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_AFFINITY_ENCHANTMENT')):
		listItems = []
		for iUnit in range(gc.getNumUnitInfos()):
			info = gc.getUnitInfo(iUnit)
			if info.isObject():
				iUnitClass = info.getUnitClassType()
				if pPlayer.isUnitClassMaxedOut(iUnitClass, 1) or CyGame().isUnitClassMaxedOut(iUnitClass, 1):
					continue
				if isWorldUnitClass(iUnitClass):
					continue
				iBonus = info.getPrereqAndBonus()
				if iBonus != -1:
					if cf.getNumSupplimentalManaUnit(iBonus, pCaster) < 1:
						continue
				listItems.append(iUnit)


	if len(listItems) > 0:
		listItems = list(set(listItems))
		if len(listItems) > 0:
			sList = ''
			while len(listItems) > 0:
				iItem= listItems.pop(0)
				sList += gc.getUnitInfo(iItem).getDescription()
				if len(listItems) > 0:
					if len(listItems) == 1:
						sList += " or "+ '\n' + localText.getText("[TAB][ICON_BULLET]", ( ))
					else:
						sList += ", "+ '\n' + localText.getText("[TAB][ICON_BULLET]", ( ))
			szBuffer += localText.getText("TXT_KEY_SPELL_CRAFT", (iNum, sList, ))

	else:
		szBuffer += localText.getText("TXT_KEY_SPELL_CRAFT_ARTIFACT_PEDIA", ( ))


	return szBuffer

