def spellHallowGraveYard(pCaster, eSpell=1):
	pPlot = pCaster.plot()
	pPlot.setImprovementType(gc.getInfoTypeForString('IMPROVEMENT_GRAVEYARD'))
	CyGame().changeGlobalCounter(-1)
	iHallowed = gc.getInfoTypeForString('FEATURE_HALLOWED_GROUND')
	iTimer = max(7, pCaster.getLevel() + cf.getNumBonusEffective(pCaster.getOwner(), gc.getInfoTypeForString('BONUS_MANA_DEATH'), pCaster))
	iSluagh = gc.getInfoTypeForString('UNIT_SLUAGH')
	bTombWarden =(pCaster.getUnitType() == gc.getInfoTypeForString('UNIT_TOMB_WARDEN'))
	for i in xrange(pPlot.getNumUnits()):
		pSluagh = pPlot.getUnit(i)
		if pSluagh.getUnitType() == iSluagh:
			if bTombWarden:
				pCaster.changeFreePromotionPick(1)
			iDuration = pSluagh.getDuration()
			if iDuration > 0:
				pSluagh.setDuration(iDuration+ iTimer)
	if pPlot.getFeatureType() != iHallowed:
		iTimer = 3 + CyGame().getSorenRandNum(iTimer, "Hallow Grave")
		pPlot.setTempFeatureType(iHallowed, 0, iTimer)

def reqHallowGraveYard(pCaster, eSpell=1):
	pPlot = pCaster.plot()
	if pPlot.getImprovementType() in [gc.getInfoTypeForString('IMPROVEMENT_GRAVEYARD'), gc.getInfoTypeForString('IMPROVEMENT_BARROW'), gc.getInfoTypeForString('IMPROVEMENT_RUINS'), gc.getInfoTypeForString('IMPROVEMENT_CITY_RUINS'), gc.getInfoTypeForString('IMPROVEMENT_DUNGEON')]:
		if pPlot.getFeatureType() == gc.getInfoTypeForString('FEATURE_HALLOWED_GROUND'):
			return False
		return True
	return False

def reqCreateDenBear(pCaster, eSpell=-1):
	if gc.getGame().isOption(GameOptionTypes.GAMEOPTION_NO_LAIRS):
		return False
	iImprovement = gc.getInfoTypeForString('IMPROVEMENT_BEAR_DEN')
	if pCaster.getDamage() > 0:
		return False
	pPlot = pCaster.plot()
	if pPlot.isOwned():
		return False
	if pPlot.getNumUnits() != 1:
		return False
	if pPlot.getImprovementType() != -1:
		return False
	if not pPlot.canHaveImprovement(iImprovement, pCaster.getTeam(), True):
		return False
	iX = pPlot.getX()
	iY = pPlot.getY()
	for iiX in xrange(iX-4, iX+ 5, 1):
		for iiY in xrange(iY-4, iY+ 5, 1):
			pPlot2 = CyMap().plot(iiX, iiY)
