def reqCrewBuccaneers(pCaster, eSpell=-1):
	pPlot = pCaster.plot()
	if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_BUCCANEERS')):
		return False
	## Make sure we dont end up with more cargo than cargo space
	if pCaster.isFull():
		if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_SKELETON_CREW')):
			return False
	if pCaster.maxMoves() < 2:
		return False
	if pCaster.baseCombatStr() < 1:
		return False

	if not pCaster.isHuman():
		if pCaster.getUnitAIType() == gc.getInfoTypeForString('UNITAI_ATTACK_SEA'):
			if gc.getUnitInfo(pCaster.getUnitType()).getMoves() > 2:
				return True
		return False
	return True

def reqCrewLongshoremen(pCaster, eSpell=-1):
	pPlot = pCaster.plot()
	if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_LONGSHOREMEN')):
		return False

	## Make sure we dont end up with more cargo than cargo space
	req_cargo = 1
	if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_SKELETON_CREW')):
		req_cargo += 1
	if pCaster.cargoSpaceAvailable(-1, gc.getInfoTypeForString('DOMAIN_LAND')) < req_cargo:
		return False

	if pCaster.baseCombatStr() < 1:
		return False

	if not pCaster.isHuman():
		if not pCaster.isFull():
			if pCaster.getUnitAIType() in [gc.getInfoTypeForString('UNITAI_ESCORT_SEA'), gc.getInfoTypeForString('UNITAI_EXPLORE_SEA'), gc.getInfoTypeForString('UNITAI_MISSIONARY_SEA')]:
				return True
		return False
	return True

