def spellReleaseSluagh(pCaster, eSpell=-1, iRange = 0):
	if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_CHANNELING3')):
		iRange +=1
	if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_CHANNELING4')):
		iRange +=1
	bPlayer = gc.getPlayer(gc.getBARBARIAN_PLAYER())
	iUndead = gc.getInfoTypeForString('PROMOTION_UNDEAD')
	iAffinity = gc.getInfoTypeForString('PROMOTION_AFFINITY_DEATH')
	iSluagh = gc.getInfoTypeForString('UNIT_SLUAGH')
	iX = pCaster.getX()
	iY = pCaster.getY()
	for iiX in xrange(iX-iRange, iX+ 1+ iRange, 1):
		for iiY in xrange(iY-iRange, iY+ 1+ iRange, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if pUnit.getRace() == iUndead:
					if pUnit.isImmuneToSpell(pCaster, eSpell):continue
					if pUnit.isResisted(pCaster, eSpell):continue
					#if pUnit.getSummoner() == -1 and isLimitedUnitClass(pUnit.getUnitClassType()):continue
					#if pUnit.isHasPromotion(iAffinity):continue
					lRemove = [iUndead,iAffinity]
					iUnit = pUnit.getUnitType()
					infoU = gc.getUnitInfo(iUnit)
					if infoU.getFreePromotions(iUndead):
						for iProm in xrange(gc.getNumPromotionInfos()):
							if infoU.getFreePromotions(iProm):
								lRemove.append(iProm)
					iUnit = pUnit.getScenarioCounter()
					if not -1 < iUnit < gc.getNumUnitInfos():
						iUnit = gc.getInfoTypeForString('UNIT_WARRIOR')
					infoU = gc.getUnitInfo(iUnit)
					if infoU.getFreePromotions(iUndead):
						continue
					newUnit = bPlayer.initUnit(iSluagh, pPlot.getX(), pPlot.getY(), UnitAITypes.UNITAI_HERO, DirectionTypes.DIRECTION_SOUTH)
					newUnit.convert(pUnit)
					for iProm in lRemove:
						newUnit.setHasPromotion(iProm, False)
					newUnit.setScenarioCounter(iUnit)


