def reqDispelMagic(pCaster, eSpell=-1, iRange = 1):
	if pCaster.canDispel(eSpell):
		return True

	pPlot = pCaster.plot()
	if pPlot.getTeam() == pCaster.getTeam() or pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_AFFINITY_METAMAGIC')):
		iBonus = pPlot.getBonusType(-1)
		if iBonus not in [-1, gc.getInfoTypeForString('BONUS_MANA')]:
			if gc.getBonusInfo(iBonus).isMana():
				if pPlot.isCity():
					return False
				iImp = pPlot.getImprovementType()
				if iImp == -1:
					return True
				elif iImp == gc.getInfoTypeForString('IMPROVEMENT_DRAGON_BONES'):
					return False
				elif not gc.getImprovementInfo(iImp).isUnique():
					return True

	iWard = gc.getInfoTypeForString('IMPROVEMENT_RING_OF_WARDING')
	iX = pCaster.getX()
	iY = pCaster.getY()
	for iiX in xrange(iX-iRange, iX+ 1+ iRange, 1):
		for iiY in xrange(iY-iRange, iY+ 1+ iRange, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			if pPlot.getImprovementType() == iWard:
				iAffinity = gc.getInfoTypeForString('PROMOTION_AFFINITY_FORCE')
				iChanneling2 = gc.getInfoTypeForString('PROMOTION_CHANNELING2')
				for i in xrange(pPlot.getNumUnits()):
					pUnit = pPlot.getUnit(i)
					if pUnit.isHasPromotion(iAffinity) and pUnit.isHasPromotion(iChanneling2):
						if pCaster.getOwner() == pUnit.getOwner():
							break
				else:
					return True
			if pPlot.isCity():
				pCity = pPlot.getPlotCity()
				if pCaster.getTeam() != pCity.getTeam():
					for i in xrange(gc.getNumBuildingInfos()):
						if gc.getBuildingInfo(i).isRequiresCaster():
							return True
	return False

def spellDispelMagic(pCaster, eSpell=-1, iRange = 1):
	pPlot = pCaster.plot()
	iBonus = pPlot.getBonusType(-1)
	if not pPlot.isCity():
		if iBonus not in [-1, gc.getInfoTypeForString('BONUS_MANA')]:
			if gc.getBonusInfo(iBonus).isMana():
				iImp = pPlot.getImprovementType()
				if iImp == -1:
					pPlot.setBonusType(gc.getInfoTypeForString('BONUS_MANA'))
				elif iImp == gc.getInfoTypeForString('IMPROVEMENT_DRAGON_BONES'):
					pass
				elif not gc.getImprovementInfo(iImp).isUnique():
					pPlot.setBonusType(gc.getInfoTypeForString('BONUS_MANA'))
					if gc.getImprovementInfo(iImp).isPermanent():
						pPlot.setImprovementType(-1)

	lSpellBuildings = []
	for i in xrange(gc.getNumBuildingInfos()):
		if gc.getBuildingInfo(i).isRequiresCaster():
			lSpellBuildings.append(i)

	iWard = gc.getInfoTypeForString('IMPROVEMENT_RING_OF_WARDING')
	sWard = gc.getImprovementInfo(iWard).getDescription()
	iX = pCaster.getX()
	iY = pCaster.getY()
	for iiX in xrange(iX-iRange, iX+ 1+ iRange, 1):
		for iiY in xrange(iY-iRange, iY+ 1+ iRange, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			if pPlot.getImprovementType() == iWard:
				iAffinity = gc.getInfoTypeForString('PROMOTION_AFFINITY_FORCE')
				iChanneling2 = gc.getInfoTypeForString('PROMOTION_CHANNELING2')
				for i in xrange(pPlot.getNumUnits()):
					pUnit = pPlot.getUnit(i)
					if pUnit.isHasPromotion(iAffinity) and pUnit.isHasPromotion(iChanneling2):
						if pCaster.getOwner() == pUnit.getOwner():
							break
				else:
					if CyGame().getSorenRandNum(10, "Dispell " + str(sWard) ) < 7:
						pPlot.setMinLevel(0)
						iReal = pPlot.getRealImprovementType()
						if iReal == iWard:
							pPlot.setImprovementType(-1)
						else:
							pPlot.setImprovementType(iReal)

			if pPlot.isCity():
				pCity = pPlot.getPlotCity()
				if pCaster.getTeam() != pCity.getTeam():
					for iBuilding in lSpellBuildings:
						if pCity.getNumRealBuilding(iBuilding) > 0:
							if CyGame().getSorenRandNum(10, "Dispell " + str(gc.getBuildingInfo(iBuilding).getDescription())) < 7:
								pCity.setNumRealBuilding(iBuilding, 0)

def helpDispelMagic(lpUnits, eSpell=-1, iRange = 1):
	szBuffer = ''
	pCaster = lpUnits[0]
	iTeam = pCaster.getTeam()
	eTeam = gc.getTeam(iTeam)
	iX = pCaster.getX()
	iY = pCaster.getY()
	iWard = gc.getInfoTypeForString('IMPROVEMENT_RING_OF_WARDING')
	sWard = gc.getImprovementInfo(iWard).getDescription()
	if pCaster.canDispel(eSpell):
		lProms = []
		for iProm in xrange(gc.getNumPromotionInfos()):
			info = gc.getPromotionInfo(iProm)
			if info.isDispellable():
				lTargets = []
				bGood = info.getAIWeight() > 0

				for iiX in xrange(iX-iRange, iX+ 1+ iRange, 1):
					for iiY in xrange(iY-iRange, iY+ 1+ iRange, 1):
						pPlot = CyMap().plot(iiX, iiY)
						if pPlot.isNone():continue
						for i in xrange(pPlot.getNumUnits()):
							pUnit = pPlot.getUnit(i)
							# if pUnit.isInvisible(iTeam, False):continue
							if pUnit.isHasPromotion(iProm):
								if pUnit.isImmuneToSpell(pCaster, eSpell):continue
								iTeam2 = pUnit.getTeam()
								if (bGood and eTeam.isAtWar(iTeam2)) or (not bGood and iTeam == iTeam2):
									lTargets.append(pUnit)
					lTargets = list(set(lTargets))
					iCount = len(lTargets)
					if iCount > 0:
						sRemove = localText.getText("TXT_KEY_HELP_SPELL_MAY_REMOVE", ())
						szBuffer = sRemove + CyGameTextMgr().getPromotionHelp(iProm, False)
						if iCount == 1:
							pUnit = lTargets.pop(0)
							pPlayer = gc.getPlayer(pUnit.getOwner())
							sList = cf.getNameWithColorScheme(pUnit, pUnit.isInvisible(pCaster.getTeam(), False))
							szBuffer += localText.getText("TXT_KEY_HELP_SPELL_TARGETS_THIS", (sList, ))
						else:
							sList = ''
							while len(lTargets) > 0:
								pUnit = lTargets.pop(0)
								pPlayer = gc.getPlayer(pUnit.getOwner())
								sList += cf.getNameWithColorScheme(pUnit, pUnit.isInvisible(pCaster.getTeam(), False))
								if len(lTargets) > 0:
									if len(lTargets) == 1:
										sList += " and "
									else:
										sList += ", "
							szBuffer += localText.getText("TXT_KEY_HELP_SPELL_TARGETS_THESE_COUNT_LIST", (iCount, sList, ))

	for iiX in xrange(iX-iRange, iX+ 1+ iRange, 1):
		for iiY in xrange(iY-iRange, iY+ 1+ iRange, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			if pPlot.getImprovementType() == iWard:
				iAffinity = gc.getInfoTypeForString('PROMOTION_AFFINITY_FORCE')
				iChanneling2 = gc.getInfoTypeForString('PROMOTION_CHANNELING2')
				for i in xrange(pPlot.getNumUnits()):
					pUnit = pPlot.getUnit(i)
					if pUnit.isHasPromotion(iAffinity) and pUnit.isHasPromotion(iChanneling2):
						if pCaster.getOwner() == pUnit.getOwner():
							break
				else:
					szBuffer += localText.getText("TXT_KEY_HELP_SPELL_MAY_REMOVE_STUFF", (sWard, ))

			if pPlot.isCity():
				pCity = pPlot.getPlotCity()
				if pCaster.getTeam() != pCity.getTeam():
					for iBuilding in xrange(gc.getNumBuildingInfos()):
						if gc.getBuildingInfo(iBuilding).isRequiresCaster():
							if pCity.getNumBuilding(iBuilding) > 0:
								pPlayer = gc.getPlayer(pCity.getOwner())
								sPlace = " from <color=%d,%d,%d,%d>%s</color>" %(pPlayer.getPlayerTextColorR(), pPlayer.getPlayerTextColorG(), pPlayer.getPlayerTextColorB(), pPlayer.getPlayerTextColorA(), pCity.getName() )+ ': \n'
								sHelp = helpBuildingHelp(iBuilding, pCity)
								szBuffer += localText.getText("TXT_KEY_HELP_SPELL_REMOVES", ()) + sPlace + sHelp

	pPlot = pCaster.plot()
	iBonus = pPlot.getBonusType(-1)
	if pPlot.getTeam() == pCaster.getTeam() or pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_AFFINITY_METAMAGIC')):
		if iBonus not in [-1, gc.getInfoTypeForString('BONUS_MANA')]:
			infoB = gc.getBonusInfo(iBonus)
			if infoB.isMana():
				iImp = pPlot.getImprovementType()
				if iImp == -1:
					szBuffer += localText.getText("TXT_KEY_HELP_SPELL_CHANGE_A_TO_B", (infoB.getDescription(), gc.getBonusInfo(gc.getInfoTypeForString('BONUS_MANA')).getDescription(), ))
				elif iImp == gc.getInfoTypeForString('IMPROVEMENT_DRAGON_BONES'):
					pass
				else:
					infoI = gc.getImprovementInfo(iImp)
					if not infoI.isUnique():
						szBuffer += localText.getText("TXT_KEY_HELP_SPELL_CHANGE_A_TO_B", (infoB.getDescription(), gc.getBonusInfo(gc.getInfoTypeForString('BONUS_MANA')).getDescription(), ))
						if infoI.isPermanent():
							szBuffer += localText.getText("TXT_KEY_HELP_SPELL_REMOVES_STUFF", (infoI.getDescription(),))
	return szBuffer


