def spellDominationGreater(pCaster, eSpell):
	iLevel = pCaster.getLevel()
	while iLevel > 0:
		if reqDomination(pCaster, eSpell):
			pDominated = spellDomination(pCaster, eSpell)
			if pDominated == -1:
				iLevel -= 1
			else:
				iLevel -= pDominated.getLevel()
		else:
			break

def reqDomination(pCaster, eSpell=-1):
	iX = pCaster.getX()
	iY = pCaster.getY()
	iResistMax = 99
	if not pCaster.isHuman():
		iResistMax = 70
	iTeam = pCaster.getTeam()
	eTeam = gc.getTeam(iTeam)
	for iiX in xrange(iX-1, iX+ 2, 1):
		for iiY in xrange(iY-1, iY+ 2, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if pUnit.isImmuneToSpell(pCaster, eSpell):continue
				if pUnit.isHasPromotion(gc.getInfoTypeForString('PROMOTION_MASK_OF_ESUS')):continue
				if pUnit.isDelayedDeath():continue
				iResist = pUnit.getResistChance(pCaster, gc.getInfoTypeForString('SPELL_DOMINATION'))
				if iResist < iResistMax:
					return True
	return False

def spellDomination(pCaster, eSpell=1):
	newUnit = -1
	iLairGuardian = gc.getInfoTypeForString('PROMOTION_LAIR_GUARDIAN')
	iX = pCaster.getX()
	iY = pCaster.getY()
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iResistMax = 99
	iBestValue = 0
	pBestUnit = -1
	if not pCaster.isHuman():
		iResistMax = 20
	iTeam = pCaster.getTeam()
	eTeam = gc.getTeam(iTeam)
	for iiX in xrange(iX-1, iX+ 2, 1):
		for iiY in xrange(iY-1, iY+ 2, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				iValue = 0
				if pUnit.isAlive():
					if pUnit.isDelayedDeath():continue
					if pUnit.isImmuneToSpell(pCaster, eSpell):continue
					if pUnit.isHasPromotion(gc.getInfoTypeForString('PROMOTION_MASK_OF_ESUS')):continue
					iResist = pUnit.getResistChance(pCaster, eSpell)
					if iResist < iResistMax:
						iValue = pUnit.baseCombatStr() * 10
						iValue += (100 - iResist)
						if iValue > iBestValue:
							iBestValue = iValue
							pBestUnit = pUnit
	if pBestUnit != -1:
		pPlot = pCaster.plot()
		if not pBestUnit.isResisted(pCaster, eSpell):
			pPlayerU = gc.getPlayer(pBestUnit.getOwner())
			sName = cf.getNameWithColorScheme(pBestUnit)
			if pBestUnit.isHasPromotion(gc.getInfoTypeForString('PROMOTION_LOYALTY')):
				CyInterface().addMessage(pBestUnit.getOwner(), True, 25, localText.getText("TXT_KEY_MESSAGE_DOMINATION_LOYALTY", (sName, )), '', 1, 'Art/Interface/Buttons/Spells/Domination.dds', ColorTypes(7), pBestUnit.getX(), pBestUnit.getY(), True, True)
				CyInterface().addMessage(pCaster.getOwner(), True, 25, localText.getText("TXT_KEY_MESSAGE_DOMINATION_LOYALTY", (sName, )), '', 1, 'Art/Interface/Buttons/Spells/Domination.dds', ColorTypes(8), pPlot.getX(), pPlot.getY(), True, True)
				pBestUnit.kill(False, 0)
			else:
				CyInterface().addMessage(pBestUnit.getOwner(), True, 25, localText.getText("TXT_KEY_MESSAGE_DOMINATION", (sName, )), '', 1, 'Art/Interface/Buttons/Spells/Domination.dds', ColorTypes(7), pBestUnit.getX(), pBestUnit.getY(), True, True)
				CyInterface().addMessage(pCaster.getOwner(), True, 25, localText.getText("TXT_KEY_MESSAGE_DOMINATION_ENEMY", (sName, )), '', 1, 'Art/Interface/Buttons/Spells/Domination.dds', ColorTypes(8), pPlot.getX(), pPlot.getY(), True, True)
				newUnit = pPlayer.initUnit(pBestUnit.getUnitType(), pPlot.getX(), pPlot.getY(), UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
				cf.removeAffinities(newUnit)
				newUnit.convert(pBestUnit)
##				newUnit.changeImmobileTimer(1)
##				if not (newUnit.isHasPromotion(gc.getInfoTypeForString('PROMOTION_SPIRIT3')) or newUnit.isHasPromotion(gc.getInfoTypeForString('PROMOTION_AFFINITY_SPIRIT'))):
##					newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_CRAZED'), True)
				newUnit.setHasPromotion(iLairGuardian, False)
				newUnit.setSummoner(pCaster.getID())
				if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_HIDDEN_NATIONALITY')):
					newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_HIDDEN_NATIONALITY'), False)
		else:
			CyInterface().addMessage(pCaster.getOwner(), True, 25, localText.getText("TXT_KEY_MESSAGE_DOMINATION_FAILED", ()), '', 1, 'Art/Interface/Buttons/Spells/Domination.dds', ColorTypes(7), pPlot.getX(), pPlot.getY(), True, True)
			if not (pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_SPIRIT3')) or pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_AFFINITY_SPIRIT'))):
				pCaster.setHasPromotion(gc.getInfoTypeForString('PROMOTION_CRAZED'), True)
	return newUnit

