def reqDominationUndead(pCaster, eSpell=-1):
	if reqNecromancyAllowed(pCaster):
		iX = pCaster.getX()
		iY = pCaster.getY()
		iPlayer = pCaster.getOwner()
		iResistMax = 95
		iUndead = gc.getInfoTypeForString('PROMOTION_UNDEAD')
		iRebel = gc.getInfoTypeForString('PROMOTION_REBEL')
		if not pCaster.isHuman():
			iResistMax = 20
		iTeam = pCaster.getTeam()
		eTeam = gc.getTeam(iTeam)
		iRange = 3
		for iiX in xrange(iX-iRange, iX + iRange+1, 1):
			for iiY in xrange(iY-iRange, iY+ iRange+1, 1):
				pPlot = CyMap().plot(iiX, iiY)
				if pPlot.isNone():continue
				if pPlot.at(iX, iY):continue
				if plotDistance(iX, iY, iiX, iiY) > iRange:continue
				for i in xrange(pPlot.getNumUnits()):
					pUnit = pPlot.getUnit(i)
					if pUnit.getRace() != iUndead:continue
					if isWorldUnitClass(pUnit.getUnitClassType()):continue
					if pUnit.isDelayedDeath():continue
					if iTeam == pUnit.getTeam():
						if pUnit.isHasPromotion(iRebel):
							return True
					elif pUnit.isHasPromotion(iRebel) or eTeam.isAtWar(pUnit.getTeam()) or pCaster.isHiddenNationality() or pUnit.isHiddenNationality():
						if pUnit.isImmuneToSpell(pCaster, eSpell):continue
						iResist = pUnit.getResistChance(pCaster, eSpell)
						if iResist < iResistMax:
							return True
	return False

def spellDominationUndead(pCaster, eSpell=1):
	iLairGuardian = gc.getInfoTypeForString('PROMOTION_LAIR_GUARDIAN')
	iX = pCaster.getX()
	iY = pCaster.getY()
	cID = pCaster.getID()
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iResistMax = 95
	iUndead = gc.getInfoTypeForString('PROMOTION_UNDEAD')
	iRebel = gc.getInfoTypeForString('PROMOTION_REBEL')
	if not pCaster.isHuman():
		iResistMax = 20
	iTeam = pPlayer.getTeam()
	eTeam = gc.getTeam(iTeam)
	iRange = 2
	for iiX in xrange(iX-iRange, iX + iRange+1, 1):
		for iiY in xrange(iY-iRange, iY+ iRange+1, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			if pPlot.at(iX, iY):continue
			if plotDistance(iX, iY, iiX, iiY) > iRange:continue
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if pUnit.getRace() != iUndead:continue
				if pUnit.isDelayedDeath():continue
				if isWorldUnitClass(pUnit.getUnitClassType()):continue
				if iTeam == pUnit.getTeam():
					if pUnit.isHasPromotion(iRebel):
						pUnit.setHasPromotion(iRebel, False)
				elif pUnit.isHasPromotion(iRebel) or eTeam.isAtWar(pUnit.getTeam()) or pCaster.isHiddenNationality() or pUnit.isHiddenNationality():
					if pUnit.isImmuneToSpell(pCaster, eSpell):continue
					if effectResisted(pUnit, pCaster, eSpell):continue
					iPlayerU = pUnit.getOwner()
					if iPlayer != iPlayerU:
						pPlayerU = gc.getPlayer(iPlayerU)
						sName = cf.getNameWithColorScheme(pUnit, pUnit.isInvisible(pCaster.getTeam(), False))
						CyInterface().addMessage(iPlayerU, True, 25, localText.getText("TXT_KEY_MESSAGE_DOMINATION", (sName,)), '', 1, 'Art/Interface/Buttons/Spells/Call of the Grave.dds', ColorTypes(7), pUnit.getX(), pUnit.getY(), True, True)
						CyInterface().addMessage(iPlayer, True, 25, localText.getText("TXT_KEY_MESSAGE_DOMINATION_ENEMY", (sName,)), '', 1, 'Art/Interface/Buttons/Spells/Call of the Grave.dds', ColorTypes(8), pPlot.getX(), pPlot.getY(), True, True)
					newUnit = pPlayer.initUnit(pUnit.getUnitType(), iX, iY, UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)

					cf.removeAffinities(newUnit)
					newUnit.convert(pUnit)
					newUnit.setHasPromotion(iLairGuardian, False)
					newUnit.setHasPromotion(iRebel, False)
					newUnit.setSummoner(cID)
					if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_HIDDEN_NATIONALITY')):
						newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_HIDDEN_NATIONALITY'), False)

