def reqDrownArmies(pCaster, eSpell=-1):
	pPlot = pCaster.plot()

	if pPlot.isWater() or pPlot.isAdjacentToWater():
		iX = pCaster.getX()
		iY = pCaster.getY()
		iPlayer = pCaster.getOwner()
		bNecromancy = reqNecromancyAllowed(pCaster)
		iTeam = pCaster.getTeam()
		eTeam = gc.getTeam(iTeam)
		iMelee = gc.getInfoTypeForString('UNITCOMBAT_MELEE')
		iCold = gc.getInfoTypeForString('DAMAGE_COLD')
		iSmoke = gc.getInfoTypeForString('IMPROVEMENT_SMOKE')
		iFlames = gc.getInfoTypeForString('FEATURE_FLAMES')
		for iiX in xrange(iX-1, iX+ 2, 1):
			for iiY in xrange(iY-1, iY+ 2, 1):
				pPlot = CyMap().plot(iiX, iiY)
				if pPlot.isNone():continue
				if pPlot.at(iX, iY):continue
				if pPlot.isWater() or pPlot.isAdjacentToWater():
					if pPlot.getNumUnits() > 0:
						if pPlot.isVisibleEnemyUnit(iPlayer):
							for i in xrange(pPlot.getNumUnits()):
								pUnit = pPlot.getUnit(i)
								if pUnit.getDamageTypeResist(iCold) < 100:
									if eTeam.isAtWar(pUnit.getTeam()) or pCaster.isHiddenNationality() or pUnit.isHiddenNationality():
										if pUnit.getDamage() < 75:
											return True
										if bNecromancy:
											if pUnit.isAlive():
												if pUnit.getUnitCombatType() == iMelee:
													if not pUnit.isImmortal():
														if pUnit.getDuration() == 0:
															if not isLimitedUnitClass(pUnit.getUnitClassType()):
																return True

					iImp = pPlot.getImprovementType()
					if iImp != -1:
						if iImp == iSmoke:
##							return True
							if pCaster.isHuman():
								return True
##							if pPlot.getOwner() == iPlayer:
##								return True
						elif not gc.getImprovementInfo(iImp).isPermanent():
##							return True
							if pCaster.isHuman():
								return True
							if pPlot.isOwned():
								if eTeam.isAtWar(pPlot.getTeam()):
									return True
					if pPlot.getFeatureType() == iFlames:
						return True

	return False


def spellDrownArmies(pCaster, eSpell=-1):

	pPlot = pCaster.plot()
	CyMapGenerator().doRiver(pPlot, CardinalDirectionTypes.NO_CARDINALDIRECTION)

	bNecromancy = reqNecromancyAllowed(pCaster) and pCaster.getReligion() == gc.getInfoTypeForString('RELIGION_OCTOPUS_OVERLORDS')

	iTeam = pCaster.getTeam()
	eTeam = gc.getTeam(iTeam)
	iX = pCaster.getX()
	iY = pCaster.getY()
	iSmoke = gc.getInfoTypeForString('IMPROVEMENT_SMOKE')
	iFlames = gc.getInfoTypeForString('FEATURE_FLAMES')
	iCold = gc.getInfoTypeForString('DAMAGE_COLD')
	iDrown = gc.getInfoTypeForString('UNIT_DROWN')
	iMelee = gc.getInfoTypeForString('UNITCOMBAT_MELEE')
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)

	lRemove = [	gc.getInfoTypeForString('PROMOTION_MITHRIL_WEAPONS'),
			gc.getInfoTypeForString('PROMOTION_IRON_WEAPONS'),
			gc.getInfoTypeForString('PROMOTION_BRONZE_WEAPONS'),
			gc.getInfoTypeForString('PROMOTION_HEROIC_DEFENSE'),
			gc.getInfoTypeForString('PROMOTION_HEROIC_DEFENSE2'),
			gc.getInfoTypeForString('PROMOTION_HEROIC_STRENGTH'),
			gc.getInfoTypeForString('PROMOTION_HEROIC_STRENGTH2'),
			gc.getInfoTypeForString('PROMOTION_BLESSED')
			]
	for iProm in xrange(gc.getNumPromotionInfos()):
		if gc.getPromotionInfo(iProm).isEquipment():
			lRemove.append(iProm)

	for iiX in xrange(iX-2, iX+ 3, 1):
		for iiY in xrange(iY-2, iY+ 3, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			if pPlot.at(iX, iY):continue
			if pPlot.isWater() or pPlot.isAdjacentToWater():
				if pPlot.getFeatureType() == iFlames:
					pPlot.setFeatureType(-1,-1)
				iImp = pPlot.getImprovementType()
				if iImp != -1:
					if iImp == iSmoke:
						pPlot.setImprovementType(-1)
					elif not gc.getImprovementInfo(iImp).isPermanent():
						if CyGame().getSorenRandNum(100, "Tsunami") < 25:
							pPlot.setImprovementType(-1)

				for i in xrange(pPlot.getNumUnits()):
					pUnit = pPlot.getUnit(i)
					if pUnit.isImmuneToMagic():continue
					if pUnit.getDamageTypeResist(iCold) > 99:continue
					if effectResisted(pUnit, pCaster, eSpell):continue
					pUnit.doDamage(50, 100, pCaster, iCold, True)
					if bNecromancy:
						if pUnit.isImmortal():continue
						if pUnit.getDuration() > 0:continue
						if pUnit.isAlive():
							if pUnit.getDamage() >= 60:
								if isLimitedUnitClass(pUnit.getUnitClassType()):continue
								if pUnit.getUnitCombatType() == iMelee:
									iTeamU = pUnit.getTeam()
									lRestore = []
									for iProm in lRemove:
										if pUnit.isHasPromotion(iProm):
											pUnit.setHasPromotion(iProm, False)
											lRestore.append(iProm)
									newUnit = pPlayer.initUnit(iDrown, pCaster.getX(), pCaster.getY(), UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
									newUnit.setBaseCombatStr(pUnit.baseCombatStr())
									newUnit.setBaseCombatStrDefense(pUnit.baseCombatStrDefense())
									for iProm in lRestore:
										if newUnit.isHasPromotion(iProm):
											newUnit.setHasPromotion(iProm, False)
									newUnit.convert(pUnit)
									newUnit.finishMoves()
									if not (pCaster.isHiddenNationality() or pUnit.isHiddenNationality()):
										if eTeam.canDeclareWar(iTeamU):
											eTeam.declareWar(iTeamU, False, WarPlanTypes.WARPLAN_LIMITED)


				CyEngine().triggerEffect(gc.getInfoTypeForString('EFFECT_SPRING'), pPlot.getPoint())

