def reqDrown(pCaster, eSpell=-1):
	if pCaster.isImmortal():
		return False
	if pCaster.isImmuneToMagic():
		return False
	if isWorldUnitClass(pCaster.getUnitClassType()):
		return False
#	if isNationalUnitClass(pCaster.getUnitClassType()):
#		return False
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iCost = 3 * ( pCaster.baseCombatStrDefense() * pCaster.baseCombatStr() + pCaster.getLevel() * gc.getUnitInfo(pCaster.getUnitType()).getTier() )
	iCost *= gc.getGameSpeedInfo(CyGame().getGameSpeedType()).getTrainPercent()
	iCost /= 100
##	iCost += (iCost * gc.getGameSpeedInfo(CyGame().getGameSpeedType()).getUpgradeCostModifier()) / 100 This does not seem to be exposed afterall
	if pPlayer.getGold() < iCost:
		return False
	if reqNecromancyAllowed(pCaster):
		pPlot = pCaster.plot()
		if pPlot.isCity():
			pCity = pPlot.getPlotCity()
			if pCity.getNumBuilding(gc.getInfoTypeForString('BUILDING_TEMPLE_OF_THE_OVERLORDS')) > 0:
				return True
		if pPlot.isWater() or pPlot.isAdjacentToWater():
			iDivine = gc.getInfoTypeForString('PROMOTION_DIVINE')
			iUndertow = gc.getInfoTypeForString('RELIGION_OCTOPUS_OVERLORDS')
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if pUnit.getOwner() == iPlayer:
					if pUnit.isHasPromotion(iDivine) and pUnit.getReligion() == iUndertow:
						return True
	return False

def spellDrown(pCaster, eSpell=-1):
	iUnit = pCaster.getUnitType()
	lRemove = [	gc.getInfoTypeForString('PROMOTION_MITHRIL_WEAPONS'),
				gc.getInfoTypeForString('PROMOTION_IRON_WEAPONS'),
				gc.getInfoTypeForString('PROMOTION_BRONZE_WEAPONS'),
				gc.getInfoTypeForString('PROMOTION_HEROIC_DEFENSE'),
				gc.getInfoTypeForString('PROMOTION_HEROIC_DEFENSE2'),
				gc.getInfoTypeForString('PROMOTION_HEROIC_STRENGTH'),
				gc.getInfoTypeForString('PROMOTION_HEROIC_STRENGTH2'),
				gc.getInfoTypeForString('PROMOTION_STRONG'),
				gc.getInfoTypeForString('PROMOTION_WEAK'),
				gc.getInfoTypeForString('PROMOTION_BLESSED')
				]
	for iProm in xrange(gc.getNumPromotionInfos()):
		if gc.getPromotionInfo(iProm).isEquipment():
			lRemove.append(iProm)
	lRestore = []
	for iProm in lRemove:
		if pCaster.isHasPromotion(iProm):
			pCaster.setHasPromotion(iProm, False)
			lRestore.append(iProm)
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	newUnit = pPlayer.initUnit(gc.getInfoTypeForString('UNIT_DROWN'), pCaster.getX(), pCaster.getY(), UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
	newUnit.setBaseCombatStr(pCaster.baseCombatStr())
	newUnit.setBaseCombatStrDefense(pCaster.baseCombatStrDefense())
	iCost = 3 * (pCaster.baseCombatStrDefense() * pCaster.baseCombatStr() + pCaster.getLevel() * gc.getUnitInfo(pCaster.getUnitType()).getTier() )
	iCost *= gc.getGameSpeedInfo(CyGame().getGameSpeedType()).getTrainPercent()
	iCost /= 100
##	iCost += (iCost * gc.getGameSpeedInfo(CyGame().getGameSpeedType()).getUpgradeCostModifier()) / 100
	pPlayer.changeGold(-iCost)
	for iProm in lRestore:
		newUnit.setHasPromotion(iProm, True)
	newUnit.convert(pCaster)
	pPlot = pCaster.plot()
	if pPlot.isCity():
		pCity =pPlot.getPlotCity()
		pCity.applyBuildEffects(newUnit)
	newUnit.finishMoves()
	newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_VAMPIRE'), False)
	newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_CRAZED'), False)
	newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_ENRAGED'), False)
	if newUnit.getScenarioCounter() == -1:
		newUnit.setScenarioCounter(iUnit)



