def reqEntangle(pCaster, eSpell=-1):
	iTeam = pCaster.getTeam()
	eTeam = gc.getTeam(iTeam)
	iPoison = gc.getInfoTypeForString('DAMAGE_POISON')
	bHostile = pCaster.isHiddenNationality()
	lTargets = []
	pPlot = pCaster.plot()
	iX = pCaster.getX()
	iY = pCaster.getY()
	if pCaster.getUnitType() == gc.getInfoTypeForString('UNIT_GUARDIAN_VINES') or pPlot.getFeatureType() in [gc.getInfoTypeForString('FEATURE_JUNGLE'), gc.getInfoTypeForString('FEATURE_FOREST_ANCIENT')]:
		for iiX in xrange(iX-2, iX+ 3, 1):
			for iiY in xrange(iY-2, iY+ 3, 1):
				pPlot = CyMap().plot(iiX, iiY)
				if pPlot.isNone():continue
				for i in xrange(pPlot.getNumUnits()):
					pUnit = pPlot.getUnit(i)
					if bHostile or eTeam.isAtWar(pUnit.getTeam()):
						# if pUnit.isInvisible(iTeam, False):continue
						if pUnit.isFlying():continue
						if pUnit.isImmuneToSpell(pCaster, eSpell):continue
						if pUnit.getDamageTypeResist(iPoison) < 100:
							if pUnit.getDamage() < 30:
								return True
						if pUnit.getImmobileTimer() < 4:
							return True
	return False

