def spellEmpowerEngine(pCaster, eSpell):
	pPlot = pCaster.plot()
	iGolem = gc.getInfoTypeForString('PROMOTION_GOLEM')
	lCombats = [gc.getInfoTypeForString('UNITCOMBAT_NAVAL'), gc.getInfoTypeForString('UNITCOMBAT_SIEGE'), gc.getInfoTypeForString('UNITCOMBAT_GUN')]
	sRetrofit = 'SPELL_RETROFIT_GOLEM'
	iTeam = pCaster.getTeam()
	lWW = [ gc.getInfoTypeForString('PROMOTION_WATER_WALKING'), gc.getInfoTypeForString('PROMOTION_WATER_WALKING_TEMP')]

	lPerks = list(set(cf.getSummonPerks(pCaster)))
	for iProm in lPerks:
		info = gc.getPromotionInfo(iProm)
		if info.isGraphicalOnly():
			lPerks.remove(iProm)
		if info.isEquipment():
			lPerks.remove(iProm)
		if info.isRace():
			lPerks.remove(iProm)
		# if info.getMinLevel() < 0:
			# lPerks.remove(iProm)

		
	if len(lPerks) > 0:

		for i in xrange(pPlot.getNumUnits()):
			pUnit = pPlot.getUnit(i)
			if iTeam == pUnit.getTeam():
				infoUnit = gc.getUnitInfo(pUnit.getUnitType())
				if infoUnit.isMechUnit() and infoUnit.getEquipmentPromotion() ==-1:
				#if pUnit.getRace() == iGolem or ( pUnit.getRace() == -1 and pUnit.getUnitCombatType() in lCombats):
					if pUnit.getID() != pCaster.getID():
						lPerksU = []
						for iProm in lPerks:
							if not pUnit.isHasPromotion(iProm):
								if not pUnit.isPromotionImmune(iProm):
									if iProm in lWW and pUnit.getDomainType() == gc.getInfoTypeForString('DOMAIN_SEA'):continue
									lPerksU.append(iProm)

						iNum = 1
						if eSpell == gc.getInfoTypeForString('SPELL_EMPOWER_ENGINE_GREATER'):
							iNum = pCaster.getLevel()
						
						while iNum > 0 and len(lPerksU) > 0:
							iProm = lPerksU.pop(CyGame().getSorenRandNum(len(lPerksU), "Empower Engine: "+ str(pUnit.getName())))
							pUnit.setHasPromotion(iProm, True)
							iNum -= 1


