def helpEmpowerEngine(lpUnits, eSpell):
	szBuffer = ''
	pCaster = lpUnits[0]
	iTeam = pCaster.getTeam()
	pPlot = pCaster.plot()
	lPerks = []
	for pCaster in lpUnits:
		lPerks += cf.getSummonPerks(pCaster)
	lPerks = list(set(lPerks))
	for iProm in lPerks:
		info = gc.getPromotionInfo(iProm)
		if info.isGraphicalOnly():
			lPerks.remove(iProm)
		if info.isEquipment():
			lPerks.remove(iProm)
		if info.isRace():
			lPerks.remove(iProm)
		# if info.getMinLevel() < 0:
			# lPerks.remove(iProm)
	if len(lPerks) < 1:
		return szBuffer
	lGolems = []
	lMachines = []
	sRetrofit = gc.getInfoTypeForString('SPELL_RETROFIT_GOLEM')
	iGolem = gc.getInfoTypeForString('PROMOTION_GOLEM')
	lCombats = [gc.getInfoTypeForString('UNITCOMBAT_NAVAL'), gc.getInfoTypeForString('UNITCOMBAT_SIEGE'), gc.getInfoTypeForString('UNITCOMBAT_GUN')]
	lWW = [ gc.getInfoTypeForString('PROMOTION_WATER_WALKING'), gc.getInfoTypeForString('PROMOTION_WATER_WALKING_TEMP')]
	for i in xrange(pPlot.getNumUnits()):
		pUnit = pPlot.getUnit(i)
		if pUnit not in lpUnits:
			infoUnit = gc.getUnitInfo(pUnit.getUnitType())
			if infoUnit.isMechUnit() and infoUnit.getEquipmentPromotion() ==-1:
			#if pUnit.getRace() == iGolem or ( pUnit.getRace() == -1 and pUnit.getUnitCombatType() in lCombats):
				if iTeam == pUnit.getTeam():
					if pUnit.getID() != pCaster.getID():
						lMachines.append(pUnit)
	if len(lMachines) < 1:
		return szBuffer

	# if len(lGolems) > 0:
		# szBuffer += helpRetrofitGolem(lGolems, sRetrofit)

	sAdd = localText.getText("TXT_KEY_HELP_SPELL_MAY_ADD", ())
	sRemove = localText.getText("TXT_KEY_HELP_SPELL_MAY_REMOVE", ())

	for iProm in cf.getSummonPerks(pCaster):
		lTargets = []
		for pUnit in lMachines:
			if pUnit.isPromotionImmune(iProm):continue
			if iProm in lWW and pUnit.getDomainType() == gc.getInfoTypeForString('DOMAIN_SEA'):continue
			if not pUnit.isHasPromotion(iProm):
				lTargets.append(pUnit)
		lTargets = list(set(lTargets))
		iCount = len(lTargets)
		if iCount > 0:
			szBuffer += sAdd + CyGameTextMgr().getPromotionHelp(iProm, False)
			if iCount == 1:
				pUnit = lTargets.pop(0)
				pPlayer = gc.getPlayer(pUnit.getOwner())
				sList = cf.getNameWithColorScheme(pUnit, pUnit.isInvisible(pCaster.getTeam(), False))
				szBuffer += localText.getText("TXT_KEY_HELP_SPELL_TARGETS_THIS", (sList, ))
			else:
				sList = ''
				while len(lTargets) > 0:
					pUnit = lTargets.pop(0)
					pPlayer = gc.getPlayer(pUnit.getOwner())
					sList += cf.getNameWithColorScheme(pUnit, pUnit.isInvisible(pCaster.getTeam(), False))
					if len(lTargets) > 0:
						if len(lTargets) == 1:
							sList += " or "
						else:
							sList += ", "
				szBuffer += localText.getText("TXT_KEY_HELP_SPELL_TARGETS_THESE_COUNT_LIST", (iCount, sList, ))

	return szBuffer


