def helpIntersticeTransport(lpUnits, eSpell):
	pCaster = lpUnits[0]
	szBuffer = localText.getText("TXT_KEY_SPELL_ESCAPE", ()) + ' to one of these cities: \n'
	listCities = []
	iInterstice =  gc.getInfoTypeForString('BUILDING_INTERSTICE')
	iIntersticeH =  gc.getInfoTypeForString('BUILDING_INTERSTICE_HOSTILE')
	for iPlayer in xrange(gc.getMAX_PLAYERS()):
		for pyCity in PyPlayer(iPlayer).getCityList() :
			loopCity = pyCity.GetCy()
			loopPlot = loopCity.plot()
			if not pCaster.atPlot(loopPlot):
				if loopCity.getNumBuilding(iInterstice) > 0 or loopCity.getNumBuilding(iIntersticeH) > 0:
					if pCaster.canMoveInto (loopPlot, False, False, False):
						listCities.append(loopCity)
						pPlayer = gc.getPlayer(loopCity.getOwner())
						szBuffer += " \n \t <color=%d,%d,%d,%d>%s</color>" %(pPlayer.getPlayerTextColorR(), pPlayer.getPlayerTextColorG(), pPlayer.getPlayerTextColorB(), pPlayer.getPlayerTextColorA(), loopCity.getName() )
	return szBuffer

def miscastEscape(pCaster, eSpell):
	pPlot = pCaster.plot()
	bWater = pCaster.getDomainType() == gc.getInfoTypeForString('DOMAIN_SEA')
	iBestValue = 0
	pBestPlot = -1
	for i in xrange (CyMap().numPlots()):
		iValue = 0
		pTargetPlot = CyMap().plotByIndex(i)
		if bWater == pTargetPlot.isWater():
			iValue = CyGame().getSorenRandNum(1000, "Escape miscast move "+ str(pCaster.getName()))
			if not pTargetPlot.isOwned():
				iValue += 1000
			if pTargetPlot == pPlot:
				iValue = 0
			if pTargetPlot.isCity():
				iValue = 0
			if iValue > iBestValue:
				iBestValue = iValue
				pBestPlot = pTargetPlot
	if pBestPlot != -1:
		pCaster.setXY(pBestPlot.getX(), pBestPlot.getY(), False, True, True)

def spellEscape(pCaster, eSpell=-1):
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iTeam = pCaster.getTeam()
	eTeam = gc.getTeam(iTeam)
	if eTeam.getNumCities() > 0:
		iX = pCaster.getX()
		iY = pCaster.getY()
		bCoastalOnly = pCaster.getDomainType() == gc.getInfoTypeForString('DOMAIN_SEA')
		pSkipCity = pPlayer.getCity(-1)
		pPlot = pCaster.plot()
		if pPlot.isCity():
			pSkipCity = pPlot.getPlotCity()
		pCity = CyMap().findCity(iX, iY, PlayerTypes.NO_PLAYER, iTeam, False, bCoastalOnly, TeamTypes.NO_TEAM, DirectionTypes.NO_DIRECTION, pSkipCity)
		if pCity != -1 and not pCity.isNone():
			pCaster.setXY(pCity.getX(), pCity.getY(), False, True, True)

def helpEscape(lpUnits, eSpell=1):
	szBuffer = ''
	pCaster = lpUnits[0]
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iTeam = pCaster.getTeam()
	eTeam = gc.getTeam(iTeam)
	if eTeam.getNumCities() > 0:
		pCity = -1
		pSkipCity = pPlayer.getCity(-1)
		pPlot = pCaster.plot()
		if pPlot.isCity():
			pSkipCity = pPlot.getPlotCity()
		iX1 = pCaster.getX()
		iY1 = pCaster.getY()
		sNameRefuge = ''
		for pCaster in lpUnits:
			iX2 = -1
			iY2 = -1
			bCoastalOnly = pCaster.getDomainType() == gc.getInfoTypeForString('DOMAIN_SEA')
			pCity = CyMap().findCity(iX1, iY1, PlayerTypes.NO_PLAYER, iTeam, False, bCoastalOnly, TeamTypes.NO_TEAM, DirectionTypes.NO_DIRECTION, pSkipCity)
			if pCity != -1 and not pCity.isNone():
				pExitPlot = pCity.plot()
				iX2 = pCity.getX()
				iY2 = pCity.getY()
				sNameRefuge ="<color=%d,%d,%d,%d>%s</color>" %(pPlayer.getPlayerTextColorR(), pPlayer.getPlayerTextColorG(), pPlayer.getPlayerTextColorB(), pPlayer.getPlayerTextColorA(), pCity.getName())
				sList = cf.getNameWithColorScheme(pCaster)
				szBuffer += localText.getText("TXT_KEY_SPELL_ESCAPE", ()) + ' to ' + sNameRefuge
				idX = iX2 - iX1
				if idX != 0:
					sdX = 'East'
					if idX < 0:
						idX = -idX
						sdX = 'West'
					szBuffer += localText.getText("TXT_KEY_HELP_MOVE_UNIT", (sList,idX, sdX, ))
				idY = iY2 - iY1
				if idY != 0:
					sdY = 'North'
					if idY < 0:
						idY = -idY
						sdY = 'South'
					szBuffer += localText.getText("TXT_KEY_HELP_MOVE_UNIT", (sList,idY, sdY, ))
	szBuffer += helpManaBlocked(lpUnits, 'VOTE_NO_DIMENSIONAL_MANA')
	return szBuffer

def spellExorcise(pCaster, eSpell=1):
	pPlot = pCaster.plot()
	iPossessed = gc.getInfoTypeForString('PROMOTION_POSSESSED')
	iUnholyTaint = gc.getInfoTypeForString('PROMOTION_UNHOLY_TAINT')
	iSaverous = gc.getInfoTypeForString('UNIT_SAVEROUS')
	iGosea = gc.getInfoTypeForString('UNIT_GOSEA')
	iInfernal = gc.getInfoTypeForString('CIVILIZATION_INFERNAL')
	iX = pCaster.getX()
	iY = pCaster.getY()
	iPlayer = pCaster.getOwner()
	iTeam = pCaster.getTeam()
	eTeam = gc.getTeam(iTeam)

	listPacts =[	gc.getInfoTypeForString('PROMOTION_PACT_WITH_WINTER'),
					gc.getInfoTypeForString('PROMOTION_PACT_WITH_HYBOREM'),
					gc.getInfoTypeForString('PROMOTION_PACT_WITH_JUDECCA'),
					gc.getInfoTypeForString('PROMOTION_PACT_WITH_LETHE'),
					gc.getInfoTypeForString('PROMOTION_PACT_WITH_MERESIN'),
					gc.getInfoTypeForString('PROMOTION_PACT_WITH_OUZZA'),
					gc.getInfoTypeForString('PROMOTION_PACT_WITH_SALLOS'),
					gc.getInfoTypeForString('PROMOTION_PACT_WITH_STATIUS')]

	for iiX in xrange(iX-2, iX+ 3, 1):
		for iiY in xrange(iY-2, iY+ 3, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if pUnit.isAlive():
					if pUnit.isHasPromotion(iPossessed) or pUnit.isHasPromotion(iUnholyTaint) or pUnit.getUnitType() in [iSaverous, iGosea]:
						if effectResisted(pUnit, pCaster, eSpell):
							continue
						iUnit = pUnit.getUnitType()
						if pUnit.isHasPromotion(iPossessed):
							pUnit.setHasPromotion(iPossessed, False)
						if pUnit.isHasPromotion(iUnholyTaint):
							pUnit.setHasPromotion(iUnholyTaint, False)
							for iProm in listPacts:
								pUnit.setHasPromotion(iProm, False)



						if iUnit == iSaverous:
							pUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_DARK_REFLECTION'), True)
							cf.makeMortal(pUnit)
							iPlayer = pCaster.getOwner()
							pPlayer = gc.getPlayer(iPlayer)
							iUnit = gc.getInfoTypeForString('UNIT_SQUIRE_SAVEROUS')
							newUnit = pPlayer.initUnit(iUnit, pCaster.getX(), pCaster.getY(), UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
							newUnit.convert(pUnit)
##							for i in xrange(gc.getNumPromotionInfos()):
##								newUnit.setHasPromotion(i, pUnit.isHasPromotion(i))
##								if gc.getPromotionInfo(i).isEquipment():
##									newUnit.setHasPromotion(i, False)
##							newUnit.setDamage(pUnit.getDamage()/2, pCaster.getOwner())
##							newUnit.setLevel(pUnit.getLevel())
##							newUnit.setExperience(pUnit.getExperience(), -1)
							for sProm in [	'PROMOTION_DEMON',
											'PROMOTION_POSSESSED',
											'PROMOTION_UNHOLY_TAINT',
											'PROMOTION_DARK_REFLECTION',
											'PROMOTION_CRAZED',
											'PROMOTION_ENRAGED',
											'PROMOTION_REBEL'
											]:
								newUnit.setHasPromotion(gc.getInfoTypeForString(sProm), False)
							newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_LOYALTY'), True)
							newUnit.setReligion(gc.getInfoTypeForString('RELIGION_RUNES_OF_KILMORPH'))
						elif iUnit == iGosea:
							pUnit.setReligion(-1)
							listAffinity = [	gc.getInfoTypeForString('PROMOTION_AFFINITY_AIR'),
												gc.getInfoTypeForString('PROMOTION_AFFINITY_BODY'),
												gc.getInfoTypeForString('PROMOTION_AFFINITY_CHAOS'),
												gc.getInfoTypeForString('PROMOTION_AFFINITY_CREATION'),
												gc.getInfoTypeForString('PROMOTION_AFFINITY_DEATH'),
												gc.getInfoTypeForString('PROMOTION_AFFINITY_DEATH_ARAWN'),
												gc.getInfoTypeForString('PROMOTION_AFFINITY_DIMENSIONAL'),
												gc.getInfoTypeForString('PROMOTION_AFFINITY_EARTH'),
												gc.getInfoTypeForString('PROMOTION_AFFINITY_ENCHANTMENT'),
												gc.getInfoTypeForString('PROMOTION_AFFINITY_ENTROPY'),
												gc.getInfoTypeForString('PROMOTION_AFFINITY_FIRE'),
												gc.getInfoTypeForString('PROMOTION_AFFINITY_FORCE'),
												gc.getInfoTypeForString('PROMOTION_AFFINITY_ICE'),
												gc.getInfoTypeForString('PROMOTION_AFFINITY_LAW'),
												gc.getInfoTypeForString('PROMOTION_AFFINITY_LIFE'),
												gc.getInfoTypeForString('PROMOTION_AFFINITY_METAMAGIC'),
												gc.getInfoTypeForString('PROMOTION_AFFINITY_MIND'),
												gc.getInfoTypeForString('PROMOTION_AFFINITY_NATURE'),
												gc.getInfoTypeForString('PROMOTION_AFFINITY_SHADOW'),
												gc.getInfoTypeForString('PROMOTION_AFFINITY_SPIRIT'),
												gc.getInfoTypeForString('PROMOTION_AFFINITY_SUN'),
												gc.getInfoTypeForString('PROMOTION_AFFINITY_WATER')
												]
							for iProm in listAffinity:
								pUnit.setHasPromotion(iProm, False)
					if pUnit.getCivilizationType() == iInfernal:
						if eTeam.isAtWar(pUnit.getTeam()):
							pUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_DARK_REFLECTION'), True)
##							cf.makeMortal(pUnit)
							iPlayer = pCaster.getOwner()
							pPlayer = gc.getPlayer(iPlayer)
							iUnit = pUnit.getUnitType()
							newUnit = pPlayer.initUnit(iUnit, pCaster.getX(), pCaster.getY(), UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
							cf.removeAffinities(newUnit)
							newUnit.convert(pUnit)
							for sProm in [
											'PROMOTION_POSSESSED',
											'PROMOTION_UNHOLY_TAINT',
											'PROMOTION_DARK_REFLECTION',
											'PROMOTION_CRAZED',
											'PROMOTION_ENRAGED',
											'PROMOTION_REBEL'
											]:
								newUnit.setHasPromotion(gc.getInfoTypeForString(sProm), False)

def reqExorcise(pCaster, eSpell=1):
	pPlot = pCaster.plot()
	iPossessed = gc.getInfoTypeForString('PROMOTION_POSSESSED')
	iUnholyTaint = gc.getInfoTypeForString('PROMOTION_UNHOLY_TAINT')
	lThralls = [gc.getInfoTypeForString('UNIT_SAVEROUS'), gc.getInfoTypeForString('UNIT_GOSEA')]
	iX = pCaster.getX()
	iY = pCaster.getY()
	iPlayer = pCaster.getOwner()
	iTeam = pCaster.getTeam()
	eTeam = gc.getTeam(iTeam)
	for iiX in xrange(iX-2, iX+ 3, 1):
		for iiY in xrange(iY-2, iY+ 3, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if pUnit.isAlive():
					if pUnit.isImmuneToSpell(pCaster, eSpell):
						continue
					if pUnit.isHasPromotion(iPossessed):
						return True
					if pUnit.isHasPromotion(iUnholyTaint):
						return True
					if pUnit.getUnitType() in lThralls:
						return True
	return False

def helpExorcise(lpUnits, eSpell=1):
	return helpTogglePromotions(lpUnits, eSpell, [], ['PROMOTION_POSSESSED', 'PROMOTION_UNHOLY_TAINT','PROMOTION_PACT_WITH_WINTER','PROMOTION_PACT_WITH_HYBOREM','PROMOTION_PACT_WITH_JUDECCA','PROMOTION_PACT_WITH_LETHE','PROMOTION_PACT_WITH_MERESIN','PROMOTION_PACT_WITH_OUZZA','PROMOTION_PACT_WITH_SALLOS','PROMOTION_PACT_WITH_STATIUS'], 1, True)



def spellExploreBadbsBlizzard(pCaster, eSpell):
	iRnd = CyGame().getSorenRandNum(90, "Explore Badbs Blizzard") + pCaster.getLevel()
	iDestroyLair = 0
	if iRnd < 50:

		pPlotBB = pCaster.plot()
		eSpell = gc.getInfoTypeForString('SPELL_EXPLORE_LAIR_BADBS_BLIZZARD')
		iBB = gc.getInfoTypeForString('IMPROVEMENT_BADBS_BLIZZARD')
		iIce = gc.getInfoTypeForString('BONUS_MANA_ICE')
		iBl = gc.getInfoTypeForString('FEATURE_BLIZZARD')
		lCold = [gc.getInfoTypeForString('TERRAIN_TUNDRA'),gc.getInfoTypeForString('TERRAIN_SNOW'),gc.getInfoTypeForString('TERRAIN_GLACIER'),gc.getInfoTypeForString('TERRAIN_WASTELAND')]
		iBestValue = 0
		pBestPlot = -1
		for i in xrange (CyMap().numPlots()):
			pTargetPlot = CyMap().plotByIndex(i)
			if pTargetPlot == pPlotBB:
				continue
			if pTargetPlot.isPeak():
				continue
			if pTargetPlot.isWater():
				continue
			if pTargetPlot.getBonusType(-1) != -1:
				continue
			iValue = 0
			iImp = pTargetPlot.getImprovementType()
			if iImp == -1:
				iValue += 100
			elif gc.getImprovementInfo(iImp).isPermanent():
				continue
			if pTargetPlot.getTerrainType() in lCold:
				iValue += 1000
			iValue += CyGame().getSorenRandNum(1000, "Badb move ")
			if not pTargetPlot.isOwned():
				iValue += 1000
			if iValue > iBestValue:
				iBestValue = iValue
				pBestPlot = pTargetPlot
		if pBestPlot != -1:
			sCaption = CvUtil.convertToStr(gc.getImprovementInfo(iBB).getDescription())
			lCaptionPlayers = []
			for i in xrange(CyEngine().getNumSigns()):
				pSign = CyEngine().getSignByIndex(i)
				if pSign.getCaption() == sCaption:
					loopPlayer = pSign.getPlayerType()
					lCaptionPlayers.append(loopPlayer)
					CyEngine().removeSign(pSign.getPlot(),loopPlayer)
			for loopPlayer in lCaptionPlayers:
				CyEngine().addSign(pBestPlot,loopPlayer, sCaption)

			iBadb = gc.getInfoTypeForString('UNIT_BADB')
			for i in xrange(pPlotBB.getNumUnits()):
				pUnit = pPlotBB.getUnit(i)
				if iBadb in [pUnit.getUnitType(), pUnit.getScenarioCounter()] or pUnit.getDelayedSpell() == eSpell:
					pUnit.setXY(pBestPlot.getX(), pBestPlot.getY(), False, True, True)
					break
			else:
				bPlayer = gc.getPlayer(gc.getBARBARIAN_PLAYER())
				iCount = bPlayer.getUnitClassCount(gc.getInfoTypeForString('UNITCLASS_BADB'))
				while iCount > 1:
					for pUnit in PyPlayer(gc.getBARBARIAN_PLAYER()).getUnitList():
						if iBadb in [pUnit.getUnitType(), pUnit.getScenarioCounter()]:
							pUnit.kill(False, -1)
							break
				if iCount == 1:
					for pUnit in PyPlayer(gc.getBARBARIAN_PLAYER()).getUnitList():
						if iBadb in [pUnit.getUnitType(), pUnit.getScenarioCounter()]:
							pUnit.setXY(pBestPlot.getX(), pBestPlot.getY(), False, True, True)
							break


			iBonusReal = pPlotBB.getRealBonusType()
			if iBonusReal == iIce:
				pPlotBB.setBonusType(-1)
			else:
				pPlotBB.setBonusType(iBonusReal)
			pPlotBB.changeTempTerrainTimer(1-pPlotBB.getTempTerrainTimer())
			iReal = pPlotBB.getRealImprovementType()
			if iReal == iBB:
				pPlotBB.setImprovementType(-1)
			else:
				pPlotBB.setImprovementType(iReal)

			pBestPlot.setTempBonusType(iIce, iRnd)

			pBestPlot.setImprovementType(iBB)
			pBestPlot.setBonusType(iIce)
			pBestPlot.setFeatureType(iBl, 0)

			if iRnd < 20:
				pCaster.setXY(pBestPlot.getX(), pBestPlot.getY(), False, True, True)
	
				CyInterface().addMessage(pCaster.getOwner(), True, 25, localText.getText("TXT_KEY_MESSAGE_BADBS_BLIZZARD_MOVED", (pCaster.getName(),)), 'AS2D_POSITIVE_DINK', 1, 'Art/Interface/Buttons/Improvements/BadbsBlizzard.dds', ColorTypes(8), pCaster.getX(), pCaster.getY(), True, True)

	elif iRnd > 95:
		if not CyGame().isUnitClassMaxedOut(gc.getInfoTypeForString('UNITCLASS_BADB'), 0):
			pBliz = cf.findImprovement(gc.getInfoTypeForString('IMPROVEMENT_BADBS_BLIZZARD'))
			if pBliz != -1:
				iUnit = gc.getInfoTypeForString('UNIT_BADB')
				newUnit = gc.getPlayer(gc.getBARBARIAN_PLAYER()).initUnit(iUnit, pBliz.getX(), pBliz.getY(), UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)

	else:
		spellExploreLairEpic(pCaster, eSpell)
		
		
