def reqExploreWilderness(pCaster, eSpell = -1):
	pPlot = pCaster.plot()
	if pCaster.getUnitType() == gc.getInfoTypeForString('UNIT_LOKI'):
		return False
	if pPlot.isOwned():
		return False
	if pPlot.isCityRadius():
		return False
	iImp = pPlot.getImprovementType()
	if iImp != -1 :
		if gc.getImprovementInfo(iImp).isPermanent():
			return False
			
	iTeam = pCaster.getTeam()
	iSluagh = gc.getInfoTypeForString('UNIT_SLUAGH')
	
	iX = pCaster.getX()
	iY = pCaster.getY()
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)

	pCity = CyMap().findCity(iX, iY, PlayerTypes.NO_PLAYER, TeamTypes.NO_TEAM, False, False, TeamTypes.NO_TEAM, DirectionTypes.NO_DIRECTION, pPlayer.getCity(-1))
	if pCity != -1 and not pCity.isNone():
		if -1 < CyMap().calculatePathDistance(pPlot, pCity.plot()) < 7:
			return False
	for iiX in xrange(iX-1, iX+ 2, 1):
		for iiY in xrange(iY-1, iY+ 2, 1):
			if pPlot.getNumUnits() > 1:
				for iUnit in xrange(pPlot.getNumUnits()):
					pUnit = pPlot.getUnit(iUnit)
					if pUnit.getUnitType() == iSluagh:
						continue
					if pUnit.isAnimal():
						continue
					if pUnit.isInvisible(iTeam, False):
						continue
					elif pUnit.getID() == pCaster.getID() and pUnit.getOwner() == iPlayer:
						continue
					else:
						return False
	return reqExploreLair(pCaster, eSpell)
	
def spellExploreWilderness(pCaster, eSpell=-1):
	pPlot = pCaster.plot()
	iRnd = CyGame().getSorenRandNum(100, "Explore Wilderness") + pCaster.getLevel()
	iDestroyLair = 0
	if iRnd < 10:
		iDestroyLair = cf.exploreLairBigBad(pCaster)
	elif iRnd < 44:
		iDestroyLair = cf.exploreLairBad(pCaster)
	elif iRnd < 74:
		iDestroyLair = cf.exploreLairNeutral(pCaster)
	elif iRnd < 98:
		iDestroyLair = cf.exploreLairGood(pCaster)
	else:
		iDestroyLair = cf.exploreLairBigGood(pCaster)

# MOD epic-lair-cooldown: the cooldown belongs to the site (plot), not the unit
# or player, so it is stored in the plot's scriptData under an 'ELCD:' segment
# holding the game turn the site reopens. setTempImprovementType cannot be used
# for this: the DLL ignores the call when the new improvement equals the current
# one, so re-stamping a lair with its own improvement never starts a timer.
# Format is 'ELCD:<turn>;' appended to whatever else already lives in scriptData.
# YK-MOD gaizao-17: per-speed epic lair cooldown in turns.
# Vanilla-equivalent values were Marathon 20 / Epic 10 / Normal 7 / Quick 4.
EPIC_LAIR_COOLDOWN_BY_SPEED = {
	'GAMESPEED_MARATHON'	:	1,
	'GAMESPEED_EPIC'		:	1,
	'GAMESPEED_NORMAL'		:	1,
	'GAMESPEED_QUICK'		:	1,
	}
EPIC_LAIR_COOLDOWN_DEFAULT = 1

def getEpicLairCooldownTurn(sData):
	# Returns the stored expiry turn, or -1 when absent/unparsable.
	if not sData:
		return -1
	iStart = sData.find('ELCD:')
	if iStart == -1:
		return -1
	iStart = iStart + 5
	iEnd = sData.find(';', iStart)
	if iEnd == -1:
		return -1
	try:
		return int(sData[iStart:iEnd])
	except:
		return -1

def setEpicLairCooldownData(sData, iTurn):
	# Replaces an existing ELCD segment or appends a new one, preserving other data.
	if not sData:
		sData = ''
	iStart = sData.find('ELCD:')
	if iStart != -1:
		iEnd = sData.find(';', iStart)
		if iEnd != -1:
			sData = sData[:iStart] + sData[iEnd+1:]
		else:
			sData = sData[:iStart]
	return sData + 'ELCD:%d;' % iTurn

def reqExploreLair(pCaster, eSpell = -1):
	if pCaster.isBarbarian():
		return False
	pPlot = pCaster.plot()
	# if pPlot.getTempImprovementTimer() > 0:
		# return False
	iReopenTurn = getEpicLairCooldownTurn(pPlot.getScriptData())
	if iReopenTurn > -1:
		if CyGame().getGameTurn() < iReopenTurn:
			return False
	if eSpell in [ gc.getInfoTypeForString('SPELL_EXPLORE_LAIR_HELLFIRE'), gc.getInfoTypeForString('SPELL_EXPLORE_LAIR_PIT')]:
		iPlayer = pCaster.getOwner()
		pPlayer = gc.getPlayer(iPlayer)
		iInf = gc.getInfoTypeForString('CIVILIZATION_INFERNAL')
		if gc.getGame().isOption(GameOptionTypes.GAMEOPTION_ADVANCED_TACTICS):
			iAV = gc.getInfoTypeForString('RELIGION_THE_ASHEN_VEIL')
			if pPlot.isBarbarian():
				if pPlayer.getCivilizationType() == iInf:
					pPlot.setOwner(iPlayer)
			elif pPlot.isOwned():
				if gc.getPlayer(pPlot.getOwner()).getCivilizationType() != iInf:
					pPlot.setOwner(gc.getBARBARIAN_PLAYER())
			else:
				if pPlayer.getCivilizationType() == iInf:
					pPlot.setOwner(iPlayer)
				else:
					pPlot.setOwner(gc.getBARBARIAN_PLAYER())
		if pPlayer.getCivilizationType() == iInf:
			return False
##	if pCaster.isOnlyDefensive():
##		return False
	if pCaster.baseCombatStr() < 2:
		return False
	# if pCaster.getSummoner() != -1:
		# return False
	if pCaster.isPermanentSummon():
		return False
	if pCaster.getDuration() > 0:
		return False
	if pCaster.getSpecialUnitType() in [gc.getInfoTypeForString('SPECIALUNIT_SPELL'), gc.getInfoTypeForString('SPECIALUNIT_BIRD')]:
		return False
	if pCaster.getUnitCombatType() == gc.getInfoTypeForString('UNITCOMBAT_SIEGE'):
		return False
	if not pPlot.isPythonActive():
		return False
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	if eSpell != -1:
		iTeam = pCaster.getTeam()
		for iUnit in xrange(pPlot.getNumUnits()):
			pUnit = pPlot.getUnit(iUnit)
			if pUnit.getOwner() == iPlayer:
				if pUnit.getID() != pCaster.getID():
					if pUnit.getDelayedSpell() == eSpell:
						return False
			elif pUnit.getFortifyTurns() > 0:
				if not pUnit.isInvisible(iTeam, False):
					return False
	if not pCaster.isHuman():
		if pPlayer.getNumCities() < 1:
			return False
		pCity = CyMap().findCity(pCaster.getX(), pCaster.getY(), iPlayer, TeamTypes.NO_TEAM, False, False, TeamTypes.NO_TEAM, DirectionTypes.NO_DIRECTION, pPlayer.getCity(-1))
		if pCity.isNone():
			pCity = pPlayer.getCapitalCity()
		if not pCity.isNone():
			if -1 < CyMap().calculatePathDistance(pPlot, pCity.plot()) < 5:
				return False
	return True

def spellExploreLair(pCaster, eSpell=-1):
	pPlot = pCaster.plot()
	#Exploring once the unit has been force off of the lair's tile can cause problems
	iImp = pCaster.plot().getImprovementType()
	if iImp != -1:
		if gc.getImprovementInfo(iImp).isPermanent():
			iRnd = CyGame().getSorenRandNum(100, "Explore Lair") + pCaster.getLevel()
			iDestroyLair = 0
			if iRnd < 14:
				iDestroyLair = cf.exploreLairBigBad(pCaster)
			elif iRnd < 44:
				iDestroyLair = cf.exploreLairBad(pCaster)
			elif iRnd < 74:
				iDestroyLair = cf.exploreLairNeutral(pCaster)
			elif iRnd < 94:
				iDestroyLair = cf.exploreLairGood(pCaster)
			else:
				iDestroyLair = cf.exploreLairBigGood(pCaster)
			iImprovement = pPlot.getImprovementType()
			if iImprovement != -1 :
				if iDestroyLair > CyGame().getSorenRandNum(100, "Explore Lair"):
					if not gc.getImprovementInfo(iImprovement).isUnique():
						CyInterface().addMessage(pCaster.getOwner(), True, 25, localText.getText("TXT_KEY_MESSAGE_LAIR_DESTROYED", ()), 'AS2D_POSITIVE_DINK', 1, 'Art/Interface/Buttons/Spells/Explore Lair.dds', ColorTypes(8), pPlot.getX(), pPlot.getY(), True, True)
						pPlot.setImprovementType(-1)
					else:
						pPlot.setPythonActive(False)
			pCaster.changeExperience(1, -1, False, False, False)

def spellExploreLairEpic(pCaster, eSpell=-1):
	pPlot = pCaster.plot()
	#Exploring once the unit has been force off of the lair's tile can cause problems
	iImp = pCaster.plot().getImprovementType()
	if iImp != -1:
		if gc.getImprovementInfo(iImp).isPermanent():
			if pCaster.getUnitType() == gc.getInfoTypeForString('UNIT_DEVOUT'):
				effectPilgrimage(pCaster)
			iRnd = CyGame().getSorenRandNum(5, "Explore Lair")
			iDestroyLair = 0
			if iRnd >= 2:
				iDestroyLair = cf.exploreLairBigBad(pCaster)
			if iRnd <= 3:
				iDestroyLair = cf.exploreLairBigGood(pCaster)
			# Unique epic lairs are repeatable, but each completed exploration
			# closes the site. Marathon is the 20-turn baseline; other speeds
			# use the standard VictoryDelayPercent ratio (20/10/7/4 turns).
			iCooldown = max(1, EPIC_LAIR_COOLDOWN_BY_SPEED.get(gc.getGameSpeedInfo(CyGame().getGameSpeedType()).getType(), EPIC_LAIR_COOLDOWN_DEFAULT)) # YK-MOD gaizao-17
			pPlot.setScriptData(setEpicLairCooldownData(pPlot.getScriptData(), CyGame().getGameTurn() + iCooldown))
			iImprovement = pPlot.getImprovementType()
			if iImprovement != -1:
				if iDestroyLair > CyGame().getSorenRandNum(100, "Explore Lair"):
					if not gc.getImprovementInfo(iImprovement).isUnique():
						CyInterface().addMessage(pCaster.getOwner(), True, 25, localText.getText("TXT_KEY_MESSAGE_LAIR_DESTROYED", ()), 'AS2D_POSITIVE_DINK', 1, 'Art/Interface/Buttons/Spells/Explore Lair.dds', ColorTypes(8), pPlot.getX(), pPlot.getY(), True, True)
						pPlot.setImprovementType(-1)
			pCaster.changeExperience(1, -1, False, False, False)

def spellEvangelizeAdjacentCity(pCaster, eSpell=-1):
	pCity = findAdjacentCity(pCaster)
	if pCity:
		pCity.setHasReligion(pCaster.getReligion(), True, False, False)

def reqEvangelizeAdjacentCity(pCaster, eSpell=-1):
	pCity = findAdjacentCity(pCaster)
	if not pCity:
		return False
	if pCity.isHasReligion(pCaster.getReligion()):
		return False
	return True

def reqEvangelizeDragonCity(pCaster, eSpell=-1):
	if gc.getGame().isOption(GameOptionTypes.GAMEOPTION_NO_ACHERON):
		return False
	return reqEvangelizeAdjacentCity(pCaster, eSpell)

def reqEvangelizeUnits(pCaster, eSpell=-1):
	iRel = pCaster.getReligion()
	if iRel != -1:
		lAnimal = [gc.getInfoTypeForString('UNITCOMBAT_ANIMAL'), gc.getInfoTypeForString('UNITCOMBAT_BEAST')]
		iSluagh = gc.getInfoTypeForString('UNIT_SLUAGH')
		iX = pCaster.getX()
		iY = pCaster.getY()
		for iiX in xrange(iX-1, iX+ 2, 1):
			for iiY in xrange(iY-1, iY+ 2, 1):
				pPlot = CyMap().plot(iiX, iiY)
				if pPlot.isNone():continue
				for i in xrange(pPlot.getNumUnits()):
					pUnit = pPlot.getUnit(i)
					if pUnit.isAlive():
						if pCaster is pUnit:continue
						if pCaster.getID() == pUnit.getID():continue
						if pUnit.getReligion() == iRel:continue
						if pUnit.getUnitCombatType() in lAnimal:continue
						if pUnit.isAvatarOfCivLeader():continue
						if pUnit.getUnitType() == iSluagh:continue
						if gc.getUnitInfo(pUnit.getUnitType()).getReligionType() == -1:
							return True
	return False

def helpEvangelizeUnits(lpUnits, eSpell = -1):
	szBuffer = ''
	pCaster = lpUnits[0]
	iTeam = pCaster.getTeam()
	lTargets = []
	iCount = 0
	iRel = pCaster.getReligion()
	if iRel != -1:
		infoRel = gc.getReligionInfo(iRel)
		szBuffer += localText.getText("TXT_KEY_SPELL_SPREAD_RELIGION", (u"%c " %(infoRel.getChar()) + infoRel.getDescription(), ))
		lAnimal = [gc.getInfoTypeForString('UNITCOMBAT_ANIMAL'), gc.getInfoTypeForString('UNITCOMBAT_BEAST')]
		iSluagh = gc.getInfoTypeForString('UNIT_SLUAGH')
		iX = pCaster.getX()
		iY = pCaster.getY()
		for iiX in xrange(iX-1, iX+ 2, 1):
			for iiY in xrange(iY-1, iY+ 2, 1):
				pPlot = CyMap().plot(iiX, iiY)
				if pPlot.isNone():continue
				for i in xrange(pPlot.getNumUnits()):
					pUnit = pPlot.getUnit(i)
					# if pUnit.isInvisible(iTeam, False):continue
					if pUnit.getReligion() == iRel:continue
					if pUnit in lpUnits:continue
					if pUnit.getUnitCombatType() in lAnimal:continue
					if pUnit.isAvatarOfCivLeader():continue
					if pUnit.getUnitType() == iSluagh:continue
					if pUnit.isAlive():
						if gc.getUnitInfo(pUnit.getUnitType()).getReligionType() == -1:
							iCount += 1
							lTargets.append(pUnit)

		lTargets = list(set(lTargets))
		iCount = len(lTargets)
		if iCount == 1:
			pUnit = lTargets.pop(0)
			pPlayer = gc.getPlayer(pUnit.getOwner())
			if pPlayer != -1:
				sList = cf.getNameWithColorScheme(pUnit, pUnit.isInvisible(pCaster.getTeam(), False))
				szBuffer += localText.getText("TXT_KEY_HELP_SPELL_TARGETS_THIS", ( sList, ))
		elif iCount > 0:
			sList = ''
			while len(lTargets) > 0:
				pUnit = lTargets.pop(0)
				pPlayer = gc.getPlayer(pUnit.getOwner())
				if pPlayer != -1:
					sList += cf.getNameWithColorScheme(pUnit, pUnit.isInvisible(pCaster.getTeam(), False))
					if len(lTargets) > 0:
						if len(lTargets) == 1:
							sList += " and "
						else:
							sList += ", "
			szBuffer += localText.getText("TXT_KEY_HELP_SPELL_TARGETS_THESE_COUNT_LIST", (iCount, sList, ))

		if eSpell != -1:
			if eSpell == gc.getInfoTypeForString('SPELL_ENLIGHTEN_UNITS'):
				szBuffer += helpTogglePromotions(lpUnits, eSpell, [], ['PROMOTION_ZEAL', 'PROMOTION_UNHOLY_TAINT', 'PROMOTION_CHANNELING4'], 1, True)
			if eSpell == gc.getInfoTypeForString('SPELL_EVANGELIZE_UNITS_DRAGON_CULT'):
				szBuffer += helpTogglePromotions(lpUnits, eSpell, [], ['PROMOTION_LOYALTY'], 1, True)

	return szBuffer

def spellEvangelizeUnits(pCaster, eSpell=-1):
	iRel = pCaster.getReligion()
	if iRel != -1:
		lAnimal = [gc.getInfoTypeForString('UNITCOMBAT_ANIMAL'), gc.getInfoTypeForString('UNITCOMBAT_BEAST')]
		iSluagh = gc.getInfoTypeForString('UNIT_SLUAGH')
		iX = pCaster.getX()
		iY = pCaster.getY()
		for iiX in xrange(iX-1, iX+ 2, 1):
			for iiY in xrange(iY-1, iY+ 2, 1):
				pPlot = CyMap().plot(iiX, iiY)
				if pPlot.isNone():continue
				for i in xrange(pPlot.getNumUnits()):
					pUnit = pPlot.getUnit(i)
					if pUnit.isAlive():
						if pCaster.getID() == pUnit.getID():continue
						if pUnit.getReligion() == iRel:continue
						if pUnit.getUnitCombatType() in lAnimal:continue
						if pUnit.isAvatarOfCivLeader():continue
						if pUnit.getUnitType() == iSluagh:continue
						if gc.getUnitInfo(pUnit.getUnitType()).getReligionType() == -1:
							if not effectResisted(pUnit, pCaster, eSpell):
								pUnit.setReligion(iRel)


def reqFeast(pCaster, eSpell=-1):
	pPlot = pCaster.plot()
	if pPlot.isCity():
		pCity = pPlot.getPlotCity()
		if pCity.getPopulation() > 2:
			iPlayer = pCaster.getOwner()
			pPlayer = gc.getPlayer(iPlayer)
			if pPlayer.getAlignment() == gc.getInfoTypeForString('ALIGNMENT_EVIL') or pPlayer.getCivilizationType() == gc.getInfoTypeForString('CIVILIZATION_CALABIM'):
				return True
	return False

def helpFeast(lpCasters, eSpell=-1):
	szBuffer = helpTogglePromotionsBuffCaster(lpCasters, eSpell, [], ['PROMOTION_RAVENOUS','PROMOTION_WITHERED','PROMOTION_WEAK'], False)
	szBuffer += PyHelpers.getText( "TXT_KEY_SPELL_FEAST_HELP" )
	# type: (List[CyUnit]) -> unicode
	eFeastSpell = gc.getInfoTypeForString( "SPELL_FEAST" )
	if len( lpCasters ) > 0 :
		pCaster = lpCasters[0]
		pCity = pCaster.plot().getPlotCity()
		if pCity is not None and not pCity.isNone() :
			if pCity.getPopulation() > 2:
				iPlayer = pCaster.getOwner()
				if pCity.getOwner() == iPlayer:
					pPlayer = gc.getPlayer(iPlayer)
					sNameCity = "<color=%d,%d,%d,%d>%s</color>" %(pPlayer.getPlayerTextColorR(), pPlayer.getPlayerTextColorG(), pPlayer.getPlayerTextColorB(), pPlayer.getPlayerTextColorA(), pCity.getName() )
					iPop = pCity.getPopulation()
					iXP = 0
					iEmpyrean = gc.getInfoTypeForString('RELIGION_THE_EMPYREAN')
					StateBelief = pPlayer.getStateReligion()
					bEmpyreanCaster = False
					for pCaster in lpCasters:
						if pCaster.canCast(eSpell, True):
							if pCaster.getReligion() == iEmpyrean:
								bEmpyreanCaster = True
							iXP = iPop*2/3
							iPop -= 1
							sNameCaster = cf.getNameWithColorScheme(pCaster)
							szBuffer += localText.getText("TXT_KEY_HELP_SPELL_CHANGE_XP", (sNameCaster, iXP, ))

					szBuffer += localText.getText("TXT_KEY_HELP_SPELL_NEW_POP", (sNameCity, iPop, ))
					if bEmpyreanCaster:
						szBuffer += localText.getText("TXT_KEY_HELP_SPELL_CHANGE_RELIGION_UNIT", ())
						szBuffer += localText.getText("TXT_KEY_NO_RELIGION", ())
					if StateBelief == iEmpyrean:
						szBuffer += localText.getText("TXT_KEY_HELP_SPELL_CHANGE_STATE_RELIGION", ())
						szBuffer += localText.getText("TXT_KEY_NO_RELIGION", ())
					if pPlayer.getAlignment() != gc.getInfoTypeForString('ALIGNMENT_EVIL'):
						szBuffer += localText.getText("TXT_KEY_HELP_SPELL_CHANGE_ALIGNMENT", ())
						szBuffer += localText.getText("TXT_KEY_ALIGNMENT_EVIL", ())
					lDiploPlayers = []
					iPlayer2 = pCity.getOriginalOwner()
					if iPlayer != iPlayer2:
						pPlayer2 = gc.getPlayer(iPlayer2)
						sPName = "<color=%d,%d,%d,%d>%s</color>" %(pPlayer2.getPlayerTextColorR(), pPlayer2.getPlayerTextColorG(), pPlayer2.getPlayerTextColorB(), pPlayer2.getPlayerTextColorA(), pPlayer2.getName() )
						lDiploPlayers.append(sPName)
					if pCity.isHasReligion(iEmpyrean):
						szBuffer += localText.getText("TXT_KEY_HELP_SPELL_MAY_REMOVE_STUFF", (gc.getReligionInfo(iEmpyrean).getDescription(), ))
						lBuildings = []
						for iBuilding in xrange(gc.getNumBuildingInfos()):
							if pCity.getNumBuilding(iBuilding) > 0:
								info = gc.getBuildingInfo(iBuilding)
								if info.getPrereqReligion() == iEmpyrean:
									if not isWorldWonderClass(info.getBuildingClassType()):
										lBuildings.append(iBuilding)
						lTargets = list(set(lBuildings))
						iCount = len(lTargets)
						if iCount > 0:
							sList = ''
							while len(lTargets) > 0:
								ItemInfo = gc.getBuildingInfo(lTargets.pop(0))
								sList += ItemInfo.getDescription()
								if len(lTargets) > 0:
									sList += ", "
									if len(lTargets) == 1:
										sList += "and "
							szBuffer += localText.getText("TXT_KEY_HELP_SPELL_MAY_REMOVE_STUFF", (sList, ))
						for sBuilding in ['BUILDING_TOWER_OF_COMPLACENCY', 'BUILDING_PILLAR_OF_CHAINS', 'BUILDING_UNYIELDING_ORDER','BUILDING_UNYIELDING_ORDER_GREATER']:
							if pCity.getNumBuilding(gc.getInfoTypeForString(sBuilding)):break
						else:
							szBuffer += localText.getText("TXT_KEY_HELP_SPELL_TRIGGER_REVOLT", (sNameCity, iPop, ))
						for iPlayer2 in xrange(gc.getMAX_PLAYERS()):
							pPlayer2 = gc.getPlayer(iPlayer2)
							if pPlayer2.isAlive():
								if pPlayer2.getStateReligion() == iEmpyrean:
									sPName = "<color=%d,%d,%d,%d>%s</color>" %(pPlayer2.getPlayerTextColorR(), pPlayer2.getPlayerTextColorG(), pPlayer2.getPlayerTextColorB(), pPlayer2.getPlayerTextColorA(), pPlayer2.getName() )
									lDiploPlayers.append(sPName)
					lDiploPlayers = list(set(lDiploPlayers))
					iCount = len(lDiploPlayers)
					if iCount > 0:
						sList = ''
						while len(lDiploPlayers) > 0:
							sList += lDiploPlayers.pop(0)
							if len(lDiploPlayers) > 0:
								if len(lDiploPlayers) == 1:
									sList += " and "
								else:
									sList += ", "
						szBuffer += localText.getText("TXT_KEY_HELP_SPELL_DIPLOMATIC_PENALTY_WITH_PLAYERS", (sList, ))
						
	return szBuffer

def spellFeast(pCaster, eSpell=-1):
	pPlot = pCaster.plot()
	if pPlot.isCity():
		pCity = pPlot.getPlotCity()
		iPop = pCity.getPopulation()
		if iPop > 2:
			pCaster.changeExperience(iPop*2/3, -1, False, False, False)
			if pCaster.experienceNeeded() < pCaster.getExperience():
				pCaster.setPromotionReady(True)
			pCity.changeHurryAngerTimer(3)
			iPlayer = pCaster.getOwner()
			pPlayer = gc.getPlayer(iPlayer)
			pPlayer2 = gc.getPlayer(pCity.getOriginalOwner())
			pPlayer2.AI_changeAttitudeExtra(iPlayer, -1)
			pPlayer.setAlignment(gc.getInfoTypeForString('ALIGNMENT_EVIL'))
			iEmpyrean = gc.getInfoTypeForString('RELIGION_THE_EMPYREAN')
			if pPlayer.getStateReligion() == iEmpyrean:
				pPlayer.setLastStateReligion(-1)
			if pCaster.getReligion() == iEmpyrean:
				pCaster.setReligion(-1)
			if pCity.isHasReligion(iEmpyrean):
				iRnd = CyGame().getSorenRandNum(100, "Empyrean vs Vampire revolt - triggered by Feast")
				if 1 < iRnd < iPop:
					for sBuilding in ['BUILDING_TOWER_OF_COMPLACENCY', 'BUILDING_PILLAR_OF_CHAINS', 'BUILDING_UNYIELDING_ORDER','BUILDING_UNYIELDING_ORDER_GREATER']:
						if pCity.getNumBuilding(gc.getInfoTypeForString(sBuilding)):break
					else:
						pCity.changeOccupationTimer(iRnd)
						pCity.changeHurryAngerTimer(iRnd)
						pCity.setRevolutionIndex(pCity.getRevolutionIndex() + iRnd)
						CyInterface().addMessage(iPlayer, True, 25, localText.getText("TXT_KEY_MESSAGE_EMPYREAN_REVOLT", ()), '', 1, 'Art/Interface/Buttons/Units/Priest Empyrean.dds', ColorTypes(7), pCity.getX(), pCity.getY(), True, True)
				elif CyGame().getSorenRandNum(100, "Empyrean revolt crushed by Vampires Feasting") < 2:
					if cf.removeReligion(iEmpyrean, pCity):
						pCity.setRevolutionIndex(pCity.getRevolutionIndex() - iRnd)
						for iPlayer2 in xrange(gc.getMAX_PLAYERS()):
							pPlayer2 = gc.getPlayer(iPlayer2)
							if pPlayer2.isAlive():
								if pPlayer2.getStateReligion() == iEmpyrean:
									pPlayer2.AI_changeAttitudeExtra(iPlayer, -1)

def reqFeed(pCaster, eSpell=-1):
	if pCaster.getUnitCombatType() == gc.getInfoTypeForString('UNITCOMBAT_ANIMAL'):
		return False
	if pCaster.getSpecialUnitType() == gc.getInfoTypeForString('SPECIALUNIT_SPELL'):
		return False
	if pCaster.getDuration() > 0:
		return False
	iVamp = gc.getInfoTypeForString('PROMOTION_VAMPIRE')
	if pCaster.isHasPromotion(iVamp):
		return False
	iUndead = gc.getInfoTypeForString('PROMOTION_UNDEAD')
	bGraveleech = False
	if not pCaster.isAlive():
		if pCaster.getRace() == iUndead:
			bGraveleech = True
		else:
			return False
	iCasterTier = gc.getUnitInfo(pCaster.getUnitType()).getTier()
	iCasterLevel = pCaster.getLevel()
	iBlood = gc.getInfoTypeForString('UNIT_BLOODPET')
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	pPlot = pCaster.plot()

	iIllusion = gc.getInfoTypeForString('PROMOTION_ILLUSION')
	iReflection = gc.getInfoTypeForString('PROMOTION_DARK_REFLECTION')
	lTransferable = [	'PROMOTION_IMMORTAL',

						'PROMOTION_HEROIC_DEFENSE',
						'PROMOTION_HEROIC_DEFENSE2',
						'PROMOTION_HEROIC_STRENGTH',
						'PROMOTION_HEROIC_STRENGTH2',
						'PROMOTION_STRONG',
						'PROMOTION_MORALE',
						'PROMOTION_OCCISOR',
						'PROMOTION_HASTED',
						'PROMOTION_REGENERATION',
						'PROMOTION_BLUR',
						'PROMOTION_SHADOWWALK',
						'PROMOTION_STONESKIN']

	lRemove = [			'PROMOTION_WEAK',
						'PROMOTION_FATIGUED',
						'PROMOTION_RAVENOUS',
						'PROMOTION_WITHERED']


	if pCaster.getSummoner() != -1:
		pUnit = pPlayer.getUnit(pCaster.getSummoner() )
		if pUnit.plot() == pPlot:
			if pUnit.isHasPromotion(iVamp):
				if bGraveleech == (pUnit.getRace() == iUndead):
					for sProm in lRemove:
						if pUnit.isHasPromotion(gc.getInfoTypeForString(sProm)):
							return True
					if pUnit.getDamage() > 25:
						return True
					if pCaster.isHuman():
						if pUnit.getDamage() > 0:
							return True
						if pCaster.getUnitType() == iBlood:
							if pUnit.isHasCasted() or (pUnit.getMoves() - gc.getMOVE_DENOMINATOR() < 0):
								return True
						if pUnit.isMadeAttack() and not pUnit.isBlitz ():
							return True
	for i in xrange(pPlot.getNumUnits()):
		pUnit = pPlot.getUnit(i)
		if pUnit.isHasPromotion(iVamp):
			if pUnit.isHasPromotion(iIllusion) or pUnit.isHasPromotion(iReflection):
				continue
			if bGraveleech == (pUnit.getRace() == iUndead):
				if pUnit.getOwner() != iPlayer:
					continue
				if gc.getUnitInfo(pCaster.getUnitType()).getTier() > gc.getUnitInfo(pUnit.getUnitType()).getTier():
					continue
				for sProm in lRemove:
					if pUnit.isHasPromotion(gc.getInfoTypeForString(sProm)):
						return True
				if pUnit.getDamage() > 25:
					return True
				if pCaster.isHuman():
					if pUnit.getDamage() > 0:
						return True
					if pCaster.getUnitType() == iBlood:
						if pUnit.isHasCasted() or (pUnit.getMoves() - gc.getMOVE_DENOMINATOR() < 0):
							return True
					if pUnit.isMadeAttack() and not pUnit.isBlitz ():
						return True
	return False

def spellFeed(pCaster, eSpell=-1):
	iVamp = gc.getInfoTypeForString('PROMOTION_VAMPIRE')

	iUndead = gc.getInfoTypeForString('PROMOTION_UNDEAD')
	bGraveleech = False
	if pCaster.getRace() == iUndead:
		bGraveleech = True

	pPlot = pCaster.plot()
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	pVamp = -1
	iVampDam = -1
	lTransferable = [	'PROMOTION_IMMORTAL',

						'PROMOTION_HEROIC_DEFENSE',
						'PROMOTION_HEROIC_DEFENSE2',
						'PROMOTION_HEROIC_STRENGTH',
						'PROMOTION_HEROIC_STRENGTH2',
						'PROMOTION_STRONG',
						'PROMOTION_MORALE',
						'PROMOTION_OCCISOR',
						'PROMOTION_HASTED',
						'PROMOTION_REGENERATION',
						'PROMOTION_BLUR',
						'PROMOTION_SHADOWWALK',
						'PROMOTION_STONESKIN']

	lRemove = [			'PROMOTION_WEAK',
						'PROMOTION_FATIGUED',
						'PROMOTION_RAVENOUS',
						'PROMOTION_WITHERED']

	if pCaster.getSummoner() != -1:
		pUnit = pPlayer.getUnit(pCaster.getSummoner())
		if pUnit.plot() == pPlot:
			if pUnit.isHasPromotion(iVamp):
				if bGraveleech == (pUnit.getRace() == iUndead):
					pVamp = pUnit
					iVampDam = pUnit.getDamage()
	if pVamp == -1:
		for i in xrange(pPlot.getNumUnits()):
			pUnit = pPlot.getUnit(i)
			if pUnit.isHasPromotion(iVamp):
				if bGraveleech == (pUnit.getRace() == iUndead):
					if pUnit.getOwner() != iPlayer:continue
					if pCaster.getLevel() > pUnit.getLevel():continue
					if gc.getUnitInfo(pCaster.getUnitType()).getTier() > gc.getUnitInfo(pUnit.getUnitType()).getTier():continue
					iDamage = pUnit.getDamage()
					if iDamage == iVampDam:
						if pUnit.getExperience() < pVamp.getExperience():
							pVamp = pUnit
					elif pUnit.getDamage() > iVampDam:
						pVamp = pUnit
						iVampDam = pUnit.getDamage()
	if pVamp != -1:
		pVamp.changeDamage(-20, PlayerTypes.NO_PLAYER)

		for sProm in lTransferable:
			iProm = gc.getInfoTypeForString(sProm)
			if pCaster.isHasPromotion(iProm):
				pVamp.setHasPromotion(iProm, True)
				pCaster.setHasPromotion(iProm, False)
		for sProm in lRemove:
			pVamp.setHasPromotion(gc.getInfoTypeForString(sProm), False)

		while pCaster.isImmortal():
			pVamp.changeImmortal(1)
			pCaster.changeImmortal(-1)

		if not pCaster.isMadeAttack():
			pVamp.setMadeAttack(False)
		if pCaster.getUnitType() == gc.getInfoTypeForString('UNIT_BLOODPET'):
			pVamp.setMoves(max(0, pVamp.getMoves() - gc.getMOVE_DENOMINATOR()))
			if not pCaster.isHasCasted():
				pVamp.setHasCasted(False)
			pVamp.changeExperience(pCaster.getExperience() / 2, -1, False, False, False)
			pCaster.changeExperience(-pCaster.getExperience() / 2, -1, False, False, False)
		pCaster.kill(True, 0)

def helpFeed(lpUnits, eSpell=-1):
	szBuffer0 = ''
	pCaster = lpUnits[0]
	lTransferable = [	'PROMOTION_IMMORTAL',

						'PROMOTION_HEROIC_DEFENSE',
						'PROMOTION_HEROIC_DEFENSE2',
						'PROMOTION_HEROIC_STRENGTH',
						'PROMOTION_HEROIC_STRENGTH2',
						'PROMOTION_STRONG',
						'PROMOTION_MORALE',
						'PROMOTION_OCCISOR',
						'PROMOTION_HASTED',
						'PROMOTION_REGENERATION',
						'PROMOTION_BLUR',
						'PROMOTION_SHADOWWALK',
						'PROMOTION_STONESKIN']

	lRemove = [			'PROMOTION_WEAK',
						'PROMOTION_FATIGUED',
						'PROMOTION_RAVENOUS',
						'PROMOTION_WITHERED']

	iVamp = gc.getInfoTypeForString('PROMOTION_VAMPIRE')
	iBloodpet = gc.getInfoTypeForString('UNIT_BLOODPET')
	bBloodpet = False
	pPlot = pCaster.plot()
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iXP = 0
	pVamp = -1
	iVampDam = -1
	for pCaster in lpUnits:
		if pCaster.canCast(eSpell, False):

			iXP = 0
			pVamp = -1
			iVampDam = -1
			lPromotions = []

			iUndead = gc.getInfoTypeForString('PROMOTION_UNDEAD')
			bGraveleech = False
			if pCaster.getRace() == iUndead:
				bGraveleech = True


			if pCaster.getUnitType() == iBloodpet:
				bBloodpet = True
				iXP += pCaster.getExperience()/2

			if pCaster.getSummoner() != -1:
				pUnit = pPlayer.getUnit(pCaster.getSummoner())
				if pUnit.plot() == pPlot:
					if pUnit.isHasPromotion(iVamp):
						if bGraveleech == (pUnit.getRace() == iUndead):
							pVamp = pUnit
							iVampDam = pUnit.getDamage()
			if pVamp == -1:
				for i in xrange(pPlot.getNumUnits()):
					pUnit = pPlot.getUnit(i)
					if pUnit.isHasPromotion(iVamp):
						if bGraveleech == (pUnit.getRace() == iUndead):
							if pUnit.getOwner() != iPlayer:continue
							if pCaster.getLevel() > pUnit.getLevel():continue
							if gc.getUnitInfo(pCaster.getUnitType()).getTier() > gc.getUnitInfo(pUnit.getUnitType()).getTier():continue

							iDamage = pUnit.getDamage()
							if iDamage == iVampDam:
								if pUnit.getExperience() < pVamp.getExperience():
									pVamp = pUnit
							elif pUnit.getDamage() > iVampDam:
								pVamp = pUnit
								iVampDam = pUnit.getDamage()

			sNameUnit = cf.getNameWithColorScheme(pCaster)
			szBuffer = localText.getText("TXT_KEY_SPELL_HELP_KILL_CASTER", (sNameUnit, ))
			if pVamp != -1:
				sVampName = cf.getNameWithColorScheme(pVamp, pVamp.isInvisible(pCaster.getTeam(), False))
				iHeal = min(iVampDam, 20*len(lpUnits))
				if iHeal > 0:
					szBuffer += localText.getText("TXT_KEY_SPELL_HELP_HEAL_SPECIFIC_UNIT", (sVampName, iHeal,))
				if pVamp.isMadeAttack():
					if not pCaster.isMadeAttack():
						if not pVamp.isBlitz ():
							szBuffer += localText.getText("TXT_KEY_SPELL_HELP_SPECIFIC_UNIT_SET_ATTACK_FALSE", (sVampName, ))
				if bBloodpet:
					if iXP > 0:
						szBuffer += localText.getText("TXT_KEY_HELP_SPELL_CHANGE_XP", (sVampName, iXP, ))
					if pVamp.isHasCasted():
						if not pCaster.isHasCasted():
							szBuffer += localText.getText("TXT_KEY_SPELL_HELP_RESTORE_CASTING", (sVampName,))
					if pVamp.getMoves() > pVamp.movesLeft():
						szBuffer += localText.getText("TXT_KEY_SPELL_HELP_RESTORE_UNITS_MOVEMENT", (sVampName,))

				lTransfer = []
				for sProm in lTransferable:
					iProm = gc.getInfoTypeForString(sProm)
					if pCaster.isHasPromotion(iProm):
						if not pVamp.isHasPromotion(iProm):
							lTransfer.append(sProm)

				szBuffer += helpTogglePromotionsSpecificUnits(lpUnits, [pVamp], eSpell, lTransfer, lRemove, False)
			szBuffer0 += szBuffer

	return szBuffer0

def reqForestStealth(pCaster, eSpell):

	if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_INVISIBLE')):
		return False

	pPlot = pCaster.plot()
	iHidden = gc.getInfoTypeForString('PROMOTION_HIDDEN')
	if pPlot.getFeatureType() in [gc.getInfoTypeForString('FEATURE_FOREST'), gc.getInfoTypeForString('FEATURE_JUNGLE'), gc.getInfoTypeForString('FEATURE_FOREST_ANCIENT')]:
		if not pCaster.isHasPromotion(iHidden):
			if pCaster.isMadeAttack():
				return False
			return True
	elif pCaster.isHasPromotion(iHidden):
		if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_GREY')):
			return False
		if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_STEALTH')):
			return False
		if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_SNOW_STEALTH')):
			if pPlot.getTerrainType() in [gc.getInfoTypeForString('TERRAIN_TUNDRA'), gc.getInfoTypeForString('TERRAIN_WASTELAND'), gc.getInfoTypeForString('TERRAIN_SNOW'), gc.getInfoTypeForString('TERRAIN_GLACIER')] or pPlot.getFeatureType() in [gc.getInfoTypeForString('FEATURE_BLIZZARD'), gc.getInfoTypeForString('FEATURE_ICE')]:
				return False


		pCaster.setHasPromotion(iHidden, False)
	return False


def spellForgive(pCaster, eSpell=-1):
	iMerry = gc.getInfoTypeForString('UNIT_MERRY_DANCER')
	iLairGuardian = gc.getInfoTypeForString('PROMOTION_LAIR_GUARDIAN')
	
	iReligions = [	gc.getInfoTypeForString('RELIGION_CULT_OF_THE_DRAGON'),
					gc.getInfoTypeForString('RELIGION_WHITE_HAND'),
					gc.getInfoTypeForString('RELIGION_THE_ASHEN_VEIL'),
					gc.getInfoTypeForString('RELIGION_OCTOPUS_OVERLORDS'),
					gc.getInfoTypeForString('RELIGION_COUNCIL_OF_ESUS'),
					gc.getInfoTypeForString('RELIGION_ANOINTED'),
					gc.getInfoTypeForString('RELIGION_EMBER_LEGION'),
					gc.getInfoTypeForString('RELIGION_SONS_OF_DISCORD')
					]
	iX = pCaster.getX()
	iY = pCaster.getY()
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iResistMax = 95
	iDemon = gc.getInfoTypeForString('PROMOTION_DEMON')
	if not pCaster.isHuman():
		iResistMax = 20
	iTeam = pPlayer.getTeam()
	eTeam = gc.getTeam(iTeam)
	for iiX in xrange(iX-1, iX+ 2, 1):
		for iiY in xrange(iY-1, iY+ 2, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if pUnit.isImmuneToSpell(pCaster, eSpell):continue
				if pUnit.isAvatarOfCivLeader():continue
				if pUnit.getRace() != iDemon:continue
				if isWorldUnitClass(pUnit.getUnitClassType()):continue
				if pUnit.isDelayedDeath():continue
				if eTeam.isAtWar(pUnit.getTeam()) or pCaster.isHiddenNationality() or pUnit.isHiddenNationality():
					if effectResisted(pUnit, pCaster, eSpell):continue
					spellPurgeEvil(pUnit)
					
					pPlot = pCaster.plot()
					pPlayerU = gc.getPlayer(pUnit.getOwner())
					sName = cf.getNameWithColorScheme(pUnit, pUnit.isInvisible(pCaster.getTeam(), False))
					CyInterface().addMessage(pUnit.getOwner(), True, 25, localText.getText("TXT_KEY_MESSAGE_DOMINATION", (sName,)), '', 1, 'Art/Interface/Buttons/Spells/Domination.dds', ColorTypes(7), pUnit.getX(), pUnit.getY(), True, True)
					CyInterface().addMessage(pCaster.getOwner(), True, 25, localText.getText("TXT_KEY_MESSAGE_DOMINATION_ENEMY", (sName,)), '', 1, 'Art/Interface/Buttons/Spells/Domination.dds', ColorTypes(8), pPlot.getX(), pPlot.getY(), True, True)
					iType = pUnit.getUnitType()
					infoUnit = gc.getUnitInfo(iType)
					if infoUnit.getFreePromotions(iDemon) or infoUnit.getPrereqReligion() in iReligions:
						iType = iMerry
					newUnit = pPlayer.initUnit(iType, pPlot.getX(), pPlot.getY(), UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
					cf.removeAffinities(newUnit)
					newUnit.convert(pUnit)
					newUnit.setHasPromotion(iLairGuardian, False)
					if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_HIDDEN_NATIONALITY')):
						newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_HIDDEN_NATIONALITY'), False)
					spellPurgeEvil(newUnit)
					newUnit.setReligion(pCaster.getReligion())
					newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_ANGEL'), True)

def reqForgive(pCaster, eSpell=-1):
	iX = pCaster.getX()
	iY = pCaster.getY()
	iPlayer = pCaster.getOwner()
	iResistMax = 95
	iDemon = gc.getInfoTypeForString('PROMOTION_DEMON')
	if not pCaster.isHuman():
		iResistMax = 20
	iTeam = pCaster.getTeam()
	eTeam = gc.getTeam(iTeam)
	for iiX in xrange(iX-1, iX+ 2, 1):
		for iiY in xrange(iY-1, iY+ 2, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if pUnit.isImmuneToSpell(pCaster, eSpell):continue
				if pUnit.isAvatarOfCivLeader():continue
				if pUnit.getRace() != iDemon:continue
				if isWorldUnitClass(pUnit.getUnitClassType()):continue
				if pUnit.isDelayedDeath():continue
				if eTeam.isAtWar(pUnit.getTeam()) or pCaster.isHiddenNationality() or pUnit.isHiddenNationality():
					iResist = pUnit.getResistChance(pCaster, eSpell)
					if iResist < iResistMax:
						return True
	return False

def helpForgive(lpUnits, eSpell=-1):

	szBuffer = ''
	pCaster = lpUnits[0]
	iCount = 0
	lTargets= []
	iX = pCaster.getX()
	iY = pCaster.getY()
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iDemon = gc.getInfoTypeForString('PROMOTION_DEMON')
	iTeam = pPlayer.getTeam()
	eTeam = gc.getTeam(iTeam)
	for iiX in xrange(iX-1, iX+ 2, 1):
		for iiY in xrange(iY-1, iY+ 2, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if pUnit.isImmuneToSpell(pCaster, eSpell):continue
				# if pUnit.isInvisible(iTeam, False):continue
				if pUnit.isAvatarOfCivLeader():continue
				if pUnit.getRace() != iDemon:continue
				if isWorldUnitClass(pUnit.getUnitClassType()):continue
				if pUnit.isDelayedDeath():continue
				if eTeam.isAtWar(pUnit.getTeam()) or pCaster.isHiddenNationality() or pUnit.isHiddenNationality():
					iCount += 1
					lTargets.append(pUnit)

	lTargets = list(set(lTargets))
	iCount = len(lTargets)
	if iCount > 0:
		szBuffer += localText.getText("TXT_KEY_HELP_SPELL_CONVERT", ())
		if iCount == 1:
			pUnit = lTargets.pop(0)
			pPlayer = gc.getPlayer(pUnit.getOwner())
			sList = cf.getNameWithColorScheme(pUnit, pUnit.isInvisible(pCaster.getTeam(), False))
			szBuffer += localText.getText("TXT_KEY_HELP_SPELL_TARGETS_THIS", ( sList, ))
		else:
			sList = ''
			while len(lTargets) > 0:
				pUnit = lTargets.pop(0)
				pPlayer = gc.getPlayer(pUnit.getOwner())
				sList += cf.getNameWithColorScheme(pUnit, pUnit.isInvisible(pCaster.getTeam(), False))
				if len(lTargets) > 0:
					if len(lTargets) == 1:
						sList += " and "
					else:
						sList += ", "
			szBuffer += localText.getText("TXT_KEY_HELP_SPELL_TARGETS_THESE_COUNT_LIST", (iCount, sList, ))
	return szBuffer




def reqForTheHorde(pCaster, eSpell=-1):
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iOrc = gc.getInfoTypeForString('PROMOTION_ORC')
	iSluagh = gc.getInfoTypeForString('UNIT_SLUAGH')
	iCount = 0
	bPlayer = gc.getPlayer(gc.getBARBARIAN_PLAYER())
	(loopUnit, iter) = bPlayer.firstUnit(False)
	while(loopUnit):
		if not loopUnit.isDead(): #is the unit alive and valid?
			if loopUnit.getRace() == iOrc:
				if loopUnit.getUnitType() != iSluagh:
					if not isWorldUnitClass(loopUnit.getUnitClassType()):
						iCount += 1
						if pCaster.isHuman():
							return True
		(loopUnit, iter) = bPlayer.nextUnit(iter, False)
	map = gc.getMap()
	if pPlayer.getNumCities() > (gc.getWorldInfo(map.getWorldSize()).getTargetNumCities() - 1):
		return True
	eTeam = gc.getTeam(pCaster.getTeam())
	if eTeam.getAtWarCount(True) == 0:
		return False
	if iCount < (pPlayer.getNumCities() * 5):
		return False
	return True

def spellForTheHorde(pCaster, eSpell=-1):
	iX = pCaster.getX()
	iY = pCaster.getY()
	gc.getTeam(pCaster.getTeam()).makePeace(gc.getBARBARIAN_TEAM())
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iOrc = gc.getInfoTypeForString('PROMOTION_ORC')

	iSluagh = gc.getInfoTypeForString('UNIT_SLUAGH')


	bPlayer = gc.getPlayer(gc.getBARBARIAN_PLAYER())
	for loopUnit in PyPlayer(gc.getBARBARIAN_PLAYER()).getUnitList():
		if loopUnit.getRace() == iOrc:
			if loopUnit.getUnitType() != iSluagh:
				if not isWorldUnitClass(loopUnit.getUnitClassType()):
					if CyGame().getSorenRandNum(100, "For the Horde") < 50:
						newUnit = pPlayer.initUnit(loopUnit.getUnitType(), iX, iY, UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
						newUnit.convert(loopUnit)
						

def reqFormWolfPack(pCaster, eSpell=-1):
	iPlayer = pCaster.getOwner()
	pPlot = pCaster.plot()
	iWolf = gc.getInfoTypeForString('UNIT_WOLF')
	iCount = 0
	for i in xrange(pPlot.getNumUnits()):
		pUnit = pPlot.getUnit(i)
		if pUnit.getUnitType() == iWolf:
			if pUnit.getOwner() == iPlayer:
				iCount += 1
	if iCount < 2:
		return False
	if not pCaster.isHuman():
		if pCaster.baseCombatStr() > 2:
			return False
	return True

def spellFormWolfPack(pCaster, eSpell=-1):
	pPlot = pCaster.plot()
	iWolf = gc.getInfoTypeForString('UNIT_WOLF')
	pWolf2 = -1
	for i in xrange(pPlot.getNumUnits()):
		pUnit = pPlot.getUnit(i)
		if pUnit.getUnitType() == iWolf:
			if pUnit.getOwner() == pCaster.getOwner():
				if pUnit.getID() != pCaster.getID():
					pWolf2 = pUnit
	if pWolf2 != -1:
		iPlayer = pCaster.getOwner()
		pPlayer = gc.getPlayer(iPlayer)
		newUnit = pPlayer.initUnit(gc.getInfoTypeForString('UNIT_WOLF_PACK'), pCaster.getX(), pCaster.getY(), UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
		newUnit.setExperience(pCaster.getExperience() + pWolf2.getExperience(), -1)
		newUnit.setUnitAIType(gc.getInfoTypeForString('UNITAI_ATTACK'))
		pCaster.kill(True, PlayerTypes.NO_PLAYER)
		pWolf2.kill(True, PlayerTypes.NO_PLAYER)

