def reqGiftOfVampirism(pCaster, eSpell=-1):
	iVamp = gc.getInfoTypeForString('PROMOTION_VAMPIRE')
	if pCaster.isHasPromotion(iVamp):
		return False
	elif cf.getUnitAlignment(pCaster) == gc.getInfoTypeForString('ALIGNMENT_GOOD'):
		return False
	elif pCaster.getLevel() < 6:
		if pCaster.getUnitType() == gc.getInfoTypeForString('UNIT_MOROI'):
			if pCaster.getLevel() < 3:
				return False
		else:
			return False
	pPlot = pCaster.plot()
	if pPlot.isCity():
		pCity = pPlot.getPlotCity()
		if pCity.getTeam() == pCaster.getTeam():
			if pCity.getNumBuilding(gc.getInfoTypeForString('BUILDING_GOVERNORS_MANOR')) > 0:
				return True

	if pCaster.getSummoner() != -1:
		iPlayer = pCaster.getOwner()
		pPlayer = gc.getPlayer(iPlayer)
		pUnit = pPlayer.getUnit(pCaster.getSummoner())
		if pUnit.isHasPromotion(iVamp):
			if pPlot == pUnit.plot():
				return True

	for i in xrange(pPlot.getNumUnits()):
		pUnit = pPlot.getUnit(i)
		if pCaster.getID() == pUnit.getID():continue
		if pUnit.isHasPromotion(iVamp):
			if pUnit.getTeam() == pCaster.getTeam():
				return True
	return False

def spellGiftOfVampirism(pCaster, eSpell=-1):

	pPlot = pCaster.plot()
	iVamp = gc.getInfoTypeForString('PROMOTION_VAMPIRE')
	pCaster.setHasPromotion(iVamp, True)
	em.onUnitPromoted([pCaster, iVamp])
	pSire = -1
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)

	iChanneling3 = gc.getInfoTypeForString('PROMOTION_CHANNELING3')
	iMastery = gc.getInfoTypeForString('PROMOTION_MASTERY')

	sName = pCaster.getNameNoDesc()
	if sName == '':
		sName = pCaster.getName()
	iTruncate = sName.find(", Thrall of ")
	if iTruncate != -1:
		sName = sName[:iTruncate]
		pCaster.setName(sName)

	if pCaster.getReligion() in [gc.getInfoTypeForString('RELIGION_THE_EMPYREAN'),gc.getInfoTypeForString('RELIGION_BROTHERHOOD_OF_WARDENS')]:
		pCaster.setReligion(-1)

	if pCaster.getSummoner() != -1:
		pUnit = pPlayer.getUnit(pCaster.getSummoner())
		if pUnit.isHasPromotion(iVamp):
			if pPlot == pUnit.plot():
				pSire = pUnit
	if pSire == -1:
		for i in xrange(pPlot.getNumUnits()):
			pUnit = pPlot.getUnit(i)
			if pUnit.isHasPromotion(iVamp):
				if pUnit.getTeam() != pCaster.getTeam():continue
				if pCaster.getID() == pUnit.getID():continue
##				if pCaster is pUnit:continue

				if pSire == -1 or getCombatOdds(pSire, pUnit) < 500:
					pSire = pUnit

	listMana = [
				(gc.getInfoTypeForString('BONUS_MANA_BODY'), gc.getInfoTypeForString('PROMOTION_BODY1'), gc.getInfoTypeForString('PROMOTION_BODY2'), gc.getInfoTypeForString('PROMOTION_BODY3'), gc.getInfoTypeForString('PROMOTION_AFFINITY_BODY')),
				(gc.getInfoTypeForString('BONUS_MANA_DEATH'), gc.getInfoTypeForString('PROMOTION_DEATH1'), gc.getInfoTypeForString('PROMOTION_DEATH2'), gc.getInfoTypeForString('PROMOTION_DEATH3'), gc.getInfoTypeForString('PROMOTION_AFFINITY_DEATH')),
				(gc.getInfoTypeForString('BONUS_MANA_MIND'), gc.getInfoTypeForString('PROMOTION_MIND1'), gc.getInfoTypeForString('PROMOTION_MIND2'), gc.getInfoTypeForString('PROMOTION_MIND3'), gc.getInfoTypeForString('PROMOTION_AFFINITY_MIND')),
				(gc.getInfoTypeForString('BONUS_MANA_SHADOW'), gc.getInfoTypeForString('PROMOTION_SHADOW1'), gc.getInfoTypeForString('PROMOTION_SHADOW2'), gc.getInfoTypeForString('PROMOTION_SHADOW3'), gc.getInfoTypeForString('PROMOTION_AFFINITY_SHADOW')),
				(gc.getInfoTypeForString('BONUS_MANA_SPIRIT'), gc.getInfoTypeForString('PROMOTION_SPIRIT1'), gc.getInfoTypeForString('PROMOTION_SPIRIT2'), gc.getInfoTypeForString('PROMOTION_SPIRIT3'), gc.getInfoTypeForString('PROMOTION_AFFINITY_SPIRIT'))
		]

	listLegacy = [
					gc.getInfoTypeForString('PROMOTION_ARCANE'),
					gc.getInfoTypeForString('PROMOTION_OCCISOR'),
					gc.getInfoTypeForString('PROMOTION_CANNIBALIZE'),
					gc.getInfoTypeForString('PROMOTION_EXTENSION1'),
					gc.getInfoTypeForString('PROMOTION_EXTENSION2'),
					gc.getInfoTypeForString('PROMOTION_FEAR'),
					gc.getInfoTypeForString('PROMOTION_ILLUSIONIST'),
					gc.getInfoTypeForString('PROMOTION_STEALTH'),
					gc.getInfoTypeForString('PROMOTION_STIGMATA'),
					gc.getInfoTypeForString('PROMOTION_STRONG'),
					gc.getInfoTypeForString('PROMOTION_SUMMONER'),
					gc.getInfoTypeForString('PROMOTION_SUNDERED'),
					gc.getInfoTypeForString('PROMOTION_TWINCAST'),
					gc.getInfoTypeForString('PROMOTION_UNHOLY_TAINT')
					]
	if pSire != -1:
		pCaster.setSummoner(pSire.getID())
		sNameS = pSire.getNameNoDesc()
		if sNameS == '':
			sNameS = pSire.getName()

		iTruncate = sNameS.find(" von ")
		if iTruncate != -1:
			sNameS = sNameS[:iTruncate]

		sNameS = " von " + sNameS
		sName += sNameS
		pCaster.setName(sName)


		iUndead = gc.getInfoTypeForString('PROMOTION_UNDEAD')
		if pSire.isHasPromotion(iUndead):#Graveleech of clan Churel
			pCaster.setHasPromotion(iUndead, True)
			em.onUnitPromoted([pCaster, iUndead])


		while len(listLegacy) > 0:
			iProm = listLegacy.pop(CyGame().getSorenRandNum(len(listLegacy), "Vampiric Legacy"))
			if pSire.isHasPromotion(iProm) and not pCaster.isHasPromotion(iProm):
				if CyGame().getSorenRandNum(pSire.getLevel(), "Vampiric inheritance") < pCaster.getLevel():
					pCaster.setHasPromotion(iProm, True)
					em.onUnitPromoted([pCaster, iProm])

		for iMana, iSpell1, iSpell2, iSpell3, iAffinity in listMana:
			if not pCaster.isHasPromotion(iAffinity):
				if cf.getNumBonusEffective(iPlayer, iMana, pCaster) > 0:
					if pSire.isHasPromotion(iAffinity):
						if CyGame().getSorenRandNum(pSire.getLevel(), "Vampiric inheritance") < pCaster.getLevel():
							if pCaster.canAcquirePromotion(iAffinity):
								pCaster.setHasPromotion(iAffinity, True)
								em.onUnitPromoted([pCaster, iAffinity])
							else:
								if pCaster.canAcquirePromotion(iSpell1):
									pCaster.setHasPromotion(iSpell1, True)
									em.onUnitPromoted([pCaster, iSpell1])
								if pCaster.canAcquirePromotion(iSpell2):
									pCaster.setHasPromotion(iSpell2, True)
									em.onUnitPromoted([pCaster, iSpell2])
								if pSire.isHasPromotion(iChanneling3):
									if pCaster.canAcquirePromotion(iSpell3):
										pCaster.setHasPromotion(iSpell3, True)
										em.onUnitPromoted([pCaster, iSpell3])
					else:
						if pSire.isHasPromotion(iSpell1):
							if CyGame().getSorenRandNum(pSire.getLevel(), "Vampiric inheritance") < pCaster.getLevel():
								if pCaster.canAcquirePromotion(iSpell1):
									pCaster.setHasPromotion(iSpell1, True)
									em.onUnitPromoted([pCaster, iSpell1])
								if pSire.isHasPromotion(iSpell2):
									if pCaster.canAcquirePromotion(iSpell2):
										pCaster.setHasPromotion(iSpell2, True)
										em.onUnitPromoted([pCaster, iSpell2])
									if pSire.isHasPromotion(iSpell3):
										if pCaster.canAcquirePromotion(iSpell3):
											pCaster.setHasPromotion(iSpell3, True)
											em.onUnitPromoted([pCaster, iSpell3])

	elif pPlot.isCity():
		pCity = pPlot.getPlotCity()
		sName += " von " + pCity.getName()
		pCaster.setName(sName)
		for iMana, iSpell1, iSpell2, iSpell3, iAffinity in listMana:
			iLiegeMana = CyGame().getSorenRandNum(pCity.getNumBonuses(iMana) + cf.getNumBonusEffective(iPlayer, iMana, pCaster), "Vampire Governor's vassal mana")/2
			if iLiegeMana > 1:
				if pCaster.canAcquirePromotion(iSpell1):
					pCaster.setHasPromotion(iSpell1, True)
					em.onUnitPromoted([pCaster, iSpell1])
				if iLiegeMana > 3:
					if pCaster.canAcquirePromotion(iSpell2):
						pCaster.setHasPromotion(iSpell2, True)
						em.onUnitPromoted([pCaster, iSpell2])
					if iLiegeMana > 7:
						if pCaster.isHasPromotion(iChanneling3):
							if pCaster.canAcquirePromotion(iSpell3):
								pCaster.setHasPromotion(iSpell3, True)
								em.onUnitPromoted([pCaster, iSpell3])

