def reqHellfire(pCaster, eSpell=-1):
	iTimer = pCaster.getLevel() + cf.getNumBonusEffective(pCaster.getOwner(), gc.getInfoTypeForString('BONUS_MANA_ENTROPY')) + cf.getNumBonusEffective(pCaster.getOwner(), gc.getInfoTypeForString('BONUS_MANA_FIRE'))
	if iTimer < 1:
		return False
	pPlot = pCaster.plot()
	if pPlot.isCity():
		return False
	iHellfire = gc.getInfoTypeForString('IMPROVEMENT_HELLFIRE')
	iImprovement = pPlot.getImprovementType()
	if iImprovement != -1:
		if iImprovement == iHellfire:
			# if -1 < pPlot.getTempImprovementTimer() < iTimer:
				# pPlot.changeTempImprovementTimer(1)
			return False
		elif gc.getImprovementInfo(iImprovement).isUnique():
			return False
	iX = pCaster.getX()
	iY = pCaster.getY()
	for iDirection in xrange(DirectionTypes.NUM_DIRECTION_TYPES):
		pAdjacentPlot = plotDirection(iX, iY, DirectionTypes(iDirection))
		if pAdjacentPlot.isNone():continue
		if pAdjacentPlot.getImprovementType() == iHellfire:
			return False
	return True

def spellHellfire(pCaster, eSpell=-1):
	pPlot = pCaster.plot()
	iTimer = pCaster.getLevel() + cf.getNumBonusEffective(pCaster.getOwner(), gc.getInfoTypeForString('BONUS_MANA_ENTROPY')) + cf.getNumBonusEffective(pCaster.getOwner(), gc.getInfoTypeForString('BONUS_MANA_FIRE'))
	iX = pCaster.getX()
	iY = pCaster.getY()
	for iDirection in xrange(DirectionTypes.NUM_DIRECTION_TYPES):
		pAdjacentPlot = plotDirection(iX, iY, DirectionTypes(iDirection))
		if pAdjacentPlot.isNone():continue
		if pCaster.canMoveOrAttackInto(pAdjacentPlot, False):
			pAdjacentPlot.changePlotCounter(iTimer)
	pPlot.setTempImprovementType(gc.getInfoTypeForString('IMPROVEMENT_HELLFIRE'), iTimer)

	if gc.getGame().isOption(GameOptionTypes.GAMEOPTION_ADVANCED_TACTICS):
		iPlayer = pCaster.getOwner()
		pPlayer = gc.getPlayer(iPlayer)
		iInf = gc.getInfoTypeForString('CIVILIZATION_INFERNAL')
		iAV = gc.getInfoTypeForString('RELIGION_THE_ASHEN_VEIL')
		if pPlot.isBarbarian():
			if pPlayer.getCivilizationType() == iInf:
				pPlot.setOwner(iPlayer)
		elif pPlot.isOwned():
			if gc.getPlayer(pPlot.getOwner()).getCivilizationType() != iInf:
				pPlot.setOwner(gc.getBARBARIAN_PLAYER())
		else:
			if pPlayer.getCivilizationType() == iInf:
				pPlot.setOwner(iPlayer)
			else:
				pPlot.setOwner(gc.getBARBARIAN_PLAYER())

def helpHellfire(lpUnits, eSpell=-1):
	iTimer = 0
	for pCaster in lpUnits:
		if pCaster.canCast(eSpell, True):
			iTimer = max(iTimer, ( pCaster.getLevel() + cf.getNumBonusEffective(pCaster.getOwner(), gc.getInfoTypeForString('BONUS_MANA_ENTROPY')) + cf.getNumBonusEffective(pCaster.getOwner(), gc.getInfoTypeForString('BONUS_MANA_FIRE')) ) )
	return helpChangeImprovement(lpUnits, 'IMPROVEMENT_HELLFIRE', iTimer, eSpell)

