def reqIllusion(pCaster, eSpell=-1):
	iIllusion = gc.getInfoTypeForString('PROMOTION_ILLUSION')
	if pCaster.isHasPromotion(iIllusion):
		return False

	pCity = findAdjacentCity(pCaster)
	if pCity:
		iUnit = pCity.getConscriptUnit()
		if iUnit != -1:
			return True

	lNonCombat = [-1, gc.getInfoTypeForString('UNITCOMBAT_CIVILIAN')]
	iX = pCaster.getX()
	iY = pCaster.getY()
	for iiX in xrange(iX-1, iX+ 2, 1):
		for iiY in xrange(iY-1, iY+ 2, 1):
			pLoopPlot = CyMap().plot(iiX, iiY)
			if pLoopPlot.isNone():continue
			for i in xrange(pLoopPlot.getNumUnits()):
				pUnit = pLoopPlot.getUnit(i)
				if pUnit.baseCombatStrDefense() > 1:
					if pUnit.isHasPromotion(iIllusion):continue
					if pUnit.isImmuneToMagic():continue
					if pUnit.isOnlyDefensive():continue
					if pUnit.isAvatarOfCivLeader():continue
					if pUnit.getUnitCombatType() in lNonCombat:continue
					if pUnit.isImmortal():continue
					info = gc.getUnitInfo(pUnit.getUnitType())
					if info.isObject():continue
					return True
	return False

def spellIllusion(pCaster, eSpell=-1):
	iIllusion = gc.getInfoTypeForString('PROMOTION_ILLUSION')
	lNonCombat = [-1, gc.getInfoTypeForString('UNITCOMBAT_CIVILIAN')]
	iRnd = CyGame().getSorenRandNum(pCaster.getLevel()/2, "Illusion") + 1
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iDuration = 1
	if pPlayer.hasTrait(gc.getInfoTypeForString('TRAIT_SUMMONER')):
		iDuration = 2
	iCount = 0
	lUnitType = []
	iX = pCaster.getX()
	iY = pCaster.getY()
	for iiX in xrange(iX-1, iX+ 2, 1):
		for iiY in xrange(iY-1, iY+ 2, 1):
			pLoopPlot = CyMap().plot(iiX, iiY)
			if pLoopPlot.isNone():continue
			for i in xrange(pLoopPlot.getNumUnits()):
				pUnit = pLoopPlot.getUnit(i)
				if pUnit.baseCombatStrDefense() > 1:
					if pUnit.isHasPromotion(iIllusion):continue
					if pUnit.isImmuneToMagic():continue
					if pUnit.isOnlyDefensive():continue
					if pUnit.isAvatarOfCivLeader():continue
					if pUnit.getUnitCombatType() in lNonCombat:continue
					if pUnit.isImmortal():continue
					info = gc.getUnitInfo(pUnit.getUnitType())
					if info.isObject():continue
					lUnitType.append(pUnit.getUnitType())

	pCity = findAdjacentCity(pCaster)
	if pCity:
		iUnit = pCity.getConscriptUnit()
		if iUnit != -1:
			lUnitType.append(iUnit)


	while iCount < iRnd and len(lUnitType) > 0:
		iCount += 1
		iUnitType = lUnitType.pop(CyGame().getSorenRandNum(len(lUnitType), "Create Illusion"))
		newUnit = pPlayer.initUnit(iUnitType, iX, iY, UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_NORTH)
		for iProm in xrange(gc.getNumPromotionInfos()):
			if gc.getPromotionInfo(iProm).isEquipment():
				newUnit.setHasPromotion(iProm, False)
		newUnit.setSummoner(pCaster.getID())
		newUnit.setDuration(iDuration)
		newUnit.setHasPromotion(iIllusion, True)
		newUnit.setIgnoreHide(True)
		if newUnit.isAvatarOfCivLeader():
			newUnit.setAvatarOfCivLeader(False)
		# newUnit.setMadeAttack(True)
		# newUnit.setHasCasted(True)
##		gc.getGame().decrementUnitClassCreatedCount(newUnit.getUnitClassType())
##		gc.getGame().decrementUnitCreatedCount(newUnit.getUnitType())

def helpIllusion(lpUnits, eSpell=1):
	szBuffer = ''
	pCaster = lpUnits[0]
	iIllusion = gc.getInfoTypeForString('PROMOTION_ILLUSION')
	lNonCombat = [-1, gc.getInfoTypeForString('UNITCOMBAT_CIVILIAN')]
	iRnd = 0
	for pCaster in lpUnits:
		if pCaster.canCast(eSpell, True):
			iRnd += pCaster.getLevel()/2 + 1
	lUnitType = []
	iX = pCaster.getX()
	iY = pCaster.getY()
	for iiX in xrange(iX-1, iX+ 2, 1):
		for iiY in xrange(iY-1, iY+ 2, 1):
			pLoopPlot = CyMap().plot(iiX, iiY)
			if pLoopPlot.isNone():continue
			for i in xrange(pLoopPlot.getNumUnits()):
				pUnit = pLoopPlot.getUnit(i)
				if pUnit.baseCombatStrDefense() > 0:
					if pUnit.isImmuneToMagic():continue
					if pUnit.isOnlyDefensive():continue
					if pUnit.isAvatarOfCivLeader():continue
					if pUnit.isHasPromotion(iIllusion):continue
					if pUnit.getUnitCombatType() in lNonCombat:continue
					if pUnit.isImmortal():continue
					info = gc.getUnitInfo(pUnit.getUnitType())
					if info.isObject():continue
					lUnitType.append(pUnit.getUnitType())

	pCity = findAdjacentCity(pCaster)
	if pCity:
		iUnit = pCity.getConscriptUnit()
		if iUnit != -1:
			lUnitType.append(iUnit)

	lRecruits = list(set(lUnitType))
	if len(lRecruits) > 0:
		sList = ''
		while len(lRecruits) > 0:
			iRecruit= lRecruits.pop(0)
			sList += gc.getUnitInfo(iRecruit).getDescription()
			if len(lRecruits) > 0:
				if len(lRecruits) == 1:
					sList += " or "
				else:
					sList += ", "
		szBuffer += localText.getText("TXT_KEY_HELP_SPELL_ILLUSION", (iRnd, sList, ))
	return szBuffer

def reqImpersonateLeader(pCaster, eSpell=-1):
	pCity = pCaster.plot().getPlotCity()
	if pCity.isBarbarian():
		return False
	if pCity.getOwner() == pCaster.getOwner():
		return False
	if pCity.isHuman():
		return False
	return True

def spellImpersonateLeader(pCaster, eSpell=-1):
	pCity = pCaster.plot().getPlotCity()
	iNewPlayer = pCity.getOwner()
	iOldPlayer = pCaster.getOwner()
	iTimer = 3 + CyGame().getSorenRandNum(7, "Impersonate Leader")
	CyGame().reassignPlayerAdvanced(iOldPlayer, iNewPlayer, iTimer)
	pCaster.changeImmobileTimer(iTimer)

def helpImpersonateLeader(lpUnits, eSpell=1):
	szBuffer = ''
	pCaster = lpUnits[0]
	pPlot = pCaster.plot()
	if pPlot.isCity():
		pCity = pPlot.getPlotCity()
		iNewPlayer = pCity.getOwner()
		if iNewPlayer != pCaster.getOwner():
			iMin = 5
			iMax = 14
			sPlayerName = gc.getPlayer(iNewPlayer).getName()
			szBuffer += localText.getText("TXT_KEY_HELP_SPELL_IMPERSONATE", (sPlayerName, iMin, iMax, ))
	return szBuffer


def spellEpiphany(pCaster, eSpell):
	iTeam = pCaster.getTeam()
	CyMap().setRevealedPlots(iTeam, True, False)
	eTeam = gc.getTeam(iTeam)
	for iTeam2 in xrange(gc.getMAX_TEAMS()):
		if iTeam == iTeam2:continue
		if iTeam2 == gc.getBARBARIAN_TEAM():continue
		eTeam2 = gc.getTeam(iTeam2)
		if eTeam2.isAlive():
			eTeam.changeStolenVisibilityTimer(iTeam2, 1)

def reqEpiphany(pCaster, eSpell):
	iTeam = pCaster.getTeam()
	eTeam = gc.getTeam(iTeam)
	for iTeam2 in xrange(gc.getMAX_TEAMS()):
		if iTeam == iTeam2:continue
		if iTeam2 == gc.getBARBARIAN_TEAM():continue
		eTeam2 = gc.getTeam(iTeam2)
		if eTeam2.isAlive():
			if not eTeam.isStolenVisibility(iTeam2):
				return True
	return False


def spellEstablishTemple(pCaster, eSpell):

	pPlot = pCaster.plot()
	if pPlot.isCity():
		pCity = pPlot.getPlotCity()
		iPlayer = pCity.getOwner()
		pPlayer = gc.getPlayer(iPlayer)
		
		iStateReligion = pPlayer.getStateReligion()

		iAlignment = pPlayer.getAlignment()
		iLeader = pPlayer.getLeaderType()
		iGood = gc.getInfoTypeForString('ALIGNMENT_GOOD')
		iEvil = gc.getInfoTypeForString('ALIGNMENT_EVIL')
		bFriendly = -1
		iTempleHostile = -1
		iTempleFriendly = gc.getSpellInfo(eSpell).getCreateBuildingType()
		if iTempleFriendly != -1:
			if iTempleFriendly == gc.getInfoTypeForString('BUILDING_TEMPLE_THE_ONE'):
				iTempleHostile = gc.getInfoTypeForString('BUILDING_TEMPLE_THE_ONE_HOSTILE')
				bFriendly = pPlayer.getStateReligion() == -1
			elif iTempleFriendly == gc.getInfoTypeForString('BUILDING_TEMPLE_OF_THE_EMPYREAN'):
				iTempleHostile = gc.getInfoTypeForString('BUILDING_TEMPLE_OF_THE_EMPYREAN_HOSTILE')
				bFriendly = pPlayer.getStateReligion() == gc.getInfoTypeForString('RELIGION_THE_EMPYREAN') or pPlayer.isFullMember(gc.getInfoTypeForString('DIPLOVOTE_OVERCOUNCIL')) or iAlignment == iGood
			elif iTempleFriendly == gc.getInfoTypeForString('BUILDING_TEMPLE_BROTHERHOOD'):
				if pCity.getCivilizationType() == gc.getInfoTypeForString('CIVILIZATION_CALABIM'):
					pCity.setNumRealBuilding(gc.getInfoTypeForString('BUILDING_TEMPLE_BROTHERHOOD_HOSTILE'), False)
					pCity.setNumRealBuilding(iTempleFriendly, False)
					iTempleFriendly = gc.getInfoTypeForString('BUILDING_TEMPLE_BLIND_BROTHERHOOD')
					pCity.setNumRealBuilding(iTempleFriendly, True)
				else:
					pCity.setNumRealBuilding(gc.getInfoTypeForString('BUILDING_TEMPLE_BLIND_BROTHERHOOD'), False)
					iTempleHostile = gc.getInfoTypeForString('BUILDING_TEMPLE_BROTHERHOOD_HOSTILE')
					bFriendly = pPlayer.getStateReligion() == gc.getInfoTypeForString('RELIGION_BROTHERHOOD_OF_WARDENS') or pPlayer.isCivic(gc.getInfoTypeForString('CIVIC_PACIFISM')) or iAlignment == iGood
			elif iTempleFriendly == gc.getInfoTypeForString('BUILDING_ARTIFICERY'):
				iTempleHostile = gc.getInfoTypeForString('BUILDING_ARTIFICERY_HOSTILE')
				bFriendly = pPlayer.getStateReligion() == gc.getInfoTypeForString('RELIGION_RINGGIVER') or iAlignment == iGood or pPlayer.isCivic(gc.getInfoTypeForString('CIVIC_ARETE'))
			elif iTempleFriendly == gc.getInfoTypeForString('BUILDING_TEMPLE_OF_THE_ORDER'):
				iTempleHostile = gc.getInfoTypeForString('BUILDING_TEMPLE_OF_THE_ORDER_HOSTILE')
				bFriendly = pPlayer.getStateReligion() == gc.getInfoTypeForString('RELIGION_THE_ORDER') or iAlignment == iGood
			elif iTempleFriendly == gc.getInfoTypeForString('BUILDING_TEMPLE_UNBLEMISHED'):
				iTempleHostile = gc.getInfoTypeForString('BUILDING_TEMPLE_UNBLEMISHED_HOSTILE')
				bFriendly = pPlayer.getStateReligion() in [gc.getInfoTypeForString('RELIGION_UNBLEMISHED'),gc.getInfoTypeForString('RELIGION_FELLOWSHIP_OF_LEAVES')] or iAlignment == iGood
			elif iTempleFriendly == gc.getInfoTypeForString('BUILDING_TEMPLE_OF_KILMORPH'):
				iTempleHostile = gc.getInfoTypeForString('BUILDING_TEMPLE_OF_KILMORPH_HOSTILE')
				bFriendly = pPlayer.getStateReligion() == gc.getInfoTypeForString('RELIGION_RUNES_OF_KILMORPH') or (iAlignment != iEvil and pPlayer.getStateReligion() != gc.getInfoTypeForString('RELIGION_FOXMEN'))
			elif iTempleFriendly == gc.getInfoTypeForString('BUILDING_TEMPLE_OF_THE_OVERLORDS'):
				iTempleHostile = gc.getInfoTypeForString('BUILDING_TEMPLE_OF_THE_OVERLORDS_HOSTILE')
				bFriendly = pPlayer.getStateReligion() == gc.getInfoTypeForString('RELIGION_OCTOPUS_OVERLORDS') or iAlignment != iGood
			elif iTempleFriendly == gc.getInfoTypeForString('BUILDING_APHOTIC_THRONE'):
				iTempleHostile = gc.getInfoTypeForString('BUILDING_APHOTIC_THRONE_HOSTILE')
				bFriendly = pPlayer.getStateReligion() == gc.getInfoTypeForString('RELIGION_COUNCIL_OF_ESUS') or pPlayer.isFullMember(gc.getInfoTypeForString('DIPLOVOTE_UNDERCOUNCIL')) or iAlignment == iEvil
			elif iTempleFriendly == gc.getInfoTypeForString('BUILDING_TEMPLE_OF_THE_HAND'):
				iTempleHostile = gc.getInfoTypeForString('BUILDING_TEMPLE_OF_THE_HAND_HOSTILE')
				bFriendly = pPlayer.getStateReligion() == gc.getInfoTypeForString('RELIGION_WHITE_HAND')
				if gc.getGame().getProjectCreatedCount(gc.getInfoTypeForString('PROJECT_THE_DRAW')) > 0:
					iAuricPlayer = cf.getLeader(gc.getInfoTypeForString('LEADER_AURIC'))
					if iAuricPlayer != -1:
						pAuricPlayer = gc.getPlayer(iAuricPlayer)
						if pAuricPlayer.getUnitClassCount(gc.getInfoTypeForString('UNITCLASS_AURIC')) > 0:
							iTeam = pPlayer.getTeam()
							eTeam = gc.getTeam(iTeam)
							iAuricTeam = pAuricPlayer.getTeam()
							if iAuricTeam == iTeam:
								bFriendly = True
							elif eTeam.isVassal(iTeam):
								bFriendly = True
							elif eTeam.isAtWar(iAuricTeam):
								bFriendly = False
			elif iTempleFriendly == gc.getInfoTypeForString('BUILDING_GAMBLING_HOUSE'):
				iTempleHostile = gc.getInfoTypeForString('BUILDING_GAMBLING_HOUSE_HOSTILE')
				bFriendly = pPlayer.getStateReligion() == gc.getInfoTypeForString('RELIGION_STEWARDS_OF_INEQUITY') or iAlignment != iGood
			elif iTempleFriendly == gc.getInfoTypeForString('BUILDING_TEMPLE_ANOINTED'):
				iTempleHostile = gc.getInfoTypeForString('BUILDING_TEMPLE_ANOINTED_HOSTILE')
				bFriendly = pPlayer.getStateReligion() == gc.getInfoTypeForString('RELIGION_ANOINTED') or iAlignment == iEvil
			elif iTempleFriendly == gc.getInfoTypeForString('BUILDING_TEMPLE_OF_THE_VEIL'):
				iTempleHostile = gc.getInfoTypeForString('BUILDING_TEMPLE_OF_THE_VEIL_HOSTILE')
				bFriendly = pPlayer.getStateReligion() == gc.getInfoTypeForString('RELIGION_THE_ASHEN_VEIL') or iAlignment == iEvil
			elif iTempleFriendly == gc.getInfoTypeForString('BUILDING_TOPHET'):
				iTempleHostile = gc.getInfoTypeForString('BUILDING_TOPHET_HOSTILE')
				bFriendly = pPlayer.getStateReligion() == gc.getInfoTypeForString('RELIGION_EMBER_LEGION') or iAlignment == iEvil
			elif iTempleFriendly == gc.getInfoTypeForString('BUILDING_INTERSTICE'):
				iTempleHostile = gc.getInfoTypeForString('BUILDING_INTERSTICE_HOSTILE')
				bFriendly = pPlayer.getStateReligion() == gc.getInfoTypeForString('RELIGION_COVEN') or (iAlignment == iEvil and pCity.getCivilizationType() != gc.getInfoTypeForString('CIVILIZATION_CALABIM'))

			if iTempleHostile != -1:
				if bFriendly:
					pCity.setNumRealBuilding(iTempleHostile, False)
					pCity.setNumRealBuilding(iTempleFriendly, True)
				else:
					pCity.setNumRealBuilding(iTempleFriendly, False)
					pCity.setNumRealBuilding(iTempleHostile, True)
			effectNotDead(pCaster)


