def reqEstablishTemple(pCaster, eSpell):
	if pCaster.isBarbarian():
		return False
	pPlot = pCaster.plot()
	if pPlot.isCity():
		pCity = pPlot.getPlotCity()
		iPlayer = pCity.getOwner()
		pPlayer = gc.getPlayer(iPlayer)
		iTeam = pPlayer.getTeam()
		eTeam = gc.getTeam(iTeam)
		
	if pPlot.isCity():
		pCity = pPlot.getPlotCity()
		iPlayer = pCity.getOwner()
		pPlayer = gc.getPlayer(iPlayer)
		
		iStateReligion = pPlayer.getStateReligion()

		iAlignment = pPlayer.getAlignment()
		iLeader = pPlayer.getLeaderType()
		iGood = gc.getInfoTypeForString('ALIGNMENT_GOOD')
		iEvil = gc.getInfoTypeForString('ALIGNMENT_EVIL')
		bFriendly = -1
		iTempleHostile = -1
		iTempleFriendly = gc.getSpellInfo(eSpell).getCreateBuildingType()
		if iTempleFriendly != -1:
			if iTempleFriendly == gc.getInfoTypeForString('BUILDING_TEMPLE_THE_ONE'):
				iTempleHostile = gc.getInfoTypeForString('BUILDING_TEMPLE_THE_ONE_HOSTILE')
				bFriendly = pPlayer.getStateReligion() == -1
			elif iTempleFriendly == gc.getInfoTypeForString('BUILDING_TEMPLE_OF_THE_EMPYREAN'):
				iTempleHostile = gc.getInfoTypeForString('BUILDING_TEMPLE_OF_THE_EMPYREAN_HOSTILE')
				bFriendly = pPlayer.getStateReligion() == gc.getInfoTypeForString('RELIGION_THE_EMPYREAN') or pPlayer.isFullMember(gc.getInfoTypeForString('DIPLOVOTE_OVERCOUNCIL')) or iAlignment == iGood
			elif iTempleFriendly == gc.getInfoTypeForString('BUILDING_TEMPLE_BROTHERHOOD'):
				if pCity.getCivilizationType() == gc.getInfoTypeForString('CIVILIZATION_CALABIM'):
					if pCity.getNumBuilding(iTempleFriendly):
						return False
					if pCity.getNumBuilding(gc.getInfoTypeForString('BUILDING_TEMPLE_BROTHERHOOD_HOSTILE')):
						return False
					iTempleFriendly = gc.getInfoTypeForString('BUILDING_TEMPLE_BLIND_BROTHERHOOD')
					iTempleHostile = -1
				else:
					if pCity.getNumBuilding(gc.getInfoTypeForString('BUILDING_TEMPLE_BLIND_BROTHERHOOD')):
						return False
					iTempleHostile = gc.getInfoTypeForString('BUILDING_TEMPLE_BROTHERHOOD_HOSTILE')
					bFriendly = pPlayer.getStateReligion() == gc.getInfoTypeForString('RELIGION_BROTHERHOOD_OF_WARDENS') or pPlayer.isCivic(gc.getInfoTypeForString('CIVIC_PACIFISM')) or iAlignment == iGood
			elif iTempleFriendly == gc.getInfoTypeForString('BUILDING_ARTIFICERY'):
				iTempleHostile = gc.getInfoTypeForString('BUILDING_ARTIFICERY_HOSTILE')
				bFriendly = pPlayer.getStateReligion() == gc.getInfoTypeForString('RELIGION_RINGGIVER') or iAlignment == iGood or pPlayer.isCivic(gc.getInfoTypeForString('CIVIC_ARETE'))
			elif iTempleFriendly == gc.getInfoTypeForString('BUILDING_TEMPLE_OF_THE_ORDER'):
				iTempleHostile = gc.getInfoTypeForString('BUILDING_TEMPLE_OF_THE_ORDER_HOSTILE')
				bFriendly = pPlayer.getStateReligion() == gc.getInfoTypeForString('RELIGION_THE_ORDER') or iAlignment == iGood
			elif iTempleFriendly == gc.getInfoTypeForString('BUILDING_TEMPLE_UNBLEMISHED'):
				iTempleHostile = gc.getInfoTypeForString('BUILDING_TEMPLE_UNBLEMISHED_HOSTILE')
				bFriendly = pPlayer.getStateReligion() in [gc.getInfoTypeForString('RELIGION_UNBLEMISHED'),gc.getInfoTypeForString('RELIGION_FELLOWSHIP_OF_LEAVES')] or iAlignment == iGood
			elif iTempleFriendly == gc.getInfoTypeForString('BUILDING_TEMPLE_OF_KILMORPH'):
				iTempleHostile = gc.getInfoTypeForString('BUILDING_TEMPLE_OF_KILMORPH_HOSTILE')
				bFriendly = pPlayer.getStateReligion() == gc.getInfoTypeForString('RELIGION_RUNES_OF_KILMORPH') or (iAlignment != iEvil and pPlayer.getStateReligion() != gc.getInfoTypeForString('RELIGION_FOXMEN'))
			elif iTempleFriendly == gc.getInfoTypeForString('BUILDING_TEMPLE_OF_THE_OVERLORDS'):
				iTempleHostile = gc.getInfoTypeForString('BUILDING_TEMPLE_OF_THE_OVERLORDS_HOSTILE')
				bFriendly = pPlayer.getStateReligion() == gc.getInfoTypeForString('RELIGION_OCTOPUS_OVERLORDS') or iAlignment != iGood
			elif iTempleFriendly == gc.getInfoTypeForString('BUILDING_APHOTIC_THRONE'):
				iTempleHostile = gc.getInfoTypeForString('BUILDING_APHOTIC_THRONE_HOSTILE')
				bFriendly = pPlayer.getStateReligion() == gc.getInfoTypeForString('RELIGION_COUNCIL_OF_ESUS') or pPlayer.isFullMember(gc.getInfoTypeForString('DIPLOVOTE_UNDERCOUNCIL')) or iAlignment == iEvil
			elif iTempleFriendly == gc.getInfoTypeForString('BUILDING_TEMPLE_OF_THE_HAND'):
				iTempleHostile = gc.getInfoTypeForString('BUILDING_TEMPLE_OF_THE_HAND_HOSTILE')
				bFriendly = pPlayer.getStateReligion() == gc.getInfoTypeForString('RELIGION_WHITE_HAND')
				if gc.getGame().getProjectCreatedCount(gc.getInfoTypeForString('PROJECT_THE_DRAW')) > 0:
					iAuricPlayer = cf.getLeader(gc.getInfoTypeForString('LEADER_AURIC'))
					if iAuricPlayer != -1:
						pAuricPlayer = gc.getPlayer(iAuricPlayer)
						if pAuricPlayer.getUnitClassCount(gc.getInfoTypeForString('UNITCLASS_AURIC')) > 0:
							iTeam = pPlayer.getTeam()
							eTeam = gc.getTeam(iTeam)
							iAuricTeam = pAuricPlayer.getTeam()
							if iAuricTeam == iTeam:
								bFriendly = True
							elif eTeam.isVassal(iTeam):
								bFriendly = True
							elif eTeam.isAtWar(iAuricTeam):
								bFriendly = False
			elif iTempleFriendly == gc.getInfoTypeForString('BUILDING_GAMBLING_HOUSE'):
				iTempleHostile = gc.getInfoTypeForString('BUILDING_GAMBLING_HOUSE_HOSTILE')
				bFriendly = pPlayer.getStateReligion() == gc.getInfoTypeForString('RELIGION_STEWARDS_OF_INEQUITY') or iAlignment != iGood
			elif iTempleFriendly == gc.getInfoTypeForString('BUILDING_TEMPLE_ANOINTED'):
				iTempleHostile = gc.getInfoTypeForString('BUILDING_TEMPLE_ANOINTED_HOSTILE')
				bFriendly = pPlayer.getStateReligion() == gc.getInfoTypeForString('RELIGION_ANOINTED') or iAlignment == iEvil
			elif iTempleFriendly == gc.getInfoTypeForString('BUILDING_TEMPLE_OF_THE_VEIL'):
				iTempleHostile = gc.getInfoTypeForString('BUILDING_TEMPLE_OF_THE_VEIL_HOSTILE')
				bFriendly = pPlayer.getStateReligion() == gc.getInfoTypeForString('RELIGION_THE_ASHEN_VEIL') or iAlignment == iEvil
			elif iTempleFriendly == gc.getInfoTypeForString('BUILDING_TOPHET'):
				iTempleHostile = gc.getInfoTypeForString('BUILDING_TOPHET_HOSTILE')
				bFriendly = pPlayer.getStateReligion() == gc.getInfoTypeForString('RELIGION_EMBER_LEGION') or iAlignment == iEvil
			elif iTempleFriendly == gc.getInfoTypeForString('BUILDING_INTERSTICE'):
				iTempleHostile = gc.getInfoTypeForString('BUILDING_INTERSTICE_HOSTILE')
				bFriendly = pPlayer.getStateReligion() == gc.getInfoTypeForString('RELIGION_COVEN') or (iAlignment == iEvil and pCity.getCivilizationType() != gc.getInfoTypeForString('CIVILIZATION_CALABIM'))

			if iTempleHostile == -1:
				if pCity.getNumBuilding(iTempleFriendly):
					return False
				if not pCaster.isHuman():
					if iTeam != pCaster.getTeam():
						return False
				return True
			elif bFriendly:
				if pCity.getNumBuilding(iTempleHostile):
					pCity.setNumRealBuilding(iTempleFriendly, 1)
					pCity.setNumRealBuilding(iTempleHostile, 0)
					return False
				if pCity.getNumBuilding(iTempleFriendly):
					return False
				if not pCaster.isHuman():
					if iTeam != pCaster.getTeam():
						return False
				return True
			else:
				if pCity.getNumBuilding(iTempleFriendly):
					pCity.setNumRealBuilding(iTempleFriendly, 0)
					pCity.setNumRealBuilding(iTempleHostile, 1)
					return False
				if pCity.getNumBuilding(iTempleHostile):
					return False
				if not pCaster.isHuman():
					if iTeam == pCaster.getTeam():
						return False
				return True
	return False
	
	
def spellInitiate(pCaster, eSpell, sReligion='RELIGION_COUNCIL_OF_ESUS'):
	pCaster.setReligion(gc.getInfoTypeForString(sReligion))

def reqInitiate(pCaster, eSpell,sReligion='RELIGION_ANOINTED'):
	if pCaster.getReligion() == -1:
		return True
	return False


def reqInitiateEsus(pCaster, eSpell=-1):
	iEsus = gc.getInfoTypeForString('RELIGION_COUNCIL_OF_ESUS')
	if pCaster.getReligion() == iEsus:
		return False
	if gc.getUnitInfo(pCaster.getUnitType()).getReligionType() != -1:
		return False
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iTeam = pCaster.getTeam()
	if pPlayer.getGold() < 25:
		return False
	if not pPlayer.isHuman():
		if pPlayer.getCivilizationType() == gc.getInfoTypeForString('CIVILIZATION_KHAZAD'):
			if pPlayer.getGold() / pPlayer.getNumCities() < 700:
				return False
	pPlot = pCaster.plot()
	iEvangelist = gc.getInfoTypeForString('PROMOTION_EVANGELIST')
	for i in xrange(pPlot.getNumUnits()):
		pUnit = pPlot.getUnit(i)
		if pUnit.isHasPromotion(iEvangelist):
			if pUnit.getReligion() == iEsus:
				if not pUnit.isInvisible(iTeam, False):
					return True
	return False

def reqInquisition(pCaster, eSpell=1):
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	if pPlayer.canInquisition():
		StateBelief = pPlayer.getStateReligion()
		UnitBelief = pCaster.getReligion()
		if UnitBelief != StateBelief:
			if StateBelief != -1:
				return False
		pPlot = pCaster.plot()
		pCity = pPlot.getPlotCity()
		if StateBelief != gc.getPlayer(pCity.getOwner()).getStateReligion():
			return False
		for iUnit in xrange(pPlot.getNumUnits()):
			pUnit = pPlot.getUnit(iUnit)
			if pUnit.getDelayedSpell() == eSpell:
				return False
		for iTarget in xrange(gc.getNumReligionInfos()):
			if UnitBelief != iTarget and StateBelief != iTarget and pCity.isHasReligion(iTarget) and not pCity.isHolyCityByType(iTarget):
				return True
	return False

def miscastInquisition(pCaster, eSpell=-1):
	pPlot = pCaster.plot()

	# lfgr 11/2021: The city may have changed owner/state religion while the spell is being cast
	if not reqInquisition(pCaster):
		return


	if pPlot.isCity():
		pCity = pPlot.getPlotCity()
		iPlayer = pCity.getOwner()
		pPlayer = gc.getPlayer(iPlayer)
		StateBelief = pPlayer.getStateReligion()
		UnitBelief = pCaster.getReligion()
		iRnd = CyGame().getSorenRandNum(4, "Inquisition")
		for iTarget in xrange(gc.getNumReligionInfos()):
			iRnd = CyGame().getSorenRandNum(1+pCity.getReligionInfluence(iTarget), "Inquisition backfires")
			pCity.changeOccupationTimer(iRnd)
			pCity.setRevolutionIndex(pCity.getRevolutionIndex() + iRnd)
			for iPlayer2 in xrange(gc.getMAX_PLAYERS()):
				pPlayer2 = gc.getPlayer(iPlayer2)
				if pPlayer2.isAlive():
					if pPlayer2.getStateReligion() == iTarget:
						pPlayer2.AI_changeAttitudeExtra(iPlayer, -1)

	effectHasCasted(pCaster)
	
	
def spellInquisition(pCaster, eSpell=-1):
	pPlot = pCaster.plot()

	# lfgr 11/2021: The city may have changed owner/state religion while the spell is being cast
	if not reqInquisition(pCaster):
		return


	if pPlot.isCity():
		pCity = pPlot.getPlotCity()
		pPlayer = gc.getPlayer(pCity.getOwner())
		StateBelief = pPlayer.getStateReligion()
		UnitBelief = pCaster.getReligion()
		iRnd = CyGame().getSorenRandNum(4, "Inquisition")
		if StateBelief == gc.getInfoTypeForString('RELIGION_THE_ORDER'):
			iRnd -= 1
		for iTarget in xrange(gc.getNumReligionInfos()):
			if UnitBelief != iTarget and StateBelief != iTarget and pCity.isHasReligion(iTarget):
				if cf.removeReligion(iTarget, pCity):
					iRnd += 1
		if iRnd >= 1:
			pCity.changeHurryAngerTimer(iRnd)

def helpInquisition(lpUnits, eSpell=-1):
	szBuffer = ''
	pCaster = lpUnits[0]
	pPlot = pCaster.plot()
	if pPlot.isCity():
		if pCaster.getTeam() == pPlot.getTeam():
			lReligions= []
			lBuildings = []
			pCity = pPlot.getPlotCity()
			pPlayer = gc.getPlayer(pCity.getOwner())
			sNameCity = "<color=%d,%d,%d,%d>%s</color>" %(pPlayer.getPlayerTextColorR(), pPlayer.getPlayerTextColorG(), pPlayer.getPlayerTextColorB(), pPlayer.getPlayerTextColorA(), pCity.getName() )
			StateBelief = pPlayer.getStateReligion()
			UnitBelief = pCaster.getReligion()
			iRnd = 3
			if StateBelief == gc.getInfoTypeForString('RELIGION_THE_ORDER'):
				iRnd -= 1
			for iTarget in xrange(gc.getNumReligionInfos()):
				if UnitBelief != iTarget and StateBelief != iTarget and pCity.isHasReligion(iTarget):
					lReligions.append(iTarget)
					iRnd += 1
					for iBuilding in xrange(gc.getNumBuildingInfos()):
						if pCity.getNumBuilding(iBuilding) > 0:
							info = gc.getBuildingInfo(iBuilding)
							if info.getPrereqReligion() == iTarget:
								if not isWorldWonderClass(info.getBuildingClassType()):
									lBuildings.append(iBuilding)
			if iRnd > 0:
				szBuffer += localText.getText("TXT_KEY_HELP_SPELL_TRIGGER_REVOLT", (sNameCity,iRnd, ))
			lTargets = list(set(lReligions))
			iCount = len(lTargets)
			if iCount > 0:
				sList = ''
				while len(lTargets) > 0:
					ItemInfo = gc.getReligionInfo(lTargets.pop(0))
					sList += u"%c" %(ItemInfo.getChar()) + ItemInfo.getDescription()
					if len(lTargets) > 0:
						if len(lTargets) == 1:
							sList += " and "
						else:
							sList += ", "
				szBuffer += localText.getText("TXT_KEY_HELP_SPELL_MAY_REMOVE_STUFF", (sList, ))
			lTargets = list(set(lBuildings))
			iCount = len(lTargets)
			if iCount > 0:
				sList = ''
				while len(lTargets) > 0:
					ItemInfo = gc.getBuildingInfo(lTargets.pop(0))
					sList += ItemInfo.getDescription()
					if len(lTargets) > 0:
						if len(lTargets) == 1:
							sList += " and "
						else:
							sList += ", "
				szBuffer += localText.getText("TXT_KEY_HELP_SPELL_MAY_REMOVE_STUFF", (sList, ))
	return szBuffer

def spellIntoTheMist(pCaster, eSpell=-1):
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iGrey = gc.getInfoTypeForString('PROMOTION_GREY')
	iHidden = gc.getInfoTypeForString('PROMOTION_HIDDEN')
	iWane = gc.getInfoTypeForString('SPELL_WANE')
	iCreature = [gc.getInfoTypeForString('UNITCOMBAT_ANIMAL'), gc.getInfoTypeForString('UNITCOMBAT_BEAST')]
	for loopUnit in PyPlayer(iPlayer).getUnitList():
		loopUnit.setHasPromotion(iHidden, True)
		if loopUnit.isAlive():
			if not loopUnit.getUnitCombatType() in iCreature:
				if loopUnit.getRace() != iGrey:
					loopUnit.setHasPromotion(iGrey, True)
				elif reqWane(loopUnit, eSpell):
					if isLimitedUnitClass(loopUnit.getUnitClassType()):
						continue
					if CyGame().getSorenRandNum(loopUnit.getLevel(), "Wane Into The Mist "+ str(loopUnit.getName())) > 3:
						loopUnit.cast(iWane)
	iTeam = pCaster.getTeam()
	for i in xrange(CyMap().numPlots()):
		pPlot = CyMap().plotByIndex(i)
		for jTeam in xrange(gc.getMAX_TEAMS()):
			if iTeam != jTeam:
				if pPlot.isVisible(jTeam, False):continue
				if pPlot.isRevealed(jTeam, False):
					pPlot.setRevealed(jTeam, False, False, -1)
	CyMap().updateVisibility()
##	for iPlotIndex in xrange(CyMap().numPlots()):
##		pLoopPlot = CyMap().plotByIndex(iPlotIndex)
##		if pLoopPlot.isOwned():
##			if pLoopPlot.getOwner() == pCaster.getOwner():
##				for iPlayer in xrange(gc.getMAX_PLAYERS()):
##					pPlayer = gc.getPlayer(iPlayer)
##					iTeam = pPlayer.getTeam()
##					if iTeam != pCaster.getTeam():
##						pLoopPlot.setRevealed(iTeam, False, False, iTeam)
##						pLoopPlot.changeInvisibleVisibilityCount(iTeam, gc.getInfoTypeForString("INVISIBLE_LAND"), -1)
##						pLoopPlot.changeInvisibleVisibilityCount(iTeam, gc.getInfoTypeForString("INVISIBLE_ANIMAL"), -1)
##						pLoopPlot.changeInvisibleVisibilityCount(iTeam, gc.getInfoTypeForString("INVISIBLE_ALL"), -1)
##						pLoopPlot.updateVisibility()
	iPlayerCaster = pCaster.getOwner()
	for iPlayer in xrange(gc.getMAX_PLAYERS()):
		pPlayer = gc.getPlayer(iPlayer)
		for iMemType in xrange(MemoryTypes.NUM_MEMORY_TYPES):
			pPlayer.AI_changeMemoryCount(iPlayerCaster, iMemType, -pPlayer.AI_getMemoryCount(iPlayerCaster, iMemType))

def reqIraUnleashed(pCaster, eSpell=-1):
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
##	if pPlayer.getUnitClassCount(gc.getInfoTypeForString('UNITCLASS_IRA')) >= 7:
	if pPlayer.isUnitClassMaxedOut(gc.getInfoTypeForString('UNITCLASS_IRA'), 0):
		return False
	return True

def spellIraUnleashed(pCaster, eSpell=-1):
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iDuration = 1
	if pPlayer.hasTrait(gc.getInfoTypeForString('TRAIT_SUMMONER')):
		iDuration += 1
	if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_AVATAR')):
		iDuration = 0
##	else:
##		for iTrait in xrange(gc.getNumTraitInfos()):
##			if pPlayer.hasTrait(iTrait):
##				iDuration += gc.getTraitInfo(iTrait).getSummonDuration()#not exposed

##	iCount = 7 - pPlayer.getUnitClassCount(gc.getInfoTypeForString('UNITCLASS_IRA'))
##	for i in xrange(iCount):
	iIra = gc.getInfoTypeForString('UNIT_IRA')
	iIraC = gc.getInfoTypeForString('UNITCLASS_IRA')
	iX = pCaster.getX()
	iY = pCaster.getY()

	while not pPlayer.isUnitClassMaxedOut(iIraC, 0):
		newUnit = pPlayer.initUnit(iIra, iX, iY, UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
		newUnit.setSummoner(pCaster.getID())
		if iDuration > 0:
			newUnit.setDuration(iDuration)
		else:
			newUnit.setPermanentSummon(True)
		cf.grantSummonPerks(newUnit, pCaster)

def helpIraUnleashed(lpUnits, eSpell):
	szBuffer = ''
	if eSpell != -1:
		iUnit = gc.getInfoTypeForString('UNIT_IRA')
		iSummons = gc.getUnitClassInfo(gc.getInfoTypeForString('UNITCLASS_IRA')).getMaxPlayerInstances() - gc.getPlayer(lpUnits[0].getOwner()).getUnitClassCount(gc.getInfoTypeForString('UNITCLASS_IRA'))
		if iSummons > 0 and iUnit > -1:
			infoU = gc.getUnitInfo(iUnit)
			for pCaster in lpUnits:
				if pCaster.canCast(eSpell, True):
					lPerks = []
					for iProm in cf.getSummonPerks(pCaster):
						if not infoU.getFreePromotions(iProm):
							lPerks.append(iProm)
					iCount = len(lPerks)
					if iCount > 0:
						szBuffer += '\n' + localText.getText("TXT_KEY_UNIT_STARTS_WITH", ())
						if iCount == 1:
							sList = gc.getPromotionInfo(lPerks.pop(0)).getDescription()
						else:
							sList = ''
							while len(lPerks) > 0:
								sList += gc.getPromotionInfo(lPerks.pop(0)).getDescription()
								if len(lPerks) > 0:
									if len(lPerks) == 1:
										sList += " and "
									else:
										sList += ", "
						szBuffer += sList
			sHelp = helpUnitHelp(iUnit)
			if iSummons == 1:
				sHelp = localText.getText("TXT_KEY_SPELL_SUMMON_UNIT", (sHelp,))
			else:
				sHelp = localText.getText("TXT_KEY_SPELL_SUMMON_UNIT_MULTIPLE", (iSummons, sHelp,))
				iStop = sHelp.rfind("(s).")#I don't want to include the "(s)."
				if iStop != -1:
					sHelp = sHelp[:iStop]
			szBuffer = '\n' + sHelp + szBuffer
	return szBuffer



def reqIssueChallenge(pCaster, eSpell=-1):
	if pCaster.isHuman():
		if pCaster.isMadeAttack():
			if not pCaster.isBlitz ():
				return False
		if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_CHALLENGER')):
			return False
		if pCaster.canCast(gc.getInfoTypeForString('SPELL_CHALLENGE_ACCEPT'), False):
			return False
		if pCaster.canAcquirePromotionAny():#There is little point in fighting each other when the experience won't be of any use to purchase promotions
			iMelee = gc.getInfoTypeForString('UNITCOMBAT_MELEE')
			ID = pCaster.getID()
			iPlayer = pCaster.getOwner()
			pPlot = pCaster.plot()
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if pUnit.getOwner() == iPlayer:
					if ID != pUnit.getID():
						if pUnit.getUnitCombatType() == iMelee:
							if not pUnit.isMadeAttack() or pUnit.isBlitz ():
								return True
	return False


def reqKidnap(pCaster, eSpell=-1):
	return reqKidnapC(pCaster, eSpell) or reqKidnapU(pCaster, eSpell)

def spellKidnap(pCaster, eSpell=-1):
	if spellKidnapU(pCaster, eSpell) == -1:
		spellKidnapC(pCaster, eSpell)
		
def miscastKidnap(pCaster, eSpell=-1):
	if not miscastKidnapU(pCaster, eSpell):
		miscastKidnapC(pCaster, eSpell)

def helpKidnap(lpUnits, eSpell=-1):
	return helpKidnapC(lpUnits, eSpell) + helpKidnapU(lpUnits, eSpell)

def reqKidnapC(pCaster, eSpell=-1):
	pPlot = pCaster.plot()
	if pPlot.isCity():
		pCity = pPlot.getPlotCity()
		if pCity.getTeam() == pCaster.getTeam():
			return False
		for sSpecialist in ['SPECIALIST_GREAT_PRIEST', 'SPECIALIST_GREAT_ARTIST', 'SPECIALIST_GREAT_MERCHANT', 'SPECIALIST_GREAT_ENGINEER', 'SPECIALIST_GREAT_SCIENTIST']:
			if pCity.getFreeSpecialistCount(gc.getInfoTypeForString(sSpecialist)) > 0:
				return True
	return False

def helpKidnapC(lpUnits, eSpell=-1):
	szBuffer = ''
	pCaster = lpUnits[0]
	pPlot = pCaster.plot()
	if pPlot.isCity():
		pCity = pPlot.getPlotCity()

		pPlayer2= gc.getPlayer(pCity.getOwner())
		dSpec = {	gc.getInfoTypeForString('UNIT_PROPHET')		:	gc.getInfoTypeForString('SPECIALIST_GREAT_PRIEST')	,
					gc.getInfoTypeForString('UNIT_ARTIST')		:	gc.getInfoTypeForString('SPECIALIST_GREAT_ARTIST')	,
					gc.getInfoTypeForString('UNIT_MERCHANT')	:	gc.getInfoTypeForString('SPECIALIST_GREAT_MERCHANT')	,
					gc.getInfoTypeForString('UNIT_ENGINEER')	:	gc.getInfoTypeForString('SPECIALIST_GREAT_ENGINEER')	,
					gc.getInfoTypeForString('UNIT_SCIENTIST')	:	gc.getInfoTypeForString('SPECIALIST_GREAT_SCIENTIST')
					}
		lTargets = []
		for iUnit, iSpecialist in dSpec.items():
			if pCity.getFreeSpecialistCount(iSpecialist) > 0:
				lTargets.append(iUnit)
		if len(lTargets) > 0:
			sList = ''
			while len(lTargets) > 0:
				iUnit= lTargets.pop(0)
				sList += gc.getUnitInfo(iUnit).getDescription()
				if len(lTargets) > 0:
					if len(lTargets) == 1:
						sList += " or "
					else:
						sList += ", "
			sList = "<color=%d,%d,%d,%d>%s</color>" %(pPlayer2.getPlayerTextColorR(), pPlayer2.getPlayerTextColorG(), pPlayer2.getPlayerTextColorB(), pPlayer2.getPlayerTextColorA(), sList)
			szBuffer = localText.getText("TXT_KEY_HELP_SPELL_KIDNAP", (sList, ))
			sPName = "<color=%d,%d,%d,%d>%s</color>" %(pPlayer2.getPlayerTextColorR(), pPlayer2.getPlayerTextColorG(), pPlayer2.getPlayerTextColorB(), pPlayer2.getPlayerTextColorA(), pPlayer2.getName() )
			szBuffer += localText.getText("TXT_KEY_HELP_SPELL_POSSIBLE_DIPLOMATIC_PENALTY_WITH_PLAYERS", (sPName, ))
	return szBuffer

def miscastKidnapC(pCaster, eSpell=-1):
	pPlot = pCaster.plot()
	newUnit = -1
	if pPlot.isCity():
		pCity = pPlot.getPlotCity()
		iX = pCaster.getX()
		iY = pCaster.getY()
		sButton = 'Art/Interface/Buttons/Spells/Kidnap.dds'

