			CyInterface().addMessage(iPlayer, True, 25, localText.getText("TXT_KEY_SPELL_KIDNAP_FAIL_ESCAPE", (pCaster.getName(), pUnit.getName(), )), '', InterfaceMessageTypes.MESSAGE_TYPE_INFO, sButton, gc.getInfoTypeForString('COLOR_GREEN'), iX, iY, True, True)
