def spellKillClerics(pCaster, eSpell):
	iMatronae = gc.getInfoTypeForString('RELIGION_MATRONAE')
	iDeath = gc.getInfoTypeForString('DAMAGE_DEATH')
	iHoly = gc.getInfoTypeForString('DAMAGE_HOLY')
	iX = pCaster.getX()
	iY = pCaster.getY()
	iRange = 1

	for iiX in xrange(iX-iRange, iX+ 1+ iRange, 1):
		for iiY in xrange(iY-iRange, iY+ 1+ iRange, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if pUnit.isImmuneToSpell(pCaster, eSpell):continue
				infoUnit = gc.getUnitInfo(pUnit.getUnitType())
				if infoUnit.getPrereqReligion() not in [-1, iMatronae]:

					if pUnit.getDamageTypeResist(iDeath) >= 100:
						pUnit.doDamage(50, 100, pCaster, iHoly, False)
					else:
						pUnit.doDamage(50, 100, pCaster, iDeath, False)


def reqKillClerics(pCaster, eSpell):
	iMatronae = gc.getInfoTypeForString('RELIGION_MATRONAE')
	iX = pCaster.getX()
	iY = pCaster.getY()
	iRange = 1
	iTeam = pCaster.getTeam()

	for iiX in xrange(iX-iRange, iX+ 1+ iRange, 1):
		for iiY in xrange(iY-iRange, iY+ 1+ iRange, 1):
			pPlot = CyMap().plot(iiX, iiY)

			if pPlot.isNone():continue
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if pUnit.isImmuneToSpell(pCaster, eSpell):continue
				infoUnit = gc.getUnitInfo(pUnit.getUnitType())
				if infoUnit.getPrereqReligion() not in [-1, iMatronae]:
					if pCaster.isHuman():
						return True
					e2Team = gc.getTeam(pUnit.getTeam())
					if e2Team.isAtWar(iTeam):
						return True
	return False



