def reqLegends(pCaster, eSpell=-1):
	if gc.getGame().isOption(GameOptionTypes.GAMEOPTION_NO_ACHERON):
		return False
	pPlot = pCaster.plot()
	if pPlot.isCity():
		pCity = pPlot.getPlotCity()
		if not pCity.isSettlement():
			return True
	return False

def spellLegends(pCaster, eSpell=-1):
	iDragonCult = gc.getInfoTypeForString('RELIGION_CULT_OF_THE_DRAGON')
	iStir = gc.getInfoTypeForString('PROJECT_STIR_FROM_SLUMBER')
	pPlot = pCaster.plot()
	pCity = pPlot.getPlotCity()
	iPlayerC = pCaster.getOwner()
	iCulture = 25 + pCity.getCulture(iPlayerC)//21


	gc.getGame().setHolyCity(iDragonCult, pCity, True)
	for iPlayer in xrange(gc.getMAX_PLAYERS()):
		pPlayer = gc.getPlayer(iPlayer)
		if pPlayer.isAlive():
			(loopCity, iter) = pPlayer.firstCity(False)
			while(loopCity):
				if ( not loopCity.isNone() and loopCity.getOwner() == iPlayer): #only valid cities
					if iPlayerC == loopCity.getOwner():
						loopCity.setHasReligion(iDragonCult, True, True, True)
						loopCity.setOccupationTimer(0)
					elif not loopCity.isHasReligion(iDragonCult):
						if CyGame().getSorenRandNum(21, "Legends spread Cult of Dragon to city") < 3:
							loopCity.setHasReligion(iDragonCult, True, True, True)
							if not cf.isHasDragon(pPlayer):
								loopCity.changeOccupationTimer(1)
					if loopCity.isHasReligion(iDragonCult):
						loopCity.changeCulture(iPlayerC, iCulture, True)
						if loopCity.isProductionProject():
							if loopCity.getProductionProject() == iStir:
								loopCity.changeProduction(500)
				(loopCity, iter) = pPlayer.nextCity(iter, False)

def reqLichdom(pCaster, eSpell=-1):
##	if pCaster.isImmortal():
##		return False
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	if pPlayer.isUnitClassMaxedOut(gc.getInfoTypeForString('UNITCLASS_LICH'), 0):
		return False
	if pPlayer.getAlignment() == gc.getInfoTypeForString('ALIGNMENT_GOOD'):
		return False
	if not pCaster.isHuman():
		for sProm in ['PROMOTION_AFFINITY_DEATH_ARAWN','PROMOTION_DEATH_ARAWN1','PROMOTION_DEATH_ARAWN2','PROMOTION_DEATH_ARAWN3']:
			if pCaster.isHasPromotion(gc.getInfoTypeForString(sProm)):
				return False
	return reqNecromancyAllowed(pCaster)


def miscastPlanarBinding(pCaster, eSpell):
	iPlayer = pCaster.getOwner()
	iTeam = pCaster.getTeam()
	eTeam = gc.getTeam(iTeam)
	iRange = 1
	iX = pCaster.getX()
	iY = pCaster.getY()
	for iiX in xrange(iX-iRange, iX+ 1+ iRange, 1):
		for iiY in xrange(iY-iRange, iY+ 1+ iRange, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
#				if pUnit.isImmuneToSpell(pCaster, eSpell):continue
				if pUnit.isAlive():continue
				if pUnit.getDuration() > 0 and not pUnit.getSpecialUnitType() == gc.getInfoTypeForString('SPECIALUNIT_SPELL'):
					if pUnit.getTeam() == iTeam:
						if pUnit.getDuration() > 1:
							pUnit.setDuration(pUnit.getDuration()-1)
						else:
							pUnit.kill(True, iPlayer)
					elif eTeam.isAtWar(pUnit.getTeam()) or pCaster.isHiddenNationality() or pUnit.isHiddenNationality():
						pUnit.setDuration(pUnit.getDuration()+ 1)

def spellPlanarBinding(pCaster, eSpell):
	iPlayer = pCaster.getOwner()
	iTeam = pCaster.getTeam()
	eTeam = gc.getTeam(iTeam)
	iRange = 1
	iX = pCaster.getX()
	iY = pCaster.getY()
	for iiX in xrange(iX-iRange, iX+ 1+ iRange, 1):
		for iiY in xrange(iY-iRange, iY+ 1+ iRange, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if pCaster is pUnit:continue
				if pCaster.getID() == pUnit.getID():continue
				if pUnit.isImmuneToSpell(pCaster, eSpell):continue
				if pUnit.isAlive():continue
				if pUnit.getDuration() > 0 and not pUnit.getSpecialUnitType() == gc.getInfoTypeForString('SPECIALUNIT_SPELL'):
					if pUnit.getTeam() == iTeam:
						pUnit.setDuration(pUnit.getDuration()+ 1)
					elif not effectResisted(pUnit, pCaster, eSpell):
						if pUnit.getDuration() > 1:
							pUnit.setDuration(pUnit.getDuration()-1)
						elif eTeam.isAtWar(pUnit.getTeam()) or pCaster.isHiddenNationality() or pUnit.isHiddenNationality():
							pUnit.kill(True, iPlayer)


