def reqManaAllowed(pCaster, sVote, iDiplovote = gc.getInfoTypeForString('DIPLOVOTE_OVERCOUNCIL'), iMembership = gc.getInfoTypeForString('CIVIC_OVERCOUNCIL')):
	if CyGame().isVotePassed(gc.getInfoTypeForString(sVote)):
		iPlayer = pCaster.getOwner()
		pPlayer = gc.getPlayer(iPlayer)
		if pPlayer.isFullMember(iDiplovote):#A Player considering joining the council may wish to be warned if their favorite spells are banned
			if pPlayer.getCivics(gc.getInfoTypeForString('CIVICOPTION_MEMBERSHIP')) == iMembership:
				return False
	return True

def helpManaBlocked(lpUnits, sVote, bOvercouncil = True):
	szBuffer = ''
	pCaster= lpUnits[0]
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)

	if bOvercouncil:
		if CyGame().isVotePassed(gc.getInfoTypeForString(sVote)):
			szBuffer = localText.getText("TXT_KEY_SPELL_HELP_BLOCKED_BY_RESOLUTION_NON_MEMBER", ())
			if pPlayer.isFullMember(gc.getInfoTypeForString('DIPLOVOTE_OVERCOUNCIL')):#A Player considering joining the council may wish to be warned if their favorite spells are banned
				if pPlayer.isCivic(gc.getInfoTypeForString('CIVIC_OVERCOUNCIL')):
					szBuffer = localText.getText("TXT_KEY_SPELL_HELP_BLOCKED_BY_RESOLUTION", ())
		else:
			szBuffer = localText.getText("TXT_KEY_SPELL_HELP_BLOCKABLE_BY_RESOLUTION", ())
	else:
		if CyGame().isVotePassed(gc.getInfoTypeForString(sVote)):
			szBuffer = localText.getText("TXT_KEY_SPELL_HELP_BLOCKED_BY_RESOLUTION_NON_MEMBER_UNDER", ())
			if pPlayer.isFullMember(gc.getInfoTypeForString('DIPLOVOTE_UNDERCOUNCIL')):#A Player considering joining the council may wish to be warned if their favorite spells are banned
				if pPlayer.isCivic(gc.getInfoTypeForString('CIVIC_UNDERCOUNCIL')):
					szBuffer = localText.getText("TXT_KEY_SPELL_HELP_BLOCKED_BY_RESOLUTION_UNDER", ())
		else:
			szBuffer = localText.getText("TXT_KEY_SPELL_HELP_BLOCKABLE_BY_RESOLUTION_UNDER", ())
	return szBuffer


def spellMakeMortal(pCaster, eSpell):
	iTeam = pCaster.getTeam()
	iX = pCaster.getX()
	iY = pCaster.getY()
	iPhysical = gc.getInfoTypeForString('DAMAGE_PHYSICAL')
	iHoly = gc.getInfoTypeForString('DAMAGE_HOLY')
	iDeath = gc.getInfoTypeForString('DAMAGE_DEATH')
	iUndead = gc.getInfoTypeForString('PROMOTION_UNDEAD')
	iImmortal = gc.getInfoTypeForString('PROMOTION_IMMORTAL')
	iGallowscurse = gc.getInfoTypeForString('PROMOTION_GALLOWBLIGHT')
	iDeathphage = gc.getInfoTypeForString('PROMOTION_DEATHPHAGE')

	lRace = [gc.getInfoTypeForString('PROMOTION_UNDEAD'),gc.getInfoTypeForString('PROMOTION_AVATAR'),gc.getInfoTypeForString('PROMOTION_ANGEL'),gc.getInfoTypeForString('PROMOTION_DEMON')]
	
	iRange = 2
	for iiX in xrange(iX-iRange, iX + iRange+1, 1):
		for iiY in xrange(iY-iRange, iY+ iRange+1, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			# if pPlot.at(iX, iY):continue
			if plotDistance(iX, iY, iiX, iiY) > iRange:continue
			
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if pUnit.isImmuneToSpell(pCaster, eSpell):continue
				pUnit.setHasPromotion(iGallowscurse, False)
				pUnit.setHasPromotion(iDeathphage, False)
				if pUnit.getTeam() != iTeam:
					if pUnit.isImmortal() or pUnit.getRace() == iUndead:
						if effectResisted(pUnit, pCaster, eSpell):continue
						if pUnit.isImmortal():
							cf.makeMortal(pUnit)
							pUnit.doDamage(70, 100, pCaster, iDeath,False)
						if pUnit.getRace() == iUndead :
							if effectResisted(pUnit, pCaster, eSpell):continue
							pUnit.doDamage(70, 100, pCaster, iHoly, False)


def reqMakeMortal(pCaster, eSpell=-1):
	iTeam = pCaster.getTeam()
	eTeam = gc.getTeam(iTeam)
	iUndead = gc.getInfoTypeForString('PROMOTION_UNDEAD')
	iGallowscurse = gc.getInfoTypeForString('PROMOTION_GALLOWBLIGHT')
	iDeathphage = gc.getInfoTypeForString('PROMOTION_DEATHPHAGE')
	iUndead = gc.getInfoTypeForString('PROMOTION_UNDEAD')
	iHoly = gc.getInfoTypeForString('DAMAGE_HOLY')
	iDeath = gc.getInfoTypeForString('DAMAGE_DEATH')
	iX = pCaster.getX()
	iY = pCaster.getY()
	iRange = 2
	for iiX in xrange(iX-iRange, iX + iRange+1, 1):
		for iiY in xrange(iY-iRange, iY+ iRange+1, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			# if pPlot.at(iX, iY):continue
			if plotDistance(iX, iY, iiX, iiY) > iRange:continue
			
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if pUnit.isImmuneToSpell(pCaster, eSpell):continue
				if pUnit.isHasPromotion(iGallowscurse):
					return True
				if pUnit.isHasPromotion(iDeathphage):
					return True
				if pUnit.getTeam() != iTeam:
					if pUnit.isImmortal():
						return True
					if eTeam.isAtWar(pUnit.getTeam()) or pCaster.isHiddenNationality() or pUnit.isHiddenNationality():
						if pUnit.getDamageTypeResist(iDeath) < 100:
							return True
						elif pUnit.getRace() == iUndead:
							if pUnit.getDamageTypeResist(iHoly) < 100:
								return True

	return reqDestroyUndeadGreater(pCaster, eSpell,2)

