def reqMarchOfTheTrees(pCaster, eSpell=-1):
	iTeam = pCaster.getTeam()
	eTeam = gc.getTeam(iTeam)
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	if not pCaster.isHuman():
		if eTeam.getAtWarCount(True) < 2:
			return False
		iEnemyPower = 0
		for i in xrange(gc.getMAX_CIV_PLAYERS()):
			if (gc.getPlayer(i).isAlive()):
				if eTeam.isAtWar(gc.getPlayer(i).getTeam()):
					iEnemyPower += gc.getPlayer(i).getPower()
#		if eTeam.getAtWarCount(True) < 2:
		if iEnemyPower < ((pPlayer.getPower() * 150) / 100):
			return False
	iAncientForest = gc.getInfoTypeForString('FEATURE_FOREST_ANCIENT')
	iForest = gc.getInfoTypeForString('FEATURE_FOREST')
	iCount = 0
	bInvaded = False
	for i in xrange (CyMap().numPlots()):
		pPlot = CyMap().plotByIndex(i)
		if pPlot.isOwned():
			if pPlot.getOwner() == iPlayer:
				if pPlot.isVisibleEnemyUnit(iPlayer):
					bInvaded = True#I don't want the AI casting this spell when there are no enemies within range for the Treants to attack
				elif pPlot.getFeatureType() in [iAncientForest, iForest]:
					if pCaster.isHuman():
						return True
					iCount += 1
				if bInvaded and iCount > 5:
					return True
	return False

def spellMarchOfTheTrees(pCaster, eSpell=-1):
	iAncientForest = gc.getInfoTypeForString('FEATURE_FOREST_ANCIENT')
	iForest = gc.getInfoTypeForString('FEATURE_FOREST')
	iNewForest = gc.getInfoTypeForString('FEATURE_FOREST_NEW')
	iTreant = gc.getInfoTypeForString('UNIT_TREANT')
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	for i in xrange (CyMap().numPlots()):
		pPlot = CyMap().plotByIndex(i)
		if pPlot.isOwned():
			if pPlot.getOwner() == iPlayer:
				if pPlot.isVisibleEnemyUnit(iPlayer):continue

				if pPlot.getFeatureType() in [iForest,iAncientForest]:
					newUnit = pPlayer.initUnit(iTreant, pPlot.getX(), pPlot.getY(), UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
					iDuration = CyGame().getSorenRandNum(5, "Treant Duration")
					newUnit.setDuration(iDuration)
					if pPlot.getFeatureType() == iAncientForest:
						pPlot.setTempFeatureType(iForest, 0, iDuration)
					if pPlot.getFeatureType() == iForest:
						pPlot.setTempFeatureType(iNewForest, 0, iDuration)
					newUnit.AI_setGroupflag(43)	# 43=GROUPFLAG_SUICIDE_SUMMON
					if newUnit.isHuman():
						newUnit.getGroup().setActivityType(ActivityTypes.ACTIVITY_SLEEP)

def helpMarchOfTheTrees(lpUnits, eSpell=-1):
	szBuffer = ''
	pCaster = lpUnits[0]
	iPlayer = pCaster.getOwner()
	iAncientForest = gc.getInfoTypeForString('FEATURE_FOREST_ANCIENT')
	iForest = gc.getInfoTypeForString('FEATURE_FOREST')
	iNewForest = gc.getInfoTypeForString('FEATURE_FOREST_NEW')
	iNumTreant = 0
	iNumForest = 0
	iNumAncient = 0
	for i in xrange (CyMap().numPlots()):
		pPlot = CyMap().plotByIndex(i)
		if pPlot.isOwned():
			if pPlot.getOwner() == iPlayer:
				if pPlot.isVisibleEnemyUnit(iPlayer):continue
				if pPlot.getFeatureType() == iForest:
					iNumTreant += 1
					iNumForest += 1
				if pPlot.getFeatureType() == iAncientForest:
					iNumTreant += 1
					iNumAncient += 1
	if iNumTreant > 0:
		szBuffer += localText.getText("TXT_KEY_HELP_SPELL_RECRUIT", (iNumTreant, gc.getUnitInfo(gc.getInfoTypeForString('UNIT_TREANT')).getDescription(), ))
	if iNumForest > 0:
		szBuffer += localText.getText("TXT_KEY_HELP_SPELL_CHANGES_PLOTS_TO_FROM", (iNumForest, gc.getFeatureInfo(iForest).getDescription(), gc.getFeatureInfo(iNewForest).getDescription(), ))
	if iNumAncient > 0:
		szBuffer += localText.getText("TXT_KEY_HELP_SPELL_CHANGES_PLOTS_TO_FROM", (iNumAncient, gc.getFeatureInfo(iAncientForest).getDescription(), gc.getFeatureInfo(iForest).getDescription(), ))
	return szBuffer

def reqMaskFacilitated(pCaster, eSpell=-1):
	if pCaster.canCast(gc.getInfoTypeForString('SPELL_MASK'), True):
		return False
	if pCaster.canCast(gc.getInfoTypeForString('SPELL_MASK_AFFINITY'), True):
		return False
	if reqMask(pCaster, eSpell):
		iTeam = pCaster.getTeam()
		iShadow = gc.getInfoTypeForString('PROMOTION_AFFINITY_SHADOW')
		iChanneling = gc.getInfoTypeForString('PROMOTION_CHANNELING3')
		pPlot = pCaster.plot()
		for i in xrange(pPlot.getNumUnits()):
			pUnit = pPlot.getUnit(i)
			if iTeam == pUnit.getTeam():
				if pUnit.isHasPromotion(iShadow) and pUnit.isHasPromotion(iChanneling):
					return True
	return False
	
def reqMask(pCaster, eSpell=-1):
	if pCaster.isHiddenNationality():
		return False
	if pCaster.hasCargo():
		return False
	if pCaster.isCargo():
		return False
	if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_AFFINITY_SUN')):
		return False
	if pCaster.getReligion() == gc.getInfoTypeForString('RELIGION_THE_EMPYREAN'):
		return False
	pGroup = pCaster.getGroup()
	if not pGroup.isNone():
		if pGroup.getNumUnits() > 1:
			return False
	return True

def reqMercurianReinforcements(pCaster, eSpell=-1):
	if not CyGame().isLeaderEverActive(gc.getInfoTypeForString('LEADER_BASIUM')):
		return False
	if pCaster.getTeam() != pCaster.plot().getTeam():
		return False
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	if pPlayer.getCivilizationType() == gc.getInfoTypeForString('CIVILIZATION_MERCURIANS'):
		return False
	if pPlayer.getStateReligion() == gc.getInfoTypeForString('RELIGION_THE_ASHEN_VEIL'):
		return False
	iHero = gc.getInfoTypeForString('UNITCLASS_BASIUM')
	if not CyGame().isUnitClassMaxedOut(iHero, 0):
		return False
	iBasiumPlayer = cf.getLeader(gc.getInfoTypeForString('LEADER_BASIUM'))
	if iBasiumPlayer == -1:
		return False
	pBasiumPlayer = gc.getPlayer(iBasiumPlayer)
	if pBasiumPlayer.getUnitClassCount(iHero) > 0:
		return False
	eTeam = gc.getTeam(pCaster.getTeam())
	if eTeam.isAVassal():
		if not eTeam.isVassal(pBasiumPlayer.getTeam()):
			return False
	iUnit = gc.getInfoTypeForString('UNIT_BASIUM')
	iSluagh = gc.getInfoTypeForString('UNIT_SLUAGH')

	lBoundProm = [	gc.getInfoTypeForString('PROMOTION_NETHERBIND'),
					gc.getInfoTypeForString('PROMOTION_CAPTUS_CAVEAE_ANGELORUM'),
					gc.getInfoTypeForString('PROMOTION_CAPTUS_CAVEAE_SAWOL'),
					gc.getInfoTypeForString('PROMOTION_INCARCERATUS_JUDICII'),
					gc.getInfoTypeForString('PROMOTION_SOUL_FORGED'),
					gc.getInfoTypeForString('PROMOTION_AFFINITY_DEATH')
					]
	if gc.getGame().getProjectCreatedCount(gc.getInfoTypeForString('PROJECT_STIR_FROM_SLUMBER')) < 1:
		lBoundProm.append(gc.getInfoTypeForString('PROMOTION_DRAGON'))
	listRemove = [
					gc.getInfoTypeForString('PROMOTION_HELD'),
					gc.getInfoTypeForString('PROMOTION_MAGIC_IMMUNE'),
					gc.getInfoTypeForString('PROMOTION_CANNOT_CAST')
				]

	if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_SAWOL_CAVEA')):
		lBoundProm.remove(gc.getInfoTypeForString('PROMOTION_CAPTUS_CAVEAE_SAWOL'))
		listRemove.append(gc.getInfoTypeForString('PROMOTION_CAPTUS_CAVEAE_SAWOL'))

	if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_ANGELORUM_CAVEA')):
		lBoundProm.remove(gc.getInfoTypeForString('PROMOTION_CAPTUS_CAVEAE_ANGELORUM'))
		listRemove.append(gc.getInfoTypeForString('PROMOTION_CAPTUS_CAVEAE_ANGELORUM'))

	if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_NETHER_BLADE')):
		lBoundProm.remove(gc.getInfoTypeForString('PROMOTION_NETHERBIND'))
		listRemove.append(gc.getInfoTypeForString('PROMOTION_NETHERBIND'))

	for pSluagh in PyPlayer(gc.getBARBARIAN_PLAYER()).getUnitList():

		if pSluagh.getScenarioCounter() == iUnit:
			if pSluagh.getUnitType() == iSluagh:
				for iProm in lBoundProm:
					if pSluagh.isHasPromotion(iProm):
						return False
				if not pSluagh.isDelayedDeath():
					return True
	return False

def spellMercurianReinforcements(pCaster, eSpell=-1):
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	pPlot = pCaster.plot()
	iMercurianPlayer = cf.getLeader(gc.getInfoTypeForString('LEADER_BASIUM'))
	if iMercurianPlayer != -1:
		pMercurianPlayer = gc.getPlayer(iMercurianPlayer)
		pMercurianPlayer.AI_changeAttitudeExtra(iPlayer, 7)
		iMercurianTeam = pMercurianPlayer.getTeam()
		eMercurianTeam = gc.getTeam(iMercurianTeam)
		iFounderTeam = pCaster.getTeam()
		if iMercurianTeam != iFounderTeam:
			eFounderTeam = gc.getTeam(iFounderTeam)
			eFounderTeam.makePeace(iMercurianTeam)
			eMercurianTeam.makePeace(iFounderTeam)
			eFounderTeam.signOpenBorders(iMercurianTeam)
			eMercurianTeam.signOpenBorders(iFounderTeam)
			eFounderTeam.signDefensivePact(iMercurianTeam)
			eMercurianTeam.signDefensivePact(iFounderTeam)
			for iTeam in xrange(gc.getMAX_TEAMS()):
				if iTeam== gc.getBARBARIAN_TEAM():continue
				if eMercurianTeam.isAtWar(iTeam):continue
				eTeam = gc.getTeam(iTeam)
				if eTeam.isAlive():
					if eFounderTeam.isAtWar(iTeam):
						if eMercurianTeam.canDeclareWar(iTeam):
							eMercurianTeam.declareWar(iTeam, False, WarPlanTypes.WARPLAN_LIMITED)
		i = 12
		if CyGame().getGameSpeedType() == gc.getInfoTypeForString('GAMESPEED_QUICK'):
			i = 9
		elif CyGame().getGameSpeedType() == gc.getInfoTypeForString('GAMESPEED_EPIC'):
			i = 17
		elif CyGame().getGameSpeedType() == gc.getInfoTypeForString('GAMESPEED_MARATHON'):
			i = 37
		i = CyGame().getGameTurn()//i
		limit = pCaster.area().getNumUnits()//4
		if i > limit:
			i = limit + 1
		iX = pPlot.getX()
		iY = pPlot.getY()
		iUnit = gc.getInfoTypeForString('UNIT_BASIUM')
		newUnit = pMercurianPlayer.initUnit(iUnit, iX, iY, UnitAITypes.UNITAI_HERO, DirectionTypes.DIRECTION_NORTH)
		if gc.getGame().getUnitClassCreatedCount(gc.getInfoTypeForString('EQUIPMENTCLASS_ANGELORUM_CAVEA')) < 1:#If Basium the player is killed before Basium the unit, then the equipment could be destroyed forever without these lines of code. It is not perfect, as the equipment can still be destroyed if another Mercurian unit takes the Clava Vindes instead of leaving it with Basium and then the player is killed, but that is less common than the player being killed shortly after being sumoned wheile Basium himself still has the item
			newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_ANGELORUM_CAVEA'), True)
		if pMercurianPlayer.getUnitClassCount(gc.getInfoTypeForString('UNITCLASS_SETTLER')) + pMercurianPlayer.getNumCities() < 1:
			iSettler = pMercurianPlayer.initUnit(gc.getInfoTypeForString('UNIT_SETTLER'), iX, iY, UnitAITypes.UNITAI_SETTLE, DirectionTypes.DIRECTION_NORTH)
		if pMercurianPlayer.getUnitClassCount(gc.getInfoTypeForString('UNITCLASS_WORKER')) < 2:
			pMercurianPlayer.initUnit(gc.getInfoTypeForString('UNIT_WORKER'), iX, iY, UnitAITypes.UNITAI_WORKER, DirectionTypes.DIRECTION_NORTH)
		lAngelUpgrades = [
					('UNIT_HERALD'		,	'TECH_ANIMAL_MASTERY'),
					('UNIT_VALKYRIE'	,	'TECH_DIVINE_ESSENCE'),
					('UNIT_ANGEL_OF_DEATH'	,	'TECH_GUILDS'),
					('UNIT_SERAPH'		,	'TECH_RAGE'),
					('UNIT_REPENTANT_ANGEL'	,	'TECH_RIGHTEOUSNESS'),
					('UNIT_RUNEWYN'		,	'TECH_STRENGTH_OF_WILL'),
					('UNIT_OPHANIM'		,	'TECH_WARHORSES')
				]
		for sUnit, sTech in lAngelUpgrades:
			iTech = gc.getInfoTypeForString(sTech)
			if eMercurianTeam.isHasTech(iTech):
				iUnit = gc.getInfoTypeForString(sUnit)
				if not pMercurianPlayer.isUnitClassMaxedOut(gc.getUnitInfo(iUnit).getUnitClassType(), 0):
					pMercurianPlayer.initUnit(iUnit, iX, iY, UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_NORTH)
					i -= 1
		iUnit = gc.getInfoTypeForString('UNIT_ANGEL')
		for j in xrange(i):
			pMercurianPlayer.initUnit(iUnit, iX, iY, UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_NORTH)
			if pMercurianPlayer.isStrike():
				break
			if pMercurianPlayer.getGold() + pMercurianPlayer.calculateGoldRate() < 50:
				break

def helpMercurianReinforcements(lpUnits, eSpell=1):
	szBuffer = ''
	pCaster = lpUnits[0]
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	pPlot = pCaster.plot()
	iMercurianPlayer = cf.getLeader(gc.getInfoTypeForString('LEADER_BASIUM'))
	if iMercurianPlayer != -1:
		pMercurianPlayer = gc.getPlayer(iMercurianPlayer)
		sLeaderName = "<color=%d,%d,%d,%d>%s</color>" %(pMercurianPlayer.getPlayerTextColorR(), pMercurianPlayer.getPlayerTextColorG(), pMercurianPlayer.getPlayerTextColorB(), pMercurianPlayer.getPlayerTextColorA(), pMercurianPlayer.getName() )
		szBuffer += localText.getText("TXT_KEY_HELP_SPELL_DIPLOMATIC_BONUS_WITH_PLAYERS", (sLeaderName, ))
		iMercurianTeam = pMercurianPlayer.getTeam()
		eMercurianTeam = gc.getTeam(iMercurianTeam)
		iFounderTeam = pCaster.getTeam()
		if iMercurianTeam != iFounderTeam:
			eFounderTeam = gc.getTeam(iFounderTeam)
			if eMercurianTeam.isAtWar(iFounderTeam):
				szBuffer += '\n' + localText.getText("TXT_KEY_PEACE_TREATY_WITH", (sLeaderName, ))
			if not eMercurianTeam.isDefensivePact(iFounderTeam):
				szBuffer +=' \n' + localText.getText("TXT_KEY_DEFENSIVE_PACT_WITH", (sLeaderName, ))
			if not eMercurianTeam.isOpenBorders(iFounderTeam):
				szBuffer += '\n' + localText.getText("TXT_KEY_OPEN_BORDERS_WITH", (sLeaderName, ))
			for iLoopPlayer in xrange(gc.getMAX_PLAYERS()):
				if iLoopPlayer == gc.getBARBARIAN_PLAYER():continue
				pLoopPlayer = gc.getPlayer(iLoopPlayer)
				iLoopTeam = pLoopPlayer.getTeam()
				if iLoopTeam == iMercurianTeam: continue
				if iLoopTeam == iFounderTeam: continue
				eLoopTeam = gc.getTeam(iLoopTeam)
				if eLoopTeam.isAlive():
					if eLoopTeam.isVassal(iMercurianTeam): continue
					if eFounderTeam.isAtWar(iLoopTeam):
						pPlayer2 = gc.getPlayer(iLoopPlayer)
						sPName = "<color=%d,%d,%d,%d>%s</color>" %(pLoopPlayer.getPlayerTextColorR(), pLoopPlayer.getPlayerTextColorG(), pLoopPlayer.getPlayerTextColorB(), pLoopPlayer.getPlayerTextColorA(),pLoopPlayer.getName() )
						szBuffer += localText.getText("TXT_KEY_PLAYER1_DECLARE_WAR_ON_PLAYER2", (sLeaderName,sPName, ))
		i = 12
		if CyGame().getGameSpeedType() == gc.getInfoTypeForString('GAMESPEED_QUICK'):
			i = 9
		elif CyGame().getGameSpeedType() == gc.getInfoTypeForString('GAMESPEED_EPIC'):
			i = 17
		elif CyGame().getGameSpeedType() == gc.getInfoTypeForString('GAMESPEED_MARATHON'):
			i = 37
		i = CyGame().getGameTurn()//i
		limit = pCaster.area().getNumUnits()//4
		if i > limit:
			i = limit + 1
		lTargets = [gc.getInfoTypeForString('UNIT_BASIUM')]
		if pMercurianPlayer.getUnitClassCount(gc.getInfoTypeForString('UNITCLASS_SETTLER')) + pMercurianPlayer.getNumCities() < 1:
			lTargets.append(gc.getInfoTypeForString('UNIT_SETTLER'))
		if pMercurianPlayer.getUnitClassCount(gc.getInfoTypeForString('UNITCLASS_WORKER')) < 2:
			lTargets.append(gc.getInfoTypeForString('UNIT_WORKER'))
		lAngelUpgrades = [
					('UNIT_HERALD'		,	'TECH_ANIMAL_MASTERY'),
					('UNIT_VALKYRIE'	,	'TECH_DIVINE_ESSENCE'),
					('UNIT_ANGEL_OF_DEATH'	,	'TECH_GUILDS'),
					('UNIT_SERAPH'		,	'TECH_RAGE'),
					('UNIT_REPENTANT_ANGEL'	,	'TECH_RIGHTEOUSNESS'),
					('UNIT_RUNEWYN'		,	'TECH_STRENGTH_OF_WILL'),
					('UNIT_OPHANIM'		,	'TECH_WARHORSES')
				]
		for sUnit, sTech in lAngelUpgrades:
			iTech = gc.getInfoTypeForString(sTech)
			if eMercurianTeam.isHasTech(iTech):
				iUnit = gc.getInfoTypeForString(sUnit)
				if not pMercurianPlayer.isUnitClassMaxedOut(gc.getUnitInfo(iUnit).getUnitClassType(), 0):
					lTargets.append(iUnit)
					i -= 1
		iUnit = gc.getInfoTypeForString('UNIT_ANGEL')
		for j in xrange(i):
			if pMercurianPlayer.isStrike():
				break
			if pMercurianPlayer.getGold() + pMercurianPlayer.calculateGoldRate() < 50:
				break
			lTargets.append(iUnit)
	if len(lTargets) > 0:
		sList = ''
		while len(lTargets) > 0:
			sList += gc.getUnitInfo(lTargets.pop(0)).getDescription()
			if len(lTargets) > 0:
				if len(lTargets) == 1:
					sList += " and "
				else:
					sList += ", "
		szBuffer += localText.getText("TXT_KEY_HELP_SPELL_MERCURIAN_REINFORCEMENTS", (sList, ))
	return szBuffer

def reqMezmerize(pCaster, eSpell=-1, sUnitCombat='UNITCOMBAT_ANIMAL'):
	iUnitCombat = gc.getInfoTypeForString(sUnitCombat)
	iX = pCaster.getX()
	iY = pCaster.getY()
	iTeam = pCaster.getTeam()
	eTeam = gc.getTeam(iTeam)
	iRange = 1
	for iiX in xrange(iX-iRange, iX + iRange+1, 1):
		for iiY in xrange(iY-iRange, iY+ iRange+1, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			# if pPlot.at(iX, iY):continue
			if plotDistance(iX, iY, iiX, iiY) > iRange:continue
			
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if pUnit.getUnitCombatType() != iUnitCombat:continue
				if pUnit.isImmuneToSpell(pCaster, eSpell):continue
				if pUnit.getTeam() == iTeam:continue
				if pUnit.isImmuneToMagic():continue
				if pUnit.isAvatarOfCivLeader():continue
				if gc.getTeam(pUnit.getTeam()).isVassal(iTeam):continue
#				if eTeam.isAtWar(pUnit.getTeam()) or pCaster.isHiddenNationality() or pUnit.isHiddenNationality():
				return True
	return False

def spellMezmerize(pCaster, eSpell=-1, sUnitCombat='UNITCOMBAT_ANIMAL'):
	iUnitCombat = gc.getInfoTypeForString(sUnitCombat)
	iX = pCaster.getX()
	iY = pCaster.getY()
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iTeam = pPlayer.getTeam()
	eTeam = gc.getTeam(iTeam)
	iLairGuardian = gc.getInfoTypeForString('PROMOTION_LAIR_GUARDIAN')
	iRange = 1
	for iiX in xrange(iX-iRange, iX + iRange+1, 1):
		for iiY in xrange(iY-iRange, iY+ iRange+1, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			# if pPlot.at(iX, iY):continue
			if plotDistance(iX, iY, iiX, iiY) > iRange:continue
			
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if pUnit.getUnitCombatType() != iUnitCombat:continue
				if pUnit.isImmuneToSpell(pCaster, eSpell):continue
				if pUnit.isDelayedDeath():continue
				if pUnit.isAvatarOfCivLeader():continue
				if pUnit.getTeam() == iTeam:continue
				if gc.getTeam(pUnit.getTeam()).isVassal(iTeam):continue
#				if eTeam.isAtWar(pUnit.getTeam()) or pCaster.isHiddenNationality() or pUnit.isHiddenNationality():
				if effectResisted(pUnit, pCaster, eSpell):continue
				newUnit = pPlayer.initUnit(pUnit.getUnitType(), iX , iY, UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
				cf.removeAffinities(newUnit)
				newUnit.convert(pUnit)
				newUnit.setHasPromotion(iLairGuardian, False)

