def reqMezmerizeSea(pCaster, eSpell=-1):
	iX = pCaster.getX()
	iY = pCaster.getY()
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iTeam = pPlayer.getTeam()
	eTeam = gc.getTeam(iTeam)
	iSea = gc.getInfoTypeForString('DOMAIN_SEA')
	iAnimal = gc.getInfoTypeForString('UNITCOMBAT_ANIMAL')
	iBeast = gc.getInfoTypeForString('UNITCOMBAT_BEAST')
	iDragon = gc.getInfoTypeForString('UNIT_THALATTH')
	iCharmed = gc.getInfoTypeForString('PROMOTION_CHARMED')
	iRange = 2
	for iiX in xrange(iX-iRange, iX + iRange+1, 1):
		for iiY in xrange(iY-iRange, iY+ iRange+1, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			# if pPlot.at(iX, iY):continue
			if plotDistance(iX, iY, iiX, iiY) > iRange:continue
			
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if pUnit.getUnitType() == iDragon:
					if pUnit.getTeam() != iTeam:return True
					if pUnit.isHasPromotion(gc.getInfoTypeForString('PROMOTION_CRAZED')):return True
				elif pUnit.getDomainType() == iSea and pUnit.getUnitCombatType() in [iAnimal, iBeast]:
					if pUnit.getTeam() == iTeam or gc.getTeam(pUnit.getTeam()).isVassal(iTeam):continue
					if eTeam.isAtWar(pUnit.getTeam()) or pCaster.isHiddenNationality() or pUnit.isHiddenNationality():
						pUnit.setHasPromotion(iCharmed, True)
						return True
	return False

def spellMezmerizeSea(pCaster, eSpell=gc.getInfoTypeForString('SPELL_MEZMERIZE_SEA')):
	iX = pCaster.getX()
	iY = pCaster.getY()
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iTeam = pPlayer.getTeam()
	eTeam = gc.getTeam(iTeam)
	listRemovePromotions = [gc.getInfoTypeForString('PROMOTION_CHARMED'), gc.getInfoTypeForString('PROMOTION_CRAZED'), gc.getInfoTypeForString('PROMOTION_ENRAGED'), gc.getInfoTypeForString('PROMOTION_BURNING_BLOOD'), gc.getInfoTypeForString('PROMOTION_LAIR_GUARDIAN')]
	iDragon = gc.getInfoTypeForString('UNIT_THALATTH')
	iSea = gc.getInfoTypeForString('DOMAIN_SEA')
	iAnimal = gc.getInfoTypeForString('UNITCOMBAT_ANIMAL')
	iBeast = gc.getInfoTypeForString('UNITCOMBAT_BEAST')
	iRange = 2
	for iiX in xrange(iX-iRange, iX + iRange+1, 1):
		for iiY in xrange(iY-iRange, iY+ iRange+1, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			# if pPlot.at(iX, iY):continue
			if plotDistance(iX, iY, iiX, iiY) > iRange:continue
			
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if pUnit.isDelayedDeath():continue
				if pUnit.getUnitType() == iDragon:
					if pUnit.getTeam() == iTeam:
						for iProm in listRemovePromotions:
							pUnit.setHasPromotion(iProm , False)
					elif not pUnit.isDelayedDeath():
						newUnit = pPlayer.initUnit(pUnit.getUnitType(), iX , iY, UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
						cf.removeAffinities(newUnit)
						newUnit.convert(pUnit)
						for iProm in listRemovePromotions:
							newUnit.setHasPromotion(iProm , False)
					continue
				if pUnit.getDomainType() == iSea and pUnit.getUnitCombatType() in [iAnimal, iBeast]:
					if pUnit.getTeam() == iTeam:continue
					if gc.getTeam(pUnit.getTeam()).isVassal(iTeam):continue
					if eTeam.isAtWar(pUnit.getTeam()) or pCaster.isHiddenNationality() or pUnit.isHiddenNationality():
						if effectResisted(pUnit, pCaster, eSpell):continue
						newUnit = pPlayer.initUnit(pUnit.getUnitType(), iX , iY, UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
						cf.removeAffinities(newUnit)
						newUnit.convert(pUnit)
						for iProm in listRemovePromotions:
							newUnit.setHasPromotion(iProm , False)


