def reqSummonHollowMan(pCaster):
	pPlot = pCaster.plot()
	if pPlot.getFeatureType() != gc.getInfoTypeForString('FEATURE_BLIZZARD'):
		if pPlot.getTerrainType() not in [	gc.getInfoTypeForString('TERRAIN_SNOW'), gc.getInfoTypeForString('TERRAIN_GLACIER')]:#,gc.getInfoTypeForString('TERRAIN_TUNDRA'),gc.getInfoTypeForString('TERRAIN_WASTELAND')]:
			return False
	return reqNecromancyAllowed(pCaster)
	

def reqSummonDemon(pCaster, eSpell=-1):
	iDemon = gc.getInfoTypeForString('PROMOTION_DEMON')
	for pUnit in cf.listSummons(pCaster):
		if pUnit.getRace() == iDemon:
			return False
	return True

def miscastSummonDemon(pCaster, eSpell=-1):
	pPlot = pCaster.plot()
	iLev = pCaster.getLevel()
	iBound = gc.getInfoTypeForString('PROMOTION_BOUND_BY_COMPACT')
	iDemon = gc.getInfoTypeForString('PROMOTION_DEMON')
	iDemonPossessed = gc.getInfoTypeForString('PROMOTION_POSSESSED')
	iDivine2 = gc.getInfoTypeForString('PROMOTION_DIVINE2')
	bTwin = pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_TWINCAST'))
	bDivine2 = pCaster.isHasPromotion(iDivine2)
	if bDivine2:
		iLev *= 2
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	eTeam = gc.getTeam(pPlayer.getTeam())
	iDuration = 1
	if pPlayer.hasTrait(gc.getInfoTypeForString('TRAIT_SUMMONER')):
		iDuration = 2
	listUnits = [gc.getInfoTypeForString('UNIT_IMP')]
	
	for i in range((iLev + cf.getNumBonusEffective(iPlayer, gc.getInfoTypeForString('BONUS_MANA_BODY'), pCaster))):
		listUnits.append(gc.getInfoTypeForString('UNIT_IMP'))
	if eTeam.isHasTech(gc.getInfoTypeForString('TECH_SORCERY')):
		for i in range((cf.getNumBonusEffective(iPlayer, gc.getInfoTypeForString('BONUS_MANA_DIMENSIONAL'), pCaster))):
			listUnits.append(gc.getInfoTypeForString('UNIT_MAGE'))
	if eTeam.isHasTech(gc.getInfoTypeForString('TECH_ARCANE_LORE')):
		for i in range((cf.getNumBonusEffective(iPlayer, gc.getInfoTypeForString('BONUS_MANA_DIMENSIONAL'), pCaster))):
			listUnits.append(gc.getInfoTypeForString('UNIT_COLUBRA'))
	if eTeam.isHasTech(gc.getInfoTypeForString('TECH_POISONS')):
		for i in range((iLev + cf.getNumBonusEffective(iPlayer, gc.getInfoTypeForString('BONUS_MANA_SHADOW'), pCaster))/3):
			listUnits.append(gc.getInfoTypeForString('UNIT_ASSASSIN'))
	if eTeam.isHasTech(gc.getInfoTypeForString('TECH_DRAMA')):
		for i in range((iLev + cf.getNumBonusEffective(iPlayer, gc.getInfoTypeForString('BONUS_MANA_BODY'), pCaster))/3):
			listUnits.append(gc.getInfoTypeForString('UNIT_SUCCUBUS'))
	if eTeam.isHasTech(gc.getInfoTypeForString('TECH_MALEVOLENT_DESIGNS')):
		if pPlayer.isUnitClassMaxedOut(gc.getInfoTypeForString('UNITCLASS_EIDOLON'), 0):
			for i in range((iLev + cf.getNumBonusEffective(iPlayer, gc.getInfoTypeForString('BONUS_MANA_BODY'), pCaster))/6):
				listUnits.append(gc.getInfoTypeForString('UNIT_EIDOLON'))
		if bDivine2:
			if pPlayer.isUnitClassMaxedOut(gc.getInfoTypeForString('UNITCLASS_CHANGELING'), 0):
				for i in range((cf.getNumBonusEffective(iPlayer, gc.getInfoTypeForString('BONUS_MANA_SHADOW'), pCaster))/6):
					listUnits.append(gc.getInfoTypeForString('UNIT_CHANGELING'))
	if eTeam.isHasTech(gc.getInfoTypeForString('TECH_HUNTING')):
		for i in range((iLev + cf.getNumBonusEffective(iPlayer, gc.getInfoTypeForString('BONUS_MANA_CHAOS'), pCaster))):
			listUnits.append(gc.getInfoTypeForString('UNIT_HELLHOUND'))
	if eTeam.isHasTech(gc.getInfoTypeForString('TECH_WARFARE')):
		for i in range((iLev + cf.getNumBonusEffective(iPlayer, gc.getInfoTypeForString('BONUS_MANA_CHAOS'), pCaster))/3):
			listUnits.append(gc.getInfoTypeForString('UNIT_CHAOS_MARAUDER'))
	for i in range((iLev + cf.getNumBonusEffective(iPlayer, gc.getInfoTypeForString('BONUS_MANA_CHAOS'), pCaster))/4):
		listUnits.append(gc.getInfoTypeForString('UNIT_PIT_BEAST'))
	if eTeam.isHasTech(gc.getInfoTypeForString('TECH_RAGE')):
		if bDivine2:
			if pPlayer.isUnitClassMaxedOut(gc.getInfoTypeForString('UNITCLASS_IRA'), 0):
				for i in range((iLev + cf.getNumBonusEffective(iPlayer, gc.getInfoTypeForString('BONUS_MANA_CHAOS'), pCaster))/8):
					listUnits.append(gc.getInfoTypeForString('UNIT_IRA'))

	if eTeam.isHasTech(gc.getInfoTypeForString('TECH_IRON_WORKING')):
		for i in range((iLev + cf.getNumBonusEffective(iPlayer, gc.getInfoTypeForString('BONUS_MANA_DEATH'), pCaster))/5):
			listUnits.append(gc.getInfoTypeForString('UNIT_SECT_OF_FLIES'))

	if eTeam.isHasTech(gc.getInfoTypeForString('TECH_WARHORSES')):
		if pPlayer.isUnitClassMaxedOut(gc.getInfoTypeForString('UNITCLASS_KNIGHT'), 0):
			for i in range((iLev + cf.getNumBonusEffective(iPlayer, gc.getInfoTypeForString('BONUS_MANA_DEATH'), pCaster))/9):
				listUnits.append(gc.getInfoTypeForString('UNIT_DEATH_KNIGHT'))
		
	if bDivine2:
		if eTeam.isHasTech(gc.getInfoTypeForString('TECH_NECROMANCY')):
			if pPlayer.isUnitClassMaxedOut(gc.getInfoTypeForString('UNITCLASS_DYBBUK'), 0):
				for i in range((iLev + cf.getNumBonusEffective(iPlayer, gc.getInfoTypeForString('BONUS_MANA_ENTROPY'), pCaster))/9):
					listUnits.append(gc.getInfoTypeForString('UNIT_DYBBUK'))
		if eTeam.isHasTech(gc.getInfoTypeForString('TECH_MALEVOLENT_DESIGNS')):
			if pPlayer.isUnitClassMaxedOut(gc.getInfoTypeForString('UNITCLASS_BEAST_OF_AGARES'), 0):
				for i in range((iLev + cf.getNumBonusEffective(iPlayer, gc.getInfoTypeForString('BONUS_MANA_ENTROPY'), pCaster))/9):
					listUnits.append(gc.getInfoTypeForString('UNIT_BEAST_OF_AGARES'))

	if eTeam.isHasTech(gc.getInfoTypeForString('TECH_FANATICISM')):
		for i in range((iLev + cf.getNumBonusEffective(iPlayer, gc.getInfoTypeForString('BONUS_MANA_FIRE'), pCaster))/4):
			listUnits.append(gc.getInfoTypeForString('UNIT_SALAMANDER'))
		if bDivine2:
			if pPlayer.isUnitClassMaxedOut(gc.getInfoTypeForString('UNITCLASS_IFRIT'), 0):
				for i in range((iLev + cf.getNumBonusEffective(iPlayer, gc.getInfoTypeForString('BONUS_MANA_FIRE'), pCaster))/9):
					listUnits.append(gc.getInfoTypeForString('UNIT_IFRIT'))
	if eTeam.isHasTech(gc.getInfoTypeForString('TECH_RELIGIOUS_LAW')):
		for i in range((iLev + cf.getNumBonusEffective(iPlayer, gc.getInfoTypeForString('BONUS_MANA_ICE'), pCaster))/3):
			listUnits.append(gc.getInfoTypeForString('UNIT_TAR_DEMON'))
			
	if eTeam.isHasTech(gc.getInfoTypeForString('TECH_WAY_OF_THE_WICKED')):
		for i in range((iLev + cf.getNumBonusEffective(iPlayer, gc.getInfoTypeForString('BONUS_MANA_MIND'), pCaster))):
			listUnits.append(gc.getInfoTypeForString('UNIT_SLAVE'))
	if eTeam.isHasTech(gc.getInfoTypeForString('TECH_FANATICISM')):
		for i in range((iLev + cf.getNumBonusEffective(iPlayer, gc.getInfoTypeForString('BONUS_MANA_MIND'), pCaster))/4):
			listUnits.append(gc.getInfoTypeForString('UNIT_STYGIAN_GUARD'))

	for iUnit in listUnits:
		iLimit = 1
		if bTwin:
			iLimit *= 2
		if len(cf.listSummons(pCaster, iUnit)) >= iLimit:
			listUnits.remove(iUnit)
		iClass = gc.getUnitInfo(iUnit).getUnitClassType()
		if isLimitedUnitClass(iClass):
			if pPlayer.isUnitClassMaxedOut(iClass, iLimit-1):
				listUnits.remove(iUnit)
	if len(listUnits) > 0:
		iUnit = listUnits[CyGame().getSorenRandNum(len(listUnits), "Summon Demon " + str(pCaster.getName()) )]
		pPlayer = gc.getPlayer(gc.getBARBARIAN_PLAYER())
		iNum = 1
		if bTwin:
			iNum = 2
		for i in range(iNum):
			pPlot2 = findClearPlot(-1, pPlot)
			if pPlot2 != -1:
				newUnit = pPlayer.initUnit(iUnit, pPlot2.getX(), pPlot2.getY(), UnitAITypes.UNITAI_ATTACK_CITY, DirectionTypes.DIRECTION_SOUTH)
				if not gc.getTeam(gc.getBARBARIAN_TEAM()).isAtWar(pCaster.getTeam()):
					newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_PARANOID'), True)
				newUnit.setDuration(2)
				cf.grantSummonPerks(newUnit, pCaster)
				newUnit.setHasPromotion(iDemon, True)
				iExperience = CyGame().getSorenRandNum(pCaster.getExperience() + pPlot.getPlotCounter()/4 + CyGame().getGlobalCounter()/2, "Summoned Demon experience " + str(newUnit.getName()))
				newUnit.setExperience(iExperience, -1)
				
				while newUnit.canAcquirePromotionAny() and newUnit.experienceNeeded() < newUnit.getExperience():
					listProms = []
					for iProm in xrange(gc.getNumPromotionInfos()):
						if newUnit.canAcquirePromotion(iProm):
							listProms.append(iProm)
					if len(listProms) > 0:
						iProm = listProms.pop(CyGame().getSorenRandNum(len(listProms), "Summoned Demon promotions per level"))
						newUnit.setHasPromotion(iProm, True)
						newUnit.setLevel(newUnit.getLevel()+1)
					else:
						break
				newUnit.setName(cf.MarnokNameGenerator(newUnit))

