def reqPacify(pCaster, eSpell=-1):
	iTeam = pCaster.getTeam()
	iProm = gc.getInfoTypeForString('PROMOTION_PACIFIED')
	lRemove = [gc.getInfoTypeForString('PROMOTION_ENRAGED'), gc.getInfoTypeForString('PROMOTION_REBEL'), gc.getInfoTypeForString('PROMOTION_BURNING_BLOOD')]
	info = gc.getPromotionInfo(iProm)
	iX = pCaster.getX()
	iY = pCaster.getY()
	iRange = 2
	for iiX in xrange(iX-iRange, iX + iRange+1, 1):
		for iiY in xrange(iY-iRange, iY+ iRange+1, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			# if pPlot.at(iX, iY):continue
			if plotDistance(iX, iY, iiX, iiY) > iRange:continue
			
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if pUnit.isHasPromotion(iProm):continue
				if pUnit.isPromotionImmune(iProm):continue
				if pUnit.isImmuneToSpell(pCaster, eSpell):continue
				for iProm2 in lRemove:
					if pCaster.isHasPromotion(iProm2):
						return True
				if info.getUnitCombat(pUnit.getUnitCombatType()):
					return True
	pPlot = pCaster.plot()
	if pPlot.isCity():
		pCity = pCaster.plot().getPlotCity()
##		for sBuilding in ['BUILDING_UNYIELDING_ORDER','BUILDING_UNYIELDING_ORDER_GREATER', 'BUILDING_TOWER_OF_COMPLACENCY', 'BUILDING_PILLAR_OF_CHAINS']:
##			if pCity.getNumBuilding(gc.getInfoTypeForString(sBuilding)) < 0:
		return True
	return False

