def helpParanoia(lpUnits, eSpell=-1):
	szBuffer = ''
	pCaster = lpUnits[0]
	iTeam = pCaster.getTeam()
	lTargets = []
	lTargetPlayers = []
	iX = pCaster.getX()
	iY = pCaster.getY()
	iRange = 2
	for iiX in xrange(iX-iRange, iX + iRange+1, 1):
		for iiY in xrange(iY-iRange, iY+ iRange+1, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			# if pPlot.at(iX, iY):continue
			if plotDistance(iX, iY, iiX, iiY) > iRange:continue
			
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if pUnit.isImmuneToMagic():continue
				if pUnit.isInvisible(iTeam, False):continue
				if pUnit in lpUnits:continue
				if pUnit.getTeam() == iTeam:continue
				if pUnit.isAvatarOfCivLeader():continue
				lTargets.append(pUnit)
				lTargetPlayers.append(pUnit.getOwner())

	lTargets = list(set(lTargets))
	lTargetPlayers = list(set(lTargetPlayers))

	iCount = len(lTargets)
	if iCount > 0:
		szBuffer += helpTogglePromotionsSpecificUnits(lpUnits, lTargets, eSpell, ['PROMOTION_PARANOID'], [], True)

	#Causes discord among these players:
	iCount = len(lTargetPlayers)
	if iCount > 1:
		sList = ''
		while len(lTargetPlayers) > 0:
			iPlayer = lTargetPlayers.pop(0)
			pPlayer = gc.getPlayer(iPlayer)
			if pPlayer != -1:
				sList += "<color=%d,%d,%d,%d>%s</color>" %(pPlayer.getPlayerTextColorR(), pPlayer.getPlayerTextColorG(), pPlayer.getPlayerTextColorB(), pPlayer.getPlayerTextColorA(), pPlayer.getName() )
				if len(lTargetPlayers) > 0:
					if len(lTargetPlayers) == 1:
						sList += " and "
					else:
						sList += ", "
		szBuffer += localText.getText("TXT_KEY_SPELL_PARANOIA_DIPLOMACY_HELP", (iCount, sList, ))
	return szBuffer

def spellParanoia(pCaster, eSpell=-1):
	iPlayer = pCaster.getOwner()
