def reqPeace(pCaster, eSpell=-1):
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iTeam = pCaster.getTeam()
	eTeam = gc.getTeam(iTeam)
	if not gc.getGame().isOption(GameOptionTypes.GAMEOPTION_NO_CHANGING_WAR_PEACE):
		if not pCaster.isBarbarian():
			if eTeam.getAtWarCount(True) > 0:
				if pCaster.isHuman():
					return True
				for iTeam2 in xrange(gc.getMAX_CIV_TEAMS()):
					if iTeam2 != iTeam:
						eTeam2 = gc.getTeam(iTeam2)
						if eTeam2.isAtWar(iTeam):
							if eTeam.getPower(True)*80 < eTeam2.getPower(True)*100:
								return True
	iPacified = gc.getInfoTypeForString('PROMOTION_PACIFIED')
	iX = pCaster.getX()
	iY = pCaster.getY()
	iRange = 2
	for iiX in xrange(iX-iRange, iX + iRange+1, 1):
		for iiY in xrange(iY-iRange, iY+ iRange+1, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			# if pPlot.at(iX, iY):continue
			if plotDistance(iX, iY, iiX, iiY) > iRange:continue
			
			if pPlot.isVisibleEnemyUnit(iPlayer):
				for i in xrange(pPlot.getNumUnits()):
					pUnit = pPlot.getUnit(i)
					if pUnit.getTeam() == iTeam:continue
					if pUnit.isImmuneToSpell(pCaster, eSpell):continue
					if eTeam.isAtWar(pUnit.getTeam()) or pUnit.isHiddenNationality():
						if not (pUnit.isHasPromotion(iPacified) or pUnit.isPromotionImmune(iPacified)):
							return True
	return False

def spellPeace(pCaster, eSpell=-1):
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iTeam = pCaster.getTeam()
	eTeam = gc.getTeam(iTeam)
	for iTeam2 in xrange(gc.getMAX_CIV_TEAMS()):
		if iTeam2 != iTeam:
			eTeam2 = gc.getTeam(iTeam2)
			if eTeam2.isAlive() and eTeam.isAtWar(iTeam2):
				eTeam.makePeace(iTeam2)
	# CyGame().changeGlobalCounter(-1 * pCaster.getLevel())

