def reqPeaceSevenPines(pCaster, eSpell=-1):
	pPlot = pCaster.plot()
	if not pPlot.isPythonActive():
		return False
	return reqPeace(pCaster, eSpell)

def spellPeaceSevenPines(pCaster, eSpell=-1):
	spellPeace(pCaster,eSpell)
	CyGame().changeGlobalCounter(-1 * (CyGame().getGlobalCounter() / 2))
	pPlot = pCaster.plot()
	pPlot.setPythonActive(False)

