def reqPillarofFire(pCaster, eSpell=-1):
	iX = pCaster.getX()
	iY = pCaster.getY()
	iPlayer = pCaster.getOwner()
	iTeam = pCaster.getTeam()
	eTeam = gc.getTeam(iTeam)
	iFire = gc.getInfoTypeForString('DAMAGE_FIRE')
	iFlames = gc.getInfoTypeForString('FEATURE_FLAMES')
	iRange = 2
	for iiX in xrange(iX-iRange, iX + iRange+1, 1):
		for iiY in xrange(iY-iRange, iY+ iRange+1, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			# if pPlot.at(iX, iY):continue
			if plotDistance(iX, iY, iiX, iiY) > iRange:continue
			
			if pPlot.isVisibleEnemyUnit(iPlayer):
				bEnemy = False
				bNeutral = False
				for i in xrange(pPlot.getNumUnits()):
					pUnit = pPlot.getUnit(i)
					if pUnit.isImmuneToSpell(pCaster, eSpell):continue
					if pUnit.getDamageTypeResist(iFire) < 100:
						if pUnit.getTeam() == iTeam:continue
						elif gc.getTeam(pUnit.getTeam()).isVassal(iTeam):continue
						elif eTeam.isAtWar(pUnit.getTeam()) or pCaster.isHiddenNationality() or pUnit.isHiddenNationality():
							if pUnit.getDamage() < 99:
								bEnemy = True
						else:
							bNeutral = True
				if bEnemy and not bNeutral:
					return True
	return False

def helpPillarofFire(lpUnits, eSpell=-1):
	szBuffer = ''
	pCaster = lpUnits[0]
	lTargets = []
	iX = pCaster.getX()
	iY = pCaster.getY()
	iPlayer = pCaster.getOwner()
	iTeam = pCaster.getTeam()
	eTeam = gc.getTeam(iTeam)
	iBestValue = 0
	pBestPlot = -1
	iFire = gc.getInfoTypeForString('DAMAGE_FIRE')
	iRange = 2
	for iiX in xrange(iX-iRange, iX + iRange+1, 1):
		for iiY in xrange(iY-iRange, iY+ iRange+1, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			# if pPlot.at(iX, iY):continue
			if plotDistance(iX, iY, iiX, iiY) > iRange:continue
			
			bNeutral = False
			iValue = 0
			if pPlot.isVisibleEnemyUnit(iPlayer):
				for i in xrange(pPlot.getNumUnits()):
					pUnit = pPlot.getUnit(i)
					if pUnit.isImmuneToSpell(pCaster, eSpell):continue
					if pUnit.getTeam() == iTeam:continue
					elif gc.getTeam(pUnit.getTeam()).isVassal(iTeam):continue
					elif eTeam.isAtWar(pUnit.getTeam()) or pCaster.isHiddenNationality() or pUnit.isHiddenNationality():
						if pUnit.getDamageTypeResist(iFire) < 100:
							iValue += 5 * pUnit.baseCombatStr()
					else:
						bNeutral = True
				if iValue > iBestValue and not bNeutral:
					iBestValue = iValue
					pBestPlot = pPlot
	if pBestPlot != -1:
		iX1 = iX
		iY1 = iY

		iX2 = pBestPlot.getX()
		iY2 = pBestPlot.getY()

		idY = iY2 - iY1
		if idY != 0:
			sdY = 'North'
			if idY < 0:
				idY = -idY
				sdY = 'South'
			sList = 'the plot ' + str(idY) + ' tiles to the ' + sdY
			szBuffer += localText.getText("TXT_KEY_HELP_SPELL_TARGETS_THIS", ( sList, ))


		idX = iX2 - iX1
		if idX != 0:
			sdX = 'East'
			if idX < 0:
				idX = -idX
				sdX = 'West'
			sList = 'the plot ' + str(idX) + ' tiles to the ' + sdX
			szBuffer += localText.getText("TXT_KEY_HELP_SPELL_TARGETS_THIS", ( sList, ))

		if pBestPlot.getFeatureType() in [gc.getInfoTypeForString('FEATURE_FOREST'), gc.getInfoTypeForString('FEATURE_JUNGLE')]:
			bValid = True
			iImprovement = pBestPlot.getImprovementType()
			if iImprovement != -1 :
				if gc.getImprovementInfo(iImprovement).isPermanent():
					bValid = False
			if bValid:
				szBuffer += localText.getText("TXT_KEY_HELP_SPELL_SMOKE", ("on the targeted plot", ))

		for i in xrange(pBestPlot.getNumUnits(), -1, -1):
			pUnit = pBestPlot.getUnit(i)
			if pUnit.isImmuneToSpell(pCaster, eSpell):continue
			# if pUnit.isInvisible(iTeam, False):continue

			if pUnit.getDamageTypeResist(iFire) < 100:
				lTargets.append(pUnit)



		lTargets = list(set(lTargets))

		iCount = len(lTargets)
		if iCount == 1:
			pUnit = lTargets.pop(0)
			pPlayer = gc.getPlayer(pUnit.getOwner())
			if pPlayer != -1:
				sList = cf.getNameWithColorScheme(pUnit, pUnit.isInvisible(pCaster.getTeam(), False))
				szBuffer += localText.getText("TXT_KEY_HELP_SPELL_TARGETS_THIS", ( sList, ))
		elif iCount > 0:
			sList = ''
			while len(lTargets) > 0:
				pUnit = lTargets.pop(0)
				iPlayer = pUnit.getOwner()
				if iPlayer > -1:
					pPlayer = gc.getPlayer(iPlayer)
					if pPlayer != -1:
						sList += cf.getNameWithColorScheme(pUnit, pUnit.isInvisible(pCaster.getTeam(), False))
						if len(lTargets) > 0:
							if len(lTargets) == 1:
								sList += " and "
							else:
								sList += ", "
			szBuffer += localText.getText("TXT_KEY_HELP_SPELL_TARGETS_THESE_COUNT_LIST", (iCount, sList, ))
	return szBuffer

def spellPillarofFire(pCaster, eSpell=-1):
	lTargets = []
	iX = pCaster.getX()
	iY = pCaster.getY()
	iPlayer = pCaster.getOwner()
	iTeam = pCaster.getTeam()
	eTeam = gc.getTeam(iTeam)
	iBestValue = 0
	pBestPlot = -1
	iFire = gc.getInfoTypeForString('DAMAGE_FIRE')
	iRange = 2
	for iiX in xrange(iX-iRange, iX + iRange+1, 1):
		for iiY in xrange(iY-iRange, iY+ iRange+1, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			# if pPlot.at(iX, iY):continue
			if plotDistance(iX, iY, iiX, iiY) > iRange:continue
			
			bNeutral = False
			iValue = 0
			if pPlot.isVisibleEnemyUnit(iPlayer):
				for i in xrange(pPlot.getNumUnits()):
					pUnit = pPlot.getUnit(i)
					if pUnit.isImmuneToSpell(pCaster, eSpell):continue
					if pUnit.getTeam() == iTeam:continue
					elif gc.getTeam(pUnit.getTeam()).isVassal(iTeam):continue
					elif eTeam.isAtWar(pUnit.getTeam()) or pCaster.isHiddenNationality() or pUnit.isHiddenNationality():
						if pUnit.getDamage() < 99:
							if pUnit.getDamageTypeResist(iFire) < 100:
								iValue += 5 * pUnit.baseCombatStr()
					else:
						bNeutral = True
				if iValue > iBestValue and not bNeutral:
					iBestValue = iValue
					pBestPlot = pPlot
	if pBestPlot != -1:
		for i in xrange(pBestPlot.getNumUnits(), -1, -1):
			pUnit = pBestPlot.getUnit(i)
			pUnit.doDamage(50, 100, pCaster, iFire, True)
		if pBestPlot.getFeatureType() in [gc.getInfoTypeForString('FEATURE_FOREST_NEW'),gc.getInfoTypeForString('FEATURE_FOREST_ANCIENT'),gc.getInfoTypeForString('FEATURE_FOREST'), gc.getInfoTypeForString('FEATURE_JUNGLE')]:
			bValid = True
			iImprovement = pBestPlot.getImprovementType()
			if iImprovement != -1 :
				if gc.getImprovementInfo(iImprovement).isPermanent():
					bValid = False
			if bValid:
				if CyGame().getSorenRandNum(100, "Flames Spread") > gc.getDefineINT('FLAMES_SPREAD_CHANCE'):
					pBestPlot.setImprovementType(gc.getInfoTypeForString('IMPROVEMENT_SMOKE'))
				else:
					pPlot.setFeatureType(gc.getInfoTypeForString('FEATURE_FLAMES'), 0)
		CyEngine().triggerEffect(gc.getInfoTypeForString('EFFECT_PILLAR_OF_FIRE'), pBestPlot.getPoint())

def reqPirateCove(pCaster, eSpell=-1):
	if pCaster.hasCargo():
		return False
	#if isLimitedUnitClass(pCaster.getUnitClassType()):
	if isWorldUnitClass(pCaster.getUnitClassType()):
		return False

	pPlot = pCaster.plot()
	if not pPlot.isWater():
		return False
	if pPlot.getImprovementType() != -1:
		return False
	if pPlot.isCity():
		return False
	if pPlot.isOwned():
		if pPlot.getOwner() != pCaster.getOwner():
			return False
	if not pPlot.isAdjacentToLand():
		if not gc.getTeam(pCaster.getTeam()).isHasTech(gc.getInfoTypeForString('TECH_ASTRONOMY')):
			return False
##	if pPlot.getBonusType(pCaster.getTeam()) != -1:
##		return False
	iX = pCaster.getX()
	iY = pCaster.getY()
	iRange = 2
	for iiX in xrange(iX-iRange, iX + iRange+1, 1):
		for iiY in xrange(iY-iRange, iY+ iRange+1, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			# if pPlot.at(iX, iY):continue
			if plotDistance(iX, iY, iiX, iiY) > iRange:continue
			
			iImprovement = pPlot.getImprovementType()
			if iImprovement != -1:
				if gc.getImprovementInfo(iImprovement).isActsAsCity():#Pirates Coves/Harbors/Ports act as cities even without advanced tactics, when forts do to
					return False
	return True

def spellPirateCove(pCaster, eSpell=-1):
	pPlot = pCaster.plot()
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	if pPlayer.getCivilizationType() == gc.getInfoTypeForString('CIVILIZATION_LANUN'):
		pPlot.setImprovementType(gc.getInfoTypeForString('IMPROVEMENT_PIRATE_COVE'))
		pCaster.kill(True, iPlayer)
		if gc.getGame().isOption(GameOptionTypes.GAMEOPTION_ADVANCED_TACTICS):
			pPlot.setOwner(iPlayer)

def helpPirateCove(lpUnits, eSpell=-1):
	szBuffer = ''
	pCaster = lpUnits[0]
	pPlot = pCaster.plot()
	if gc.getGame().isOption(GameOptionTypes.GAMEOPTION_ADVANCED_TACTICS):
		if pPlot.getOwner() != pCaster.getOwner():
			szBuffer += localText.getText("TXT_KEY_HELP_SPELL_PIRATE_COVE", ())
	return szBuffer

def reqPirateHN(pCaster, eSpell=-1):
	if pCaster.isOnlyDefensive():
		return False
	if pCaster.isHiddenNationality():
		if pCaster.hasCargo():
			iID = pCaster.getID()
			pPlot = pCaster.plot()
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if pUnit.getTransportUnit().getID() == iID:
					if not pUnit.isHiddenNationality():
						if pUnit.isOnlyDefensive():continue
						return True
		return False
	return True

def spellPirateHN(pCaster, eSpell=-1):
	iHN = gc.getInfoTypeForString('PROMOTION_HIDDEN_NATIONALITY')
	if pCaster.hasCargo():
		iID = pCaster.getID()
		pPlot = pCaster.plot()
		for i in xrange(pPlot.getNumUnits()):
			pUnit = pPlot.getUnit(i)
			if pUnit.getTransportUnit().getID() == iID:
				pUnit.setHasPromotion(iHN, True)

def spellDybbukPossess(pCaster, eSpell, iRange=1):

	if reqNecromancyAllowed(pCaster):
		iGhoul = gc.getInfoTypeForString('UNIT_GHOUL')
		pPlot = pCaster.plot()
		iX = pCaster.getX()
		iY = pCaster.getY()
		iPlayer = pCaster.getOwner()
		pPlayer = gc.getPlayer(iPlayer)
		iTeam = pCaster.getTeam()
		eTeam = gc.getTeam(iTeam)
		iX = pCaster.getX()
		iY = pCaster.getY()
		lSluaghs = []
		lUndead = []
		lHosts = []
		iPossessed = gc.getInfoTypeForString('PROMOTION_POSSESSED')
		iGood = gc.getInfoTypeForString('ALIGNMENT_GOOD')
		iEvil = gc.getInfoTypeForString('ALIGNMENT_EVIL')
		iUndead = gc.getInfoTypeForString('PROMOTION_UNDEAD')
		iSluagh = gc.getInfoTypeForString('UNIT_SLUAGH')
		lBoundProm = [	gc.getInfoTypeForString('PROMOTION_NETHERBIND'),
						gc.getInfoTypeForString('PROMOTION_CAPTUS_CAVEAE_SAWOL'),
						gc.getInfoTypeForString('PROMOTION_CAPTUS_CAVEAE_ANGELORUM'),
						gc.getInfoTypeForString('PROMOTION_INCARCERATUS_JUDICII'),
						gc.getInfoTypeForString('PROMOTION_SOUL_FORGED'),
						gc.getInfoTypeForString('PROMOTION_DRAGON')
						]
		listRemove = [
						gc.getInfoTypeForString('PROMOTION_HELD'),
						gc.getInfoTypeForString('PROMOTION_MAGIC_IMMUNE'),
						gc.getInfoTypeForString('PROMOTION_CANNOT_CAST')
					]

		if gc.getGame().getProjectCreatedCount(gc.getInfoTypeForString('PROJECT_STIR_FROM_SLUMBER')) > 0 or pCaster.getReligion() == gc.getInfoTypeForString('RELIGION_CULT_OF_THE_DRAGON'):
			lBoundProm.remove(gc.getInfoTypeForString('PROMOTION_DRAGON'))

		if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_SAWOL_CAVEA')):
			lBoundProm.remove(gc.getInfoTypeForString('PROMOTION_CAPTUS_CAVEAE_SAWOL'))
			listRemove.append(gc.getInfoTypeForString('PROMOTION_CAPTUS_CAVEAE_SAWOL'))

		if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_ANGELORUM_CAVEA')):
			lBoundProm.remove(gc.getInfoTypeForString('PROMOTION_CAPTUS_CAVEAE_ANGELORUM'))
			listRemove.append(gc.getInfoTypeForString('PROMOTION_CAPTUS_CAVEAE_ANGELORUM'))

		if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_NETHER_BLADE')):
			lBoundProm.remove(gc.getInfoTypeForString('PROMOTION_NETHERBIND'))
			listRemove.append(gc.getInfoTypeForString('PROMOTION_NETHERBIND'))
		iRange = 1
		for iiX in xrange(iX-iRange, iX + iRange+1, 1):
			for iiY in xrange(iY-iRange, iY+ iRange+1, 1):
				pPlot = CyMap().plot(iiX, iiY)
				if pPlot.isNone():continue
				# if pPlot.at(iX, iY):continue
				if plotDistance(iX, iY, iiX, iiY) > iRange:continue
				
				for i in xrange(pPlot.getNumUnits()):
					pUnit = pPlot.getUnit(i)
					if cf.getUnitAlignment(pUnit, False) != iGood:
						if pUnit.getUnitType() == iSluagh:
							for iProm in lBoundProm:
								if pUnit.isHasPromotion(iProm):
									break
							else:
								if pUnit.isDelayedDeath():
									continue
								iUnit = pUnit.getScenarioCounter()
								if -1 < iUnit < gc.getNumUnitInfos():
									info = gc.getUnitInfo(iUnit)
									iTech = info.getPrereqAndTech()
									if iTech != -1 and not eTeam.isHasTech(iTech):
										continue
	##								if isWorldUnitClass(info.getUnitClassType()):
	##									continue
								lSluaghs.append(pUnit)
						elif pUnit.getRace() == iUndead:
							lUndead.append(pUnit)
						elif pUnit.isAlive():
							lHosts.append(pUnit)

		for pUnit in lUndead:
			if len(lSluaghs) > 0:
				if effectResisted(pUnit, pCaster, eSpell):
					continue
				pSluagh = lSluaghs.pop(len(lSluaghs)-1)
				pUnit.convert(pSluagh)
				iUnit = pUnit.getUnitType()
				info = gc.getUnitInfo(iUnit)
				for iProm in listRemove:
					if not info.getFreePromotions(iProm):
						pUnit.setHasPromotion(iProm, False)
				if pUnit.getTeam() != iTeam:
					newUnit = pPlayer.initUnit(iGhoul, iX, iY, UnitAITypes.UNITAI_HERO, DirectionTypes.DIRECTION_SOUTH)
					newUnit.convert(pUnit)

		for pUnit in lHosts:
			if True:#not pUnit.isHasPromotion(iPossessed):
				if effectResisted(pUnit, pCaster, eSpell):
					continue
				pUnit.setHasPromotion(iPossessed, True)
				if pUnit.getTeam() != iTeam:
					if len(lSluaghs) > 0:
						##pSluagh = lSluaghs.pop(CyGame().getSorenRandNum(len(lSluaghs), "Dybbuk Possession"))
						pSluagh = lSluaghs.pop(len(lSluaghs)-1)
						newUnit = pPlayer.initUnit(pUnit.getUnitType(), iX, iY, UnitAITypes.UNITAI_HERO, DirectionTypes.DIRECTION_SOUTH)
						newUnit.convert(pUnit)


