def spellPotionOfRestoration(pCaster, eSpell):
	pCaster.setDamage(0, pCaster.getOwner())
	if pCaster.isMadeAttack():
		pCaster.setMadeAttack(False)
	if pCaster.isHasCasted():
		pCaster.setHasCasted(False)
	infoUnit = gc.getUnitInfo(pCaster.getUnitType())
	for iProm in xrange(gc.getNumPromotionInfos()):
		infoProm = gc.getPromotionInfo(iProm)
		if not infoProm.isEquipment():
			if pCaster.isHasPromotion(iProm):
				if infoProm.getAIWeight() < 0:
					pCaster.setHasPromotion(iProm, False)
			elif infoUnit.getFreePromotions(iProm):
				if infoProm.getAIWeight() > 0:
					pCaster.setHasPromotion(iProm, True)

def reqPotionOfRestoration(pCaster, eSpell):
	if pCaster.isHasCasted():
		return True
	if pCaster.isMadeAttack():
		return True
	if pCaster.getDamage() > 0:
		if pCaster.isHuman():
			return True
		elif pCaster.getDamage() > 50:
			return True
	infoUnit = gc.getUnitInfo(pCaster.getUnitType())
	for iProm in xrange(gc.getNumPromotionInfos()):
		infoProm = gc.getPromotionInfo(iProm)
		if not infoProm.isEquipment():
			if pCaster.isHasPromotion(iProm):
				if infoProm.getAIWeight() < 0:
					return True
			elif infoUnit.getFreePromotions(iProm):
				if infoProm.getAIWeight() > 0:
					return True
	return False

def helpPotionOfRestoration(lpUnits, eSpell):
	szBuffer = ''
	pCaster = lpUnits[0]
	if pCaster.getDamage() > 0:
		szBuffer += localText.getText("TXT_KEY_SPELL_HEALING_SALVE_HELP", ()) + '\n'
	if pCaster.isMadeAttack() and not pCaster.isBlitz():
		szBuffer += localText.getText("TXT_KEY_SPELL_HELP_SPECIFIC_UNIT_SET_ATTACK_FALSE", (pCaster.getName(), ))
	liAddProms = []
	liRemoveProms = [gc.getInfoTypeForString('PROMOTION_POTION_OF_RESTORATION')]
	infoUnit = gc.getUnitInfo(pCaster.getUnitType())
	for iProm in xrange(gc.getNumPromotionInfos()):
		infoProm = gc.getPromotionInfo(iProm)
		if not infoProm.isEquipment():
			if pCaster.isHasPromotion(iProm):
				if infoProm.getAIWeight() < 0:
					liRemoveProms.append(iProm)
			elif infoUnit.getFreePromotions(iProm):
				if infoProm.getAIWeight() > 0:
					liAddProms.append(iProm)
	szBuffer += helpTogglePromotionsBuffCasterIndex(lpUnits, eSpell, liAddProms, liRemoveProms, bResistable=False)
	return szBuffer

def reqPurgeEvil(pCaster, eSpell=-1):
	if cf.getUnitAlignment(pCaster) == gc.getInfoTypeForString('ALIGNMENT_EVIL'):
		return True
	return False

def spellPurgeEvil(pCaster, eSpell=-1):
	if cf.getUnitAlignment(pCaster) == gc.getInfoTypeForString('ALIGNMENT_EVIL'):
		CyGame().changeGlobalCounter(-1)
		if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_UNDEAD')):
			pCaster.kill(True, PlayerTypes.NO_PLAYER)
		else:
			pCaster.doDamageNoCaster(20, 95, gc.getInfoTypeForString('DAMAGE_HOLY'), False)
			if pCaster.getReligion() in [	gc.getInfoTypeForString('RELIGION_CULT_OF_THE_DRAGON'),
											gc.getInfoTypeForString('RELIGION_WHITE_HAND'),
											gc.getInfoTypeForString('RELIGION_THE_ASHEN_VEIL'),
											gc.getInfoTypeForString('RELIGION_OCTOPUS_OVERLORDS'),
											gc.getInfoTypeForString('RELIGION_COUNCIL_OF_ESUS'),
											gc.getInfoTypeForString('RELIGION_ANOINTED'),
											gc.getInfoTypeForString('RELIGION_EMBER_LEGION'),
											gc.getInfoTypeForString('RELIGION_SONS_OF_DISCORD')
											]:
				pCaster.setReligion(-1)
			for sProm in [	'PROMOTION_UNHOLY_TAINT',
							'PROMOTION_POSSESSED',
							'PROMOTION_VAMPIRE',
							'PROMOTION_SHEUT_STONE',
							'PROMOTION_NIGHTMARE',

							'PROMOTION_DEATH1',
							'PROMOTION_DEATH2',
							'PROMOTION_DEATH3',
							'PROMOTION_DIMENSIONAL1',
							'PROMOTION_DIMENSIONAL2',
							'PROMOTION_DIMENSIONAL3',
							'PROMOTION_ENTROPY1',
							'PROMOTION_ENTROPY2',
							'PROMOTION_ENTROPY3',

							'PROMOTION_SUNDERED',

							'PROMOTION_PACT_WITH_HYBOREM',
							'PROMOTION_PACT_WITH_JUDECCA',
							'PROMOTION_PACT_WITH_LETHE',
							'PROMOTION_PACT_WITH_MERESIN',
							'PROMOTION_PACT_WITH_OUZZA',
							'PROMOTION_PACT_WITH_SALLOS',
							'PROMOTION_PACT_WITH_STATIUS',

							'PROMOTION_PACT_WITH_WINTER',
							'PROMOTION_BOUND_BY_COMPACT'
							]:
				iProm = gc.getInfoTypeForString(sProm)
				if pCaster.isHasPromotion(iProm):
					pCaster.setHasPromotion(iProm, False)
					pCaster.doDamageNoCaster(5, 95, gc.getInfoTypeForString('DAMAGE_HOLY'), False)
			if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_DEMON')):
				pCaster.setHasPromotion(gc.getInfoTypeForString('PROMOTION_ANGEL'), True)
				if pCaster.getLevel() > 2:
					if gc.getUnitInfo(pCaster.getUnitType()).getTier() > 3:
						iPlayer = pCaster.getOwner()
						pPlayer = gc.getPlayer(iPlayer)
						iUnit = gc.getInfoTypeForString('UNIT_REPENTANT_ANGEL')
						if not pPlayer.isUnitClassMaxedOut(gc.getUnitInfo(iUnit).getUnitClassType(), 0):
							iX = pCaster.getX()
							iY = pCaster.getY()
							newUnit = pPlayer.initUnit(iUnit, iX, iY, UnitAITypes.UNITAI_HERO, DirectionTypes.DIRECTION_SOUTH)
							sName = cf.getNameWithColorScheme(pCaster)
							CyInterface().addMessage(iPlayer, True, 25, localText.getText("TXT_KEY_MESSAGE_PURGE_EVIL_REPENTANT_ANGEL", (sName, )), '', 1, 'Art/Interface/Buttons/TechTree/Righteousness.dds', ColorTypes(8), iX, iY, True, True)
							cf.removeAffinities(newUnit)
							newUnit.convert(pCaster)

def helpPurgeEvil(lpUnits, eSpell=-1):
	szBuffer = ''
	lsRemoveProms = [	'PROMOTION_DEATH1',
						'PROMOTION_DEATH2',
						'PROMOTION_DEATH3',
						'PROMOTION_DIMENSIONAL1',
						'PROMOTION_DIMENSIONAL2',
						'PROMOTION_DIMENSIONAL3',
						'PROMOTION_ENTROPY1',
						'PROMOTION_ENTROPY2',
						'PROMOTION_ENTROPY3',
						'PROMOTION_UNHOLY_TAINT',
						'PROMOTION_POSSESSED',
						'PROMOTION_VAMPIRE',
						'PROMOTION_SUNDERED'
						]
	szBuffer += helpTogglePromotionsBuffCaster(lpUnits, eSpell, [], lsRemoveProms, False)
	lEvilFaiths = [	gc.getInfoTypeForString('RELIGION_WHITE_HAND'),
			gc.getInfoTypeForString('RELIGION_THE_ASHEN_VEIL'),
			gc.getInfoTypeForString('RELIGION_OCTOPUS_OVERLORDS'),
			gc.getInfoTypeForString('RELIGION_COUNCIL_OF_ESUS'),
			gc.getInfoTypeForString('RELIGION_ANOINTED'),
			gc.getInfoTypeForString('RELIGION_EMBER_LEGION'),
			gc.getInfoTypeForString('RELIGION_SONS_OF_DISCORD')
			]
	iAngel = gc.getInfoTypeForString('PROMOTION_ANGEL')
	iDemon = gc.getInfoTypeForString('PROMOTION_DEMON')
	sAngel = gc.getPromotionInfo(iAngel).getDescription()
	sDemon = gc.getPromotionInfo(iDemon).getDescription()
	iCounter = 0
	for pCaster in lpUnits:
		if reqPurgeEvil(pCaster, eSpell):
			iCounter -=1
			if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_UNDEAD')):
				szBuffer += '\n' + localText.getText("TXT_KEY_SPELL_SACRIFICE_CASTER", ())
			else:
##				pCaster.doDamageNoCaster(20, 95, gc.getInfoTypeForString('DAMAGE_HOLY'), False)
				if pCaster.getReligion() in lEvilFaiths:
					infoRel = gc.getReligionInfo(pCaster.getReligion())
					szBuffer += localText.getText("TXT_KEY_HELP_SPELL_REMOVES_STUFF", ( u"%c" %(infoRel.getChar()) + infoRel.getDescription(), )) + " from " + pCaster.getName()
				if pCaster.isHasPromotion(iDemon):
					szBuffer += '\n' + localText.getText("TXT_KEY_HELP_SPELL_CHANGE_A_TO_B", (sDemon, sAngel, ))
					if pCaster.getLevel() > 2:
						if gc.getUnitInfo(pCaster.getUnitType()).getTier() > 3:
							iPlayer = pCaster.getOwner()
							pPlayer = gc.getPlayer(iPlayer)
							iUnit = gc.getInfoTypeForString('UNIT_REPENTANT_ANGEL')
							if not pPlayer.isUnitClassMaxedOut(gc.getUnitInfo(iUnit).getUnitClassType(), 0):
								sName = cf.getNameWithColorScheme(pCaster)
								sName2 = gc.getUnitInfo(iUnit).getDescription()
								szBuffer += '\n' + localText.getText("TXT_KEY_HELP_SPELL_CHANGE_A_TO_B", (sName, sName2, ))
	if iCounter != 0:
		szBuffer += '\n' + localText.getText("TXT_KEY_EVENT_GLOBAL_COUNTER", (iCounter, ))
	return szBuffer

def reqPromoteSettlement(pCaster, eSpell=-1):
	pPlot = pCaster.plot()
	pCity = pPlot.getPlotCity()
	if not pCity.isSettlement():
		return False
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iAbundance = gc.getInfoTypeForString('BUILDING_ABUNDANCE')

	if pCity.getNumBuilding(iAbundance) > 0:
		return True
	iGardens = gc.getInfoTypeForString('BUILDING_PIXIE_GARDEN')
	iSlums = gc.getInfoTypeForString('BUILDING_CITY_OF_A_THOUSAND_SLUMS')

	iNumHubs = pPlayer.getNumCities() - pPlayer.getNumSettlements()
	iNumAllowedHubs = pPlayer.getMaxCities() + pPlayer.countNumBuildings(iAbundance) + pPlayer.countNumBuildings(iGardens) + pPlayer.countNumBuildings(iSlums)
	if iNumHubs >= iNumAllowedHubs:
		return False

	if not pPlayer.isHuman():
		return True
	return True

def spellPromoteSettlement(pCaster, eSpell=-1):
	pPlot = pCaster.plot()
	pCity = pPlot.getPlotCity()
	pCity.setSettlement(False)
	pCity.setPlotRadius(3)

def miscastRage(pCaster, eSpell=-1):
	iSpell = gc.getInfoTypeForString('SPELL_BERSERK')
	if pCaster.canCast(iSpell, True):
		pCaster.cast(iSpell)

def reqRagingSeas(pCaster, eSpell=-1):
	if not pCaster.isHuman():
		eTeam = gc.getTeam(pCaster.getTeam())
		iCount = 0
		for iPlayer in xrange(gc.getMAX_CIV_PLAYERS()):
			pPlayer = gc.getPlayer(iPlayer)
			if pPlayer.isAlive():
				if eTeam.isAtWar(pPlayer.getTeam()):
					iCount += pPlayer.countNumCoastalCities()
		if iCount > 5:
			return True
		return False
	return True

def spellRagingSeas(pCaster, eSpell=-1):
	iCold = gc.getInfoTypeForString('DAMAGE_COLD')
	iFlames = gc.getInfoTypeForString('FEATURE_FLAMES')
	iLanun = gc.getInfoTypeForString('CIVILIZATION_LANUN')
	iSmoke = gc.getInfoTypeForString('IMPROVEMENT_SMOKE')
	iSpring = gc.getInfoTypeForString('EFFECT_SPRING')
	for i in xrange (CyMap().numPlots()):
		pPlot = CyMap().plotByIndex(i)
		if pPlot.isAdjacentToWater():
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if pUnit.getCivilizationType() != iLanun:
					pUnit.doDamageNoCaster(75, 100, iCold, False)
			if pPlot.getImprovementType() != -1:
				if pPlot.getFeatureType() == iFlames:
					pPlot.setFeatureType(-1, 0)
				if pPlot.getImprovementType() == iSmoke:
					pPlot.setImprovementType(-1)
				elif pPlot.isOwned():
					if not gc.getImprovementInfo(pPlot.getImprovementType()).isPermanent():
						if gc.getPlayer(pPlot.getOwner()).getCivilizationType() != iLanun:
							if CyGame().getSorenRandNum(100, "Raging Seas") < 25:
								pPlot.setImprovementType(-1)
			if pPlot.isVisibleToWatchingHuman():
				CyEngine().triggerEffect(iSpring, pPlot.getPoint())

def reqRaiseSkeleton(pCaster, eSpell=-1):
	if reqNecromancyAllowed(pCaster):
		return canSummonLimited(pCaster, eSpell, 'UNIT_SKELETON')
	return False

def reqRally(pCaster, eSpell=-1):
	if not pCaster.isHuman():
		iPlayer = pCaster.getOwner()
		pPlayer = gc.getPlayer(iPlayer)
#		if not pPlayer.isCivic(gc.getInfoTypeForString('CIVIC_CRUSADE')):
#			return False
		iTeam = pCaster.getTeam()
		eTeam = gc.getTeam(iTeam)
		if eTeam.getAtWarCount(True) == 0:
			return False
		if pPlayer.getImprovementCount(gc.getInfoTypeForString('IMPROVEMENT_TOWN')) < (3 * pPlayer.getNumCities()):
			return False
	return True

def spellRally(pCaster, eSpell=-1):
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	pPlayer.changeAnarchyTurns(-pPlayer.getAnarchyTurns())
	iCivicOption = gc.getInfoTypeForString('CIVICOPTION_MEMBERSHIP')
	iCivic = gc.getInfoTypeForString('CIVIC_CRUSADE')
	if pPlayer.getCivics(iCivicOption) != iCivic:
		if pPlayer.canDoCivics(iCivic):
			pPlayer.setCivics(iCivicOption, iCivic)
	iReligion = pPlayer.getStateReligion()
	iRecruiter = gc.getInfoTypeForString('PROMOTION_RECRUITER')
	iDemagog = gc.getInfoTypeForString('UNIT_DEMAGOG')
	iFlagbearer = gc.getInfoTypeForString('UNIT_FLAGBEARER')
	lTown = [gc.getInfoTypeForString('IMPROVEMENT_TOWN'), gc.getInfoTypeForString('IMPROVEMENT_ENCLAVE')]
	iVillage = gc.getInfoTypeForString('IMPROVEMENT_VILLAGE')
	pCity = pPlayer.getCapitalCity()
	for i in xrange (CyMap().numPlots()):
		pPlot = CyMap().plotByIndex(i)
		if pPlot.getOwner() == iPlayer:
			if pPlot.isVisibleEnemyUnit(iPlayer):continue
			if pPlot.isCity():
				newUnit = pPlayer.initUnit(iDemagog, pPlot.getX(), pPlot.getY(), UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
				newUnit.setHasPromotion(iRecruiter, False)
				pCity.applyBuildEffects(newUnit)
				newUnit.setReligion(iReligion)
				newUnit = pPlayer.initUnit(iFlagbearer, pPlot.getX(), pPlot.getY(), UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
				pCity.applyBuildEffects(newUnit)
				newUnit.setReligion(iReligion)
			elif pPlot.getImprovementType() in lTown:
				pPlot.setImprovementType(iVillage)
				newUnit = pPlayer.initUnit(iDemagog, pPlot.getX(), pPlot.getY(), UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
				pCity = CyMap().findCity(pPlot.getX(), pPlot.getY(), iPlayer, TeamTypes.NO_TEAM, False, False, TeamTypes.NO_TEAM, DirectionTypes.NO_DIRECTION, pPlayer.getCity(-1))
				if not pCity.isNone():
					pCity.applyBuildEffects(newUnit)
				newUnit.setReligion(iReligion)

def helpRally(lpUnits, eSpell=-1):
	szBuffer = ''
	pCaster = lpUnits[0]
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	if pPlayer.isAnarchy():
		szBuffer += localText.getText("TXT_KEY_HELP_SPELL_END_ANARCHY", ())
	iCivicOption = gc.getInfoTypeForString('CIVICOPTION_MEMBERSHIP')
	iCivic = gc.getInfoTypeForString('CIVIC_CRUSADE')
	if not pPlayer.isCivic(iCivic):
		if pPlayer.canDoCivics(iCivic):
			szBuffer += localText.getText("TXT_KEY_HELP_SPELL_CHANGE_CIVIC", (gc.getCivicInfo(iCivic).getDescription(), gc.getCivicOptionInfo(iCivicOption).getDescription(), ))
			szBuffer += '\n' + CyGameTextMgr().parseCivicInfo(iCivic, False, True, False)
	iTown = gc.getInfoTypeForString('IMPROVEMENT_TOWN')
	iEnclave = gc.getInfoTypeForString('IMPROVEMENT_ENCLAVE')
	iVillage = gc.getInfoTypeForString('IMPROVEMENT_VILLAGE')
	iNumDemagog = 0
	iNumFlag = 0
	iNumTown = 0
	iNumEnclave = 0
	for i in xrange (CyMap().numPlots()):
		pPlot = CyMap().plotByIndex(i)
		if pPlot.getOwner() == iPlayer:
			if pPlot.isVisibleEnemyUnit(iPlayer):continue
			if pPlot.isCity():
				iNumDemagog += 1
				iNumFlag += 1
			elif pPlot.getImprovementType() == iTown:
				iNumTown += 1
				iNumDemagog += 1
			elif pPlot.getImprovementType() == iEnclave:
				iNumEnclave += 1
				iNumDemagog += 1
	if iNumDemagog > 0:
		szBuffer += localText.getText("TXT_KEY_HELP_SPELL_RECRUIT", (iNumDemagog, gc.getUnitInfo(gc.getInfoTypeForString('UNIT_DEMAGOG')).getDescription(), ))
	if iNumFlag > 0:
		szBuffer += localText.getText("TXT_KEY_HELP_SPELL_RECRUIT", (iNumFlag, gc.getUnitInfo(gc.getInfoTypeForString('UNIT_FLAGBEARER')).getDescription(), ))
	if iNumTown > 0:
		szBuffer += localText.getText("TXT_KEY_HELP_SPELL_CHANGES_PLOTS_TO_FROM", (iNumTown, gc.getImprovementInfo(gc.getInfoTypeForString('IMPROVEMENT_TOWN')).getDescription(), gc.getImprovementInfo(gc.getInfoTypeForString('IMPROVEMENT_VILLAGE')).getDescription(), ))
	if iNumEnclave > 0:
		szBuffer += localText.getText("TXT_KEY_HELP_SPELL_CHANGES_PLOTS_TO_FROM", (iNumEnclave, gc.getImprovementInfo(gc.getInfoTypeForString('IMPROVEMENT_ENCLAVE')).getDescription(), gc.getImprovementInfo(gc.getInfoTypeForString('IMPROVEMENT_TOWN')).getDescription(), ))
	return szBuffer


