def helpRebuildMithrilGolem(lpUnits, eSpell=-1):
	szBuffer = helpShowUnitDetails('UNIT_MITHRIL_GOLEM')
	pCaster = lpUnits[0]
	pPlot = pCaster.plot()
	if pPlot.isCity():
		pCity = pPlot.getPlotCity()
		iPlayer = pCaster.getOwner()
		iCityPlayer = pCity.getOwner()
		pCityPlayer = gc.getPlayer(iCityPlayer)
		if pCityPlayer.getStateReligion() == gc.getInfoTypeForString('RELIGION_RUNES_OF_KILMORPH'):
			if iPlayer != iCityPlayer:
				szBuffer += localText.getText("TXT_KEY_HELP_SPELL_IMPROVE_RELATIONS", (pCityPlayer.getName(), 2, ))
			iUnit = gc.getInfoTypeForString('UNIT_MITHRIL_GOLEM')
			lPromotions = []
			iHeld = gc.getInfoTypeForString('PROMOTION_HELD')

			lBoundProm = [	gc.getInfoTypeForString('PROMOTION_NETHERBIND'),
							gc.getInfoTypeForString('PROMOTION_CAPTUS_CAVEAE_SAWOL'),
							gc.getInfoTypeForString('PROMOTION_CAPTUS_CAVEAE_ANGELORUM'),
							gc.getInfoTypeForString('PROMOTION_INCARCERATUS_JUDICII'),
							gc.getInfoTypeForString('PROMOTION_SOUL_FORGED'),
							gc.getInfoTypeForString('PROMOTION_AFFINITY_DEATH')
							]
			listRemove = [
							gc.getInfoTypeForString('PROMOTION_HELD'),
							gc.getInfoTypeForString('PROMOTION_MAGIC_IMMUNE'),
							gc.getInfoTypeForString('PROMOTION_CANNOT_CAST')
						]

			if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_SAWOL_CAVEA')):
				lBoundProm.remove(gc.getInfoTypeForString('PROMOTION_CAPTUS_CAVEAE_SAWOL'))
				listRemove.append(gc.getInfoTypeForString('PROMOTION_CAPTUS_CAVEAE_SAWOL'))
			if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_ANGELORUM_CAVEA')):
				lBoundProm.remove(gc.getInfoTypeForString('PROMOTION_CAPTUS_CAVEAE_ANGELORUM'))
				listRemove.append(gc.getInfoTypeForString('PROMOTION_CAPTUS_CAVEAE_ANGELORUM'))
			if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_NETHER_BLADE')):
				lBoundProm.remove(gc.getInfoTypeForString('PROMOTION_NETHERBIND'))
				listRemove.append(gc.getInfoTypeForString('PROMOTION_NETHERBIND'))

			lSluaghs = []
			for pSluagh in PyPlayer(gc.getBARBARIAN_PLAYER()).getUnitList():

				if pSluagh.getScenarioCounter() == iUnit:
					for iProm in lBoundProm:
						if pSluagh.isHasPromotion(iProm):
							break
					else:
						lSluaghs.append(pSluagh)
			if len(lSluaghs) > 0:
				pUnit = lSluaghs[0]
				sName = pUnit.getName()[:pUnit.getName().find("'s Sluagh")]
				for iProm in xrange(gc.getNumPromotionInfos()):
					if pUnit.isHasPromotion(iProm):
						if iProm in [ iHeld, gc.getInfoTypeForString('PROMOTION_CANNOT_CAST'), gc.getInfoTypeForString('PROMOTION_MAGIC_IMMUNE')]:continue
						if gc.getPromotionInfo(iProm).isEquipment():continue
						lPromotions.append(iProm)
				lPromotions = list(set(lPromotions))
				iCount = len(lPromotions)
				if iCount > 0:
					sList = ''
					while len(lPromotions) > 0:
						iProm = lPromotions.pop(0)
						infoProm = gc.getPromotionInfo(iProm)
						sList += infoProm.getDescription()
						if len(lPromotions) > 0:
							if len(lPromotions) == 1:
								sList += " and "
							else:
								sList += ", "
					szBuffer += localText.getText("TXT_KEY_HELP_SPELL_GRANT_PROMOTIONS_TO_SPECIFIC_UNIT", (sName, sList, ))
	return szBuffer

def reqRecruit(pCaster, eSpell=-1):
	pPlot = pCaster.plot()
	pCity = findAdjacentCity(pCaster)
	if not pCity:
		return False
	iPlayerU = pCaster.getOwner()
	pPlayerU = gc.getPlayer(iPlayerU)
	iTeamU = pCaster.getTeam()
	pTeamU = gc.getTeam(iTeamU)

	iPlayerC = pCity.getOwner()
	pPlayerC = gc.getPlayer(iPlayerC)
	iTeamC = pCity.getTeam()
	pTeamC = gc.getTeam(iTeamC)

	iPop = pCity.getPopulation()
	if not pPlayerU.hasTrait(gc.getInfoTypeForString('TRAIT_TOLERANT')):
		iPop *= pCity.calculateCulturePercent(iPlayerU)
		iPop /= 100

	iOccupation = pCity.getOccupationTimer()
	iAnger = pCity.getHurryAngerTimer()


	if iTeamC == iTeamU:
		iPop -= 2 * iOccupation + iAnger
	elif pTeamU.isVassal(iTeamC):
		iPop += pCity.getPopulation()/3
		iPop -= 2 * iOccupation + iAnger
	elif pTeamU.isAtWar(iTeamC):
		iPop += 2 * iOccupation + iAnger

	iRel = pCaster.getReligion()
	if iRel > -1:
		if pCity.isHasReligion(iRel):
			iPop += 1
			if pPlayerU.getStateReligion() == iRel:
				iPop += 1
			if pPlayerC.getStateReligion() == iRel:
				iPop -= 2

	if iPop < 1:
		return False

	if not pCaster.isHuman():
		if pCaster.getUnitType() == gc.getInfoTypeForString('UNIT_DONAL'):
			if iPop > 8:
				return True
		return False

	if pCaster.getUnitType() == gc.getInfoTypeForString('UNIT_DEMAGOG'):
		for iUnitClass in [	gc.getInfoTypeForString('UNIT_DEMAGOG'),
					gc.getInfoTypeForString('UNIT_CRUSADER'),
					gc.getInfoTypeForString('UNIT_FLAGBEARER'),
					gc.getInfoTypeForString('UNIT_WITCH_HUNTER')
					]:
			if pCity.canTrain(iUnitClass, True, False):
				return True
		return False

	return True

def helpRecruit(lpUnits, eSpell=-1):
	pCaster =lpUnits[0]
	szBuffer = ''
	pCity = findAdjacentCity(pCaster)
	if not pCity:
		szBuffer += localText.getText("TXT_KEY_HELP_NOT_ADJACENT_CITY", ())
