def reqBecomeMercenaryRecruiter(pCaster, eSpell=-1):
	if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_MERCENARY_RECRUITER')):
		return False
	if CyGame().getBuildingClassCreatedCount(gc.getInfoTypeForString('BUILDINGCLASS_GUILD_OF_THE_NINE')) < 1:
		return False
	iCost = 60#The price of the cheapest Hire Mercenary abilities
	iCost *= gc.getGameSpeedInfo(CyGame().getGameSpeedType()).getTrainPercent()
	iCost /= 100
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	if pPlayer.isStrike():#If you gold is this low, the mercenaries would quickly turn barbarian
		return False
	iGold = pPlayer.getGold()
	if iGold < iCost:
		return False
	pPlot = pCaster.plot()
	pCity = pPlot.getPlotCity()
	iTeam = pPlayer.getTeam()
	eTeam = gc.getTeam(iTeam)
	if eTeam.isAtWar(pCity.getTeam()):
		return False
	iPlayerC = pCity.findHighestCulture()
	if iPlayerC == -1:
		iPlayerC = pCity.getOwner()
	if iPlayerC != iPlayer:
		if gc.getPlayer(iPlayerC).getCivilizationType() == gc.getInfoTypeForString('CIVILIZATION_INFERNAL'):
			if pPlayer.getStateReligion() != gc.getInfoTypeForString('RELIGION_THE_ASHEN_VEIL'):
				return False
	if not pCaster.isHuman():
		iGoldRate = pPlayer.calculateGoldRate()
		iCiv = pPlayer.getCivilizationType()
		if iCiv != gc.getInfoTypeForString('CIVILIZATION_HIPPUS'):
			if iGold + iGoldRate < 3*iCost:
				return False
			if iCiv == gc.getInfoTypeForString('CIVILIZATION_KHAZAD'):
				if iGoldRate < 0:
					return False
				if (iGold - iCost) / pPlayer.getNumCities() < 500:
					return False
		if eTeam.getAtWarCount(True) < 1:
			return False
		iArea = pCaster.area()
		iLocalTeamUnits = eTeam.countNumUnitsByArea(iArea)
		iLocalHostileUnits = 0
		for iTeam2 in xrange(gc.getMAX_TEAMS()):
			if eTeam.isAtWar(iTeam2):
				eTeam2 = gc.getTeam(iTeam2)
				if eTeam2.isAlive():
					iLocalHostileUnits += eTeam.countNumUnitsByArea(iArea)
		if iLocalHostileUnits < iLocalTeamUnits:
			return False
		iRecruiter = gc.getInfoTypeForString('PROMOTION_MERCENARY_RECRUITER')
		for i in xrange(pPlot.getNumUnits()):
			pUnit = pPlot.getUnit(i)
			if pUnit.getOwner() == iPlayer:
				if pUnit.isHasPromotion(iRecruiter):
					return False
	return True

def helpRecruitMercenaryType(lpUnits, eSpell, sUnitClass):
	szBuffer = ''
	pCaster = lpUnits[0]
	pPlot = pCaster.plot()
	if pPlot.isCity():
		iUnitClass = gc.getInfoTypeForString(sUnitClass)
		if iUnitClass != -1:
			iPlayer = pCaster.getOwner()
			pPlayer = gc.getPlayer(iPlayer)
			iTeam = pPlayer.getTeam()
			eTeam = gc.getTeam(iTeam)
			iCiv = pPlayer.getCivilizationType()
			infoCiv = gc.getCivilizationInfo(iCiv)


			pCity = -1
			if pPlot.isCity():
				pCity = pPlot.getPlotCity()
			else:
				pCity = CyMap().findCity(pPlot.getX(), pPlot.getY(), iPlayer, TeamTypes.NO_TEAM, False, False, TeamTypes.NO_TEAM, DirectionTypes.NO_DIRECTION, pPlayerPlot.getCity(-1))
			if pCity != -1:


				iPlayerC = pCity.findHighestCulture()
				if iPlayerC == -1:
					iPlayerC = pCity.getOwner()
				pPlayerC = gc.getPlayer(iPlayerC)
				iCivC = pPlayerC.getCivilizationType()
				infoCivC = gc.getCivilizationInfo(iCivC)
				iUnit = infoCivC.getCivilizationUnits(iUnitClass)
				if iUnit != -1:
					info = gc.getSpellInfo(eSpell)
					iCost = info.getCost()
					iCost *= gc.getGameSpeedInfo(CyGame().getGameSpeedType()).getTrainPercent()
					iCost /= 100
					if len(lpUnits) > 1:
						iCostBase = iCost
						iCost = 0
						iGold = pPlayer.getGold()
						for pCaster in lpUnits:
							if iCost >= iGold:break
							if pCaster.canCast(eSpell, True):
								iCost += iCostBase
					infoUnit = gc.getUnitInfo(iUnit)
					lPerks = []
					iGuild = gc.getInfoTypeForString('BUILDING_GUILD_OF_THE_NINE')
					if pPlayer.getNumBuilding(iGuild) < 1:
						iFee = iCost//4
						if iFee > 0:
							for iLoopPlayer in xrange(gc.getMAX_PLAYERS()):
								pLoopPlayer = gc.getPlayer(iLoopPlayer)
								if pLoopPlayer.isAlive():
									if pLoopPlayer.getNumBuilding(iGuild) > 0:
										sName = "<color=%d,%d,%d,%d>%s</color>" %(pLoopPlayer.getPlayerTextColorR(), pLoopPlayer.getPlayerTextColorG(), pLoopPlayer.getPlayerTextColorB(), pLoopPlayer.getPlayerTextColorA(), pLoopPlayer.getName() )
										szBuffer += localText.getText("TXT_KEY_HELP_SPELL_PAY_GOLD", (iFee, sName))
					if iPlayerC != iPlayer:
						iFee = iCost//10
						if iFee > 0:
							sName = "<color=%d,%d,%d,%d>%s</color>" %(pPlayerC.getPlayerTextColorR(), pPlayerC.getPlayerTextColorG(), pPlayerC.getPlayerTextColorB(), pPlayerC.getPlayerTextColorA(), pPlayerC.getName() )
							szBuffer += localText.getText("TXT_KEY_HELP_SPELL_PAY_GOLD", (iFee, sName))
					szBuffer += '\n' + localText.getText("TXT_KEY_SPELL_RECRUIT_MERCENARY_HELP", ()) + ' ' + helpUnitHelp(iUnit)
					if iCiv != iCivC:
						if not infoUnit.isMechUnit():
							for iProm in xrange(gc.getNumPromotionInfos()):
								if infoUnit.getFreePromotions(iProm):
									infoProm = gc.getPromotionInfo(iProm)
									if infoProm.isRace():
										break
