	for loopCity in lCities:
		newUnit = pPlayer.initUnit(iUnit, loopCity.getX(), loopCity.getY(), UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
		loopCity.applyBuildEffects(newUnit)
