def reqEquipGolem(pCaster, eSpell=-1):
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	pPlot = pCaster.plot()
	lProms = []
	iGolem = gc.getInfoTypeForString('PROMOTION_GOLEM')
	pCity = -1
	if pPlot.isCity():
		pCity = pPlot.getPlotCity()
	else: 
		pCity = CyMap().findCity(pCaster.getX(), pCaster.getY(), pCaster.getOwner(), TeamTypes.NO_TEAM, False, False, TeamTypes.NO_TEAM, DirectionTypes.NO_DIRECTION, pPlayer.getCity(-1))
	if not pCity.isNone():
		if pCity.getNumRealBuilding(gc.getInfoTypeForString('BUILDING_ADULARIA_CHAMBER')) > 0:
			lProms.append(gc.getInfoTypeForString('PROMOTION_STEALTH'))
			lProms.append(gc.getInfoTypeForString('PROMOTION_HIDDEN'))
		if pCity.getNumRealBuilding(gc.getInfoTypeForString('BUILDING_BLASTING_WORKSHOP')) > 0:
			lProms.append(gc.getInfoTypeForString('PROMOTION_FIRE2'))
##			if pCity.getNumRealBuilding(gc.getInfoTypeForString('BUILDING_DWARVEN_SMITHY')) > 0:
##				lProms.append(gc.getInfoTypeForString('PROMOTION_STRONG'))
		if pCity.getNumRealBuilding(gc.getInfoTypeForString('BUILDING_GOLEM_TRACKS')) > 0:
			lProms.append(gc.getInfoTypeForString('PROMOTION_MOBILITY2'))
		if pCity.getNumRealBuilding(gc.getInfoTypeForString('BUILDING_PALLENS_ENGINE')) > 0:
			lProms.append(gc.getInfoTypeForString('PROMOTION_PERFECT_SIGHT'))
		if pCity.getNumRealBuilding(gc.getInfoTypeForString('BUILDING_TOWER_OF_ALTERATION')) > 0:
			lProms.append(gc.getInfoTypeForString('PROMOTION_STRONG'))

	for i in xrange(pPlot.getNumUnits()):
		pUnit = pPlot.getUnit(i)
		iRace = pUnit.getRace()
		if iRace == iGolem:
			for iProm in lProms:
				if not pUnit.isHasPromotion(iProm):
					return True
			infoUnit = gc.getUnitInfo(pUnit.getUnitType())
			for iProm in xrange(gc.getNumPromotionInfos()):
				infoProm = gc.getPromotionInfo(iProm)
				if infoProm.isRace() or infoProm.isEquipment():continue
				if infoUnit.getFreePromotions(iProm):
					if not pUnit.isHasPromotion(iProm):
						return True

	return False
	
	
