def reqReveal(pCaster, eSpell=-1):
	if pCaster.isIgnoreHide():
		return False
	pPlot = pCaster.plot()
	if pPlot.getOwner() != pCaster.getOwner():
		return False
	return True

def spellReveal(pCaster, eSpell=-1):
	pCaster.setIgnoreHide(True)

	pPlot = pCaster.plot()
	iPlayer = pCaster.getOwner()
	if pPlot.getOwner != pCaster.getOwner():
		if not pPlot.isVisibleEnemyUnit(iPlayer):
			if pPlot.isCity():
				if pPlot.isEnemyCity(pCaster):
					pPlot.setOwner(iPlayer)
			elif gc.getGame().isOption(GameOptionTypes.GAMEOPTION_ADVANCED_TACTICS):
				iImprovement = pPlot.getImprovementType()
				if gc.getImprovementInfo(iImprovement).isActsAsCity():
					if pPlot.isOwned():
						if gc.getTeam(pCaster.getTeam()).isAtWar(pPlot.getTeam()):
							pPlot.setOwner(iPlayer)
					else:
						pPlot.setOwner(iPlayer)

def reqRevelry(pCaster, eSpell=-1):
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	if pPlayer.isGoldenAge():
		return False
	if not pPlayer.isHuman():
#		if pPlayer.getTotalPopulation() < 25:
		map = gc.getMap()
		if pPlayer.getNumCities() < gc.getWorldInfo(map.getWorldSize()).getTargetNumCities():
			return False
	return True

def spellRevelry(pCaster, eSpell=-1):
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	pPlayer.changeGoldenAgeTurns(CyGame().goldenAgeLength() * 2)

def reqRevelation(pCaster, eSpell=-1):
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iTeam = pPlayer.getTeam()
	iSluagh = gc.getInfoTypeForString('UNIT_SLUAGH')
	iShadowrider = gc.getInfoTypeForString('UNIT_SHADOWRIDER')
	iIllusion = gc.getInfoTypeForString('PROMOTION_ILLUSION')
	iReflection = gc.getInfoTypeForString('PROMOTION_DARK_REFLECTION')
	iChangeling = gc.getInfoTypeForString('PROMOTION_CHANGELING')
	iVamp = gc.getInfoTypeForString('PROMOTION_VAMPIRE')
	iHiddenNationality = gc.getInfoTypeForString('PROMOTION_HIDDEN_NATIONALITY')
	iHidden = gc.getInfoTypeForString('PROMOTION_HIDDEN')
	iInvisible = gc.getInfoTypeForString('PROMOTION_INVISIBLE')
	iBlur = gc.getInfoTypeForString('PROMOTION_BLUR')
	iShadow = gc.getInfoTypeForString('PROMOTION_SHADOWWALK')
	iParanoid = gc.getInfoTypeForString('PROMOTION_PARANOID')
	iCharmed = gc.getInfoTypeForString('PROMOTION_CHARMED')
	iBlind = gc.getInfoTypeForString('PROMOTION_BLIND')
	iCalabim = gc.getInfoTypeForString('CIVILIZATION_CALABIM')
	iSidar = gc.getInfoTypeForString('CIVILIZATION_SIDAR')
	iEmp = gc.getInfoTypeForString('RELIGION_THE_EMPYREAN')
	lEsusPriests = [ gc.getInfoTypeForString('UNIT_PRIEST_ESUS'), gc.getInfoTypeForString('UNIT_HIGH_PRIEST_ESUS')]
	iWhisperingWood = gc.getInfoTypeForString('IMPROVEMENT_WHISPERING_WOOD')
	pPlot = pCaster.plot()
	iRange = 3
	if pPlot.getImprovementType() in [gc.getInfoTypeForString('IMPROVEMENT_MIRROR_OF_HEAVEN'), gc.getInfoTypeForString('IMPROVEMENT_CITADEL_OF_LIGHT')]:
		iRange += 1
	iX = pCaster.getX()
	iY = pCaster.getY()
	for iiX in xrange(iX-iRange, iX + iRange+1, 1):
		for iiY in xrange(iY-iRange, iY+ iRange+1, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			# if pPlot.at(iX, iY):continue
			if plotDistance(iX, iY, iiX, iiY) > iRange:continue
			
			if plotDistance(iX, iY, iiX, iiY) > iRange:continue
			if not pPlot.isRevealed(iTeam, False):
				return True
			if pPlot.getImprovementType() == iWhisperingWood:
				if pPlot.isPythonActive():
					return True
			for iUnit in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(iUnit)
				if pUnit.isImmuneToMagic():continue
				if pUnit.getUnitType() == iSluagh:continue
				if pUnit.getUnitType() == iShadowrider:
					return True
				if pUnit.isHasPromotion(iVamp):
					return True
				elif pUnit.getUnitType() in lEsusPriests:
					return True
				elif pUnit.isHasPromotion(iParanoid):
					return True
				if pUnit.getTeam() == iTeam:
					if pUnit.isHasPromotion(iBlind):
						return True
				else:
					for iProm in [iHidden, iHiddenNationality, iInvisible, iIllusion, iReflection, iBlur, iShadow]:
						if pUnit.isHasPromotion(iProm):
							return True
					if pUnit.isHasPromotion(iChangeling):
						if reqAssumeTrueForm(pUnit, 'SPELL_ASSUME_TRUE_FORM'):
							return True
					else:
						iCiv = pUnit.getCivilizationType()
						if iCiv == iCalabim:
							if pUnit.getReligion() == iEmp:
								return True
						elif iCiv == iSidar:
							if not pUnit.isIgnoreHide():
								if pUnit.getOwner() == pPlot.getOwner():
									return True
					if pUnit.isAlive():
						if pUnit.getSummoner() != -1:
							pPlayerV = gc.getPlayer(pUnit.getOwner())
							pSire = pPlayerV.getUnit(pUnit.getSummoner())
							if pSire.isHasPromotion(iVamp):
								return True
	return False

