def reqSmokelessFire(pCaster, eSpell):
	iNumIfrit = 0
	iIfritClass = gc.getInfoTypeForString('UNITCLASS_IFRIT')
	for iLoopPlayer in xrange(gc.getMAX_PLAYERS()):
		pLoopPlayer = gc.getPlayer(iLoopPlayer)
		iNumIfrit += pLoopPlayer.getUnitClassCount(iIfritClass)
		if iNumIfrit > 6:
			return False

	if pCaster.isHuman():
		return True
	else:
		iTeam = pCaster.getTeam()
		eTeam = gc.getTeam(iTeam)
		if eTeam.getAtWarCount(True) > 0:
			iRange = 1
			iX = pCaster.getX()
			iY = pCaster.getY()
			for iiX in xrange(iX-iRange, iX + iRange+1, 1):
				for iiY in xrange(iY-iRange, iY+ iRange+1, 1):
					pPlot = CyMap().plot(iiX, iiY)
					if pPlot.isNone():continue
					# if pPlot.at(iX, iY):continue
					if plotDistance(iX, iY, iiX, iiY) > iRange:continue
					
					if pPlot.getNumVisibleEnemyDefenders(pCaster) > 5:
						return True
	return False

def miscastSmokelessFire(pCaster, eSpell):
	if pCaster.canCast(gc.getInfoTypeForString('SPELL_BLAZE'), False):
		pCaster.cast(gc.getInfoTypeForString('SPELL_BLAZE'))
	pCaster.doDamageNoCaster(50, 100, gc.getInfoTypeForString('DAMAGE_PSYCHIC'), False)
	pCaster.doDamageNoCaster(100, 200, gc.getInfoTypeForString('DAMAGE_FIRE'), False)

def spellMonopolize(pCaster, eSpell=-1):
	pPlot = pCaster.plot()
#	pCaster.setHasCasted(False)#the game won't let a unit conduct a trade mission after casting, and bHasCast seems to setHasCasted(True) before calling its PyResult, so without this iGold =0
#	iGold = pCaster.getTradeGold(pPlot)
	if pPlot.isCity():
		pCity = pPlot.getPlotCity()
		iPlayer = pCaster.getOwner()
		iPlayer2 = pCity.getOwner()
		pPlayer = gc.getPlayer(iPlayer)
		pPlayer2 = gc.getPlayer(iPlayer2)
		pCapital = pPlayer.getCapitalCity()
		if pCapital != -1:
			iBaseTrade = 50
			iTradeMultiplier = 100
			iGold = iBaseTrade + iTradeMultiplier * pCity.calculateTradeProfit(pCapital)
			iGold *= gc.getGameSpeedInfo(CyGame().getGameSpeedType()).getUnitTradePercent()
			iGold /= 100;
			iGold = max(0, iGold)
			iGold = min(iGold,pPlayer2.getGold())
	if iGold > 0:
		pPlayer = gc.getPlayer(iPlayer)
		pPlayer.changeGold(iGold)
		if pPlot.isOwned():
			iPlayer2 = pPlot.getOwner()
			pPlayer2 = gc.getPlayer(iPlayer2)
			pPlayer2.changeGold(-iGold)
##			if not isWorldUnitClass(pCaster.getUnitClassType()):
	##			pCaster.kill(False, PlayerTypes.NO_PLAYER)

