def reqScorch(pCaster, eSpell=-1):
	if reqSunAllowed(pCaster, eSpell):
		pPlot = pCaster.plot()
		iPlayer = pCaster.getOwner()
		pPlayer = gc.getPlayer(iPlayer)
		iFeature = pPlot.getFeatureType()
		if iFeature == gc.getInfoTypeForString('FEATURE_ICE'):
			return True
		elif iFeature == gc.getInfoTypeForString('FEATURE_BLIZZARD'):
			if pPlayer.getStateReligion() != gc.getInfoTypeForString('RELIGION_WHITE_HAND'):
				return True
		iTerrain = pPlot.getTerrainType()
		if iTerrain in [gc.getInfoTypeForString('TERRAIN_PLAINS'), gc.getInfoTypeForString('TERRAIN_FIELDS_OF_PERDITION'), gc.getInfoTypeForString('TERRAIN_MARSH')]:
			if not pPlayer.isHuman():
				if pCaster.getTeam() == pPlot.getTeam():
					return False
			return True
		elif iTerrain in [gc.getInfoTypeForString('TERRAIN_SNOW'), gc.getInfoTypeForString('TERRAIN_GLACIER')]:
			if not pPlayer.isHuman():
				if pCaster.getOwner() != pPlot.getOwner():
					return False
				if pPlayer.getCivilizationType() in [gc.getInfoTypeForString('CIVILIZATION_DOVIELLO'), gc.getInfoTypeForString('CIVILIZATION_ILLIANS')]:
					return False
			return True
		if iTerrain == gc.getInfoTypeForString('TERRAIN_MARSH'):
			if not pPlayer.isHuman():
				if pCaster.getTeam() != pPlot.getTeam():
					return False
			return True
	return False

def helpScorch(lpUnits, eSpell=-1):
	szBuffer = ''
	pCaster = lpUnits[0]
	pPlot = pCaster.plot()
	iFeature = pPlot.getFeatureType()
	iTerrain = pPlot.getTerrainType()
	if iFeature in [gc.getInfoTypeForString('FEATURE_ICE'), gc.getInfoTypeForString('FEATURE_BLIZZARD')]:
		sFeature = gc.getFeatureInfo(iFeature).getDescription()
		szBuffer += localText.getText("TXT_KEY_HELP_SPELL_REMOVES_STUFF", (sFeature, ))
	iTerrainNew = -1
	if iTerrain == gc.getInfoTypeForString('TERRAIN_PLAINS'):
		iTerrainNew = gc.getInfoTypeForString('TERRAIN_DESERT')
	elif iTerrain == gc.getInfoTypeForString('TERRAIN_FIELDS_OF_PERDITION'):
		iTerrainNew = gc.getInfoTypeForString('TERRAIN_BURNING_SANDS')
	elif iTerrain == gc.getInfoTypeForString('TERRAIN_SNOW'):
		iTerrainNew = gc.getInfoTypeForString('TERRAIN_TUNDRA')
	elif iTerrain == gc.getInfoTypeForString('TERRAIN_GLACIER'):
		iTerrainNew = gc.getInfoTypeForString('TERRAIN_WASTELAND')
	elif iTerrain == gc.getInfoTypeForString('TERRAIN_MARSH'):
		iTerrainNew = gc.getInfoTypeForString('TERRAIN_PLAINS')
	if iTerrainNew != -1:
		sTerrain = gc.getTerrainInfo(iTerrain).getDescription()
		sTerrainNew = gc.getTerrainInfo(iTerrainNew).getDescription()
		szBuffer += localText.getText("TXT_KEY_HELP_SPELL_CHANGE_A_TO_B", (sTerrain, sTerrainNew, ))
	if pPlot.isOwned():
		iTeamC = pCaster.getTeam()
