def spellScorch(pCaster, eSpell=-1):
	pPlot = pCaster.plot()
	iFeature = pPlot.getFeatureType()
	iTerrain = pPlot.getTerrainType()
	iTimerTerrain = pPlot.getTempTerrainTimer()
	iRealTerrain = pPlot.getRealTerrainType()
	iTimerFeature = pPlot.getTempFeatureTimer()
	iRealFeature = pPlot.getRealFeatureType()
	iRealFeatureVariety = pPlot.getRealFeatureVariety()
	if iFeature == gc.getInfoTypeForString('FEATURE_ICE'):
		pPlot.setFeatureType(-1, -1)
##		CyMap().calculateCanalAndChokePoints()#This may be needed for the AI in the future, but has not been exposed to python yet
	elif iFeature == gc.getInfoTypeForString('FEATURE_BLIZZARD'):
		pPlot.setFeatureType(-1, -1)
	if iTerrain == gc.getInfoTypeForString('TERRAIN_PLAINS'):
		pPlot.setTerrainType(gc.getInfoTypeForString('TERRAIN_DESERT'), True, True)
	elif iTerrain == gc.getInfoTypeForString('TERRAIN_FIELDS_OF_PERDITION'):
		pPlot.setTerrainType(gc.getInfoTypeForString('TERRAIN_BURNING_SANDS'), True, True)
	elif iTerrain == gc.getInfoTypeForString('TERRAIN_SNOW'):
		pPlot.setTerrainType(gc.getInfoTypeForString('TERRAIN_TUNDRA'), True, True)
	elif iTerrain == gc.getInfoTypeForString('TERRAIN_GLACIER'):
		pPlot.setTerrainType(gc.getInfoTypeForString('TERRAIN_WASTELAND'), True, True)
	elif iTerrain == gc.getInfoTypeForString('TERRAIN_MARSH'):
		pPlot.setTerrainType(gc.getInfoTypeForString('TERRAIN_PLAINS'), True, True)
	if pPlot.isOwned():
		if pCaster.getTeam() != pPlot.getTeam():
			cf.startWar(pCaster.getOwner(), pPlot.getOwner(), WarPlanTypes.WARPLAN_TOTAL)

#Tholal made pPlot.setTerrainType() reset the timer and real types, but I would rather not
	if iTimerFeature > 0:
		pPlot.setRealFeatureType(iRealFeature)
		pPlot.setRealFeatureVariety(iRealFeatureVariety)
		pPlot.changeTempFeatureTimer(iTimerFeature)
		if iRealFeature == gc.getInfoTypeForString('FEATURE_ICE'):
			pPlot.setRealFeatureType(-1)
			pPlot.getRealFeatureVariety(-1)
	##		CyMap().calculateCanalAndChokePoints()#This may be needed for the AI in the future, but has not been exposed to python yet
		elif iRealFeature == gc.getInfoTypeForString('FEATURE_BLIZZARD'):
			pPlot.setRealFeatureType(-1)
			pPlot.getRealFeatureVariety(-1)
	if iTimerTerrain > 0:
		pPlot.setRealTerrainType(iRealTerrain)
		pPlot.changeTempTerrainTimer(iTimerTerrain)
		if iRealTerrain == gc.getInfoTypeForString('TERRAIN_PLAINS'):
			pPlot.setRealTerrainType(gc.getInfoTypeForString('TERRAIN_DESERT'))
		elif iRealTerrain == gc.getInfoTypeForString('TERRAIN_FIELDS_OF_PERDITION'):
			pPlot.setRealTerrainType(gc.getInfoTypeForString('TERRAIN_BURNING_SANDS'))
		elif iRealTerrain == gc.getInfoTypeForString('TERRAIN_SNOW'):
			pPlot.setRealTerrainType(gc.getInfoTypeForString('TERRAIN_TUNDRA'))
		elif iRealTerrain == gc.getInfoTypeForString('TERRAIN_GLACIER'):
			pPlot.setRealTerrainType(gc.getInfoTypeForString('TERRAIN_WASTELAND'))
		elif iRealTerrain == gc.getInfoTypeForString('TERRAIN_MARSH'):
			pPlot.setRealTerrainType(gc.getInfoTypeForString('TERRAIN_PLAINS'))

