def spellServileRevolt(pCaster, eSpell):

	pCity = findAdjacentCity(pCaster)
	if pCity:
		iPlayer = pCity.getOwner()
		pPlayer = gc.getPlayer(iPlayer)
		if pPlayer.isCivic(gc.getInfoTypeForString('CIVIC_SLAVERY')):
			pCity.changeOccupationTimer(1)


	iSlave = gc.getInfoTypeForString('UNIT_SLAVE')
	iRel = gc.getInfoTypeForString('RELIGION_COVEN')
	iD = gc.getInfoTypeForString('PROMOTION_DIVINE')


	iR = gc.getInfoTypeForString('PROMOTION_REBEL')
	iL = gc.getInfoTypeForString('PROMOTION_LOYALTY')

	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iTeam = pCaster.getTeam()
	eTeam = gc.getTeam(iTeam)
	iX = pCaster.getX()
	iY = pCaster.getY()
	for iiX in xrange(iX-1, iX+ 2, 1):
		for iiY in xrange(iY-1, iY+ 2, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if pCaster is pUnit:
					continue
				if pCaster.getID() == pUnit.getID():
					continue
				if pUnit.isAlive():
					iPlayerUnit = pUnit.getOwner()
					pPlayerUnit = gc.getPlayer(iPlayerUnit)
					if pUnit.getUnitType() == iSlave:

						if not effectResisted(pUnit, pCaster, eSpell):
							if eTeam.isAtWar(pUnit.getTeam()):
								sName = cf.getNameWithColorScheme(pUnit, pUnit.isInvisible(pCaster.getTeam(), False))
								CyInterface().addMessage(iPlayerUnit, True, 25, localText.getText("TXT_KEY_MESSAGE_DEFECT_RELIGION", (sName, )), '', InterfaceMessageTypes.MESSAGE_TYPE_INFO, pCaster.getButton(), gc.getInfoTypeForString('COLOR_RED'), iX, iY, True, True)
								CyInterface().addMessage(iPlayer, True, 25, localText.getText("TXT_KEY_MESSAGE_DEFECT_TO_RELIGION", (sName, pPlayerUnit.getName(), )), '', InterfaceMessageTypes.MESSAGE_TYPE_INFO, pCaster.getButton(), gc.getInfoTypeForString('COLOR_GREEN'), iX, iY, True, True)

								pCity = CyMap().findCity(iX, iY, pUnit.getOwner(), TeamTypes.NO_TEAM, False, False, TeamTypes.NO_TEAM, DirectionTypes.NO_DIRECTION, pPlayer.getCity(-1))
								if not pCity.isNone():
									iUnit =pCity.getConscriptUnit()
									if iUnit != -1:
										newUnit = pPlayer.initUnit(pUnit.getUnitType(), iX, iY, UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
										newUnit.convert(pUnit)

										newUnit.setReligion(iRel)
							else:
								pUnit.setHasPromotion(iR, True)




def reqServileRevolt(pCaster, eSpell):

	iR = gc.getInfoTypeForString('PROMOTION_REBEL')
	iSlave = gc.getInfoTypeForString('UNIT_SLAVE')

	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iX = pCaster.getX()
	iY = pCaster.getY()

	if pCaster.getUnitType() == iSlave:
		CyInterface().addMessage(iPlayer,True,25,localText.getText("TXT_KEY_MESSAGE_SLAVE_REVOLT", ()),'',1,'Art/Interface/Buttons/Units/Slave.dds',ColorTypes(8),iX,iY,True,True)
		bPlayer = gc.getPlayer(gc.getBARBARIAN_PLAYER())
		iUnit = gc.getInfoTypeForString('UNIT_WARRIOR')
		pCity = CyMap().findCity(iX, iY, pUnit.getOwner(), TeamTypes.NO_TEAM, False, False, TeamTypes.NO_TEAM, DirectionTypes.NO_DIRECTION, pPlayer.getCity(-1))
		if not pCity.isNone():
			iUnit = pCity.getConscriptUnit()
			if iUnit == -1:
				iUnit = gc.getInfoTypeForString('UNIT_WARRIOR')
		pNewUnit = bPlayer.initUnit(iUnit, iX, iY, UnitAITypes.UNITAI_ATTACK_CITY_LEMMING, DirectionTypes.DIRECTION_SOUTH)
		pNewUnit.convert(pUnit)
		pNewUnit.setHasPromotion(iR, True)
		return False
	elif pPlayer.isCivic(gc.getInfoTypeForString('CIVIC_SLAVERY')):
		pCaster.setHasPromotion(iR, True)
		return False
	else:
		iTeam = pCaster.getTeam()
		eTeam = gc.getTeam(iTeam)
		for iiX in xrange(iX-1, iX+ 2, 1):
			for iiY in xrange(iY-1, iY+ 2, 1):
				pPlot = CyMap().plot(iiX, iiY)
				if pPlot.isNone():continue
				for i in xrange(pPlot.getNumUnits()):
					pUnit = pPlot.getUnit(i)
					if pUnit.getUnitType() != iSlave:continue
					if pUnit.isImmuneToSpell(pCaster, eSpell):continue
					if pUnit.getTeam() == iTeam:continue
					if pUnit.isImmuneToMagic():continue
					if gc.getTeam(pUnit.getTeam()).isVassal(iTeam):continue
					if eTeam.isAtWar(pUnit.getTeam()) or pCaster.isHiddenNationality() or pUnit.isHiddenNationality():
						return True
		pCity = findAdjacentCity(pCaster)
		if pCity:
			iPlayer = pCity.getOwner()
			pPlayer = gc.getPlayer(iPlayer)
			if pPlayer.isCivic(gc.getInfoTypeForString('CIVIC_SLAVERY')):
				return True
	return False

