def reqChangelingInfiltration(pCaster, eSpell=-1):
	if reqShadowAllowed(pCaster, eSpell):
		iX = pCaster.getX()
		iY = pCaster.getY()
		iResistMax = 95

		iTeam = pCaster.getTeam()
		eTeam = gc.getTeam(iTeam)
		for iiX in xrange(iX-1, iX+ 2, 1):
			for iiY in xrange(iY-1, iY+ 2, 1):
				pPlot = CyMap().plot(iiX, iiY)
				if pPlot.isNone():continue
				for i in xrange(pPlot.getNumUnits()):
					pUnit = pPlot.getUnit(i)
					if pUnit.isImmuneToSpell(pCaster, eSpell):continue
					if pUnit.isHasPromotion(gc.getInfoTypeForString('PROMOTION_MASK_OF_ESUS')):continue
					if pUnit.isDelayedDeath():continue
					if pUnit.getTeam() == iTeam:
						continue
					if pUnit.isOnlyDefensive():
						continue
					if not pUnit.isAlive():
						continue
					if pUnit.isImmuneToMagic():
						continue
					if pUnit.isAvatarOfCivLeader():
						continue
					if isLimitedUnitClass(pUnit.getUnitClassType()):
						continue
					iUnit = pUnit.getUnitType()
					info = gc.getUnitInfo(iUnit)
					if info.isAbandon():#It would be wasteful to change into a unit that would promptly abandon you
						continue
					if info.isObject():#Should not duplicate equipment
						continue

					iResist = pUnit.getResistChance(pCaster, gc.getInfoTypeForString('SPELL_SUMMON_CHANGELING'))
					if iResist < iResistMax:
						return True
	return False

def spellChangelingInfiltration(pCaster, eSpell=1):
	newUnit = -1
	iLairGuardian = gc.getInfoTypeForString('PROMOTION_LAIR_GUARDIAN')
	iX = pCaster.getX()
	iY = pCaster.getY()
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iResistMax = 95
	iBestValue = 0
	pBestUnit = -1

	iTeam = pCaster.getTeam()
	eTeam = gc.getTeam(iTeam)

	lTargets = []
	for iiX in xrange(iX-1, iX+ 2, 1):
		for iiY in xrange(iY-1, iY+ 2, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if pUnit.isAlive():
					if pUnit.isDelayedDeath():continue
					if pUnit.isImmuneToSpell(pCaster, eSpell):continue
					if pUnit.isHasPromotion(gc.getInfoTypeForString('PROMOTION_MASK_OF_ESUS')):continue
					if pUnit.getTeam() == iTeam:
						continue
					if pUnit.isOnlyDefensive():
						continue
					if not pUnit.isAlive():
						continue
					if pUnit.isImmuneToMagic():
						continue
					if pUnit.isAvatarOfCivLeader():
						continue
					if isLimitedUnitClass(pUnit.getUnitClassType()):
						continue
					iUnit = pUnit.getUnitType()
					info = gc.getUnitInfo(iUnit)
					if info.isAbandon():#It would be wasteful to change into a unit that would promptly abandon you
						continue
					if info.isObject():#Should not duplicate equipment
						continue

					lTargets.append(pUnit)
	for loopUnit in lTargets:
		iValue = 0
		iResist = loopUnit.getResistChance(pCaster, eSpell)
		if iResist < iResistMax:
			iValue = loopUnit.baseCombatStr() * 10
			iValue += (100 - iResist)
			if iValue > iBestValue:
				iBestValue = iValue
				pBestUnit = loopUnit
				lTargets.remove(loopUnit)

	if pBestUnit != -1:
		pPlot = pCaster.plot()
		while pBestUnit.isResisted(pCaster, eSpell) and len(lTargets) > 0 :

			for loopUnit in lTargets:
				iValue = 0
				iResist = loopUnit.getResistChance(pCaster, eSpell)
				if iResist < iResistMax:
					iValue = loopUnit.baseCombatStr() * 10
					iValue += (100 - iResist)
					if iValue > iBestValue:
						iBestValue = iValue
						pBestUnit = loopUnit
						lTargets.remove(loopUnit)

		pPlayerU = gc.getPlayer(pBestUnit.getOwner())
		sName = cf.getNameWithColorScheme(pBestUnit)

		CyInterface().addMessage(pBestUnit.getOwner(), True, 25, localText.getText("TXT_KEY_MESSAGE_CHANGELING_REPLACED", (sName, )), '', 1, 'Art/Interface/Buttons/Spells/Domination.dds', ColorTypes(7), pBestUnit.getX(), pBestUnit.getY(), True, True)
		CyInterface().addMessage(pCaster.getOwner(), True, 25, localText.getText("TXT_KEY_MESSAGE_CHANGELING_REPLACED", (sName, )), '', 1, 'Art/Interface/Buttons/Spells/Domination.dds', ColorTypes(8), pPlot.getX(), pPlot.getY(), True, True)
		newUnit = pPlayer.initUnit(pBestUnit.getUnitType(), pPlot.getX(), pPlot.getY(), UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
		cf.removeAffinities(newUnit)
		newUnit.convert(pBestUnit)

		newUnit.setHasPromotion(iLairGuardian, False)
		newUnit.setSummoner(pCaster.getID())
		newUnit.setScenarioCounter(gc.getInfoTypeForString('UNIT_CHANGELING'))
		newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_CHANGELING'), True)
		newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_HIDDEN_NATIONALITY'), True)

def helpChangelingInfiltration(lpUnits, eSpell=-1):
	szBuffer = helpShowSummonDetails(lpUnits, eSpell) + helpManaBlocked(lpUnits, 'VOTE_NO_SHADOW_MANA')
	pCaster = lpUnits[0]
	lTargets= []
	iLairGuardian = gc.getInfoTypeForString('PROMOTION_LAIR_GUARDIAN')
	iX = pCaster.getX()
	iY = pCaster.getY()
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iResistMax = 95
	iBestValue = 0
	pBestUnit = -1

	iTeam = pCaster.getTeam()
	eTeam = gc.getTeam(iTeam)
	for iiX in xrange(iX-1, iX+ 2, 1):
		for iiY in xrange(iY-1, iY+ 2, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				iValue = 0
				if pUnit.isAlive():
					if pUnit.isDelayedDeath():continue
					if pUnit.isImmuneToSpell(pCaster, eSpell):continue
					if pUnit.isHasPromotion(gc.getInfoTypeForString('PROMOTION_MASK_OF_ESUS')):continue
					# if pUnit.isInvisible(iTeam, False):continue
					if pUnit.getTeam() == iTeam:
						continue
					if pUnit.isOnlyDefensive():
						continue
					if not pUnit.isAlive():
						continue
					if pUnit.isImmuneToMagic():
						continue
					if pUnit.isAvatarOfCivLeader():
						continue
					if isLimitedUnitClass(pUnit.getUnitClassType()):
						continue
					iUnit = pUnit.getUnitType()
					info = gc.getUnitInfo(iUnit)
					if info.isAbandon():#It would be wasteful to change into a unit that would promptly abandon you
						continue
					if info.isObject():#Should not duplicate equipment
						continue

					lTargets.append(pUnit)

	lTargets = list(set(lTargets))
	iCount = len(lTargets)
	if iCount > 0:
		szBuffer += localText.getText("TXT_KEY_HELP_SPELL_CONVERT", ())
		if iCount == 1:
			pUnit = lTargets.pop(0)
			pPlayer = gc.getPlayer(pUnit.getOwner())
			sList = cf.getNameWithColorScheme(pUnit, pUnit.isInvisible(pCaster.getTeam(), False))
			szBuffer += localText.getText("TXT_KEY_HELP_SPELL_TARGETS_THIS", ( sList, ))
		else:
			sList = ''
			while len(lTargets) > 0:
				pUnit = lTargets.pop(0)
				pPlayer = gc.getPlayer(pUnit.getOwner())
				sList += cf.getNameWithColorScheme(pUnit, pUnit.isInvisible(pCaster.getTeam(), False))
				if len(lTargets) > 0:
					if len(lTargets) == 1:
						sList += " and "
					else:
						sList += ", "
			szBuffer += localText.getText("TXT_KEY_HELP_SPELL_TARGETS_THESE_COUNT_LIST", (iCount, sList, ))


	lPerks = [gc.getInfoTypeForString('PROMOTION_CHANGELING'),gc.getInfoTypeForString('PROMOTION_HIDDEN_NATIONALITY')]
	iCount = len(lPerks)
	sList = ''
	while len(lPerks) > 0:
		sList += gc.getPromotionInfo(lPerks.pop(0)).getDescription()
		if len(lPerks) > 0:
			if len(lPerks) == 1:
				sList += " and "
			else:
				sList += ", "
	szBuffer += '\n' + localText.getText("TXT_KEY_UNIT_STARTS_WITH", ()) + sList


	return szBuffer



