def spellSellSoul(pCaster, eSpell=-1):
	lPromotions = []

	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iInfernal = gc.getInfoTypeForString('CIVILIZATION_INFERNAL')

	pPlot = pCaster.plot()
	iTeam = pCaster.getTeam()
	eTeam = gc.getTeam(iTeam)
	lPacts = [
				(gc.getInfoTypeForString('PROMOTION_PACT_WITH_HYBOREM'),gc.getInfoTypeForString('LEADER_HYBOREM'),gc.getInfoTypeForString('UNITCLASS_HYBOREM')),
				(gc.getInfoTypeForString('PROMOTION_PACT_WITH_JUDECCA'),gc.getInfoTypeForString('LEADER_JUDECCA'),gc.getInfoTypeForString('UNITCLASS_JUDECCA')),
				(gc.getInfoTypeForString('PROMOTION_PACT_WITH_LETHE'),gc.getInfoTypeForString('LEADER_LETHE'),gc.getInfoTypeForString('UNITCLASS_LETHE')),
				(gc.getInfoTypeForString('PROMOTION_PACT_WITH_MERESIN'),gc.getInfoTypeForString('LEADER_MERESIN'),gc.getInfoTypeForString('UNITCLASS_MERESIN')),
				(gc.getInfoTypeForString('PROMOTION_PACT_WITH_OUZZA'),gc.getInfoTypeForString('LEADER_OUZZA'),gc.getInfoTypeForString('UNITCLASS_OUZZA')),
				(gc.getInfoTypeForString('PROMOTION_PACT_WITH_SALLOS'),gc.getInfoTypeForString('LEADER_SALLOS'),gc.getInfoTypeForString('UNITCLASS_SALLOS')),
				(gc.getInfoTypeForString('PROMOTION_PACT_WITH_STATIUS'),gc.getInfoTypeForString('LEADER_STATIUS'),gc.getInfoTypeForString('UNITCLASS_STATIUS'))
				]

	for iPact, iDemon, iAvatar in lPacts:
		if pCaster.isHasPromotion(iPact):
			return False
		elif pCaster.isPromotionImmune(iPact):
			continue
		elif pPlayer.getCivilizationType() == iInfernal:
			continue
		elif pPlot.isOwned():
			pPlayerPlot = gc.getPlayer(pPlot.getOwner())
			if pPlayerPlot.getCivilizationType() == iInfernal:
				if pPlayerPlot.getLeaderType() != iDemon:
					continue

		if not CyGame().isLeaderEverActive(iDemon):
			continue
		iPactPlayer = cf.getLeader(iDemon)
		if iPactPlayer == -1:
			continue
		pPactPlayer = gc.getPlayer(iPactPlayer)
		if not pPactPlayer.isAlive():
			continue

		if eTeam.isAtWar(pPactPlayer.getTeam()):
			continue
		if pPactPlayer.getUnitClassCount(iAvatar) < 1:
			continue
		lPromotions.append(iPact)
	if len(lPromotions) > 0:
		iProm = lPromotions.pop(CyGame().getSorenRandNum(len(lPromotions), "Sell Soul"))

		pCaster.setHasPromotion(iProm, True)
		em.onUnitPromoted([pCaster, iProm])

