def reqSironasTouch(pCaster, eSpell=-1):
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)


	if not pPlayer.isFeatAccomplished(FeatTypes.FEAT_HEAL_UNIT_PER_TURN):
		return False
	if pCaster.getDamage() > 0:
		if not pCaster.isHuman():
			if pCaster.getDamage() < 15:
				return False
		return True
	for sProm in ['PROMOTION_DISEASED', 'PROMOTION_PLAGUED', 'PROMOTION_POISONED', 'PROMOTION_WITHERED', 'PROMOTION_ENRAGED','PROMOTION_BURNING_BLOOD','PROMOTION_PARANOID']:
		if pCaster.isHasPromotion(gc.getInfoTypeForString(sProm)):
			return True
	return False

def spellSironasTouch(pCaster, eSpell=-1):
	iAmount = 10
	if pCaster.getReligion() == gc.getInfoTypeForString('RELIGION_BROTHERHOOD_OF_WARDENS'):
		iAmount = 25
	pCaster.changeDamage(-iAmount, PlayerTypes.NO_PLAYER)

	for sProm in ['PROMOTION_DISEASED', 'PROMOTION_PLAGUED', 'PROMOTION_POISONED', 'PROMOTION_WITHERED', 'PROMOTION_ENRAGED','PROMOTION_BURNING_BLOOD','PROMOTION_PARANOID']:
		pCaster.setHasPromotion(gc.getInfoTypeForString(sProm), False)
	iTeam = pCaster.getTeam()
	eTeam = gc.getTeam(iTeam)
	if eTeam.getNumMembers() > 1:
		for iPlayer2 in xrange(gc.getMAX_PLAYERS()):
			pPlayer2 = gc.getPlayer(iPlayer2)
			if pPlayer2.isAlive():
				if pPlayer2.getTeam() == iTeam:
					pPlayer2.setFeatAccomplished(FeatTypes.FEAT_HEAL_UNIT_PER_TURN, False)
	else:
		gc.getPlayer(pCaster.getOwner()).setFeatAccomplished(FeatTypes.FEAT_HEAL_UNIT_PER_TURN, False)


def helpSironasTouch(lpUnits, eSpell=-1):
	szBuffer = ''
	for pCaster in lpUnits:
		if pCaster.canCast(eSpell, True):
			iAmount = 10
			if pCaster.getReligion() == gc.getInfoTypeForString('RELIGION_BROTHERHOOD_OF_WARDENS'):
				iAmount = 25
			iHeal = min(pCaster.getDamage(), iAmount)
			if iHeal > 0:
				szBuffer += localText.getText("TXT_KEY_SPELL_HELP_HEAL_SPECIFIC_UNIT", (pCaster.getName(), iHeal,))
	szBuffer += helpTogglePromotionsBuffCaster(lpUnits, eSpell, [], ['PROMOTION_DISEASED', 'PROMOTION_PLAGUED', 'PROMOTION_POISONED', 'PROMOTION_WITHERED', 'PROMOTION_ENRAGED','PROMOTION_BURNING_BLOOD','PROMOTION_PARANOID'], False)
	return szBuffer

