def iterNeighborSmokeOrFlamePlots( pPlot ) :
	# type: (CyPlot) -> Iterator[CyPlot]
	for pPlot2 in PyHelpers.PyPlot( pPlot ).iterThisAndNeighborPlots() :
		if ( pPlot2.getFeatureType() == gc.getInfoTypeForString('FEATURE_FLAMES')
				or pPlot2.getImprovementType() == gc.getInfoTypeForString('IMPROVEMENT_SMOKE') ) :
			yield pPlot2

def reqSpring(pCaster, eSpell=-1):
	if not pCaster.isHuman():
		if pCaster.getCivilizationType() == gc.getInfoTypeForString('CIVILIZATION_INFERNAL'):
			return False
	pPlot = pCaster.plot()
	if pPlot.getTerrainType() == gc.getInfoTypeForString('TERRAIN_DESERT'):
		if pPlot.getFeatureType() not in [gc.getInfoTypeForString('FEATURE_FLOOD_PLAINS'), gc.getInfoTypeForString('FEATURE_OASIS')]:
			if pCaster.isHuman():
				return True
			if pCaster.getOwner() == pPlot.getOwner():
				return True
	iFlames = gc.getInfoTypeForString('FEATURE_FLAMES')
	iSmoke = gc.getInfoTypeForString('IMPROVEMENT_SMOKE')
	iX = pPlot.getX()
	iY = pPlot.getY()
	for iiX in xrange(iX-1, iX+ 2, 1):
		for iiY in xrange(iY-1, iY+ 2, 1):
			pPlot2 = CyMap().plot(iiX, iiY)
			if pPlot2.isNone():
				continue
			if pPlot2.getFeatureType() == iFlames:
				return True
			if pPlot2.getImprovementType() == iSmoke:
				return True
	return False

def miscastDie(pCaster, eSpell=-1):
	pCaster.kill(True, -1)

def miscastSpring(pCaster, eSpell=-1):
	iDamage = CyGame().getSorenRandNum(100, "Miscast Spring")
	if iDamage > 10:
		iCold = gc.getInfoTypeForString('DAMAGE_COLD')
		pCaster.doDamage(iDamage, 50, pCaster, iCold, True)
		if iDamage > 70:
			if reqTsunami(pCaster, eSpell):
				spellTsunami(pCaster, eSpell)

def spellSpring(pCaster, eSpell=-1):
	pPlot = pCaster.plot()

	iFeature = pPlot.getFeatureType()
	iTerrain = pPlot.getTerrainType()

	iTimerTerrain = pPlot.getTempTerrainTimer()
	iRealTerrain = pPlot.getRealTerrainType()

	iTimerFeature = pPlot.getTempFeatureTimer()
	iRealFeature = pPlot.getRealFeatureType()
	iRealFeatureVariety = pPlot.getRealFeatureVariety()

	if iTerrain == gc.getInfoTypeForString('TERRAIN_DESERT') and iFeature not in [gc.getInfoTypeForString('FEATURE_OASIS'), gc.getInfoTypeForString('FEATURE_FLOOD_PLAINS')]:
		pPlot.setTerrainType(gc.getInfoTypeForString('TERRAIN_PLAINS'), True, True)
		if iFeature == gc.getInfoTypeForString('FEATURE_SCRUB'):
			pPlot.setFeatureType(-1, -1)
	iX = pPlot.getX()
	iY = pPlot.getY()
	for iiX in xrange(iX-1, iX+ 2, 1):
		for iiY in xrange(iY-1, iY+ 2, 1):
			pPlot2 = CyMap().plot(iiX, iiY)
			if pPlot2.isNone():continue
			if pPlot2.getFeatureType() == gc.getInfoTypeForString('FEATURE_FLAMES'):
				pPlot2.setFeatureType(-1, -1)
			if pPlot2.getImprovementType() == gc.getInfoTypeForString('IMPROVEMENT_SMOKE'):
				pPlot2.setImprovementType(-1)


#Tholal made pPlot.setTerrainType() reset the timer and real types, but I would rather not
	if iTimerTerrain > 0:
		pPlot.setRealTerrainType(iRealTerrain)
		pPlot.changeTempTerrainTimer(iTimerTerrain)

		pPlot.setRealFeatureType(iRealFeature)
		pPlot.setRealFeatureVariety(iRealFeatureVariety)
		pPlot.changeTempFeatureTimer(iTimerFeature)

		if iRealTerrain == gc.getInfoTypeForString('TERRAIN_DESERT') and iRealFeature not in [gc.getInfoTypeForString('FEATURE_OASIS'), gc.getInfoTypeForString('FEATURE_FLOOD_PLAINS')]:
			pPlot.setRealTerrainType(gc.getInfoTypeForString('TERRAIN_PLAINS'))
			if iTimerFeature > 0:
				if iRealFeature == gc.getInfoTypeForString('FEATURE_SCRUB'):
					pPlot.setRealFeatureType(-1)
					pPlot.setRealFeatureVariety(-1)


def helpSpringGreater(lpUnits, eSpell=-1):
	szBuffer = ''
	pCaster = lpUnits[0]
	pPlot = pCaster.plot()
	iFeature = pPlot.getFeatureType()
	iTerrain = pPlot.getTerrainType()
	iImprovement = pPlot.getImprovementType()
	iOasis = gc.getInfoTypeForString('FEATURE_OASIS')

	if pPlot.getTerrainType() == gc.getInfoTypeForString('TERRAIN_DESERT'):
		if not (pPlot.isFreshWater() or pPlot.isWater() or pPlot.isAdjacentToWater() or pPlot.isRiverSide()) and (pPlot.canHaveFeature(iOasis) or pPlot.getFeatureType() == gc.getInfoTypeForString('FEATURE_SCRUB')):
			szBuffer += localText.getText("TXT_KEY_HELP_SPELL_ADDS", ( )) + CyGameTextMgr().getFeatureHelp(iOasis, False)
		elif iFeature not in [iOasis, gc.getInfoTypeForString('FEATURE_FLOOD_PLAINS')]:
			sTerrain = gc.getTerrainInfo(iTerrain).getDescription()
			sTerrainNew = gc.getTerrainInfo(gc.getInfoTypeForString('TERRAIN_PLAINS')).getDescription()
			szBuffer += localText.getText("TXT_KEY_HELP_SPELL_CHANGE_A_TO_B", (sTerrain, sTerrainNew, ))
			if iFeature == gc.getInfoTypeForString('FEATURE_SCRUB'):
				sFeature = gc.getFeatureInfo(iFeature).getDescription()
				szBuffer += localText.getText("TXT_KEY_HELP_SPELL_REMOVES_STUFF", (sFeature, ))
	if iFeature == gc.getInfoTypeForString('FEATURE_FLAMES'):
		sFeature = gc.getFeatureInfo(iFeature).getDescription()
		szBuffer += localText.getText("TXT_KEY_HELP_SPELL_REMOVES_STUFF", (sFeature, ))
	if iImprovement == gc.getInfoTypeForString('IMPROVEMENT_SMOKE'):
		sImprovement = gc.getImprovementInfo(iImprovement).getDescription()
		szBuffer += localText.getText("TXT_KEY_HELP_SPELL_REMOVES_STUFF", (sImprovement, ))
	lDirections = ['North', 'Northeast', 'East', 'Southeast', 'South', 'Southwest', 'West', 'Northwest']
	iX = pPlot.getX()
	iY = pPlot.getY()
	for iDirection in xrange(DirectionTypes.NUM_DIRECTION_TYPES):
		pPlot2 = plotDirection(iX, iY, DirectionTypes(iDirection))
		if pPlot2.isNone():continue
		iFeature = pPlot2.getFeatureType()
		iImprovement = pPlot2.getImprovementType()
		if iFeature == gc.getInfoTypeForString('FEATURE_FLAMES'):
			sFeature = gc.getFeatureInfo(iFeature).getDescription()
			szBuffer += localText.getText("TXT_KEY_HELP_SPELL_REMOVES_STUFF", (sFeature, )) + ' from the ' + lDirections[iDirection]
		if iImprovement == gc.getInfoTypeForString('IMPROVEMENT_SMOKE'):
			sImprovement = gc.getImprovementInfo(iImprovement).getDescription()
			szBuffer += localText.getText("TXT_KEY_HELP_SPELL_REMOVES_STUFF", (sImprovement, )) + ' from the ' + lDirections[iDirection]
	return szBuffer

def reqSpringGreater(pCaster, eSpell=-1):

	if not pCaster.isHuman():
		if pCaster.getCivilizationType() == gc.getInfoTypeForString('CIVILIZATION_INFERNAL'):
			return False
	pPlot = pCaster.plot()
	if pPlot.getTerrainType() == gc.getInfoTypeForString('TERRAIN_DESERT'):
		if pPlot.getFeatureType() not in [gc.getInfoTypeForString('FEATURE_FLOOD_PLAINS'), gc.getInfoTypeForString('FEATURE_OASIS')]:
			if pCaster.isHuman():
				return True
			if pCaster.getOwner() == pPlot.getOwner():
				return True
	iFlames = gc.getInfoTypeForString('FEATURE_FLAMES')
	iSmoke = gc.getInfoTypeForString('IMPROVEMENT_SMOKE')
	iX = pPlot.getX()
	iY = pPlot.getY()
	for iiX in xrange(iX-1, iX+ 2, 1):
		for iiY in xrange(iY-1, iY+ 2, 1):
			pPlot2 = CyMap().plot(iiX, iiY)
			if pPlot2.isNone():
				continue
			if pPlot2.getFeatureType() == iFlames:
				return True
			if pPlot2.getImprovementType() == iSmoke:
				return True
	return False

