def spellSteal(pCaster, eSpell=-1):
	iTeam = pCaster.getTeam()
	pPlot = pCaster.plot()
	for i in xrange(pPlot.getNumUnits()):
		pUnit = pPlot.getUnit(i)
		if pUnit.isDelayedDeath():continue
		if pUnit.getTeam() == iTeam:continue
		if pUnit.isInvisible(iTeam, False):continue
		iUnit = pUnit.getUnitType()
		if iUnit == -1: continue
		if gc.getUnitInfo(iUnit).isObject():
			iProm = gc.getUnitInfo(iUnit).getEquipmentPromotion()
			if iProm != -1:
				if not pCaster.isHasPromotion(iProm):
					
					pCaster.setHasPromotion(iProm, True)
					pUnit.kill(True, PlayerTypes.NO_PLAYER)
					continue
		for iProm in xrange(gc.getNumPromotionInfos()):
			if not pCaster.isHasPromotion(iProm):
				if pUnit.isHasPromotion(iProm):
					if gc.getPromotionInfo(iProm).isEquipment():
						if iProm == gc.getInfoTypeForString('PROMOTION_PIECES_OF_BARNAXUS') and iUnit == gc.getInfoTypeForString('UNIT_BARNAXUS'):
							continue
						if iProm == gc.getInfoTypeForString('PROMOTION_PIECES_OF_MITHRIL_GOLEM') and iUnit == gc.getInfoTypeForString('UNIT_MITHRIL_GOLEM'):
							continue
						if iProm == gc.getInfoTypeForString('PROMOTION_PIECES_OF_WAR_MACHINE') and iUnit == gc.getInfoTypeForString('UNIT_WAR_MACHINE'):
							continue
						pCaster.setHasPromotion(iProm, True)
						pUnit.setHasPromotion(iProm, False)
						break
	if pPlot.isCity():
		pCity = pPlot.getPlotCity()
		if pCity.getTeam() != iTeam:
			for iBuild in xrange(gc.getNumBuildingInfos()):
				if pCity.getNumRealBuilding(iBuild) > 0:
					if gc.getBuildingInfo(iBuild).isEquipment():
						for iUnit in xrange(gc.getNumUnitInfos()):
							if gc.getUnitInfo(iUnit).getBuildings(iBuild):
								iProm = gc.getUnitInfo(iUnit).getEquipmentPromotion()
								if not pCaster.isHasPromotion(iProm):
									pCity.setNumRealBuilding(iBuild, 0)
									pCaster.setHasPromotion(iProm, True)

def helpSteal(lpUnits, eSpell=-1):
	szBuffer = ''
	pCaster = lpUnits[0]
	lEquipment = []
	iTeam = pCaster.getTeam()
	pPlot = pCaster.plot()
	for i in xrange(pPlot.getNumUnits()):
		pUnit = pPlot.getUnit(i)
		if pUnit.isDelayedDeath():continue
		if pUnit.getTeam() == iTeam:continue
		# if pUnit.isInvisible(iTeam, False):continue
		iUnit = pUnit.getUnitType()

		if gc.getUnitInfo(iUnit).isObject():
			iProm = gc.getUnitInfo(iUnit).getEquipmentPromotion()
			if iProm != -1:
				if not pCaster.isHasPromotion(iProm):
					lEquipment.append(iProm)

		for iProm in xrange(gc.getNumPromotionInfos()):
			if pUnit.isHasPromotion(iProm):
				if not pCaster.isHasPromotion(iProm):
					if gc.getPromotionInfo(iProm).isEquipment():
						if iProm == gc.getInfoTypeForString('PROMOTION_PIECES_OF_BARNAXUS') and iUnit == gc.getInfoTypeForString('UNIT_BARNAXUS'):
							continue
						if iProm == gc.getInfoTypeForString('PROMOTION_PIECES_OF_MITHRIL_GOLEM') and iUnit == gc.getInfoTypeForString('UNIT_MITHRIL_GOLEM'):
							continue
						if iProm == gc.getInfoTypeForString('PROMOTION_PIECES_OF_WAR_MACHINE') and iUnit == gc.getInfoTypeForString('UNIT_WAR_MACHINE'):
							continue
						lEquipment.append(iProm)
	if pPlot.isCity():
		pCity = pPlot.getPlotCity()
		if pCity.getTeam() != iTeam:
			for iBuild in xrange(gc.getNumBuildingInfos()):
				if pCity.getNumRealBuilding(iBuild) > 0:
					if gc.getBuildingInfo(iBuild).isEquipment():
						for iUnit in xrange(gc.getNumUnitInfos()):
							if gc.getUnitInfo(iUnit).getBuildings(iBuild):
								iProm = gc.getUnitInfo(iUnit).getEquipmentPromotion()
								if not pCaster.isHasPromotion(iProm):
									lEquipment.append(iProm)
	lEquipment = list(set(lEquipment))
	if len(lEquipment) > 0:
		sList = ''
		while len(lEquipment) > 0:
			iProm = lEquipment.pop(0)
			infoProm = gc.getPromotionInfo(iProm)
			sList += infoProm.getDescription()
			if len(lEquipment) > 0:
				if len(lEquipment) == 1:
					sList += " or "
				else:
					sList += ", "
		szBuffer += localText.getText("TXT_KEY_HELP_SPELL_STEAL_EQUIPMENT", (sList, ))
	return szBuffer

def reqSabotage(pCaster, eSpell=-1):
	pPlot = pCaster.plot()

	iCost = pCaster.sabotageCost(pPlot)
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	if pPlayer.getGold() < iCost:
		return False

	if pCaster.canSabotage(pPlot,False):
		return False
	if pPlot.getTeam() != pCaster.getTeam():
		if pCaster.isHuman():
			iImprovement = pPlot.getImprovementType()
			iCost = 20
			if iImprovement not in [-1, gc.getInfoTypeForString('IMPROVEMENT_SMOKE'), gc.getInfoTypeForString('IMPROVEMENT_HELLFIRE'), gc.getInfoTypeForString('IMPROVEMENT_WATER_WORKED'), gc.getInfoTypeForString('IMPROVEMENT_RING_OF_WARDING')]:
				info = gc.getImprovementInfo(iImprovement)
				iCost -= info.getPillageGold()
				if info.isPermanent():
					iCost += 1000
				if info.isUnique():
					iCost += 1000
				iPlayer = pCaster.getOwner()
				pPlayer = gc.getPlayer(iPlayer)
				if pPlayer.getGold() > iCost:
					return True
	return False

