def reqDestroyPiratesCove(pCaster, pSpell):
	if pCaster.isHiddenNationality() or pCaster.getCivilizationType() in [ gc.getInfoTypeForString('CIVILIZATION_BARBARIAN'),gc.getInfoTypeForString('CIVILIZATION_LANUN')]:
		return False
	pPlot = pCaster.plot()
	if pPlot.isOwned():
		iTeamC = pCaster.getTeam()
		iTeamP = pPlot.getTeam()
		if iTeamC == iTeamP:
			if gc.getPlayer(pPlot.getOwner()).getCivilizationType() in [ gc.getInfoTypeForString('CIVILIZATION_BARBARIAN'),gc.getInfoTypeForString('CIVILIZATION_LANUN')]:
				return False
		elif not (gc.getTeam(iTeamC).isAtWar(iTeamP)):
				return False
	return True

def reqDestroyProduction(pCaster, eSpell):
	pPlot = pCaster.plot()
	if pCaster.canDestroy(pPlot,False):
		return False
	pCity = pPlot.getPlotCity()
	if pCity.getTeam() != pCaster.getTeam():
		iProduction = pCity.getProduction()
		if iProduction > 0:

			iCost = pCaster.destroyCost(pPlot)
			iPlayer = pCaster.getOwner()
			pPlayer = gc.getPlayer(iPlayer)
			if pPlayer.getGold() < iCost:
				return False

			if pCaster.isHuman():
				return True
			if iProduction > 100:
				if pCity.getProductionNeeded() > 3/4*iProduction:
					return True
	return False

def spellDestroyProduction(pCaster, eSpell):
	pPlot = pCaster.plot()
	pCity = pPlot.getPlotCity()

	iCost = pCaster.destroyCost(pPlot)
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	pPlayer.changeGold(-iCost)

	if CyGame().getSorenRandNum(100, "DestroyProduction "+ str(pCaster.getName())) < pCaster.destroyProb(pPlot, 1):
		pCity.changeProduction(-pCity.getProduction())
	else:
		iMemType = 7#Spy Caught
		iMalus = int(1 + pCity.getProduction()/100)
		gc.getPlayer(pCity.getOwner()).AI_changeMemoryCount(iPlayer, iMemType, iMalus)


