def reqTakeEquipmentPromotion(pCaster, unit, eSpell=-1):
	if pCaster.getSpecialUnitType() in [gc.getInfoTypeForString('SPECIALUNIT_SPELL'), gc.getInfoTypeForString('SPECIALUNIT_BIRD')]:
		return False
	if pCaster.getUnitCombatType() in [-1, gc.getInfoTypeForString('UNITCOMBAT_NAVAL'), gc.getInfoTypeForString('UNITCOMBAT_SIEGE')]:
		return False
	if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_ILLUSION')) or pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_DARK_REFLECTION')):
		return False
	iUnit = gc.getInfoTypeForString(unit)
	iProm = gc.getUnitInfo(iUnit).getEquipmentPromotion()
	if pCaster.isHasPromotion(iProm):
		return False
	iPlayer = pCaster.getOwner()
	pPlot = pCaster.plot()
	pHolder = -1
	iSluagh = gc.getInfoTypeForString('UNIT_SLUAGH')
	for i in xrange(pPlot.getNumUnits()):
		pUnit = pPlot.getUnit(i)
		if pUnit.isHasPromotion(iProm):
			if pUnit.getOwner() == iPlayer:
				if pUnit.getUnitType() != iSluagh:
					if pUnit.getID() != pCaster.getID():
						if pUnit.getImmobileTimer() == 0:
							pHolder = pUnit
	if pHolder == -1:
		return False
	if pHolder.isHasCasted():
		return False
	if pHolder.isMadeAttack():
		return False
	iType = pHolder.getUnitType()

	if iType == gc.getInfoTypeForString('UNIT_BARNAXUS'):
		if iProm == gc.getInfoTypeForString('PROMOTION_PIECES_OF_BARNAXUS'):
			return False
	elif iType == gc.getInfoTypeForString('UNIT_WAR_MACHINE'):
		if iProm == gc.getInfoTypeForString('PROMOTION_PIECES_OF_WAR_MACHINE'):
			return False
	elif iType == gc.getInfoTypeForString('UNIT_MITHRIL_GOLEM'):
		if iProm == gc.getInfoTypeForString('PROMOTION_PIECES_OF_MITHRIL_GOLEM'):
			return False

	if not pCaster.isHuman():
		if pCaster.baseCombatStr() - 2 <= pHolder.baseCombatStr():
			return False
		if gc.getUnitInfo(pHolder.getUnitType()).getFreePromotions(iProm):
			return False
	return True

def spellTakeEquipmentPromotion(pCaster, unit, eSpell=-1, sBonusProm=-1):
	iUnit = gc.getInfoTypeForString(unit)
	iProm = gc.getUnitInfo(iUnit).getEquipmentPromotion()
	iPlayer = pCaster.getOwner()
	pPlot = pCaster.plot()
	pHolder = -1
	iSluagh = gc.getInfoTypeForString('UNIT_SLUAGH')
	for i in xrange(pPlot.getNumUnits()):
		pUnit = pPlot.getUnit(i)
		if pUnit.isHasPromotion(iProm):
			if pUnit.getOwner() == iPlayer:
				if pUnit.getUnitType() != iSluagh:
					if pUnit.getID() != pCaster.getID():
						if pUnit.getImmobileTimer() == 0:
							pHolder = pUnit
	if pHolder != -1:
		pHolder.setHasPromotion(iProm, False)
		pCaster.setHasPromotion(iProm, True)

		if sBonusProm != -1:
			iBonusProm = gc.getInfoTypeForString(sBonusProm)
			if iBonusProm != -1:
				if not gc.getUnitInfo(pHolder.getUnitType()).getFreePromotions(iBonusProm):
					pHolder.setHasPromotion(iBonusProm, False)
				pCaster.setHasPromotion(iBonusProm, True)

	iUnitClass = gc.getUnitInfo(iUnit).getUnitClassType()
	if gc.getGame().getUnitClassCreatedCount(iUnitClass) == 0:
		gc.getGame().incrementUnitClassCreatedCount(iUnitClass)


def helpTakeEquipmentPromotion(lpUnits, unit, eSpell=-1, sBonusProm=-1):
	szBuffer = ''
	iUnit = gc.getInfoTypeForString(unit)
	iProm = gc.getUnitInfo(iUnit).getEquipmentPromotion()
	sName = gc.getUnitInfo(iUnit).getDescription()
	pCaster = lpUnits[0]
	pPlot = pCaster.plot()
	iPlayer = pCaster.getOwner()
	pHolder = -1
	iSluagh = gc.getInfoTypeForString('UNIT_SLUAGH')
	for i in xrange(pPlot.getNumUnits()):
		pUnit = pPlot.getUnit(i)
		if pUnit.isHasPromotion(iProm):
			if pUnit.getOwner() == iPlayer:
				if pUnit.getUnitType() != iSluagh:
					if pUnit not in lpUnits:
						if pUnit.getImmobileTimer() == 0:
							pHolder = pUnit
	if pHolder != -1:
		sAdd = localText.getText("TXT_KEY_HELP_SPELL_ADDS", ())
		sRemove = localText.getText("TXT_KEY_HELP_SPELL_REMOVES", ())
		szBuffer += sAdd + CyGameTextMgr().getPromotionHelp(iProm, False)

		if sBonusProm != -1:
			iBonusProm = gc.getInfoTypeForString(sBonusProm)
			if iBonusProm != -1:
				szBuffer += sAdd + CyGameTextMgr().getPromotionHelp(iBonusProm, False)

		pPlayer = gc.getPlayer(pHolder.getOwner())
		szColorBuffer = cf.getNameWithColorScheme(pHolder, pHolder.isInvisible(pCaster.getTeam(), False))
		szBuffer += localText.getText("TXT_KEY_HELP_SPELL_TAKE_EQUIPMENT", (sName, szColorBuffer, ))
	return szBuffer

def reqTakeEquipmentUnit(pCaster, unit, eSpell=-1):
	if pCaster.getSpecialUnitType() in [gc.getInfoTypeForString('SPECIALUNIT_SPELL'), gc.getInfoTypeForString('SPECIALUNIT_BIRD')]:
		return False
	if pCaster.getUnitCombatType() in [-1, gc.getInfoTypeForString('UNITCOMBAT_NAVAL'), gc.getInfoTypeForString('UNITCOMBAT_SIEGE')]:
		return False
	if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_ILLUSION')) or pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_DARK_REFLECTION')):
		return False
	iUnit = gc.getInfoTypeForString(unit)
	iProm = gc.getUnitInfo(iUnit).getEquipmentPromotion()
	if pCaster.isHasPromotion(iProm):
		return False
	iPlayer = pCaster.getOwner()
	pPlot = pCaster.plot()
	pHolder = -1
	for i in xrange(pPlot.getNumUnits()):
		pUnit = pPlot.getUnit(i)
		if pUnit.getUnitType() == iUnit:
			if pUnit.isDelayedDeath():continue
			pHolder = pUnit
	if pHolder == -1:
		return False
	if pHolder.isMadeAttack():
		return False
	return True

def spellTakeEquipmentUnit(pCaster, unit, eSpell=-1, sBonusProm=-1):
	iUnit = gc.getInfoTypeForString(unit)
	iProm = gc.getUnitInfo(iUnit).getEquipmentPromotion()
	iPlayer = pCaster.getOwner()
	pPlot = pCaster.plot()
	pHolder = -1
	for i in range(pPlot.getNumUnits()):
		pUnit = pPlot.getUnit(i)
		if pUnit.getOwner() == iPlayer and pUnit.getUnitType() == iUnit:
			if not pUnit.isDelayedDeath():
				pHolder = pUnit
	if pHolder != -1:
		pHolder.setHasCasted(True)
		pHolder.kill(False, PlayerTypes.NO_PLAYER)

def reqTakeEquipmentRivalUnit(pCaster, eSpell=-1):
##	if pCaster.isHuman():
	iTeam = pCaster.getTeam()
	pPlot = pCaster.plot()
	for i in xrange(pPlot.getNumUnits()):
		pUnit = pPlot.getUnit(i)
		if pUnit.isDelayedDeath():continue
		if pUnit.getTeam() == iTeam:continue
		if pUnit.isInvisible(iTeam, False):continue
		if pPlot.getNumDefenders(pUnit.getOwner()) > 0:continue
		iUnit = pUnit.getUnitType()
		if iUnit != -1:
			if gc.getUnitInfo(iUnit).isObject():
				return True
	return False

