def reqTaunt(pCaster, eSpell=-1):
	pPlot = pCaster.plot()
	if not pPlot.isNone():
		if pPlot.isCity():#Forcing units to attack a city seems to cause the game to crash
			return False
		iTeam = pCaster.getTeam()
		for i in xrange(pPlot.getNumUnits()):
			pUnit = pPlot.getUnit(i)
			if pUnit.getTeam() != iTeam:
				return False
		iPlayer = pCaster.getOwner()
		eTeam = gc.getTeam(iTeam)
		iSpirit = gc.getInfoTypeForString('PROMOTION_SPIRIT3')
		iSpiritA = gc.getInfoTypeForString('PROMOTION_AFFINITY_SPIRIT')
		iX = pCaster.getX()
		iY = pCaster.getY()
		for iDirection in xrange(DirectionTypes.NUM_DIRECTION_TYPES):
			pLoopPlot = plotDirection(iX, iY, DirectionTypes(iDirection))
			if pLoopPlot.isNone():continue
			for i in xrange(pLoopPlot.getNumUnits()):
				pUnit = pLoopPlot.getUnit(i)
				if pUnit.isImmuneToSpell(pCaster, eSpell):continue
				if pUnit.isOnlyDefensive():continue
				if pUnit.isHasPromotion(iSpirit):continue
				if pUnit.isHasPromotion(iSpiritA):continue
				if pUnit.getImmobileTimer() > 0:continue
				if pUnit.canMoveInto(pPlot, True, False, False):
					return True
	return False

def spellTaunt(pCaster, eSpell=-1):
	pPlot = pCaster.plot()
	if not pPlot.isNone():
		iPlayer = pCaster.getOwner()
		iTeam = pCaster.getTeam()
		eTeam = gc.getTeam(iTeam)
		iSpirit = gc.getInfoTypeForString('PROMOTION_SPIRIT3')
		iSpiritA = gc.getInfoTypeForString('PROMOTION_AFFINITY_SPIRIT')
		iEnraged = gc.getInfoTypeForString('PROMOTION_ENRAGED')
		lTaunted = []
		iX = pCaster.getX()
		iY = pCaster.getY()
		for iDirection in xrange(DirectionTypes.NUM_DIRECTION_TYPES):
			pLoopPlot = plotDirection(iX, iY, DirectionTypes(iDirection))
			if pLoopPlot.isNone():continue
			for i in xrange(pLoopPlot.getNumUnits()):
				pUnit = pLoopPlot.getUnit(i)
				if pUnit.isImmuneToSpell(pCaster, eSpell):continue
				if pUnit.getImmobileTimer() > 0:continue
				if pUnit.isOnlyDefensive():continue
				if pUnit.isHasPromotion(iSpirit):continue
				if pUnit.isHasPromotion(iSpiritA):continue
				if pUnit.canAttack():
					if pUnit.canMoveInto(pPlot, True, False, True):
						if effectResisted(pUnit, pCaster, eSpell):continue
						lTaunted.append(pUnit)
		while len(lTaunted) > 0 and pPlot.getNumDefenders(iPlayer) > 0:
			pUnit = lTaunted.pop(CyGame().getSorenRandNum(len(lTaunted), "Taunt"))
			if pUnit.getGroup().getNumUnits() > 1:
				pUnit.joinGroup(gc.getPlayer(pUnit.getOwner()).getSelectionGroup(-1))
			pUnit.attack(pPlot, False)
			pUnit.setHasPromotion(iEnraged, False)

def helpProvoke(lpUnits, eSpell=-1):
	szBuffer = ''
	szBuffer += helpTaunt(lpUnits, eSpell)
	szBuffer += helpTogglePromotions(lpUnits, eSpell, ['PROMOTION_ENRAGED'], [], 2, False)
	return szBuffer

