def reqTreetopDefence(pCaster, eSpell=-1):
	pPlot = pCaster.plot()
	if pPlot.getFeatureType() in [	gc.getInfoTypeForString('FEATURE_FOREST'),
									gc.getInfoTypeForString('FEATURE_FOREST_ANCIENT'),
									gc.getInfoTypeForString('FEATURE_JUNGLE'),
									gc.getInfoTypeForString('FEATURE_FOREST_BURNT'),
									gc.getInfoTypeForString('FEATURE_FOREST_NEW'),
									]:
		iTeam = pCaster.getTeam()
		iMaxFortify = gc.getDefineINT('MAX_FORTIFY_TURNS')
		for i in xrange(pPlot.getNumUnits()):
			pUnit = pPlot.getUnit(i)
			if pUnit.getTeam() == iTeam:
				if pUnit.getFortifyTurns() < iMaxFortify:
					return True
	return False

