def reqTsunami(pCaster, eSpell=-1):
	pPlot = pCaster.plot()
	if pPlot.isWater() or pPlot.isAdjacentToWater() or pPlot.isRiverSide():
		iX = pCaster.getX()
		iY = pCaster.getY()
		iPlayer = pCaster.getOwner()
		eTeam = gc.getTeam(pCaster.getTeam())
		lConvert = []
		if pCaster.getReligion() == gc.getInfoTypeForString('RELIGION_OCTOPUS_OVERLORDS'):
			lConvert = [gc.getInfoTypeForString('UNIT_KRAKEN'),gc.getInfoTypeForString('UNIT_DROWN')]
		iSmoke = gc.getInfoTypeForString('IMPROVEMENT_SMOKE')
		iFlames = gc.getInfoTypeForString('FEATURE_FLAMES')
		iRange = 2
		for iiX in xrange(iX-iRange, iX + iRange+1, 1):
			for iiY in xrange(iY-iRange, iY+ iRange+1, 1):
				pPlot = CyMap().plot(iiX, iiY)
				if pPlot.isNone():continue
				if pPlot.at(iX, iY):continue
				if plotDistance(iX, iY, iiX, iiY) > iRange:continue
				if pPlot.isWater() or pPlot.isAdjacentToWater() or pPlot.isRiverSide():
					if pPlot.getNumUnits() > 0:
##						return True
						if pCaster.isHuman():
							return True
						if pPlot.isVisibleEnemyUnit(iPlayer):
							return True
						for i in xrange(pPlot.getNumUnits()):
							pUnit = pPlot.getUnit(i)
							if pUnit.getUnitType() in lConvert:
								if pUnit.isBarbarian():
									return True
					iImp = pPlot.getImprovementType()
					if iImp != -1:
						if iImp == iSmoke:
##							return True
							if pCaster.isHuman():
								return True
##							if pPlot.getOwner() == iPlayer:
##								return True
						elif not gc.getImprovementInfo(iImp).isPermanent():
##							return True
							if pCaster.isHuman():
								return True
							if pPlot.isOwned():
								if eTeam.isAtWar(pPlot.getTeam()):
									return True
					if pPlot.getFeatureType() == iFlames:
						return True

	return False

def spellTsunami(pCaster, eSpell=-1):
	iX = pCaster.getX()
	iY = pCaster.getY()
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iManaDuration = cf.getNumBonusEffective(iPlayer, gc.getInfoTypeForString('BONUS_MANA_MIND'), pCaster) + cf.getNumBonusEffective(iPlayer, gc.getInfoTypeForString('BONUS_MANA_WATER'), pCaster)
	lConvert = []
	if pCaster.getReligion() == gc.getInfoTypeForString('RELIGION_OCTOPUS_OVERLORDS'):
		lConvert = [gc.getInfoTypeForString('UNIT_KRAKEN'),gc.getInfoTypeForString('UNIT_DROWN')]
	iSmoke = gc.getInfoTypeForString('IMPROVEMENT_SMOKE')
	iFlames = gc.getInfoTypeForString('FEATURE_FLAMES')
	iCold = gc.getInfoTypeForString('DAMAGE_COLD')
	iRange = 2
	for iiX in xrange(iX-iRange, iX + iRange+1, 1):
		for iiY in xrange(iY-iRange, iY+ iRange+1, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			if pPlot.at(iX, iY):continue
			if plotDistance(iX, iY, iiX, iiY) > iRange:continue
			if pPlot.isWater() or pPlot.isAdjacentToWater() or pPlot.isRiverSide():
				for i in xrange(pPlot.getNumUnits()):
					pUnit = pPlot.getUnit(i)
					pUnit.doDamage(30, 75, pCaster, iCold, False)
					if pUnit.getUnitType() in lConvert:
						if pUnit.isBarbarian():
							iDuration = pCaster.getDuration() + 1 + iManaDuration
							if iDuration < 1:
								iDuration = pCaster.getLevel()
							else:
								iDuration = min(iDuration, pCaster.getLevel())

							newUnit = pPlayer.initUnit(pUnit.getUnitType(), iX , iY, UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
							newUnit.convert(pUnit)
							newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_BURNING_BLOOD'), True)
							newUnit.setDuration(iDuration)

				if pPlot.getFeatureType() == iFlames:
					pPlot.setFeatureType(-1,-1)

				iImp = pPlot.getImprovementType()
				if iImp != -1:
					if iImp == iSmoke:
						pPlot.setImprovementType(-1)
					elif not gc.getImprovementInfo(iImp).isPermanent():
						if CyGame().getSorenRandNum(100, "Tsunami") < 25:
							pPlot.setImprovementType(-1)
				CyEngine().triggerEffect(gc.getInfoTypeForString('EFFECT_SPRING'), pPlot.getPoint())

