def spellTempest(pCaster, eSpell):

	iX = pCaster.getX()
	iY = pCaster.getY()
	iSmoke = gc.getInfoTypeForString('IMPROVEMENT_SMOKE')
	iFlames = gc.getInfoTypeForString('FEATURE_FLAMES')
	iCold = gc.getInfoTypeForString('DAMAGE_COLD')
	iLightning = gc.getInfoTypeForString('DAMAGE_LIGHTNING')
	iPhysical = gc.getInfoTypeForString('DAMAGE_PHYSICAL')

	lFlamable = [	gc.getInfoTypeForString('FEATURE_FOREST'),
			gc.getInfoTypeForString('FEATURE_FOREST_ANCIENT'),
			gc.getInfoTypeForString('FEATURE_FOREST_NEW'),
			gc.getInfoTypeForString('FEATURE_JUNGLE')
			]

##	lTossed = []

	for iiX in xrange(iX-2, iX+ 3, 1):
		for iiY in xrange(iY-2, iY+ 3, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isNone():continue
			if pPlot.at(iX, iY):continue
			iImp = pPlot.getImprovementType()
			iFeature = pPlot.getFeatureType()
			if pPlot.isWater() or pPlot.isAdjacentToWater() or pPlot.isRiverSide():
				CyEngine().triggerEffect(gc.getInfoTypeForString('EFFECT_SPRING'), pPlot.getPoint())
				if iImp == iSmoke:
					pPlot.setImprovementType(-1)
				if iFeature == iFlames:
					pPlot.setFeatureType(-1,-1)
				for i in xrange(pPlot.getNumUnits()):
					pUnit = pPlot.getUnit(i)
					pUnit.doDamage(30, 90, pCaster, iCold, False)

			elif iFeature in lFlamable:
				if CyGame().getSorenRandNum(100, "Tempest start fire") < 10:
					if iImp == iSmoke:
						if CyGame().getSorenRandNum(20, "Tempest estinguish fire") < 10:
							pPlot.setImprovementType(-1)
						else:
							pPlot.setFeatureType(iFlames,0)
					elif iImp == -1 or not gc.getImprovementInfo(iImp).isPermanent():
						pPlot.setImprovementType(iSmoke)

			if iImp != -1:
				if iImp != iSmoke:
					if not gc.getImprovementInfo(iImp).isPermanent():
						if CyGame().getSorenRandNum(100, "Tempest destroy improvements") < 15:
							pPlot.setImprovementType(-1)

			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if CyGame().getSorenRandNum(100, "Tempest Lighning Strike") < 15:
					pUnit.doDamage(10, 100, pCaster, iLightning, False)
##				if cf.doFear(pUnit, pPlot, -1, False):
##					pUnit.doDamage(10, 25, pCaster, iPhysical, True)


