def spellUnyieldingOrder(pCaster, eSpell=-1):
	pPlot = pCaster.plot()
	if pPlot.isCity():
		pCity = pPlot.getPlotCity()
		pCity.setOccupationTimer(0)
		iChange = -9
		pTimer = pCity.getHurryAngerTimer()
		if pTimer < 9:
			iChange = 0 - pTimer
		pCity.changeHurryAngerTimer(iChange)
		if pCity.getRevolutionIndex() > 0:
			pCity.setRevolutionIndex(0)

def effectUnyieldingOrder(pCaster, eSpell=-1):
	pCity = pCaster.plot().getPlotCity()
	for sBuilding in ['BUILDING_UNYIELDING_ORDER','BUILDING_UNYIELDING_ORDER_GREATER', 'BUILDING_TOWER_OF_COMPLACENCY', 'BUILDING_PILLAR_OF_CHAINS']:
		if pCity.getNumBuilding(gc.getInfoTypeForString(sBuilding)) > 0:
			spellUnyieldingOrder(pCaster, eSpell)
			break
	return False

def reqUpgradeDovielloWarrior(pCaster, eSpell=-1):
	if not pCaster.isHuman():
		if gc.getTeam(pCaster.getTeam()).getAtWarCount(True) == 0:
			return False
		iPlayer = pCaster.getOwner()
		pPlayer = gc.getPlayer(iPlayer)
		if 1.7* pPlayer.getNumCities() > pPlayer.getUnitClassCount(gc.getInfoTypeForString('UNITCLASS_WORKER')):
			return False
	return True

def reqUpgradeAnywhere(pCaster, eSpell, sUnit=''):
	if eSpell != -1:
		iUnit = gc.getSpellInfo(eSpell).getConvertUnitType()
	if iUnit == -1:
		iUnit = gc.getInfoTypeForString(sUnit)

	if iUnit != -1:
		if pCaster.canUpgrade(iUnit, True):
			return False#When a unit can upgrade the normal way, the option to upgrade though this ability is just a distraction
		if gc.getPlayer(pCaster.getOwner()).isUnitClassMaxedOut(gc.getUnitInfo(iUnit).getUnitClassType(), 0):
			return False#This ability should not let you circumvent the limits on world or national units
		return True
	return False


def miscastAttackSelf(pCaster, eSpell=-1, sDamage = 'DAMAGE_PHYSICAL'):
	iDamage = gc.getInfoTypeForString(sDamage)
	pCaster.doDamage(50, 100, pCaster, iDamage, True)


def miscastSummonBarbarian(pCaster, eSpell, iNum = 1):
	pPlot = pCaster.plot()
	if eSpell != -1:
		iUnit = gc.getSpellInfo(eSpell).getCreateUnitType()
		iNum = gc.getSpellInfo(eSpell).getCreateUnitNum()
		if pCaster.isHasPromotion(gc.getInfoTypeForString('PROMOTION_TWINCAST')):
			iNum *= 2
		if iUnit > -1:
			pPlayer = gc.getPlayer(gc.getBARBARIAN_PLAYER())
			for i in range(iNum):
				pPlot2 = findClearPlot(-1, pPlot)
				if pPlot2 != -1:
					newUnit = pPlayer.initUnit(iUnit, pPlot2.getX(), pPlot2.getY(), UnitAITypes.UNITAI_ATTACK_CITY, DirectionTypes.DIRECTION_SOUTH)
					newUnit.setDuration(2)
					if not gc.getTeam(gc.getBARBARIAN_TEAM()).isAtWar(pCaster.getTeam()):
						newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_PARANOID'), True)
					for iProm in cf.getSummonPerks(pCaster):
						newUnit.setHasPromotion(iProm, True)
					if not newUnit.isOnlyDefensive():
						newUnit.setHasPromotion(gc.getInfoTypeForString('PROMOTION_ENRAGED'), True)
						if newUnit.canMoveOrAttackInto(pPlot, False):
							newUnit.attack(pPlot, False)


def helpShowSummonDetails(lpUnits, eSpell, iNum = 1, sCreateUnitPromotion = -1):
	szBuffer = ''

	if eSpell != -1:
		iUnit = gc.getSpellInfo(eSpell).getCreateUnitType()
##		iNum = gc.getSpellInfo(eSpell).getCreateUnitNum()#This is not exposed yet

		if iUnit > -1:
			iSummons = 0
			iTwincast = gc.getInfoTypeForString('PROMOTION_TWINCAST')
			infoU = gc.getUnitInfo(iUnit)
			for pCaster in lpUnits:
				if pCaster.canCast(eSpell, True):
					iSummons += iNum
					if pCaster.isHasPromotion(iTwincast):
						iSummons += iNum
					lPerks = []
					if sCreateUnitPromotion != -1:
						lPerks.append(gc.getInfoTypeForString(sCreateUnitPromotion))
					for iProm in cf.getSummonPerks(pCaster):
						if not infoU.getFreePromotions(iProm):
							lPerks.append(iProm)
					iCount = len(lPerks)
					if iCount > 0:
						szBuffer += '\n' + localText.getText("TXT_KEY_UNIT_STARTS_WITH", ())
						if iCount == 1:
							sList = gc.getPromotionInfo(lPerks.pop(0)).getDescription()
						else:
							sList = ''
							while len(lPerks) > 0:
								sList += gc.getPromotionInfo(lPerks.pop(0)).getDescription()
								if len(lPerks) > 0:
									if len(lPerks) == 1:
										sList += " and "
									else:
										sList += ", "
						szBuffer += sList
			sHelp = helpUnitHelp(iUnit)
			if iSummons == 1:
				sHelp = localText.getText("TXT_KEY_SPELL_SUMMON_UNIT", (sHelp,))
			else:
				sHelp = localText.getText("TXT_KEY_SPELL_SUMMON_UNIT_MULTIPLE", (iSummons, sHelp,))
				iStop = sHelp.rfind("(s).")#I don't want to include the "(s)."
				if iStop != -1:
					sHelp = sHelp[:iStop]
			szBuffer = '\n' + sHelp + szBuffer


			iPlayer = pCaster.getOwner()
			pPlayer = gc.getPlayer(iPlayer)
			iTeam = pCaster.getTeam()
			eTeam = gc.getTeam(iTeam)
			info = gc.getUnitInfo(iUnit)
			iPlayer = pCaster.getOwner()
			iUnitClass = info.getUnitClassType()
			iUnitCombat = info.getUnitCombatType()
			if iUnitCombat != -1:
				iMana = info.getPrereqAndBonus()

				if iMana != -1:
					if info.getFreePromotions(gc.getInfoTypeForString('PROMOTION_ANGEL')):
						iNumMana = 0
						if eTeam.isBuildingClassMaxedOut(gc.getInfoTypeForString('BUILDINGCLASS_TOWER_OF_DIVINATION'),0):
							iNumMana += 1 + max(0,cf.getNumBonusEffective(iPlayer, iMana))//(pPlayer.getUnitClassCount(iUnitClass)+ iNum)
						if iUnit in [gc.getInfoTypeForString('UNIT_ANGEL_OF_DEATH'),gc.getInfoTypeForString('UNIT_TOMB_WARDEN')]:
							if eTeam.isBuildingClassMaxedOut(gc.getInfoTypeForString('BUILDINGCLASS_TOWER_OF_NECROMANCY'),0):
								iMana = gc.getInfoTypeForString('BONUS_MANA_DEATH')
								iNumMana += 1 + max(0,cf.getNumBonusEffective(iPlayer, iMana))//(pPlayer.getUnitClassCount(iUnitClass)+ iNum)
						if iNumMana > 1:
							szBuffer += '\n' + localText.getText("TXT_KEY_BUILDING_FREE_PROMOTION_PICK_RANGE", (1,iNumMana,))
						else:
							szBuffer += '\n' + localText.getText("TXT_KEY_BUILDING_FREE_PROMOTION_PICK", (1,))

					if info.getFreePromotions(gc.getInfoTypeForString('PROMOTION_ELEMENTAL')):
						if eTeam.isBuildingClassMaxedOut(gc.getInfoTypeForString('BUILDINGCLASS_TOWER_OF_THE_ELEMENTS'),0):
							iNumMana = 1 + max(0,cf.getNumBonusEffective(iPlayer, iMana))//(pPlayer.getUnitClassCount(iUnitClass)+ iNum)
							if iNumMana > 1:
								szBuffer += '\n' + localText.getText("TXT_KEY_BUILDING_FREE_PROMOTION_PICK_RANGE", (1,iNumMana,))
							else:
								szBuffer += '\n' + localText.getText("TXT_KEY_BUILDING_FREE_PROMOTION_PICK", (1,))
				if info.getFreePromotions(gc.getInfoTypeForString('PROMOTION_UNDEAD')):
					if eTeam.isBuildingClassMaxedOut(gc.getInfoTypeForString('BUILDINGCLASS_TOWER_OF_NECROMANCY'),0):
						if iMana == -1:
							iMana = gc.getInfoTypeForString('BONUS_MANA_DEATH')
						iNumMana = 1 + max(0,cf.getNumBonusEffective(iPlayer, iMana))//(pPlayer.getUnitClassCount(iUnitClass)+ iNum)
						if iNumMana > 1:
							szBuffer += '\n' + localText.getText("TXT_KEY_BUILDING_FREE_PROMOTION_PICK_RANGE", (1,iNumMana,))
						else:
							szBuffer += '\n' + localText.getText("TXT_KEY_BUILDING_FREE_PROMOTION_PICK", (1,))



	return szBuffer

