def helpToggleBuildingsIndex(lpUnits, lAddBuildings = [], lRemoveBuildings = [], iRange = 0):
	szBuffer = ''
	pCaster = lpUnits[0]
	pPlot = pCaster.plot()
	iX = pCaster.getX()
	iY = pCaster.getY()
	for iiX in xrange(iX-iRange, iX+ 1+ iRange, 1):
		for iiY in xrange(iY-iRange, iY+ 1+ iRange, 1):
			pPlot = CyMap().plot(iiX, iiY)
			if pPlot.isCity():
				pCity = pPlot.getPlotCity()
				for iBuilding in lAddBuildings:
					if iBuilding > -1:
		##				if pCity.getNumBuilding(iBuilding) < 1:
							pPlayer = gc.getPlayer(pCity.getOwner())
							sPlace = " in <color=%d,%d,%d,%d>%s</color>" %(pPlayer.getPlayerTextColorR(), pPlayer.getPlayerTextColorG(), pPlayer.getPlayerTextColorB(), pPlayer.getPlayerTextColorA(), pCity.getName() ) + ': \n'
							sHelp = helpBuildingHelp(iBuilding, pCity)
							szBuffer += localText.getText("TXT_KEY_HELP_SPELL_ADDS", ()) + sPlace + sHelp
				for iBuilding in lRemoveBuildings:
					if iBuilding > -1:
						if pCity.getNumBuilding(iBuilding) > 0:
							pPlayer = gc.getPlayer(pCity.getOwner())
							sPlace = " from <color=%d,%d,%d,%d>%s</color>" %(pPlayer.getPlayerTextColorR(), pPlayer.getPlayerTextColorG(), pPlayer.getPlayerTextColorB(), pPlayer.getPlayerTextColorA(), pCity.getName() )+ ': \n'
							sHelp = helpBuildingHelp(iBuilding, pCity)
							szBuffer += localText.getText("TXT_KEY_HELP_SPELL_REMOVES", ()) + sPlace + sHelp
	return szBuffer
	
