def reqVeilOfNight(pCaster, eSpell=-1):
	if not pCaster.isHuman():
		iPlayer = pCaster.getOwner()
		pPlayer = gc.getPlayer(iPlayer)
		if pPlayer.getNumUnits() < 25:
			return False
#		if gc.getTeam(pCaster.getTeam()).getAtWarCount(True) == 0:
#			return False
	return True

def spellVeilOfNight(pCaster, eSpell=-1):
	iHN = gc.getInfoTypeForString('PROMOTION_HIDDEN_NATIONALITY')
	iStealth = gc.getInfoTypeForString('PROMOTION_STEALTH')
	iMark = gc.getInfoTypeForString('PROMOTION_MARKSMAN')
	iCoE = gc.getInfoTypeForString('RELIGION_COUNCIL_OF_ESUS')
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	for loopUnit in PyPlayer(iPlayer).getUnitList():
		if pUnit.baseCombatStr() > 0:
			pUnit.setHasPromotion(iHN, True)
			pUnit.setHasPromotion(iStealth, True)
			if pUnit.getReligion() ==-1:
				pUnit.setReligion(iCoE)
			if pUnit.getReligion() == iCoE:
				pUnit.setHasPromotion(iMark, True)


	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iTeam = pCaster.getTeam()
	eTeam = gc.getTeam(iTeam)
	for iTeam2 in xrange(gc.getMAX_CIV_TEAMS()):
		if iTeam2 != iTeam and iTeam2 != gc.getBARBARIAN_TEAM():
			eTeam2 = gc.getTeam(iTeam2)
			if eTeam2.isAlive():
				eTeam.makePeace(iTeam2)


def spellOvergrowth(pCaster, eSpell=-1):
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iTeam = pCaster.getTeam()

	iWeak = gc.getInfoTypeForString('PROMOTION_WEAK')
	lHeroicPromotions = [	gc.getInfoTypeForString('PROMOTION_STRONG'),
							gc.getInfoTypeForString('PROMOTION_HEROIC_DEFENSE'),
							gc.getInfoTypeForString('PROMOTION_HEROIC_DEFENSE2'),
							gc.getInfoTypeForString('PROMOTION_HEROIC_STRENGTH'),
							gc.getInfoTypeForString('PROMOTION_HEROIC_STRENGTH2')]

	pPlotC = pCaster.plot()
	iNature = cf.getNumBonusEffective(pCaster.getOwner(), gc.getInfoTypeForString('BONUS_MANA_NATURE'), pCaster)
	bAllowBloomAllImprovements = pPlayer.getCivilizationType() in [gc.getInfoTypeForString('CIVILIZATION_LJOSALFAR'), gc.getInfoTypeForString('CIVILIZATION_SVARTALFAR'), gc.getInfoTypeForString('CIVILIZATION_KURIOTATES')]

	if not bAllowBloomAllImprovements:
		lBloomableImprovements = [	-1,
						gc.getInfoTypeForString('IMPROVEMENT_CAMP'),
						gc.getInfoTypeForString('IMPROVEMENT_LUMBERMILL'),
						gc.getInfoTypeForString('IMPROVEMENT_SEVEN_PINES'),
						gc.getInfoTypeForString('IMPROVEMENT_YGGDRASIL'),
						gc.getInfoTypeForString('IMPROVEMENT_TOMB_OF_SUCELLUS'),
						gc.getInfoTypeForString('IMPROVEMENT_MANA_NATURE'),
						gc.getInfoTypeForString('IMPROVEMENT_MANA_CREATION')
						]

	iForestNew = gc.getInfoTypeForString('FEATURE_FOREST_NEW')
	dFeatures = {	gc.getInfoTypeForString('FEATURE_FOREST')		:	gc.getInfoTypeForString('FEATURE_FOREST_ANCIENT'),
			iForestNew						:	gc.getInfoTypeForString('FEATURE_FOREST'),
			gc.getInfoTypeForString('FEATURE_FOREST_BURNT')		:	gc.getInfoTypeForString('FEATURE_FOREST'),
			gc.getInfoTypeForString('FEATURE_SCRUB')		:	iForestNew,
			gc.getInfoTypeForString('FEATURE_BLIZZARD')		:	-1,
			gc.getInfoTypeForString('FEATURE_ICE')			:	-1
			}

	for i in xrange (CyMap().numPlots()):
		pPlot = CyMap().plotByIndex(i)
		if -1< CyMap().calculatePathDistance(pPlotC, pPlot) < iNature:

			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if iTeam == pUnit.getTeam():
					if pUnit.isAnimal():
						pUnit.setHasPromotion(iWeak, False)
						for iProm in lHeroicPromotions:
							pUnit.setHasPromotion(iProm, True)

			pPlot.changePlotCounter(-100)
			if not pPlot.isWater():

				if not pPlot.isPeak():
					iFeature = pPlot.getFeatureType()
					if iFeature == -1:
						if bAllowBloomAllImprovements or pPlot.getImprovementType() in lBloomableImprovements:
							if pPlot.canHaveFeature(iForestNew):
								pPlot.setFeatureType(iForestNew, 0)
					elif iFeature in dFeatures:
						iFeatureNew = dFeatures[iFeature]
						pPlot.setFeatureType(iFeatureNew, 0)


def reqOvergrowth(pCaster, eSpell=-1):
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iTeam = pCaster.getTeam()
	pPlotC = pCaster.plot()
	iNature = cf.getNumBonusEffective(pCaster.getOwner(), gc.getInfoTypeForString('BONUS_MANA_NATURE'), pCaster)

	bAllowBloomAllImprovements = pPlayer.getCivilizationType() in [gc.getInfoTypeForString('CIVILIZATION_LJOSALFAR'), gc.getInfoTypeForString('CIVILIZATION_SVARTALFAR'), gc.getInfoTypeForString('CIVILIZATION_KURIOTATES')]

	iWeak = gc.getInfoTypeForString('PROMOTION_WEAK')
	lHeroicPromotions = [	gc.getInfoTypeForString('PROMOTION_STRONG'),
							gc.getInfoTypeForString('PROMOTION_HEROIC_DEFENSE'),
							gc.getInfoTypeForString('PROMOTION_HEROIC_DEFENSE2'),
							gc.getInfoTypeForString('PROMOTION_HEROIC_STRENGTH'),
							gc.getInfoTypeForString('PROMOTION_HEROIC_STRENGTH2')]

	if not bAllowBloomAllImprovements:
		lBloomableImprovements = [	-1,
						gc.getInfoTypeForString('IMPROVEMENT_CAMP'),
						gc.getInfoTypeForString('IMPROVEMENT_LUMBERMILL'),
						gc.getInfoTypeForString('IMPROVEMENT_SEVEN_PINES'),
						gc.getInfoTypeForString('IMPROVEMENT_YGGDRASIL'),
						gc.getInfoTypeForString('IMPROVEMENT_TOMB_OF_SUCELLUS'),
						gc.getInfoTypeForString('IMPROVEMENT_MANA_NATURE'),
						gc.getInfoTypeForString('IMPROVEMENT_MANA_CREATION')
						]

	iForestNew = gc.getInfoTypeForString('FEATURE_FOREST_NEW')
	dFeatures = {	gc.getInfoTypeForString('FEATURE_FOREST')		:	gc.getInfoTypeForString('FEATURE_FOREST_ANCIENT'),
			iForestNew						:	gc.getInfoTypeForString('FEATURE_FOREST'),
			gc.getInfoTypeForString('FEATURE_FOREST_BURNT')		:	gc.getInfoTypeForString('FEATURE_FOREST'),
			gc.getInfoTypeForString('FEATURE_SCRUB')		:	iForestNew,
			gc.getInfoTypeForString('FEATURE_BLIZZARD')		:	-1,
			gc.getInfoTypeForString('FEATURE_ICE')			:	-1
			}


	for i in xrange (CyMap().numPlots()):
		pPlot = CyMap().plotByIndex(i)
		if -1< CyMap().calculatePathDistance(pPlotC, pPlot) < iNature:
			if pPlot.getPlotCounter() > 50:
				return True

			if not pPlot.isWater():
				if not pPlot.isPeak():
					iFeature = pPlot.getFeatureType()
					if iFeature == -1:
						if bAllowBloomAllImprovements or pPlot.getImprovementType() in lBloomableImprovements:
							if pPlot.canHaveFeature(iForestNew):
								return True
					elif iFeature in dFeatures:
						if dFeatures[iFeature] != -1:
							return True

			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)

				if pUnit.isAnimal():
					if pUnit.getTeam() == iTeam:
						if pUnit.isHasPromotion(iWeak):
							return True
						for iProm in lHeroicPromotions:
							if not pUnit.isHasPromotion(iProm):
								return True

	return False


def helpOvergrowth(lpUnits, eSpell=-1):
	szBuffer = ''
	pCaster = lpUnits[0]
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	iTeam = pCaster.getTeam()

	iWeak = gc.getInfoTypeForString('PROMOTION_WEAK')
	iStrong = gc.getInfoTypeForString('PROMOTION_STRONG')
	lHeroicPromotions = [	gc.getInfoTypeForString('PROMOTION_HEROIC_DEFENSE'),
							gc.getInfoTypeForString('PROMOTION_HEROIC_DEFENSE2'),
							gc.getInfoTypeForString('PROMOTION_HEROIC_STRENGTH'),
							gc.getInfoTypeForString('PROMOTION_HEROIC_STRENGTH2')]

	pPlotC = pCaster.plot()
	iNature = cf.getNumBonusEffective(pCaster.getOwner(), gc.getInfoTypeForString('BONUS_MANA_NATURE'), pCaster)
	bAllowBloomAllImprovements = pPlayer.getCivilizationType() in [gc.getInfoTypeForString('CIVILIZATION_LJOSALFAR'), gc.getInfoTypeForString('CIVILIZATION_SVARTALFAR'), gc.getInfoTypeForString('CIVILIZATION_KURIOTATES')]

	if not bAllowBloomAllImprovements:
		lBloomableImprovements = [	-1,
						gc.getInfoTypeForString('IMPROVEMENT_CAMP'),
						gc.getInfoTypeForString('IMPROVEMENT_LUMBERMILL'),
						gc.getInfoTypeForString('IMPROVEMENT_SEVEN_PINES'),
						gc.getInfoTypeForString('IMPROVEMENT_YGGDRASIL'),
						gc.getInfoTypeForString('IMPROVEMENT_TOMB_OF_SUCELLUS'),
						gc.getInfoTypeForString('IMPROVEMENT_MANA_NATURE'),
						gc.getInfoTypeForString('IMPROVEMENT_MANA_CREATION')
						]

	iForestNew = gc.getInfoTypeForString('FEATURE_FOREST_NEW')
	dFeatures = {	iForestNew										:	gc.getInfoTypeForString('FEATURE_FOREST'),
					gc.getInfoTypeForString('FEATURE_FOREST_BURNT')	:	gc.getInfoTypeForString('FEATURE_FOREST'),
					gc.getInfoTypeForString('FEATURE_FOREST')		:	gc.getInfoTypeForString('FEATURE_FOREST_ANCIENT'),
					gc.getInfoTypeForString('FEATURE_SCRUB')		:	iForestNew,
					gc.getInfoTypeForString('FEATURE_BLIZZARD')		:	-1,
					gc.getInfoTypeForString('FEATURE_ICE')			:	-1
					}
	szBuffer += localText.getText("TXT_KEY_SPELL_RANGE", (iNature, ))+ '\n'
	lPlots = []
	lAnimals= []
	for i in xrange (CyMap().numPlots()):
		pPlot = CyMap().plotByIndex(i)
		if -1< CyMap().calculatePathDistance(pPlotC, pPlot) < iNature:
			lPlots.append(pPlot)
			for i in xrange(pPlot.getNumUnits()):
				pUnit = pPlot.getUnit(i)
				if pUnit.isAnimal():
					if pUnit.getTeam() == iTeam:
						if not pUnit.isHasPromotion(iWeak):
							lAnimals.append(pUnit)
						else:
							for iProm in lHeroicPromotions:
								if not pUnit.isHasPromotion(iProm):
									lAnimals.append(pUnit)
									continue
	if len(lAnimals) >0:
		szBuffer += helpTogglePromotionsSpecificUnits(lpUnits, lAnimals, eSpell, ['PROMOTION_STRONG','PROMOTION_HEROIC_DEFENSE','PROMOTION_HEROIC_DEFENSE2','PROMOTION_HEROIC_STRENGTH','PROMOTION_HEROIC_STRENGTH2'],['PROMOTION_WEAK'], False)

	for iFeatureOld, iFeatureNew in dFeatures.items():
		iNum = 0
		for loopPlot in lPlots:
			if iFeatureOld == loopPlot.getFeatureType():
				iNum +=1
		if iNum > 0:
			sOld = 'none'
			if iFeatureOld != -1:
				sOld = gc.getFeatureInfo(iFeatureOld).getDescription()
			sNew = 'none'
			if iFeatureNew != -1:
				sNew = gc.getFeatureInfo(iFeatureNew).getDescription()

			szBuffer += localText.getText("TXT_KEY_HELP_SPELL_CHANGE_A_TO_B", (sOld, sNew, )) + ' on ' + str(iNum) + ' plots '

	iNumBloom =0
	for loopPlot in lPlots:
		if loopPlot.getFeatureType() == -1:
			if bAllowBloomAllImprovements or loopPlot.getImprovementType() in lBloomableImprovements:
				if loopPlot.canHaveFeature(iForestNew):
					iNumBloom +=1
	if iNumBloom > 0:
		szBuffer += localText.getText("TXT_KEY_HELP_SPELL_ADDS", ( )) + gc.getFeatureInfo(iForestNew).getDescription() + ' on ' + str(iNumBloom) + ' plots '

	return szBuffer


def reqVitalize(pCaster,eSpell=-1):
	eSpell2 = gc.getInfoTypeForString('SPELL_VITALIZE_AREA')
