def reqTransmogrifyBaboon(pCaster, eSpell=-1):
	if pCaster.isAlive():
		if pCaster.getUnitType() == gc.getInfoTypeForString('UNIT_BABOON'):
			return False
		if isWorldUnitClass(pCaster.getUnitClassType()):
			return False
		return True
	return False

def spellTransmogrifyBaboon(pCaster, eSpell=-1):
	iPlayer = pCaster.getOwner()
	pPlayer = gc.getPlayer(iPlayer)
	pPlot = pCaster.plot()
	CyInterface().addMessage(iPlayer, True, 25, localText.getText("TXT_KEY_MESSAGE_WONDER_BABOON", ()), '', 1, 'Art/Interface/Buttons/Units/Margalard.dds', ColorTypes(8), pPlot.getX(), pPlot.getY(), True, True)
	for iProm in xrange(gc.getNumPromotionInfos()):
		if pCaster.isHasPromotion(iProm):
			if gc.getPromotionInfo(iProm).isRace():
				pCaster.setHasPromotion(iProm, False)
	newUnit = pPlayer.initUnit(gc.getInfoTypeForString('UNIT_BABOON'), pCaster.getX(), pCaster.getY(), UnitAITypes.NO_UNITAI, DirectionTypes.DIRECTION_SOUTH)
	newUnit.convert(pCaster)
	if pPlayer.isHuman():
		t = "TROPHY_FEAT_BABOON"
		if not CyGame().isHasTrophy(t):
			CyGame().changeTrophyValue(t, 1)




def reqDefile(pCaster, eSpell=-1):
	if reqEntropyAllowed(pCaster, eSpell):
		iTeam = pCaster.getTeam()
		iProm = gc.getInfoTypeForString('PROMOTION_UNHOLY_TAINT')
		iPromR = gc.getInfoTypeForString('PROMOTION_BLESSED')
		info = gc.getPromotionInfo(iProm)
		iX = pCaster.getX()
		iY = pCaster.getY()
		for iiX in xrange(iX-1, iX+ 2, 1):
			for iiY in xrange(iY-1, iY+ 2, 1):
				pPlot = CyMap().plot(iiX, iiY)
				if pPlot.isNone():
					continue
				for i in xrange(pPlot.getNumUnits()):
					pUnit = pPlot.getUnit(i)
					if pUnit.isImmuneToSpell(pCaster, eSpell):continue
					if pUnit.isHasPromotion(iPromR):
						return True
					if pUnit.isHasPromotion(iProm):continue
					if pUnit.isPromotionImmune(iProm):continue
					if info.getUnitCombat(pUnit.getUnitCombatType()):
						return True
				if not gc.getGame().isOption(GameOptionTypes.GAMEOPTION_NO_PLOT_COUNTER):
					if pCaster.atPlot(pPlot) or pCaster.canMoveOrAttackInto(pPlot, True):
						if pPlot.getPlotCounter() < 99:
							return True
	return False

def spellDefile(pCaster, eSpell=-1):

	iInfernal = gc.getInfoTypeForString('CIVILIZATION_INFERNAL')
	iMercurians = gc.getInfoTypeForString('CIVILIZATION_MERCURIANS')
	iBarb = gc.getInfoTypeForString('CIVILIZATION_BARBARIAN')
	iAshenVeil = gc.getInfoTypeForString('RELIGION_THE_ASHEN_VEIL')
	iBurningSands = gc.getInfoTypeForString('TERRAIN_BURNING_SANDS')
